window.GQ={"S":["화재조사론","화재감식론","증거물관리 및 법과학","화재조사보고 및 피해평가","화재조사관계법규"],"M":{"과목":[["화재조사론",20],["화재감식론",20],["증거물관리 및 법과학",20],["화재조사보고 및 피해평가",20],["화재조사관계법규",20]],"총":100,"유형":"기사","분율":1.5},"Q":[["ew20130928-1",0,"T007","2013-09-28",1,92,"다음 중 분진폭발의 위험이 가장 낮은 것은?",["알루미늄","적린","황","생석회"],4,0,"ew20130928"],["ew20130928-2",0,"T001","2013-09-28",2,89,"불기둥에 의해 수직벽면에 생성되는 패턴으로 옳지 않는 것은?",["V 패턴","모래시계 패턴","도넛형태 패턴","U 패턴"],3,0,"ew20130928"],["ew20130928-3",0,"T001","2013-09-28",3,73,"화재가 나타나는 V 패턴의 설명으로 가장 거리가 먼 것은?",["불꽃과 대류 또는 복사열에 의해서 생성된다.","연소가 진행될 때 수직으로 된 벽면에 나타난다.","패턴이 나타내는 각도가 넓으면 연소속도가 느리다.","발화지점이 아닌 곳에서도 생성될 수 있다."],3,0,"ew20130928"],["ew20130928-4",0,"","2013-09-28",4,86,"아마인유, 대두유, 오동유 등의 건성유를 90∼100℃에서 5∼10시간 공기를 불어 넣으면서 가열하여 색과 점도를 준 것으로 요오드가가 145 이상인 보일유에 안료와 전색제 등을 혼합한 착색도료는?",["락카","페인트","시너","알코올"],2,0,"ew20130928"],["ew20130928-5",0,"T027","2013-09-28",5,76,"다음 중 박리 흔(spalling)이 발생할 수 있는 조건으로 가장 거리가 먼 것은?",["습기가 적은 노후 건물의 콘크리트","철근, 철망과 콘크리트의 열팽창 차","콘크리트 혼합의 정도 차","수열면과 이면부의 온도 차"],1,0,"ew20130928"],["ew20130928-6",0,"T014","2013-09-28",6,87,"화재조사 측면에서의 화재진압 및 구조대원이 역할이라고 볼 수 없는 것은?",["구조대원은 피해자들의 화상부위와 정도를 확인하고 이를 화재조사자에게 통보한다.","진압을 위해 출입문을 강제로 개발할 때 다른 강제적인 흔적이 발견된다면 이 흔적이 겹치지지 않도록 다른 곳을 파괴 한다.","잔불정리 과정에서 과도하게 변형시키지 않으며, 변경 되었을 경우에는 화재조사자에게 통보 한다.","진압시 자가발전설비가 부착된 기구를 재급유 할 때에는 화재현장에서 신속하게 진행한다."],4,0,"ew20130928"],["ew20130928-7",0,"T016","2013-09-28",7,88,"화재현장 복원 요령으로 가장 옳은 것은?",["형체가 소실되어 배치가 불가능한 것은 끈이나 로프 또는 대용품을 사용하되 대용품이라는 것이 인식되도록 한다.","복원은 현장식별이 가능하지 않는 것도 복원한다.","불확실하지 않아도 예측에 의존하여 복원한다.","관계인은 복원현장에 입회시키지 않는다."],1,0,"ew20130928"],["ew20130928-8",0,"T011","2013-09-28",8,74,"점화원에 대한 설명으로 옳은 것은?",["온도가 높을수록 최소점화에너지는 높아진다.","가스와 공기의 혼합비율이 연소하한계에 가까울수록 점화에너지는 작아진다.","가스와 공기의 혼합비율이 연소상한계에 가까울수록 점화에너지는 작아진다.","연소범위 내에 있는 가연성 가스는 정전기 등의 약한 에너지도 점화될 수 있다."],4,0,"ew20130928"],["ew20130928-9",0,"T020","2013-09-28",9,78,"메틸에틸케톤(MEK) 화재의 분류로 적합한 것은?",["A급 화재","B급 화재","C급 화재","D급 화재"],2,0,"ew20130928"],["ew20130928-10",0,"T024","2013-09-28",10,87,"화염의 색이 백적색일 때 불꽃의 온도는?",["350℃ 정도","800℃ 정도","1,300℃ 정도","1,500℃ 정도"],3,0,"ew20130928"],["ew20130928-11",0,"T003","2013-09-28",11,83,"목재의 탄화심도를 측정시 유의사항으로 적합하지 않은 것은?",["게이지로 측정된 깊이 외에 소실된 부분의 깊이를 더하여 비교하여야 한다.","탄화되지 않는 곳까지 삽입될 수 있으므로 송곳과 같은 날카로운 측정기구를 사용한다.","측정기구는 목재와 직각으로 삽입하여 측정한다.","탄화된 요철 부위 중 철(凸)부위를 택하여 측정한다."],2,0,"ew20130928"],["ew20130928-12",0,"T026","2013-09-28",12,83,"다음 중 산소공급원의 역할을 하는 물질은?",["과산화나트륨","황린","칼륨","디에틸에테르"],1,0,"ew20130928"],["ew20130928-13",0,"T010","2013-09-28",13,66,"다음 중 발화온도가 가장 높은 것은?",["메탄","프로판","이소프탄","노르말 헥산"],1,0,"ew20130928"],["ew20130928-14",0,"T012","2013-09-28",14,84,"화재원인조사에 해당하는 조사의 종류와 범위로 옳은?",["발화원인조사 - 화재의 발견, 통보 및 초기소화 등 일련의 과정","연소상황조사 – 소방시설의 사용 또는 작동 등의 상황","소방시설조사 – 열에 의한 탄화, 용융, 파손 등의 피해","피난상황조사 – 피난경로, 피난상의 장애요인 등의 상황"],4,0,"ew20130928"],["ew20130928-15",0,"T015","2013-09-28",15,85,"다음 화재현장의 특징 중 건축물 방화현장의 특징으로 가장 거리가 먼 것은?",["화재가 건물의 구조, 가연물 등에 비해 급격히 확산된 경우","최초 발화지점에서 유류 등 연료물질을 사용한 흔적이 있는 경우","출입문, 창 등에 잠김 강제로 진입한 흔적이 있는 경우","연소기구를 중심으로 연소확대가 진행된 흔적이 있는 경우"],4,0,"ew20130928"],["ew20130928-16",0,"","2013-09-28",16,82,"유류화재와 관련된 용어의 설명으로 틀린 것은?",["인화점은 외부로부터 에너지를 받아서 착화 가능한 최저온도","발화점은 외부로부터 점화에너지 공급 없이 물질 스스로 착화되는 최저온도","증기밀도는 공기이 분자량을 가연성 물질의 분자량으로 나눈 값","연소점은 화염이 꺼지지 않고 지속되는 최저온도"],3,0,"ew20130928"],["ew20130928-17",0,"T012","2013-09-28",17,83,"화재조사의 책임과 권한으로 옳은 것은?",["소방서장은 관계보험사가 그 화재원인과 피해상황을 조사하고자 할 때에는 이를 허용해서는 아니 된다.","소방법상 소방서장은 화재가 발생했을 때 그 원인과 화재 또는 소화로 인해 생긴 손해의 조사는 소화활동 후에 시작해야 한다.","실화책임의 경우에 민법 제750조의 규정을 적용함에 있어 경미한 과실이 있는 경우에 한하여 적용한다.","소방서장은 화재조사를 위하여 필요한 경우에는 수사에 지장을 주지 아니하는 범위에서 피의자 또는 압수된 증거물에 대한 조사를 할 수 있다."],4,0,"ew20130928"],["ew20130928-18",0,"T008","2013-09-28",18,67,"프로판 50vol%, 메탄 30vol%, 수소 20vol%의 조성으로 혼합된 가연성연료가 공기 중에 존재한다고 할 때 이 연료가스의 연소하한계(LFL)는 얼마인가? (단, 프로판의 LFL은 2.1vol%, 메탄의 LFL은 5vol%, 수소의 LFL은 4vol%이다.)",["2.27 vol%","2.87 vol%","3.97 vol%","4.07 vol%"],2,0,"ew20130928"],["ew20130928-19",0,"T001","2013-09-28",19,83,"액체가연물이 연소되면서 발생되는 열에 의해 가열되어 주변으로 튀거나 액체를 뿌릴 때 바닥면에 액체 방울이 튄 것처럼 연소하는 패턴은?",["고스트 마크(ghost mark)","스플래쉬 패턴(splash pattern)","푸어 패턴(pour pattern)","도넛 패턴(doughnut pattern)"],2,0,"ew20130928"],["ew20130928-20",0,"T012","2013-09-28",20,84,"소방법령에 근거한 화재조사의 범위에 포함 되지 않는 것은?",["인명피해 조사","피난상황 조사","재산피해 조사","보험관계 조사"],4,0,"ew20130928"],["ew20130928-21",1,"T051","2013-09-28",21,65,"나무에서 공통적으로 나타나는 탄화와 균열의 특성으로 틀린 것은?",["유염연소가 무염연소보다 타 들어가는 것이 깊다.","불에 오래도록 강하게 탈수록 탄화의 깊이는 깊다.","탄화모양을 형성하고 있는 패인 골이 깊을수록 소손이 강하다.","탄화모양을 형성하고 있는 패인 골의 폭이 넓을수록 소손이 강하다."],1,0,"ew20130928"],["ew20130928-22",1,"T036","2013-09-28",22,82,"항공기 화재에서 가연성 금속화재의 분류(class)로 옳은 것은?",["Class A","Class B","Class C","Class D"],4,0,"ew20130928"],["ew20130928-23",1,"","2013-09-28",23,80,"산화성 고체가 아닌 것은?",["질산염류","염소산염류","과염소산염류","질산에스테르류"],4,0,"ew20130928"],["ew20130928-24",1,"","2013-09-28",24,79,"발화원에 대한 설명으로 틀린 것은?",["발화원은 가연물의 발화온도에 이르는 높은 에너지를 가지고 있다.","발화원은 대체로 발화지점이나 그 근처에 존재할 수 있다.","발화원은 발화원인을 증명하기 위해 꼭 확인되어야 한다.","발화원은 발견되거나 파괴되지 않은 상태로 존재한다."],4,0,"ew20130928"],["ew20130928-25",1,"","2013-09-28",25,54,"자동차 엔진이 회전할 때 기관 내부 주요부위 온도를 나타낸 것 중 옳은 것은?",["연소실 가스 : 3,900℃","연소실의 벽 : 200 ∼ 260℃","피스톤 헤드 중심 : 150 ∼ 260℃","배기 밸브 헤드 부위 : 290 ∼ 310℃"],2,0,"ew20130928"],["ew20130928-26",1,"T051","2013-09-28",26,49,"연소가 확대된 연소경로의 방향성을 알기 위한 주요 판단요소가 아닌 것은?",["연소흔의 형태","점화원의 형태","백열전구의 변형","동물 사체의 탄화정도"],2,0,"ew20130928"],["ew20130928-27",1,"T046","2013-09-28",27,61,"일반적으로 사용되고 있는 안전밸브의 종류가 옳게 연결된 것은?",["LPG 용기 : 가용전(가용합금식) 안전밸브","산화에틸렌 용기 : 파열식 안전밸브","아르곤 압축가스 용기 : 스프링식 안전밸브","초저온 용기 : 스프링식과 파열식의 2중 안전밸브"],4,0,"ew20130928"],["ew20130928-28",1,"T048","2013-09-28",28,55,"누전에 의한 화재를 입증하기 위한 조건에 해당하지 않는 것은?",["누전점","접지점","출화점","인화점"],4,0,"ew20130928"],["ew20130928-29",1,"T054","2013-09-28",29,74,"pH = 3인 수용액의 [H+]는 pH=5인 수용액의 [H+]의 몇 배인가?",["0.01","10","100","1,000"],3,0,"ew20130928"],["ew20130928-30",1,"T038","2013-09-28",30,77,"선박화재의 직접적인 발화(發火)원으로 보기 어려운 것은?",["전기과열","정전기","아크","접지"],4,0,"ew20130928"],["ew20130928-31",1,"T033","2013-09-28",31,84,"방화 범죄 특징에 대한 설명 중 틀린 것은?",["방화는 정신이상, 원한, 보복 등 비정상적인 사고에 의해 발생한다.","방화에 사용된 증거물이 전소되고 은닉되는 것이 대부분이기 때문에 방화원인을 규명하는데 많은 어려움이 있다.","방화는 일반적으로 은폐된 공간에서 이루어지고 순간화재 확산이 빠른 인화성 물질을 사용하는 경우가 많아 피해범위가 크다.","방화는 일반적으로 계절적인 측면에 좌우되고 주기적으로 발생한다."],4,0,"ew20130928"],["ew20130928-32",1,"T033","2013-09-28",32,78,"방화의 일반적인 판단요소로 가장 거리가 먼 것은?",["화상피해자의 유무","무단침입과 출입흔적","범죄흔적","이상(異常)연소현상"],1,0,"ew20130928"],["ew20130928-33",1,"T046","2013-09-28",33,71,"인화성 기체(고압가스)의 폭발사고 조사 시 용기의 색은 기체 종류 파악에 중요하다. 기체의 종류에 따른 용기의 색이 옳게 연결된 것은?",["수소 - 주황색","아세틸렌 - 녹색","액화암모니아 - 회색","LPG – 백색"],1,0,"ew20130928"],["ew20130928-34",1,"T050","2013-09-28",34,73,"정전기를 방지하기 위한 대책으로 틀린 것은?",["땅속으로 정전기를 흘려보내는 접지 조치","공기 중의 습도를 70% 이상으로 유지","비전도성 물질에 탄소, 금속분 등의 대전방지제를 첨가","위험물 등이 배관 내를 흐를 때 빠른 유속 유지"],4,0,"ew20130928"],["ew20130928-35",1,"T044","2013-09-28",35,76,"자동차 점화장치의 전류 흐름 순서는?",["점화스위치 → 배터리 → 시동모터 → 점화코일 → 배전기 → 고압케이블 → 스파크플러그","점화스위치 → 점화코일 →시동모터 → 배터리 → 배전기 → 고압케이블 → 스파크플러그","점화스위치 → 스파크플러그 → 점화코일 → 시동모터 → 배터리 → 배전기 → 고압케이블","점화스위치 → 스파크플러그 → 배터리 → 시동모터 → 점화코일 → 배전기 → 고압케이블"],1,0,"ew20130928"],["ew20130928-36",1,"T047","2013-09-28",36,60,"액화천연가스(LNG)와 액화석유가스(LPG)를 비교한 것으로 틀린 것은?",["LNG의 주성분은 메탄(CH4)이고, LPG의 주성분은 프로판(C3H8)과 부탄(C4H10)이다.","LNG의 연소속도는 느리고 LPG의 연소속도는 빠르다.","LNG는 공기보다 가볍고, LPG는 공기보다 무겁다.","액체에서 기체로의 체적변화는 LNG가 LPG보다 크게 팽창한다."],2,0,"ew20130928"],["ew20130928-37",1,"T042","2013-09-28",37,63,"담뱃불 발화 메커니즘에 대한 설명으로 옳은 것은?",["훈소가 지속될 수 있는 가연물과의 접촉 → 훈소 → 착염 → 출화 의 과정을 겪는다.","담뱃불의 연소 선단에서의 온도는 100∼200℃ 정도이다.","담뱃불의 연소성은 풍속 0.5m/s 에서 최적조건이고 1m/s 이상이면 꺼지기 쉬우며, 산소농도 16% 이하에서는 연소하지 않는다.","담뱃불의 연소시간은 레귤러 사이즈(84mm)의 경우 1개비는 수평 18~19분, 수직 16~17분 정도가 소요된다."],1,0,"ew20130928"],["ew20130928-38",1,"T041","2013-09-28",38,85,"산불진화 시 열 스트레스 손상으로 가장 거리가 먼 것은?",["열 경련","탈수 피로","열 발작","혼수상태"],4,0,"ew20130928"],["ew20130928-39",1,"T039","2013-09-28",39,79,"다음 중 우리나라 임야화재의 발생건수가 가장 많은 계절은?",["봄","여름","가을","겨울"],1,0,"ew20130928"],["ew20130928-40",1,"T061","2013-09-28",40,78,"폭발 현장에서 수집한 배경 정보를 바탕으로 폭발 전 및 폭발시 사고 경위를 표로 만든 후 인과관계이론과 일치하는지 아닌지를 추론한 후 “최적”이론을 설정하는 분석을 무엇이라 하는가?",["손상패턴 분석","구조물 분석","열효과 상관분석","타임 라인 분석"],4,0,"ew20130928"],["ew20130928-41",2,"T068","2013-09-28",41,79,"사진이나 비디오 등 영상물의 증거능력을 인정할 수 있는 권한이 있는 자로 옳은 것은?",["변호사","법관","검사","경찰"],2,0,"ew20130928"],["ew20130928-43",2,"T074","2013-09-28",43,68,"액체증거물 수집에 대한 설명으로 틀린 것은?",["액체 탄화수소물의 밀봉을 위해서 고무로 만들어진 링이나 혹은 고무마개를 지니고 있는 병을 사용하여야 한다.","적은 양의 액체는 피펫 혹은 깨끗한 흡수섬유, 거즈 혹은 탈지면에 흡수시키고 적절한 밀폐용기에 그것을 밀봉할 수 있다.","의심스러운 가연성 액체가 콘크리트에서 발견된다면 습식 브러시로 쓸어 담가나 흡수성 재질을 펼쳐 흡수시킨다.","흡수제는 별도의 캔에 밀봉되어 보관되어야 한다."],1,0,"ew20130928"],["ew20130928-44",2,"T076","2013-09-28",44,84,"화재현장에서 채취한 증거물의 감정기관 이송 시 우편법상의 금지 물품이 아닌 것은?",["흙과 모래 등이 섞인 물질","폭발성 물질","발화성 물질","인화성 물질"],1,0,"ew20130928"],["ew20130928-45",2,"T081","2013-09-28",45,66,"다음 중 화재조사자가 작성해야 하는 서류가 아닌 것은?",["화재발생종합보고서","방화 · 방화의심 조사서","재산피해신고서","소방·방화시설 활용조사서"],3,0,"ew20130928"],["ew20130928-46",2,"T070","2013-09-28",46,79,"화재현장에서 역광 촬영을 하고자 한다. 다음 중 카메라 측광방식으로 가장 옳은 것은?",["스팟측광","중앙부 중점 측광","평균측광","다분할 측광"],1,0,"ew20130928"],["ew20130928-47",2,"T082","2013-09-28",47,83,"화재현장에서 진압대원의 역할과 책임에 관한 설명으로 옳지 않은 것은?",["소화활동 시 화재조사를 고려하여 불필요한 파괴작업을 지양한다.","증거물을 발견하였을 경우 현장지휘자에게 보고하여야 한다.","직사직수로 방수할 경우 최대한 발화지점을 훼손하지 않도록 주의하여야 한다.","화재진압대원은 신속 정확한 진압이 우선이므로 현장보존은 생각할 필요가 없다."],4,0,"ew20130928"],["ew20130928-48",2,"","2013-09-28",48,75,"용융점이 높은 것에서 낮은 순서로 옳게 나열된 것은?",["스테인레스 – 텅스텐 – 아연 – 마그네슘 - 동","텅스텐 – 스테인레스 – 동 – 마그네슘 - 아연","텅스텐 – 스테인레스 – 마그네슘 – 동 - 아연","스테인레스 – 텅스텐 – 동 – 아연 – 마그네슘"],2,0,"ew20130928"],["ew20130928-49",2,"T073","2013-09-28",49,83,"화재현장을 촬영하는 위치에 대한 설명으로 옳은 것은?",["피사체가 냉장고일 경우 전후좌우의 4면을 각각 촬영한다.","촬영방향은 발화부로 추정되는 곳의 앞면을 집중적으로 촬영한다.","카메라는 가능하면 수직으로 촬영한다.","촬영된 사진은 화재조사자를 위한 자료이므로 촬영위치는 조사자의 재량에 달려있다."],1,0,"ew20130928"],["ew20130928-50",2,"","2013-09-28",50,81,"화재현장에서 화재조사자들이 증거물 관련 부분을 직접 인지해야 하는 부분이 아닌 것은?",["화재현장에서 어떻게 다른 물질이 불과 반응했는지 여부","화재의 유형, 화재의 원인","최초 발화지점의 특징, 구조물 내에서 불이 어떻게 진행했는지 여부","화재진압 후 구조물의 안전 여부"],4,0,"ew20130928"],["ew20130928-51",2,"T087","2013-09-28",51,62,"사후강직이란 사망 후 몸이 경직되는 것이다. 경직이 남아 있는 최대 시간은?",["5∼7일","2∼3일","12시간∼1일","2∼6시간"],2,0,"ew20130928"],["ew20130928-52",2,"T069","2013-09-28",52,83,"화재현장 사진 및 비디오 촬영에 대한 설명으로 가장 옳은 것은?",["화재현장은 화재조사자의 경험과 노하우에 의존하여 촬영한다.","명백한 증거물에는 번호표 등의 표식을 생략하고 촬영한다.","최초로 도착하였을 때의 원 상태를 그대로 촬영한다.","현장이 어느 정도 정리된 후에 촬영한다."],3,0,"ew20130928"],["ew20130928-53",2,"T073","2013-09-28",53,81,"화재현장 촬영 시 주요 촬영대상에 대한 설명으로 틀린 것은?",["소방용 설비의 사용 및 작동상황","화재현장에 도착한 소방차 배치상황","발화원으로 추정된 감식 및 감정대상물","화재로 인한 사망자의 위치"],2,0,"ew20130928"],["ew20130928-54",2,"T088","2013-09-28",54,76,"타임라인과 마인드 매핑에 대한 설명으로 틀린 것은?",["상대적 시간은 추정을 근거로 한다.","타임라인은 증거와 정보의 조합이고 마인드 매핑은 사건이 일어난 시간의 재구성이다.","타임라인의 정확성은 가설의 신뢰도를 높인다.","마인드매핑은 수집된 정보를 바탕으로 객관적 사실을 조합하는 과정이다."],2,0,"ew20130928"],["ew20130928-55",2,"","2013-09-28",55,79,"화재현장에서 관계인의 진술 및 증거확보에 관한 설명으로 옳지 않은 것은?",["증거물 특성상 수집이나 보관이 어려워 중요한 단서가 유실되거나 변질 또는 파손되더라도 법적 증거로서의 가치로 인정받는 데는 문제가 없다.","일반 증거물도 수열된 상태로 부식, 파손, 변질되기 쉬우므로 가능한 한 수거 즉시 정밀 감정을 실시하는 것이 원칙인데 현실적으로 소화직후부터 사진 및 동영상으로 촬영한 자료를 통해 증거능력을 인정받는 추세이다.","화재감식에서 수거된 물증이 증거능력을 가지기 위해서는 확보 수집단계부터 사건 종료까지 보관관리가 적절하여야 한다.","증거자료의 수거 및 봉인은 공개적으로 관계인의 입회하에 사진기록과 함께 실시하며, 보관 이송 등의 과정을 명확하게 한다."],1,0,"ew20130928"],["ew20130928-56",2,"","2013-09-28",56,74,"훈소 발화가 가능한 물질에 해당하는 것은?",["스티로폼","플라스틱","종이","나일론 섬유"],3,0,"ew20130928"],["ew20130928-57",2,"T082","2013-09-28",57,86,"화재현장을 보존하기 위한 방법으로 옳지 않은 것은?",["소방(경찰)공무원을 배치하여 일정영역을 접근하지 못하도록 한다.","경고테이프 등을 이용하여 조사 중임을 표시한다.","소방활동구역으로 설정하여 출입을 통제한다.","소방활동구역을 설정할 경우 범위는 최대한 넓게 설정하여야 한다."],4,0,"ew20130928"],["ew20130928-58",2,"T082","2013-09-28",58,82,"화재현장 및 물리적 증거물의 보존에 대한 책임이 있는 자가 아닌 것은?",["화재조사자","소방관","제조사 직원","경찰관"],3,0,"ew20130928"],["ew20130928-59",2,"T088","2013-09-28",59,57,"타임라인에서 상대적 시간에 포함되는 것은?",["알람의 설정과 작동시간","목격자에 의해서 발견된 시간","완전소화시간","목격된 지속시간"],4,0,"ew20130928"],["ew20130928-60",2,"","2013-09-28",60,83,"어떤 물체 내부의 실체를 전혀 알 수 없거나 감정물건의 내부를 확인할 때 사용되는 기기는?",["광학카메라","비파괴 촬영기","디지털카메라","비디오카메라"],2,0,"ew20130928"],["ew20130928-61",3,"T101","2013-09-28",61,83,"화재조사 및 보고규정상 건축·구조물 화재 중 반소의 소실범위는?",["건물의 20% 이상 50% 미만","건물의 20% 이상 70% 미만","건물의 30% 이상 50% 미만","건물의 30% 이상 70% 미만"],4,0,"ew20130928"],["ew20130928-62",3,"T127","2013-09-28",62,83,"화재현장조사서 도면 작성 방법 중 옳지 않은 것은?",["도면은 원칙적으로 지도와 같은 형태로 북쪽을 위로 작성한다.","정확한 축적으로 작성해야 할 필요는 없다.","제도기호 등의 표준화된 기호로 작성하는 것이 기본이며 필요에 따라 문자도 삽입한다.","도면은 이해하기 쉽도록 작성하여야 한다."],2,0,"ew20130928"],["ew20130928-63",3,"T103","2013-09-28",63,72,"화재증명원 발급의 내용으로 옳은 것은?",["화재증명원 발급 시 재산피해내역을 금액으로 기재한다.","이해당사자가 아닌 자가 화재증명원의 발급을 신청하면 화재증명원을 발급하여서는 아니 된다.","사후조사를 할 경우 발화장소 및 발화지점의 현장이 보존되어 있지 않아도 일단 조사를 한다.","소방대가 출동하지 아니한 화재장소에 화재증명원 발급 요청이 있는 경우 사후조사를 할 수 있다."],4,0,"ew20130928"],["ew20130928-64",3,"T104","2013-09-28",64,75,"화재피해액 산정기준에서의 화재피해액 산정대상인 것은?",["인적손해","영업이익","특허권","애완동물"],4,0,"ew20130928"],["ew20130928-65",3,"T105","2013-09-28",65,85,"화재조사서류 작성상의 유의사항으로 옳지 않은 것은?",["원칙적으로 평이하고 알기 쉬운 문장으로 작성토록 노력한다.","오자, 탈자 등이 없도록 글자 하나라도 가볍게 보아서는 안 된다.","필요한 서류가 첨부되어야 한다.","화재유형별 조사서류는 유형에 관계없이 동일 양식에 기재하여야 한다."],4,0,"ew20130928"],["ew20130928-66",3,"T107","2013-09-28",66,63,"가재도구 개별품목별로 화재피해액을 산정하는 공식으로 옳은 것은?",["「재구입비 × [1-(0.8 × 경과연수/내용연수)] × 손해율」","「m2 당 표준단가 × 소실면적 × [1-(0.9 x 경과연수/내용연수)] × 손해율」","「소실단위의 원시건축비 × 물가상승율 × [1-(0.9 × 경과연수/내용연수)] × 손해율」","「건물신축단가 × 소실면적 × 설비종류별 재설비 비율 × [1-(0.8 × 경과연수/내용연수)] × 손해율」"],1,0,"ew20130928"],["ew20130928-67",3,"T108","2013-09-28",67,81,"화재조사서류(사진 포한)를 문서로 기록하고 전자기록 등의 보존방법에 따라 보존해야할 기간은?",["영구보존","10년","5년","2년"],1,0,"ew20130928"],["ew20130928-68",3,"T109","2013-09-28",68,49,"화재조사 및 보고규정에서 긴급상황보고를 해야 하는 대형화재에 해당하지 않는 것은?",["사망자가 6명 발생한 화재","중상자 1명, 경상자 12명이 발생한 화재","이재민이 120명 발생한 화재","재산피해가 60억원 발생한 화재"],3,0,"ew20130928"],["ew20130928-69",3,"T110","2013-09-28",69,83,"화재현장에서 부상을 당한 후 몇 시간 이내에 사망하는 경우 화재로 인한 사망자로 구분하는가?",["24시간","48시간","72시간","96시간"],3,0,"ew20130928"],["ew20130928-70",3,"T111","2013-09-28",70,59,"화재현황조사서에 기입해야 할 항목이 아닌 것은?",["연소학대 사유","발화관련 기기","방화동기","보험가입 사항"],3,0,"ew20130928"],["ew20130928-71",3,"T102","2013-09-28",71,54,"철근콘크리트 슬래브지붕 4층 건물의 2층에서 화재가 발생하여 1층 점포는 천장 1면만 50m2가 수손되고, 2층은 100m2가 전소되었으며, 3층은 바닥, 벽, 처장 등 3면에 70m2가 연기에 그을렸다. 화재피해액 산정 시 소실면적은?",["150m2","170m2","180m2","220m2"],3,0,"ew20130928"],["ew20130928-72",3,"T109","2013-09-28",72,65,"긴급상황보고 대상 중 특수화재에 속하지 않은 것은?",["철도","지하구","항공기","변전소"],2,0,"ew20130928"],["ew20130928-73",3,"T120","2013-09-28",73,78,"화재발생종합보고서 작성요령으로 틀린 것은?",["발화지점, 발화열원, 최초착화물 등 발화원인을 조사하여 기재한다.","화재의 연소경로 및 확대요인 등 연소현상을 조사하여 이를 기재한다.","소방시설은 화재 발생층의 시설에 한하여 조사하고 이를 기재한다.","피난경로, 피난상의 장애요인 등 피난상황을 조사하여 기재한다."],3,0,"ew20130928"],["ew20130928-74",3,"T112","2013-09-28",74,82,"화재현장조사서 작성 시 화재원인 검토와 관련된 내용 중 필수 검토항목이 아닌 것은?",["방화 가능성","전기적 요인","인적 부주의","관련 조치사항"],4,0,"ew20130928"],["ew20130928-75",3,"T101","2013-09-28",75,59,"소실정도에 대한 설명으로 옳은 것은?",["국소란 건물의 50% 이상 70% 미만이 소실된 것을 말한다.","부분소란 전소 · 반소화재에 해당되지 아니하는 것을 말한다.","건축·구조물화재의 소실정도는 전소, 반소, 부분소, 즉소 4종류로 구분한다.","전소란 건물의 70% 이상(바닥면적에 대한 비율을 말한다)이 소실되었거나 또는 그 미만 이라도 잔존부분을 보수하여도 재사용이 불가능 한 것을 말한다."],2,0,"ew20130928"],["ew20130928-76",3,"T113","2013-09-28",76,66,"화재조사 및 보고규정상 건축물에 대한 화재피해액 산정방법으로 옳은 것은?",["복성식평가법","매매사례비교법","수익환원법","정액법"],1,0,"ew20130928"],["ew20130928-77",3,"T114","2013-09-28",77,63,"화재피해액 산정에 있어서 영업시설의 소손 정도에 따른 손해율 60%에 해당하는 것은?",["불에 타거나 변형되고 그을음과 수침 정도가 심한 경우","손상정도가 다소 심하여 상당부분 교체 내지 수리가 필요한 경우","영업시설의 일부를 교체 또는 수리하거나 도장 내지 도배가 필요한 경우","부분적인 소손 및 오염의 경우"],2,0,"ew20130928"],["ew20130928-78",3,"T104","2013-09-28",78,82,"화재피해 산정의 대상이 되지 않는 것은?",["건축물, 구축물의 피해","화재로 인한 영업손실 피해","기계설비, 공·기구류, 부품의 피해","정원수목, 과수목 및 입목의 피해"],2,0,"ew20130928"],["ew20130928-79",3,"T115","2013-09-28",79,77,"화재 피해물의 경제적 내용연수가 다한 경우 잔존하는 가치의 재구입비에 대한 비율은?",["최종잔가율","손해율","잔가율","보정률"],1,0,"ew20130928"],["ew20130928-80",3,"T117","2013-09-28",80,71,"예술품 및 귀중품의 화재피해액 산정기준에 관한 내용으로 틀린 것은?",["복수의 전문가의 감정을 받거나 감정서 등의 금액을 피해액으로 인정한다.","감가공제를 하지 아니한다.","예술품 및 귀중품에 대한 그 가치를 손상하지 아니하고 원상태로 복원이 가능한 경우에는 피해액을 인정하지 아니한다.","공인감정기관에서 인정하는 금액을 화재로 인한 피해액으로 산정한다."],3,0,"ew20130928"],["ew20130928-81",4,"T133","2013-09-28",81,80,"「화재조사 및 보고규정」에 따른 건축·구조물화재 소실정도의 구분이 아닌 것은?",["전소","반소","부분소","국소"],4,1,"ew20130928"],["ew20130928-82",4,"","2013-09-28",82,79,"「화재조사 및 보고규정」에서 정의한 사상자로 옳은 것은?",["사상자는 화재현장에서 사망한 사람을 말한다.","사상자는 화재현장에서 부상당한 사람을 말한다.","사상자는 화재현장에서 피해를 입은 사람을 말한다.","사상자는 화재현장에서 사망 또는 부상당한 사람을 말한다."],4,1,"ew20130928"],["ew20130928-83",4,"","2013-09-28",83,68,"화재조사서류 작성에 관한 내용으로 틀린 것은?",["치외법권지역 등 조사권을 행사 할 수 없는 경우 화재현장출동보고서만 작성한다.","서장은 관할 구역 내에서 발생한 화재에 대하여 화재발생종합보고서를 작성한다.","질문기록서를 작성한다.","화재현장출동보고서를 작성한다."],1,1,"ew20130928"],["ew20130928-84",4,"T145","2013-09-28",84,69,"「제조물책임법」에 따른 손해배상 청구권 소멸시효는 몇 년인가?",["3년","5년","7년","15년"],1,0,"ew20130928"],["ew20130928-86",4,"T149","2013-09-28",86,79,"신체손해배상특약부화재보험에서 상해급별 1급 보험금액으로 옳은 것은?",["1,500만원","800만원","750만원","700만원"],1,1,"ew20130928"],["ew20130928-87",4,"T165","2013-09-28",87,36,"특수건물 소유자가 의무적으로 가입하는 보험금액 등에 대한 설명으로 틀린 것은?",["화재보험 : 특수건물이 시가에 해당하는 금액","특수건물이 시가 결정에 관한 기준 : 대통령령으로 정한다.","신체손해배상책임보험 중 사망의 경우 : 피해자 1명당 50만원 이상으로써 대통령령이 정하는 금액","신체손해배상책임보험 중 부상의 경우 : 피해자 1명당 사망자에 대한 보험금액의 범위에서 대통령령으로 정하는 금액"],2,1,"ew20130928"],["ew20130928-88",4,"T135","2013-09-28",88,80,"소방법령에 따른 화재조사권자가 아닌 자는?",["소방방재청장","시·도지사","소방본부장","소방서장"],2,1,"ew20130928"],["ew20130928-89",4,"T148","2013-09-28",89,79,"제조물책임법의 제정목적이 아닌 것은?",["피해자의 보호를 도모","국민경제의 건전한 발전","제조자의 이익증진","국민생활의 안전향상"],3,1,"ew20130928"],["ew20130928-90",4,"T152","2013-09-28",90,74,"승객이 있는 기차에 불을 놓은 경우에 해당되는 죄는 무엇인가?",["현주건조물등에의 방화","공용건조물등에의 방화","일반건조물등에의 방화","일반물건에의 방화"],1,1,"ew20130928"],["ew20130928-91",4,"T135","2013-09-28",91,54,"화재조사에 대한 설명으로 틀린 것은?",["운행 중인 차량에서 화재가 발생한 경우 소화활동을 행한 출동대의 소방본부장, 소방서장에게 화재조사의 책임이 있다.","화재현장에서 부상을 당한 사람이 사망한 경우 사망시간에 따라서 화재로 인한 사망으로 볼 수도 있다.","외부기관으로부터 조사의 내용에 대한 발표요청이 있는 경우에는 특별한사유가 없는 한 그 내용을 발표한다.","조사본부는 그 기능이 완료되면 이를 해체한다."],1,1,"ew20130928"],["ew20130928-92",4,"","2013-09-28",92,57,"신체손해배상특약부 화재보험의 설명으로 옳은 것은?",["장해가 남은 것이란 정상기능의 5분의 2 이상을 상실한 경우를 말한다.","제대로 못쓰게 된 것이란 정상기능의 5분의 4 이상을 상실한 경우를 말한다.","뚜렷한 장해가 남은 것이란 정상기능의 5분의 3 이상을 상실한 경우를 말한다.","향상보호 또는 수시보호의 기간은 의사가 판정하는 노동능력상실기간을 기준으로 하여 타당한 기간으로 한다."],4,1,"ew20130928"],["ew20130928-93",4,"T153","2013-09-28",93,67,"공용건조물 등에의 방화죄 대상물이 아닌 것은?",["건조물","자동차","임야","광갱"],3,1,"ew20130928"],["ew20130928-94",4,"T174","2013-09-28",94,54,"사법경찰리에 해당되지 않는 것은?",["경위","경사","경장","순경"],1,0,"ew20130928"],["ew20130928-95",4,"T136","2013-09-28",95,57,"화재조사자가 화재원인 및 피해조사활동을 개시하는 시점으로 옳은 것은?",["화재출동과 동시","화재의 각지와 동시","119상황실에 화재신고가 접수되어 출동지령과 동시","현장에 소방차량이 도착함과 동시"],2,1,"ew20130928"],["ew20130928-96",4,"","2013-09-28",96,78,"화재가 발생하였을 때에 화재의 원인 및 피해 등에 대해 조사를 하는 것을 무엇이라 하는가?",["화재감식","화재수사","화재감정","화재조사"],4,1,"ew20130928"],["ew20130928-97",4,"T139","2013-09-28",97,62,"소방법령상 100만원 이하의 벌금에 해당하는 행위가 아닌 것은?",["화재경계지구안의 소방대상물에 대한 소방특별조사를 거부 · 방해 또는 기피한 자","화재조사를 수행하면서 알게 된 비밀을 다른 사람에게 누설한 자","소방본부장 등의 피난명령을 위반한 자","위험물질 공급의 차단조치를 정당한 사유 없이 방해한 자"],2,1,"ew20130928"],["ew20130928-98",4,"T156","2013-09-28",98,71,"실화책임에 관한 법률에서 정하고 있는 손해배상액의 경감사유와 거리가 먼 것은?",["피해정도","화재의 원인","배상의무자의 정신적 상태","피해확대의 원인"],3,1,"ew20130928"],["ew20130928-99",4,"T156","2013-09-28",99,66,"실화책임에 관한 법률에 대한 설명으로 옳은 것은?",["실화자에게 중대한 과실이 없는 경우 그 손해배상액을 경감할 수 있다.","실화로 인하여 화재가 발생한 경우에 피해자에게 적용하는 법률이다.","실화자에게 경과실이 있다면 손해배상을 면책할 수 있다.","민법의 무과실책임의 원칙을 우선 적용하고 있다."],1,1,"ew20130928"],["ew20130928-100",4,"T154","2013-09-28",100,54,"화재에 있어서 진화용의 시설 또는 물건을 은닉 또는 손괴하거나 기타 방법으로 진화를 방해한 자에 대한 형법상 벌칙은?",["10년 이상의 징역","10년 이하의 징역","3년 이상의 징역","3년 이하의 징역"],2,1,"ew20130928"],["ew20150919-1",0,"T005","2015-09-19",1,77,"철의 열적 변형에 대한 설명으로 옳지 않은 것은?",["녹는점은 660℃이다.","적열상태가 되면 연성이 증가한다.","수열이 있는 반대방향으로 휜다.","산화반응이 일어나 변색된다."],1,0,"ew20150919"],["ew20150919-2",0,"T016","2015-09-19",2,85,"증거물 수집 용기와 시료 적응성을 연결한 것으로 틀린 것은?",["종이상자 : 고체","금속캔 : 고체, 액체","유리병 : 고체, 액체","비닐 백 : 액체"],4,0,"ew20150919"],["ew20150919-3",0,"T027","2015-09-19",3,61,"화재패턴 중 폭열에 대한 설명으로 가장 옳은 것은?",["가열되는 경우에 다른 열팽창 정도로 인해 폭열이 발생하며, 냉각되는 과정에서는 발생하지 않는다.","단일 재료에 의해 만들어진 자연석도 폭열이 발생한다.","구획실의 바닥면에서 폭열이 발생하는 경우 액체가연물이 연소된 흔적으로 추정할 수 있다.","실제 현장에서의 폭열은 열은 받은 부위가 중력에 의해 떨어지며 소음이 발생하지 않는다."],2,0,"ew20150919"],["ew20150919-4",0,"T003","2015-09-19",4,79,"발화부 주변의 일반적인 연소현상에 대한 설명으로 옳지 않은 것은?",["발화부를 향해 소락되거나 도괴된다.","발화부와 가까울수록 탄화심도가 깊다.","목재표면에 발생하는 균열은 발화부와 멀수록 골이 넓어진다.","발화부는 일반적으로 밝은 색을 띠며 발화부와 멀어질수록 어두운 빛을 나타낸다."],3,0,"ew20150919"],["ew20150919-5",0,"T008","2015-09-19",5,83,"메탄 40vol%, 에탄 30vol%, 프로판 30vol%가 혼합되어 있는 혼합성기체의 공기 중 폭발하한계는 약 몇 vol%인가? (단, 각 물질의 폭발범위 메탄 : 5~15vol%, 에탄 : 3~12.4vol%, 프로판 : 2.1~9.5vol%)",["2.5","3.1","4.3","5.7"],2,0,"ew20150919"],["ew20150919-6",0,"T019","2015-09-19",6,79,"연기에 대한 설명으로 옳지 않은 것은?",["연기는 공기 중에 부유하고 있는 고체 또는 액체의 미립자이다.","건물 내에서 연기의 확산 속도는 수평으로 약 0.5m/s 이다.","알코올이 연소될 경우 연기의 색이 진한 검정색을 띤다.","고층건물에서 연기를 이동시키는 주요 추진력은 굴뚝효과이다."],3,0,"ew20150919"],["ew20150919-7",0,"T004","2015-09-19",7,67,"화재현장에서 유리는 화재로 인해 받은 열의 정도에 따라 그 형태가 각기 다르게 나타난다. 이에 대한 설명으로 옳지 않은 것은?",["열을 받은 유리는 수열방향으로 보다 많이 낙하한다.","유리는 열을 받으면 방사형 균열이 발생한다.","열을 받은 유리의 조개껍질 모양의 박리는 고온일수록 많고 깊다.","유리는 열을 받은 정도가 클수록 용융범위가 넓어진다."],2,0,"ew20150919"],["ew20150919-8",0,"T006","2015-09-19",8,78,"복사체로부터의 열전달률은 해당물질의 절대온도의 몇 제곱에 비례하는가?",["5","4","3","2"],2,0,"ew20150919"],["ew20150919-9",0,"T011","2015-09-19",9,84,"혼합가연물의 최소착화에너지에 영향을 미치는 요인에 대한 설명으로 옳은 것은?",["온도가 높을수록 최소착화에너지는 높아진다.","연소범위에 따라서 최소착화에너지는 변한다.","가연물의 종류에 따라서 최소착화에너지는 일정하다.","혼합된 공기의 산소농도에 따라서 최소착화에너지는 일정하다."],2,0,"ew20150919"],["ew20150919-10",0,"T023","2015-09-19",10,75,"연소현황 중 완전연소에 대한 설명으로 옳은 것은?",["산소의 공급이 불충분한 상태에서의 연소현상이다.","연소 시 다량의 가연성 가스의 공급이 완전연소의 원인이 된다.","탄화수소가 완전연소하면 이산화탄소와 수증기가 생성된다.","환기가 제대로 되지 않은 상태에서 실내에 가스기구를 사용하는 경우에 발생한다."],3,0,"ew20150919"],["ew20150919-11",0,"T001","2015-09-19",11,83,"인화성 및 발화성의 가연물이 연소할 때 중심부의 가연성 액체를 기화시키면서 나타나는 화재패턴은?",["포워패턴(Pour pattern)","레인보우패턴(Rainbow pattern)","스프래쉬패턴(Splash pattern)","도넛패턴(Doughnut pattern)"],4,0,"ew20150919"],["ew20150919-12",0,"T006","2015-09-19",12,84,"열전달 방식 중 복사에 의한 열전달 사례인 것은?",["화재현장에서 창문을 파괴하거나 뜨거운 열기가 급격히 분출되었다.","대규모 산불현장에서 너무 뜨거워 소방관이 멀리 떨어져 소화활동을 하였다.","방바닥이 너무 뜨거워서 발에 화상을 입었다.","가마솥에 밥을 다하고 나서 밥 위에 고구마를 넣었더니 20분 만에 익었다."],2,0,"ew20150919"],["ew20150919-13",0,"","2015-09-19",13,86,"화재피해조사 중 건물의 소실정도를 나타내는 것으로 옳은 것은?",["전소 : 건물의 입체면적 70% 이상 소실","반소 : 건물의 입체면적 50% 이상 소실","즉소 : 건물의 입체면적 30% 이상 소실","부분소 : 건물의 입체면적 50% 미만 30% 이상 소실"],1,0,"ew20150919"],["ew20150919-14",0,"T012","2015-09-19",14,84,"화재원인조사의 조사범위가 아닌 것은?",["소방활동 중 발생한 사망자 및 부상자","화재의 연소경로 및 확대원인 등의 상황","피난경로, 피난상의 장애요인 등의 상황","화재가 발생한 과정, 화재가 발생한 지점 및 불이 붙기 시작한 물질"],1,0,"ew20150919"],["ew20150919-15",0,"T023","2015-09-19",15,74,"연소의 특성에 대한 설명으로 옳지 않은 것은?",["연소속도는 재료의 질량유속으로 정의되며 g/m2s로 나타낸다.","일반적으로 표면에서의 질량유속은 5~50 g/m2s 범위에 있으며, 그 값이 5 이하인 것은 소화된다.","화염속도는 물적조건과 에너지조건인 농도, 압력, 온도보다 난류의 영향으로 가속된다.","연소속도는 화학양론비 부근에서 최소가 되고 연소상한계, 연소하한계로 갈수록 연소속도는 증가한다."],4,0,"ew20150919"],["ew20150919-16",0,"T005","2015-09-19",16,77,"물질의 융점으로 옳은 것은?",["납 : 327℃","구리 : 1540℃","파라핀 : 660℃","알루미늄 : 54℃"],1,0,"ew20150919"],["ew20150919-17",0,"T013","2015-09-19",17,71,"소방기본법 상 화재조사 기자재 중 감식·감정용 기기가 아닌 것은?",["절연저항제","클램프메타","거리측정기","복합가스측정기"],3,0,"ew20150919"],["ew20150919-18",0,"T014","2015-09-19",18,79,"조사관의 현장 조사업무로 거리가 먼 것은?",["현장 탐색","관계인 인터뷰","증거물의 감정","증거수집 및 보존"],3,0,"ew20150919"],["ew20150919-19",0,"T007","2015-09-19",19,64,"분진폭발을 가스폭발과 비교할 때 분진폭발의 특징으로 옳은 것은?",["최소발화에너지가 크다.","연소속도가 빠르다.","불완전연소가 적다.","연소시간이 짧다."],1,0,"ew20150919"],["ew20150919-20",0,"T017","2015-09-19",20,85,"화재조사 진행순서로서 가장 옳은 것은?",["현장관찰 → 관계자질문 → 발굴 → 감정 → 발화원인 판정","관계자질문 → 발굴 → 현장관찰 → 감정 → 발화원인 판정","관계자질문 → 발굴 → 현장관찰 → 발화원인 판정 → 감정","현장관찰 → 발굴 → 관계자질문 → 발화원인 판정 → 감정"],1,0,"ew20150919"],["ew20150919-21",1,"T035","2015-09-19",21,64,"항공기에서 화재감지장치(fire detection system)가 설치되지 않는 곳은?",["화장실(lavatory)","연료탱크(fuel tank)","바퀴실(wheel well)","블리드에어 덕트(bleed air duct)"],2,0,"ew20150919"],["ew20150919-22",1,"T048","2015-09-19",22,66,"절연물이 소규모 방전 또는 고온의 불꽃에 의해 탄화되어 도전성 물질로 되는 것은?",["접촉불량","흑연화","반단선","단락"],2,0,"ew20150919"],["ew20150919-23",1,"T051","2015-09-19",23,81,"구획실에서 유염(불꽃)화재 연소과정으로 바르게 나열한 것은?",["점화 → 성장기 → 플래시오버 → 최성기 → 감쇠기 → 소화","점화 → 성장기 → 최성기 → 플래시오버 → 감쇠기 → 소화","점화 → 최성기 → 성장기 → 플래시오버 → 감쇠기 → 소화","점화 → 성장기 → 최성기 → 감쇠기 → 플래시오버 → 소화"],1,0,"ew20150919"],["ew20150919-24",1,"T043","2015-09-19",24,75,"미소화원에 대한 설명으로 옳은 것은?",["유염화원에 비하여 에너지량이 훨씬 많다.","표면적으로 연소가 확대되는 경우가 많다.","담뱃불, 향불, 불티 등과 같은 무염화원을 지칭한다.","협의로 해석할 때는 나화라고도 하여 유염화원과 구분한다."],3,0,"ew20150919"],["ew20150919-26",1,"T061","2015-09-19",26,67,"다수의 사실로부터 일반적인 사항을 도출해내는 추론방법은?",["합리적 추론","귀납적 추론","연역적 추론","형식적 추론"],2,0,"ew20150919"],["ew20150919-27",1,"T033","2015-09-19",27,87,"방화의 특징으로 옳지 않은 것은?",["방화의 원인이 다양하다.","방화의 발생은 계절과 상관관계가 높다.","용도별로는 주택 및 차량에 대한 방화가 많다.","휘발유, 시너 등을 사용하는 경우가 많아 화재확산이 매우 빠르다."],2,0,"ew20150919"],["ew20150919-28",1,"T049","2015-09-19",28,55,"캡타이어코드(0.75mm2/30본) 0.18mm 한 가닥의 용단전류는 약 몇 A 인가? (단, 재료는 구리로 간주한다.)",["5.11","6.11","7.11","8.11"],2,0,"ew20150919"],["ew20150919-29",1,"T038","2015-09-19",29,82,"철제 선박화재의 진화가 어려운 이유가 아닌 것은?",["선박 윗부분으로의 화재확산이 어렵기 때문","철판이 열을 다른 구획실로 쉽게 전달하기 때문","전기, 유압 시스템 등의 수직 관통부를 통한 대류현상 때문","발화부에 인접한 구획실에 존재하는 가연물이 발화온도에 쉽게 도달하기 때문"],1,0,"ew20150919"],["ew20150919-30",1,"T054","2015-09-19",30,54,"표준상태 0℃, 1기압에서 메탄(CH4) 3.2kg을 이상기체 상태방정식으로 계산하면 부피는(L) 얼마인가? (단, 기체상수 R = 0.082 L·atm/mol·K, 탄소 원자량 : 12, 수소 원자량 : 1로 계산한다.)",["447.7","4477.2","223.8","2238.6"],2,0,"ew20150919"],["ew20150919-31",1,"T064","2015-09-19",31,61,"유류를 이용한 자살 방화 현장의 특징으로 옳지 않은 것은?",["유류를 사용한 용기가 존재한다.","우발적이기보다는 계획적으로 실행한다.","연소면적에 비해 탄화심도가 깊다.","급격한 연소 확대로 연소의 방향성 식별이 어렵다."],3,0,"ew20150919"],["ew20150919-32",1,"T064","2015-09-19",32,74,"석유류의 연소특성에 대한 설명으로 옳지 않은 것은?",["휘발성이 낮은 중질유는 미세한 크기로 미립화하여 분무연소한다.","원유탱크의 화재가 장시간 지속되면 고온층이 형성되어 유류화재의 위험한 현상들이 나타날 수 있다.","대부분의 석유류가 포함되어 있는 제4류 위험물은 인화점이 높고, 연소하한계가 높아서 화재위험성이 크다.","휘발유, 등유는 증기비중이 공기보다 크기 때문에 증발한 증기는 낮은 곳에 체류한다."],3,0,"ew20150919"],["ew20150919-33",1,"T046","2015-09-19",33,67,"LPG 차량의 충전밸브에 부착된 안전밸브의 작동 압력은?",["14 kgf/cm2","16kgf/cm2","24kgf/cm2","26kgf/cm2"],3,0,"ew20150919"],["ew20150919-35",1,"T039","2015-09-19",35,80,"임야화재에 영향을 주는 3대 중요 요소가 아닌 것은?",["기후","지형","가연물","점화원"],4,0,"ew20150919"],["ew20150919-36",1,"T033","2015-09-19",36,78,"방화의 직접적 단서가 될 수 없는 것은?",["도화선(Trailer)","색다른 촉진제","비정상적인 연료하중","출입문의 잠김 상태"],4,0,"ew20150919"],["ew20150919-37",1,"T064","2015-09-19",37,68,"유류성분 감정기구인 가스크로마토그래피 분석의 장점으로 거리가 먼 것은?",["물질이 유사한 여러 성분의 혼합계 분리에 매우 유효하다.","가스 상태로 분석하기 때문에 조작도 간단하고 시간도 빠르다.","각 성분을 검출하여 그 양을 전기적인 신호로 기록계에 저장하고 도형적으로 기록함으로써 분석결과가 객관적이다.","현장조사 시 휴대 및 가스 포집이 간편하며 성분판별이 가능하다."],4,0,"ew20150919"],["ew20150919-38",1,"T057","2015-09-19",38,77,"물질의 상태에 대한 설명으로 옳은 것은?",["물의 증발잠열은 80 cal/g 이다.","액체상태에서 에너지를 제거하면 기체상태가 된다.","온도 변화없이 상태 변화를 위해 필요한 열을 잠열이라 한다.","분자 간의 질소도는 기체 ＞ 액체 ＞ 고체의 순이다."],3,0,"ew20150919"],["ew20150919-39",1,"","2015-09-19",39,73,"측정원리에 의한 분류 중 산업용으로 사용되는 추측식 가스계량기에 해당하는 것은?",["터빈형","드럼(drim)형","회전식(루트식)","막식(다이어프램식)"],1,0,"ew20150919"],["ew20150919-40",1,"T045","2015-09-19",40,84,"일반화재와 구별되어야 하는 차량화재의 특수성에 대한 설명으로 옳지 않은 것은?",["차량은 동력기계계통, 전기전자계통, 연료공급계통, 배기계통 등 기구의 복잡성이 있다.","연료, 시트 등 화재 하중이 낮고, 외기에 개방된 상태인 환기지배형 화재의 특성을 보인다.","다양한 부착물 및 이의 변·개조가 용이하므로, 이러한 구조적 특수성에 의한 화재위험성에 노출되어 있다고 볼 수 있다.","차량은 개방된 공간에 존치되는 특수성에 의해 사회적 불만이나 주차불만을 가진 자가 불특정한 방법으로 방화할 개연성이 높다고 볼 수 있다."],2,0,"ew20150919"],["ew20150919-41",2,"T090","2015-09-19",41,78,"인화점 측정을 위한 장비가 아닌 것은?",["Pensky-Martens","Tag Closed Cup","Cleveland Open Cup","Scanning Electron Microscope"],4,0,"ew20150919"],["ew20150919-42",2,"T082","2015-09-19",42,88,"화재현장 보존을 위한 소방인력의 역할 및 주의사항에 대한 설명으로 옳지 않은 것은?",["잔화 정리하는 동안 남아있는 증거물이 훼손될 수 있으므로 주의하여야 한다.","화재현장에 있는 설비, 기구, 장비 또는 시설의 손잡이를 돌리거나 작동 스위치릴 켜는 것을 자제하여야 한다.","화재현장에서 가솔린이나 디젤 연료로 작동되는 도구 및 설비를 사용하는 것은 자제하는 것이 좋다.","화재현장에 대한 접근은 소방 화재조사관만으로 한정한다."],4,0,"ew20150919"],["ew20150919-43",2,"T072","2015-09-19",43,80,"현장사진촬영의 필요성에 대한 설명 중 옳지 않은 것은?",["기록과 사진, 영상 모두 한계가 있으므로 문제가 해결될 때 까지 현장을 보존하는 것이 가장 중요하다.","사진을 보는 사람이 실제적인 감각으로 느끼게 함으로써 그 때의 상황을 충분히 전달할 수 있는 것이 중요하다.","현장조사 시 실수로 빠트렸거나 수집이 불가능했던 많은 정보와 사실들을 사진을 통해 얻을 수 있다.","화재현장의 소손상황, 감식·감정의 대상이 되는 관계물건 등의 상황을 정확하게 기록하는 수단으로서 사진과 영상이 중요하다."],1,0,"ew20150919"],["ew20150919-44",2,"T079","2015-09-19",44,86,"물적증거의 종류에 해당하는 것은?",["관계가 진술","감정인 소견","유류 용기","증언"],3,0,"ew20150919"],["ew20150919-45",2,"T091","2015-09-19",45,65,"화재열로 파손된 유리의 특징으로 옳은 것은?",["리플마트가 형성된다.","거미줄형태로 파손된다.","방사형 형태로 깨진다.","구불구불한 불규칙한 형태로 깨진다."],4,0,"ew20150919"],["ew20150919-46",2,"T092","2015-09-19",46,78,"전선 중 연선이 절연피복 내에서 일부 단선되어 그 부분에서 단선과 이어짐을 되풀이하는 상태는?",["반단선","트래킹","흑연화","누전"],1,0,"ew20150919"],["ew20150919-47",2,"T093","2015-09-19",47,81,"화상의 중증도를 분류하는 가장 큰 요소는?",["화상의 부위","화열의 강도","피부의 색","화상의 깊이 및 범위"],4,0,"ew20150919"],["ew20150919-48",2,"T075","2015-09-19",48,82,"물리적 증거의 오염 위험이 가장 높은 단계는?",["증거물의 수집","증거물의 운송","증거물의 보존","증거물의 감정"],1,0,"ew20150919"],["ew20150919-49",2,"T094","2015-09-19",49,46,"1기압 25℃에서 연소하한계가 가장 높은 물질은?",["프로판","부탄","메탄","일산화탄소"],4,0,"ew20150919"],["ew20150919-50",2,"T079","2015-09-19",50,87,"화재증거물 수집 시 고려해야 할 사항에 대한 설명으로 옳지 않은 것은?",["물리적 상태(고체, 액체, 기체)를 고려하여 수집","휘발성이 낮은 것에서 높은 순서로 수집","물리적 특성(크기, 모양, 무게 등)을 고려하여 수집","파손성을 감안하여 수집"],2,0,"ew20150919"],["ew20150919-51",2,"T095","2015-09-19",51,67,"증거물의 수집에 관한 고려사항으로 가장 옳은 것은?",["등유와 같은 탄화수소계 액체 위험물은 물과 쉽게 혼합된다.","화재 촉진제로 사용되는 휘발유와 같은 인화성 액체는 상온에서 자연발화하지 않는다.","경유와 같이 흔히 사용되는 화재 촉진제 증기는 공기보다 더 가볍다.","고체 표본을 수집할 때 용기에 3/4 이상 채운다."],2,0,"ew20150919"],["ew20150919-52",2,"T069","2015-09-19",52,84,"화재현장 촬영 시 유의사항이 아닌 것은?",["각 방위별로 출화의 방향성에 착안하여 구조물의 형태를 확인하여 촬영한다.","발화건물과 인접 도로 및 주변 건물과 경계선을 파악하여 촬영한다.","높은 곳에서 전체를 관찰하고 연소 확대 상황을 관찰하여 촬영한다.","너무 많은 사진 자료는 혼란을 야기하므로 사진 촬영은 발화대상물에만 초점을 맞추어 촬영한다."],4,0,"ew20150919"],["ew20150919-53",2,"T071","2015-09-19",53,83,"카메라에서 얇은 금속날개를 이용하여 원하는 크기의 렌즈구경을 만들고 빛의 양을 조절하는 것은?",["플레어","감도","셔터","조리개"],4,0,"ew20150919"],["ew20150919-54",2,"T077","2015-09-19",54,82,"화재증거물수집관리규칙상 수집한 증거물 이송시 포장을 하고 상세정보를 기록할 사항이 아닌 것은?",["수집일시 및 증거물번호","수집장소 및 수집자","증거물 내용 및 봉인자","소유자 및 관리자 성명"],4,0,"ew20150919"],["ew20150919-55",2,"T085","2015-09-19",55,83,"일산화탄소 중독사의 특징으로 볼 수 있는 것은?",["선홍색 시반이 나타난다.","수포주위에 홍반이 생긴다.","코에서 출혈이 심하게 나타난다.","피부의 세포조직이 검게 타는 탄피층이 형성된다."],1,0,"ew20150919"],["ew20150919-56",2,"T078","2015-09-19",56,80,"화재현장의 증거물 시료 채취 시 유의사항이 아닌 것은?",["가급적 증거물 전체를 수집 또는 채취","동일한 물질이 있을 때는 채취하지 않고 내용만 기술","채취된 증거물의 물질이 상이할 때에는 서로 섞이지 않도록 분리하여 채취, 보관","감정의뢰서에 증거물을 수집, 채취한 경과와 사건개요를 기술"],2,0,"ew20150919"],["ew20150919-57",2,"T084","2015-09-19",57,83,"화재조사와 관련한 질문의 원칙으로 옳지 않은 것은?",["질문을 할 때에는 시기, 장소 등을 고려하여 피질문자의 임의진술을 얻도록 하여야 한다.","질문을 할 때에는 기대나 희망하는 진술내용을 얻기 위하여 상대방에게 암시하는 등의 방법으로 임의진술을 하여야 한다.","소문 등에 의한 사항은 그 사실을 직접 경험한 사람의 진술을 얻도록 하여야 한다.","관계자 등에 대한 질문 사항은 질문기록서에 작성하여 그 증거를 확보한다."],2,0,"ew20150919"],["ew20150919-58",2,"T078","2015-09-19",58,67,"증거물 관리에 대한 설명으로 옳은 것은?",["어떠한 종류의 증거물이 발견되거나 조심스럽게 보존되었다면 완벽하게 관리되거나 문서로 기록되지 않더라도 증거로서 가치가 있다.","증거목록의 전달에 있어서 인수자의 서명과 전달일자와 시간만 기록되면 된다.","증거물의 파손을 최소화하기 위해서는 증거물을 취급하는 사람의 수를 최소화해야 한다.","여러 사람이 같은 범죄현장에서 증거를 찾고 있다면 각각 증거기록을 유지하는 것이 바람직하다."],3,0,"ew20150919"],["ew20150919-59",2,"T096","2015-09-19",59,71,"화염과 접촉할 때 연소성이 가장 낮은 것은?",["아크릴","나일론","양모","유리섬유"],4,0,"ew20150919"],["ew20150919-60",2,"T073","2015-09-19",60,79,"현장사진의 범주에 들지 않는 대상은?",["증거물","출동 전 소방차 배치사진","화재현장에서 발견된 물건","화재조사현장과 관련된 사람"],2,0,"ew20150919"],["ew20150919-61",3,"T116","2015-09-19",61,57,"화재피해액 산정과 관련된 용어 정의 중 옳지 않은 것은?",["재구입비는 화재 당시의 피해물과 똑같은 것을 구입하는 데 필요한 금액에 감가상각을 반영한 것을 말한다.","잔가율은 화재 당시에 피해물의 재구입비에 대한 현재가의 비율을 말한다.","내용연수란 고정자산을 경제적으로 사용할 수 있는 연수를 말한다.","연소확대물은 연소가 확대되는데 있어 결정적 영향을 미친 가연물을 말한다."],1,0,"ew20150919"],["ew20150919-62",3,"T118","2015-09-19",62,63,"화재조사 및 보고규정상 구분하는 화재의 유형이 아닌 것은?",["건축·구조물 화재","임야화재","위험물·가스제조소 화재","공장화재"],4,0,"ew20150919"],["ew20150919-63",3,"T119","2015-09-19",63,60,"재고자산 화재피해액의 산정방법 중 가장 처음으로 산정해야 하는 방식은?",["간이평가 방식","회계장부상 현재가액 산정방식","물가정보지 현재가액 산정방식","재구입비, 감가공제 등을 통한 실질적·구체적 방식"],2,0,"ew20150919"],["ew20150919-64",3,"T114","2015-09-19",64,74,"집기비품의 소손 정도에 따른 손해율 30%에 해당하는 것은?",["손해정도가 보통인 경우","손해정도가 다소 심한 경우","오염·수침손의 경우","50%이상 소손되거나, 수침오염 정도가 심한 경우"],1,0,"ew20150919"],["ew20150919-65",3,"T106","2015-09-19",65,72,"화재현장 조사서에서 발화열원의 분류 항목인 것은?",["부주의","전기적 요인","폭발물, 폭죽","가스누출(폭발)"],3,0,"ew20150919"],["ew20150919-66",3,"T103","2015-09-19",66,71,"화재 사후조사에 대한 화재발생종합보고서 작성요령으로 옳은 것은?",["소방대가 출동하지 아니한 화재장소의 화재 증명원 발급요청이 있는 경우 조사관이 주관적으로 판단하여 사후조사를 실시한 후 보고서를 작성한다.","사후조사는 발화장소 및 발화지점 등 현장이 보존되어 있는 경우 조사를 할 수 있다.","사후조사의 경우에도 화재현장 출동보고서를 반드시 작성하여야 한다.","사후조사의 경우 화재발생종합보고서는 화재 조사 및 보고규정의 서식이 아닌 별도의 서식에 의해 작성한다."],2,0,"ew20150919"],["ew20150919-67",3,"T105","2015-09-19",67,79,"화재현장조사서 작성에 대한 설명으로 옳지 않은 것은?",["화재현장조사서의 기재에 있어서 조사자의 주관적 의사나 판단이 개입되도록 표현하는 것은 바람직하지 못하다.","조사서의 작성자가 조사현장에서 도출된 발화원인 등의 결론을 언급한 용어를 사용하는 것은 부적절하다.","형용사를 사용하여 문장을 강조하는 것은 조사서의 객관성 유지에 지장을 줄 수 있다.","입회인의 설명내용과 조사원의 관찰·확인 사실은 구분하지 않고 정리한 뒤 작성한다."],4,0,"ew20150919"],["ew20150919-69",3,"T104","2015-09-19",69,85,"화재조사 및 보고규정상 화재로 인한 재산피해의 범위에 해당하지 않는 것은?",["화재로 인한 영업손실의 피해","연기에 의한 그을음 피해","소화활동으로 발생한 수손 피해","열에 의한 탄화, 용융, 파손 피해"],1,0,"ew20150919"],["ew20150919-70",3,"T108","2015-09-19",70,84,"화재조사 및 보고규정에 따르면 관할구역 내에서 발생한 화재에 대하여 작성해야 하는 서류가 아닌 것은?",["화재발생종합보고서","질문기록서","화재현장 출동보고서","범죄사실 보고서"],4,0,"ew20150919"],["ew20150919-71",3,"T122","2015-09-19",71,68,"시중매매가격에 의해 화재피해액을 산정하는 것이 아닌 것은?",["차량의 전부손해","귀금속의 전부손해","식물의 전부손해","동물의 전부손해"],2,0,"ew20150919"],["ew20150919-72",3,"T115","2015-09-19",72,71,"화재 등으로 인한 피해액 산정에 있어 최종잔가율 20%를 적용할 수 없는 것은?",["건물","부대설비","비품","가재도구"],3,0,"ew20150919"],["ew20150919-73",3,"T123","2015-09-19",73,50,"영업시설의 피해액 산정 시에 개·보수한 때를 기준으로 경과연수를 산정하는 것은 재설치비의 몇 % 이상 개·보수한 경우인가?",["50","60","70","80"],4,0,"ew20150919"],["ew20150919-74",3,"T120","2015-09-19",74,78,"화재조사 서류작성 및 보고요령으로 옳지 않은 것은?",["화재보고는 최초보고, 중간보고, 최종보고로 구분한다.","최종보고는 화재종류 후 최초보고, 중간보고를 취합하여 보고한다.","최초보고는 선착대가 현장도착 즉시 현장지휘관 책임하에 화재규모, 인명피해 발생여부, 건물구조 개요, 정확한 재산피해 내역을 보고하여야 한다.","중간보고는 최초보고 후 화재상황 진전에 따라 연소확대 여부, 인명구조 및 진압활동 상황, 화재원인 및 재산피해 등을 수시로 보고한다."],3,0,"ew20150919"],["ew20150919-75",3,"T111","2015-09-19",75,46,"화재현황조사서에 기입해야 할 항목이 아닌 것은?",["화재발생 일시 및 장소","기상상황","인명피해 및 재산피해","소방시설 현황"],4,0,"ew20150919"],["ew20150919-76",3,"T115","2015-09-19",76,73,"최종잔가율에 대한 설명으로 옳은 것은?",["고정자산을 경제적으로 사용할 수 있는 비율을 말한다.","화재 당시에 피해물의 재구입비에 대한 현재가의 비율을 말한다.","피해물의 종류, 손상상태 및 정도에 따라 피해액을 적정화시키는 비율을 말한다.","피해물의 경제적 내용연수가 다한 경우 잔존하는 가치의 재구입비에 대한 비율을 말한다."],4,0,"ew20150919"],["ew20150919-78",3,"T112","2015-09-19",78,74,"화재조사를 화재원인조사와 화재피해조사로 구분할 때 화재원인조사 범위에 해당하는 것은?",["화재진압 중 발생한 사망자 및 부상자","소화활동으로 발생한 수손","피난경로, 피난상의 장애요인","화재로 인한 사망자 및 부상자"],3,0,"ew20150919"],["ew20150919-79",3,"T113","2015-09-19",79,79,"건물의 화재피해약 산정기준 공식으로 옳은 것은?",["신축단가(m2당) × 소실면적 × [1 - (0.6 × 경과년수 / 내용년수)] × 손해율","신축단가(m2당) × 소실면적 × [1 - (0.7 × 경과년수 / 내용년수)] × 손해율","신축단가(m2당) × 소실면적 × [1 - (0.8 × 경과년수 / 내용년수)] × 손해율","신축단가(m2당) × 소실면적 × [1 - (0.9 × 경과년수 / 내용년수)] × 손해율"],3,0,"ew20150919"],["ew20150919-80",3,"T106","2015-09-19",80,64,"발화원인의 판정방법 중 소거법에 가장 가까운 것은?",["분석·측정기기 등에 의한 데이터의 제시","재현실험에 의한 재현성의 확보","유사화재 사례의 유무 확인","화원 각각에 대하여 발화원으로서 가능성 검토"],4,0,"ew20150919"],["ew20150919-81",4,"T149","2015-09-19",81,59,"신체손해배상 특약부 화재보험의 설명으로 틀린 것은?",["발가락을 잃은 것이란 발가락 말단의 2분의 1이상을 잃은 경우를 말한다.","흉타거 남은 것이란 성형수술을 하였어도 육안으로 식별이 가능한 흔적이 있는 상태를 말한다.","항상 보호를 받아야 하는 것은 일상생활에서 기본적인 음식섭취, 배뇨 등을 타인에게 의존해야 하는 것을 말한다.","수시로 보호를 받아야 하는 것은 일상생활에서 기본적인 음식섭취, 배뇨 등은 가능하나 그 외의 일은 타인에게 의존해야 하는 것을 말한다."],1,1,"ew20150919"],["ew20150919-82",4,"T142","2015-09-19",82,79,"화재조사 및 보고규정에서 정하는 화재의 정의에 포함되지 않는 내용은?",["사람의 의도에 반하여 발생한 화재로 소화할 필요가 있는 연소현상","사람의 고의에 의하여 발생한 화재로 소화할 필요가 있는 연소현상","소화시설 등을 사용하여 소화할 필요가 있는 연소현상","압력을 동반한 물리적 폭발현상"],4,1,"ew20150919"],["ew20150919-83",4,"T135","2015-09-19",83,74,"운행중인 차량, 선박 및 항공기에서 발생한 화재의 조사책임은?",["화재신고를 초최 접수한 소방본부장 또는 소방서장","소화활동을 행한 소방본부장 또는 소방서장","차량, 선박 및 항공기 등록지를 관할하는 소방본부장 또는 소방서장","소화활동을 행한 장소를 관할하는 소방본부장 또는 소방서장"],4,1,"ew20150919"],["ew20150919-84",4,"T145","2015-09-19",84,74,"제조물 책임법상의 피해자가 손해 및 손해배상책임을 지는 자를 알게 된 날부터 손해배상 청구권은 몇 년간 행사하지 않으면 소멸하는가?",["10년","5년","3년","1년"],3,0,"ew20150919"],["ew20150919-85",4,"","2015-09-19",85,81,"보일러, 고압가스 기타 폭발성 있는 물건을 파열시켜 사람의 생명, 신체 또는 재산에 대하여 위험을 발생시키는 범죄명은?",["폭발성물건파열죄","방화죄","파열죄","신체상해죄"],1,1,"ew20150919"],["ew20150919-86",4,"T138","2015-09-19",86,85,"소방법령에서 정하고 있는 화재조사에 대한 내용으로 옳지 않은 것은?",["소방서장은 화재조사 원인 및 피해 등에 대한 조사를 하여야 한다.","수사기관이 증거물을 압수한 때에는 소방서장은 그 증거물에 대한 조사가 불가능하다.","소방서장은 화재조사에 필요한 경우, 관계인에 대하여 자료제출을 명할 수 있다.","화재조사를 하는 소방공무원이 관계인의 정당한 업무를 방해한 경우, 벌금에 처한다."],2,1,"ew20150919"],["ew20150919-87",4,"T151","2015-09-19",87,80,"한국화재보험협회에서 보험계약을 체결할 때 실시하는 특수건물의 안전점검 내용으로 옳은 것은?",["안전점검이 필요하다고 인정될 때 관계인의 승낙 없이도 검사를 실시할 수 있다.","협회는 안전점검을 실시하고자 할 때에는 24시간 전에 관계인에게 통지하여야 한다.","안전점검을 실시하는 자는 안전점검을 함에 있어서 관계인의 업무를 방해하거나 지득한 비밀을 누설하여서는 아니 된다.","안전점검은 관계인의 업무를 방해하지 않도록 일출전 또는 일몰후에 실시하여야 한다."],3,1,"ew20150919"],["ew20150919-88",4,"","2015-09-19",88,51,"소방기본법상 소방자동차가 화재진압 및 구조·구급 활동을 위하여 출동하는 때에 이를 방해하는 자에 대한 벌칙은?",["5년이하의 징역 또는 5천만원 이하의 벌금","5년이상의 징역 또는 5천만원 이하의 벌금","3년이하의 징역 또는 1천500만원 이하의 벌금","2년이하의 징역 또는 1천만원 이하의 벌금"],1,1,"ew20150919"],["ew20150919-89",4,"T149","2015-09-19",89,42,"신체손해배상특약부 화재보험과 관련한 후유장해의 설명으로 틀린 것은?",["신체장해가 2 이상 있을 경우에는 중한 신체장해에 해당하는 장해등급으로 한다.","시력의 측정은 국제식 시력표에 의하며, 굴절이상이 있는 사람에 대하여는 원칙적으로 교정시력을 측정한다.","손가락을 잃은 것이란 엄지손가락에 있어서는 지관절, 기타의 손가락에 있어서는 제1관절 이상을 잃은 경우를 말한다.","손가락을 제대로 못 쓰게 된 것이란 손가락의 말단의 2분의 1 이상을 잃거나, 중수지관절 또는 제1지관절에 뚜렷한 운동장해가 남은 경우를 말한다."],1,1,"ew20150919"],["ew20150919-90",4,"T154","2015-09-19",90,72,"화재 시 소화기를 사용 못 하도록 하거나 옥내소화전을 파괴하는 등의 행동을 했다면 형법에 의하여 어떤 처벌을 받을 수 있는가?",["10년 이하의 징역","7년 이하의 징역","3년 이하의 금고","1천 5백만원 이하의 벌금"],1,1,"ew20150919"],["ew20150919-91",4,"T149","2015-09-19",91,45,"특수건물에서 발생한 화재로 부상자가 발생한 경우 상해부위를 상해급별로 구분하였을 때 9급에 해당하는 것은?",["상박골경부골절","대퇴골간부골절","수근주상골골절","요골골두골골절"],4,0,"ew20150919"],["ew20150919-92",4,"T144","2015-09-19",92,81,"소방법령상 화재피해조사의 조사범위로 가장 거리가 먼 것은?",["소화활동 중 사용된 물로 인한 피해","소방활동 중 발생한 사망자 및 부상자","연기, 물품반출, 화재로 인한 폭발 등에 의한 피해","소화활동으로 발생한 영업 손실 피해"],4,1,"ew20150919"],["ew20150919-93",4,"T155","2015-09-19",93,53,"업무상과실 또는 중대한 과실로 인하여 실화의 죄를 범한 자에 대한 벌칙은?",["3년 이하의 금고 또는 1천5백만원 이하의 벌금","3년 이하의 금고 또는 2천만원 이하의 벌금","2년 이하의 징역 또는 1천5백만원 이하의 벌금","2년 이하의 징역 또는 2천만원 이하의 벌금"],2,1,"ew20150919"],["ew20150919-94",4,"T157","2015-09-19",94,78,"화재증거물수집관리규칙상 화재현장 증거물은 화재증거 수집의 목적달성 후에는 어떻게 하여야 하는가?",["3년까지 보존하여야 한다.","10년까지 보존하여야 한다.","관계인에게 반환하여야 한다.","즉시 폐기하여야 한다."],3,0,"ew20150919"],["ew20150919-95",4,"T151","2015-09-19",95,47,"화재로 인한 재해보상과 보험가입에 관한 법률에 따르면 화재보험협회가 보험계획을 체결할 때 또는 보험계약을 갱신할 때마다 해당특수건물의 화재예방 및 소화시설의 안전점검을 실시하고 그 결과를 며칠 이내에 소방관서의 장에게 통지하여야 하는가?",["즉시","10일","20일","30일"],2,1,"ew20150919"],["ew20150919-96",4,"T152","2015-09-19",96,64,"현주건조물 등에의 방화한 사람에게 가하는 벌칙으로 옳지 않은 것은?",["사람을 상해에 이르게 한 때에는 무기 또는 5년 이상의 징역","사람을 사망에 이르게 한 때에는 사형, 무기 또는 7년 이상의 징역","사람이 주거로 사용하거나 사람이 현존하는 건조물, 기차, 전차, 자동차, 선박, 항공기 또는 광갱을 소훼한 자는 무기 또는 3년 이상의 징역","자기 소유에 속한 물건을 소훼한 때에는 5년 이하의 징역"],4,1,"ew20150919"],["ew20150919-97",4,"T146","2015-09-19",97,72,"제조물 책임법상 제조상의 결함에 해당되는 것은?",["제조사가 합리적인 대체설계를 채용하였더라면 피해나 위험을 줄이거나 피할 수 있었음에도 대체설계를 채용하지 아니하여 당해 제조물이 안전하지 못한 경우","제조업자의 제조물에 대한 제조·가공상의 주의의무의 이행여부와 관계없이 제조물이 원래 의도한 설계와 다르게 제조·가공됨으로써 안전하지 못한 경우","제조업자가 합리적인 설명·지시·경고 기타의 표시를 하였더라면 당해 제조물에 의하여 발생될 수 있는 피해나 위험을 줄이거나 피하 수 있었음에도 이를 하지 않은 경우","제조업자가 물류·유통과정에서 발생할 수 있는 위험을 인지하지 못하여 제조물의 파손을 초래한 경우"],2,0,"ew20150919"],["ew20150919-98",4,"T153","2015-09-19",98,45,"형법성 공용건조믈 등에의 방화죄에 대한 벌칙은?",["무기 또는 3년 이상의 징역","무기 또는 3년 이하의 징역","10년 이상의 징역","1년 이상의 징역"],1,1,"ew20150919"],["ew20150919-99",4,"T158","2015-09-19",99,68,"화재를 유형에 따라 구분한 것으로 잘못된 것은?",["피견인차량이 소손된 경우, 자동차·철도차량 화재에 해당된다.","구조물 안에 있는 물건이 소손된 경우, 건축·구조물 화재에 해당된다.","경작물이 소손된 경우, 기타화재에 해당된다.","들판의 수목이 소손된 경우, 임야화재에 해당된다."],3,1,"ew20150919"],["ew20150919-100",4,"T159","2015-09-19",100,78,"화재조사 및 보고규정에서 정하는 건물의 동수산정에 대한 설명으로 옳지 않은 것은?",["주요구조부가 하나로 연결되어 있는 것은 1동으로 한다.","건물의 외벽을 이용하여 실을 만들어 작업실로 사용하고 있는 것은 주건물과 1동으로 본다.","구조에 관계없이 지붕 및 실이 하나로 연결되어 있는 것은 별동으로 본다.","목조건물의 경우 격벽으로 방화구획이 되어 있는 경우 동일동으로 한다."],3,1,"ew20150919"],["ew20170923-1",0,"T009","2017-09-23",1,72,"증기운 형성물질 중 비점이상의 온도지만 가압하여 액화된 물질로 열전달 및 확산이 증발을 제한하는 특징을 갖는 물질은?",["액화암모니아","벤젠","액화천연가스","액화석유가스"],2,0,"ew20170923"],["ew20170923-2",0,"T006","2017-09-23",2,88,"동일한 거리에서 복사열에 노출되었을 때 물질의 열전도성이 가장 좋은 물질은?",["참무나 판자","구리","포리스티렌 판","석고보드"],2,0,"ew20170923"],["ew20170923-3",0,"T002","2017-09-23",3,54,"고체가연물 중 표면연소의 형태를 갖는 물질은?",["금속분","목재","양초","니토로셀룰로오스"],1,0,"ew20170923"],["ew20170923-4",0,"T011","2017-09-23",4,83,"점화원에 대한 설명으로 옳은 것은?",["온도가 높을수록 최소점화에너지는 높아진다.","혼합된 공기의 산소농도에 관계없이 최소 착화에너지는 변하지 않는다.","압력이 높을수록 최소 착화에너지는 높아진다.","연소범위 내에 있는 가연성 가스는 정전기 등의 약한 에너지로도 점화될 수 있다."],4,0,"ew20170923"],["ew20170923-5",0,"T024","2017-09-23",5,87,"화염의 색이 백적색일 때 불꽃의 온도는?",["약 350℃","약 800℃","약 1300℃","약 1500℃"],3,0,"ew20170923"],["ew20170923-6",0,"T005","2017-09-23",6,52,"고분자물질과 융점의 연결이 틀린 것은?",["폴리에틸렌 – 약 220℃","폴리프로필렌 – 약 214℃","폴리카보네이트 – 약 175℃","폴리우레탄 – 약 155℃"],3,0,"ew20170923"],["ew20170923-7",0,"T012","2017-09-23",7,89,"화재조사의 책임과 권한에 대한 설명으로 옳은 것은?",["소방서장은 관계보험사가 그 화재원인과 피해상황을 조사하고자 할때에는 이를 허용해서는 안된다.","소방서장은 화재의 원인 및 피해 등에 대한 조사를 소화활동 후에 실시하여야 한다.","과실로 인한 위법행위로 타인에게 손해를 가한 자는 그 손해를 배상할 책임이 없다.","소방서장은 화재조사를 위하여 필요한 경우에는 수사에 지장을 주지 아니하는 범위에서 그 피의자 또는 압수된 증거물에 대한 조사를 할 수 있다."],4,0,"ew20170923"],["ew20170923-8",0,"T020","2017-09-23",8,87,"가연물별 분류에 따른 화재와 색상이 옳은 것은?",["일반화재 - 황색","유류화재 - 백색","전기화재 - 빨간색","금속화재 – 무색"],4,0,"ew20170923"],["ew20170923-9",0,"T001","2017-09-23",9,56,"삼각형(△) 패턴에 대한 설명으로 틀린 것은?",["삼각형 패턴은 유류가 사용된 곳에서 연소가 끝난 바닥면에 나타난다.","삼각형 패턴은 연소가 짧은 시간에 이루어질 때 수직벽면에 나타난다.","삼각형 패턴은 바닥에서 천장까지 완전히 전개되지 않는 화재에 나타난다.","삼각형 패턴은 불기둥을 수직적으로 차단하지 않을 경우에 나타난다."],1,0,"ew20170923"],["ew20170923-10",0,"T010","2017-09-23",10,83,"발화점이 약 34℃로 매우 낮아 공기 중에 노출되면 자연발화를 일으키므로 이를 방지하기 위하여 물속에 저장하여야 하는 위험물은?",["유황","리튬","황린","나트륨"],3,0,"ew20170923"],["ew20170923-11",0,"T013","2017-09-23",11,67,"소방기본법령상 소방본부(거점소방서 포함) 화재조사전담부서에서 갖추어야 할 화재조사 장비 및 시설 중 발굴용구가 아닌 것은?",["접자","니퍼","뜰채","양동이"],1,0,"ew20170923"],["ew20170923-12",0,"T019","2017-09-23",12,58,"감광계수(m-1)에 따른 가시거리가 틀린 것은?",["감광계수 0.1 – 가시거리 20~30m","감광계수 0.3 – 가시거리 5m","감광계수 0.5 – 가시거리 1~2m","감광계수 10 – 가시거리 0.2~0.5m"],3,0,"ew20170923"],["ew20170923-13",0,"T003","2017-09-23",13,46,"다음 목재의 표면에 나타나는 특징에 따른 균열혼으로 옳은 것은?",["완소흔","강소흔","박리흔","열소흔"],4,0,"ew20170923"],["ew20170923-14",0,"T009","2017-09-23",14,80,"끓는점 이상의 온도이지만 압력에 의해 액체 상태를 유지하고 있는 물질이 탱크의 균열이나 파열에 의해 외부로 누출되면서 급격히 기화되어 압력을 발생시키는 폭발현상은?",["보일오버(Boil Over)","비등액체패창증기폭발(BLEVE)","증기운폭발(UVCE)","급격한 상변화에 의한 폭발(ERPT)"],2,0,"ew20170923"],["ew20170923-15",0,"","2017-09-23",15,83,"여러 동의 인접한 건물이 소손되어 있는 화재현상에서 발화건물 판정을 위한 일반적인 조사요령에 관한 설명 중 틀린 것은?",["화재현장 전체의 연소방향은 가급적 낮은 쪽에서 높은 쪽을 바라보며 파악한다.","각 건물의 연소방햐은 타다 멈춘 부분 또는 연소강약이 명확한 부분부터 파악한다.","타서 허물어진 부분을 보고 연소방향을 추정할 수 있다.","복수의 건물이 소손되어 있으면 인접동 간격, 외벽구조, 개구부상황 등으로부터 연소상황을 파악한다."],1,0,"ew20170923"],["ew20170923-16",0,"T026","2017-09-23",16,59,"물과 접촉 시 가연성 기체를 발생하지 않고 발열반응으로 인하여 주변의 가연물을 발화시키는 물질은?",["산화칼슘","인화알루미늄","탄화칼슘","칼륨"],1,0,"ew20170923"],["ew20170923-17",0,"T017","2017-09-23",17,68,"화학화재 발생 시 조사자가 행하여할 절차 중 옳은 것은?",["가치부여 → 자료의 수집 → 체계부여 → 타당성을 밝힘 → 화재원인의 결정","자료의 수집 → 가치부여 → 체계부여 → 타당성을 밝힘 → 화재원인의 결정","자료의 수집 → 체계부여 → 가치부여 → 타당성을 밝힘 → 화재원인의 결정","자료의 수집 → 가치부여 → 타당성을 밝힘 → 체계부여 → 화재원인의 결정"],2,0,"ew20170923"],["ew20170923-18",0,"T004","2017-09-23",18,43,"유리의 파단면 분석에 대한 설명으로 옳은 것은?",["충격에 의한 파괴유리의 충격방향을 확인하기 위해서는 동심원파단면의 월러라인(Wallnet Line)을 확인하는 것이 효과적이다.","여러 종류의 외력이 혼합되어 순차적으로 유리가 파괴되었을 때에 모두 쏟아졌다고 하여도 외력의 순서를 알 수 있다.","화재와 폭발 이벤트가 함께 이루어진 현장의 유리파편에서 현장으로 멀리 비산된 유리에 그을음이 부착되어 있다면 화재이전 폭발이 발생하였다고 추정할 수 있다.","강화유리의 자발파괴(Spontaneous Breakage)형태는 쌍을 이루는 8각형의 파편이 발견된다."],2,0,"ew20170923"],["ew20170923-19",0,"T026","2017-09-23",19,54,"탄화알루미늄이 상온에서 물과 반응할 경우 생성되는 가연성 기체는?",["수소","아세틸렌","메탄","프로판"],3,0,"ew20170923"],["ew20170923-20",0,"T015","2017-09-23",20,87,"방화의 식별에 따른 일반적인 방화의 가능성이 있는 경우가 아닌 것은?",["화재가 건물의 구조, 가연물 등에 비해 급격히 확산된 경우","최초 발화지점에서 유류 등 연료물질을 사용한 흔적이 있는 경우","출입문, 창 등에 강제로 진입한 흔적이 있는 경우","연소기구를 중심으로 연소 확대가 진행된 흔적이 있는 경우"],4,0,"ew20170923"],["ew20170923-22",1,"T054","2017-09-23",22,70,"연소한계에 대한 설명 중 옳은 것은?",["연소하한계는 저온에서는 약간 증가하나 고온에서는 일정하다.","연소한계는 온도와 관계없이 일정하다.","연소상한계는 온도의 증가와 함께 증가한다.","연소하한계는 온도의 증가와 함께 증가한다."],3,0,"ew20170923"],["ew20170923-23",1,"T053","2017-09-23",23,72,"분해열의 축적으로 자연발화를 일으키는 물질이 아닌 것은?",["폴리에스테르","셀룰로이드","니트로글리세린","니트로셀룰로오스"],1,0,"ew20170923"],["ew20170923-24",1,"T050","2017-09-23",24,77,"서로 밀착되어 있는 물체가 떨어지거나 벗겨져 떨어질 때 전하분리가 일어나 정전기가 발생하는 현상은?",["박리대전","유동대전","마찰대전","분출대전"],1,0,"ew20170923"],["ew20170923-25",1,"T055","2017-09-23",25,62,"분진폭발을 일으킬 가능성이 없는 것은?",["목분","마그네슘 분말","폴리에틸렌 분말","산화규소 분말"],4,0,"ew20170923"],["ew20170923-26",1,"T037","2017-09-23",26,74,"선박용 축전지의 보관방법으로 틀린 것은?",["축전지 상자는 다른 전기설비와 격리한다.","축전지실은 화기로부터 격리한다.","발전기에 의해 충전되는 축전지에는 역류방지장치를 설치한다.","축전지 및 축전지 상자는 대기와 차단한다."],4,0,"ew20170923"],["ew20170923-27",1,"T040","2017-09-23",27,67,"임야화재 시 수관화의 특징으로 옳은 것은?",["중심부의 화염온도는 2000℃ 이다.","주변의 연기온도는 1000℃이다.","바람이 강할 때 연소속도는 10 km/h 이다.","임야화재 연소 중에 수십 m의 상승기류가 발생한다."],4,0,"ew20170923"],["ew20170923-28",1,"T054","2017-09-23",28,64,"다음 중 황의 산화수가 가장 큰 것은?",["S8","H2SO4","SO32-","Na2S2O3"],2,0,"ew20170923"],["ew20170923-29",1,"T033","2017-09-23",29,85,"방화로 의심할 수 있는 경우가 아닌 것은?",["출입문이 잠겨 있는 경우","촉진제의 용기가 발견된 경우","외부침입 흔적이 발견된 경우","다른 범죄의 증거가 발견된 경우"],1,0,"ew20170923"],["ew20170923-30",1,"T041","2017-09-23",30,81,"산불의 강도를 가중시키는 조건으로 틀린 것은?",["연료온도를 증가시키는 사면","가파른 경사","굴뚝지형","평지"],4,0,"ew20170923"],["ew20170923-31",1,"T051","2017-09-23",31,62,"유염연소와 무염연소를 비교하였을 때 특징으로 틀린 것은?",["목재의 무염연소 시 가연물의 내부보다는 표면으로 전파되는 속도가 빠르다.","무염연소는 고체가연물에서만 가능하며 유염연소는 고체, 액체, 기체에서 모두 가능하다.","무염연소는 연소반응속도가 느리다.","무염연소는 발열량이 적고, 유염연소는 발열량이 크다."],1,0,"ew20170923"],["ew20170923-32",1,"T035","2017-09-23",32,63,"항공기 보조동력장치(APU)의 소화용기(container) 내용물이 과도한 열로 인하여 외부로 배출 시 나타나는 반응으로 옳은 것은?",["온도방출지시기(thermal discharge indicator)의 Red Disk가 없다.","온도방출지시기(thermal discharge indicator)의 Yellow Disk가 없다.","배출밸브(discharge valve)가 열린다.","조종실에 경고등이 들어온다."],1,0,"ew20170923"],["ew20170923-33",1,"T055","2017-09-23",33,74,"산화에틸렌 90%와 메탄 10%가 혼합되어 있는 경우 폭발하한계로 옳은 것은? (단, 메탄의 연소범위는 5~15 vol.%, 산화에틸렌의 연소범위는 3~80 vol.%이다.)",["1.79 vol.%","3.13 vol.%","32 vol.%","55.81 vol.%"],2,0,"ew20170923"],["ew20170923-34",1,"T045","2017-09-23",34,81,"자동차화재의 특성에 대한 설명으로 옳은 것은?",["차량화재는 연료, 시트 등 화재하중이 낮고, 외기와 밀폐된 상태인 환기 지배형의 화재특성을 보인다.","차량화재의 조사는 특별한 전문지식이 없어도 화재조사가 가능하다.","차량화재는 대체로 전소가 되지 않기 때문에 발화지점 및 발화원인의 조사가 용이하다.","개방된 공간에 존치되는 환경적인 특수성으로 인해 사회적인 불만을 가진자 등이 불특정한 방법으로 방화를 할 수 있다."],4,0,"ew20170923"],["ew20170923-35",1,"T048","2017-09-23",35,55,"전기세탁기 화재가 발생하였을 때 전기화재의 조사 요점으로 틀린 것은?",["잡음 방지 콘덴서의 절연열화 상태","마그네트론의 열화","배수 전자 밸브의 이상","세탁기 내부 배선간의 단락 여부"],2,0,"ew20170923"],["ew20170923-36",1,"T061","2017-09-23",36,58,"하나의 전제에서 결론이 도출되는 직접추리와 2개 이상의 전제에서 결론이 나타나는 간접추리로 나누는 추론 방법은?",["귀납적 추론","연역적 추론","실용적 추론","형식적 추론"],2,0,"ew20170923"],["ew20170923-37",1,"T045","2017-09-23",37,45,"차량의 동력전달장치 순서가 옳은 것은?",["기관 → 클러치 → 변속기 → 종 감속장치 및 차동기어장치 → 추진축(앞 기관 뒷바퀴 구동의 경우) → 차축 → 구동바퀴","기관 → 변속기 → 클러치 → 종 감속장치 및 차동기어장치 → 추진축(앞 기관 뒷바퀴 구동의 경우) → 차축 → 구동바퀴","기관 → 클러치 → 변속기 → 추진축(앞 기관 뒷바퀴 구동의 경우) → 차축 → 종 감속장치 및 차동기어장치 → 구동바퀴","기관 → 클러치 → 변속기 → 추진축(앞 기관 뒷바퀴 구동의 경우) → 종 감속장치 및 차동기어장치 → 차축 → 구동바퀴"],4,0,"ew20170923"],["ew20170923-38",1,"","2017-09-23",38,86,"화학물질의 혼합발화와 관련하여 감식요령으로 틀린 것은?",["물질의 성질, 취급의 상황, 장송의 환경조건에 대하여 조사한다.","혼합 물질의 재현실험은 실시하지만 단독 물질의 발화 여부 실험은 하지 않는다.","화재가 난 곳에서 존재하는 물질에 대하여 성분, 성질, 형상, 양을 관계자와 진술과 문헌·자료 등을 기초로 조사한다.","혼합발화에 의한 화재는 혼합한 물질 자체가 연소하므로 증거가 소실되는 경우가 많다."],2,0,"ew20170923"],["ew20170923-39",1,"T060","2017-09-23",39,68,"양초의 성상과 연소특징에 대한 설명으로 틀린 것은?",["가솔린, 벤젠 등에 녹는다.","물과 친화성이 없고 전기절연성이 우수하다.","휘발성이 강하고 착화가 어려우며, 유해가스를 발생시키지 않고 연소한다.","양초의 연소는 증발연소이며, 심지 없이 양초 자체만으로는 연소가 지속되지 않는다."],3,0,"ew20170923"],["ew20170923-40",1,"","2017-09-23",40,82,"발화원에 대한 설명으로 틀린 것은?",["가연물의 발화온도에 이르는 높은 에너지를 가지고 있다.","대체로 발화지점이나 그 근처에 존재할 수 있다.","변경되거나 파괴되지 않은 상태로 존재한다.","발화원인을 증명하기 위해 확인되어야 한다."],3,0,"ew20170923"],["ew20170923-41",2,"T079","2017-09-23",41,83,"화재현장에서 증거물 채취의 일반적인 절차로 옳은 것은?",["채취 과정의 입증조치는 입회인만 있으면 된다.","화재현장은 어둡고 확인이 되지 않으므로 무조건 많은 증거물을 채취한다.","증거물의 발견장소는 중요하지 않으므로 관계자 진술로 대처한다.","수집증거의 발견 장소 및 그 상태를 명확하게 해놓아야 한다."],4,0,"ew20170923"],["ew20170923-42",2,"T093","2017-09-23",42,75,"뜨거운 물에 접촉하여 새기는 화상을 무엇이라 하는가?",["접촉화상","열탕화상","화학하상","화염화상"],2,0,"ew20170923"],["ew20170923-44",2,"T084","2017-09-23",44,84,"화재조사와 관련하여 관계자에게 질문 시 유의사항으로 틀린 것은?",["질문내용을 사전에 준비한다.","희망하는 진술내용을 얻기 위하여 먼저 신분을 밝히지 않는 것이 좋다.","희망하는 진술내용을 얻기 위하여 상대방에게 암시하는 등의 방법으로 유도하여서는 안 된다.","소문 등에 의한 사항은 그 사실을 직접 경험한 사람의 진술을 얻도록 하여야 한다."],2,0,"ew20170923"],["ew20170923-45",2,"T085","2017-09-23",45,71,"화재피해자의 CO-Hb 농도로 추정할 수 있는 것은?",["화재 피해자의 화재 시 생존 여부","화재 피해자의 음주여부","화재 피해자의 연령대","화재 피해자의 사망시간"],1,0,"ew20170923"],["ew20170923-46",2,"T093","2017-09-23",46,58,"외부에서 열이 가해지면 열에 의한 손상의 범위를 결정하는 사항이 아닌 것은?",["가연물의 양","가해진 온도","열이 가해진 시간","과다한 열을 배출하는 체표면의 능력"],1,0,"ew20170923"],["ew20170923-47",2,"T075","2017-09-23",47,83,"물적증거를 오염으로부터 방지할 수 있는 방법으로 틀린 것은?",["평소 증거용기를 오염되지 않도록 관리한다.","증거수집용기는 현장에서 증거를 수집한 후 즉시 밀폐한다.","증거물 보관용기를 수집기구로 쓰는 것은 오염을 증가시킬 수 있으므로 되도록 하지 않는다.","수집용기의 오염원을 제한하기 위해 제조업자로부터 공급받은 즉시 용기를 밀봉하는 방법도 있다."],3,0,"ew20170923"],["ew20170923-48",2,"T096","2017-09-23",48,61,"플라스틱 증거물에 관한 설명으로 옳은 것은?",["탄화수소계의 기본적인 고체 가연물인 플라스틱의 약 90%는 열경화성이다.","PVC와 같은 열경화성 물질은 가열되면 용융, 변형, 그리고 드롭다운 패턴이 형성된다.","폴리우레탄 같은 열가소성 물질은 탄화물질을 형성하지 않는다.","열가소성 물질은 용해되고 흘러서 2차 화재의 원인이 된다."],4,0,"ew20170923"],["ew20170923-49",2,"T074","2017-09-23",49,44,"증거물 수집용기 중 모양과 크기가 다양하고 보관이 편리하며 휘발서 액체의 오염 방지의 장점을 가진 것은?",["금속 캔","유리병","특수증거물 봉투","일반 플라스틱 용기"],3,0,"ew20170923"],["ew20170923-50",2,"T091","2017-09-23",50,72,"화재현장에 있는 벽면이나 철판 등에 발생하는 백화현상에 대한 설명으로 옳은 것은?",["한번 부착된 그을음은 없어지지 않는다.","그을음이 부착되었다가 열에 의해 연소한 흔적이다.","열에 의해 가열되었다가 급속히 냉각된 흔적이다.","훈소로 발생한 가연성 증기가 응축하면서 부착된 흔적이다."],2,0,"ew20170923"],["ew20170923-51",2,"T076","2017-09-23",51,86,"화재 증거물의 수송으로 권장할 만한 가장 적절한 방법인 것은?",["화물로의 배송","직접운반","제3자 전달","우편배송"],2,0,"ew20170923"],["ew20170923-52",2,"T087","2017-09-23",52,82,"시반에 관한 설명으로 옳은 것은?",["시반은 사망 시간을 나타내는 지표로 사용된다.","시반은 시신의 사망 전 이동 여부를 나타낸다.","시반은 3~4시간 후에 더 이상 진행되지 않는다.","시반은 우리 몸의 가장 높은 신체부위에 발생한다."],1,0,"ew20170923"],["ew20170923-53",2,"T069","2017-09-23",53,86,"화재현장 촬영기법에 대한 설명으로 틀린 것은?",["인근의 높은 건물에 올라가서 화재현장 전체를 촬영한다.","원거리, 중거리, 근거리의 순으로 화재현장을 촬영한다.","한 장에 다 들어가지 않으면 연결(파노라마)사진으로 촬영한다.","발화지점 위주로만 촬영한다."],4,0,"ew20170923"],["ew20170923-54",2,"T074","2017-09-23",54,60,"인화성 액체를 유리병 용기에 수집하는 경우 주의사항으로 옳은 것은?",["인화성액체를 깨끗이 정제한 후 수집할 것","유리병 뚜껑은 접착제나 고무봉인이 없을 것","유리병 내용적의 1/3 이상을 채우지 않을 것","장기간 보관 용기로 사용하지 말 것"],2,0,"ew20170923"],["ew20170923-55",2,"T071","2017-09-23",55,76,"피사계 심도를 깊게 하기 위한 방법으로 옳은 것은?",["조리개를 좁힌다.","조리개를 넓힌다.","셔터 스피드를 길게 한다.","셔터 스피드를 짧게 한다."],1,0,"ew20170923"],["ew20170923-56",2,"T091","2017-09-23",56,73,"가연성 액체가 살포된 수평재에서 발견되는 패턴이 아닌 것은?",["포어 패턴","도넛 패턴","V 패턴","스플래쉬 패턴"],3,0,"ew20170923"],["ew20170923-57",2,"T090","2017-09-23",57,66,"밀도가 낮고 인화점이 93℃ 미만인 액체의 인화점을 테스트하는 방법은?",["Tag Closed Tester","Cleveland Open Cup","Tag Open Cup Apparatus","Pensky-Martens Closed Tester"],1,0,"ew20170923"],["ew20170923-58",2,"T094","2017-09-23",58,75,"연소범위에 영향을 미치는 요인에 대한 설명으로 틀린 것은?",["압력이 높아지면 하한값은 크게 변하지 않으나 상한값은 높아진다.","고온·고압의 경우 연소범위는 더욱 넓어진다.","혼합기를 이루는 공기의 산소농도가 높을수록 연소범위는 넓어진다.","온도가 높아질수록 연소범위는 좁아진다."],4,0,"ew20170923"],["ew20170923-59",2,"T097","2017-09-23",59,49,"화재사의 소견이 아닌 것은?",["투사형자세가 되었다.","매가 기도내에 부착되었다.","십이지장내에서 매가 발견되었다.","상기도의 점막에서 충혈, 종창 등 열에 의한 변화가 일어났다."],1,0,"ew20170923"],["ew20170923-60",2,"T097","2017-09-23",60,47,"화상사의 사체소견이 아닌 것은?",["각 장기에서 빈혈상을 보인다.","피부 표면에 1도에서 4도의 화상이 보인다.","내부 장기는 열로 인해 부풀어 오른다.","사망이 지연되면 실질장기의 혼탁종창이 나타난다."],3,0,"ew20170923"],["ew20170923-61",3,"T112","2017-09-23",61,76,"화재현장조사서 작성 시 화재원인 검토와 관련된 내용 중 필수 검토항목이 아닌 것은?",["방화 가능성","전기적 요인","인적 부주의","관련 조치사항"],4,0,"ew20170923"],["ew20170923-63",3,"T107","2017-09-23",63,44,"가재도구 화재피해액 산정기준의 간이평가방식 중 주택종류별 가중치는 몇 % 인가?",["10%","20%","30%","40%"],1,0,"ew20170923"],["ew20170923-65",3,"T108","2017-09-23",65,77,"화재조사 및 보고규정상 소방서장이 관할 구역 내에서 발생한 화재에 대하여 작성하여야 할 화재조사서류가 아닌 것은?",["재산회계 보고서","질문기록서","화재현장출동보고서","화재발생종합보고서"],1,0,"ew20170923"],["ew20170923-66",3,"T103","2017-09-23",66,73,"화재조사 및 보고규정상 화재증명원의 발급에 대한 설명으로 옳은 것은?",["소방대가 출동하지 아니한 화재장소의 화재증명원 발급요청이 있는 경우 즉시 발급하여야 한다.","화재증명원 발급 시 재산피해 및 인명피해에 대하여 조사중인 경우 “조사중”으로 기재한다.","화재증명원 발급 시 재산피해내역은 피해금액과 종류를 기재한다.","보험사에서 화재증명원을 공문으로 발급요청을 하더라도 공용 발급할 수는 없다."],2,0,"ew20170923"],["ew20170923-67",3,"T126","2017-09-23",67,76,"화재범위가 2이상의 관할구역에 걸친 화재에 대한 설명으로 옳은 것은?",["발화 소방대상물의 소재지를 관할하는 소방서와 출동한 소방서에서 각각 1건의 화재로 한다.","관할 소방서장과 출동한 소방서장과 협의하여 정한다.","출동하여 진압한 소방서에서 1건의 화재로 한다.","발화 소방대상물의 소재지를 관할하는 소방서에서 1건의 화재로 한다."],4,0,"ew20170923"],["ew20170923-68",3,"","2017-09-23",68,49,"화재현장조사서 작성 시 연소확대물에 대한 설명으로 틀린 것은?",["연소확대물은 최초착화물에 불이 붙어 화재가 발생한 후 연소가 확대되는데 있어 결정적 영향을 미친 가연물을 말한다.","연소확대물의 분류항목은 최초착화물의 분류항목과 동일하다.","최초착화물과 연소확대물이 동일한 경우에도 연소확대물을 표시한다.","연소확대물은 필수 입력사항이므로 반드시 코드를 기재해야 한다."],4,0,"ew20170923"],["ew20170923-69",3,"T102","2017-09-23",69,66,"난로의 과열로 인해 화재가 발생하여 바닥 5m2와 한쪽 벽 3m2만 소실되었다. 이 경우 화재피해조사서(재산피해) 작성 시 소실면적은 몇 m2인가?",["8","4","2","1.6"],4,0,"ew20170923"],["ew20170923-70",3,"T125","2017-09-23",70,73,"화재유형별 조사서(위험물·가스제조소등 화재)의 위험물 제조소 등의 항목이 아닌 것은?",["액화석유가스 저장시설","옥외탱크 저장소","판매 취급소","주유 취급소"],1,0,"ew20170923"],["ew20170923-71",3,"T120","2017-09-23",71,72,"화재발생종합보고서 작성 시 건물의 동수 산정에 관한 기준으로 틀린 것은?",["주요 구조부가 하나로 연결되어 있는 것은 1동으로 한다. 다만, 건널 복도 등으로 2이상의 동에 연결되어 있는 것은 그 부분을 절반으로 분리하여 각 동으로 한다.","구조와 관계없이 지붕 및 실이 하나로 연결되어 있는 것은 동일 동으로 본다.","목조 또는 내화조 건물의 경우 격벽으로 방화구획이 되어 있는 경우는 별동으로 한다.","독립된 건물과 건물 사이에 차광막, 비막이 등의 덮개를 설치하고 그 밑을 통로 등으로 사용하는 경우는 별동으로 한다."],3,0,"ew20170923"],["ew20170923-72",3,"T124","2017-09-23",72,79,"화재현장출동보고서의 작성자에 대한 설명으로 틀린 것은?",["원칙적으로 일반대원보다 선착대의 대장을 작성자로 한다.","화재현장에 출동한 소방대원이 실제로 관찰·확인한 연소상황이나 정보를 직접 기재한다.","구조대원 또는 구급대원은 작성자가 될 수 없다.","보고서의 작성자는 화재현장에 출동한 소방공무원으로 한정된다."],3,0,"ew20170923"],["ew20170923-73",3,"T111","2017-09-23",73,60,"화재현황조사서에 명시된 발화요인으로 옳은 것은?",["작동기기","교통사고","불꽃, 불티","담뱃불, 라이터불"],2,0,"ew20170923"],["ew20170923-75",3,"T122","2017-09-23",75,81,"동·식물의 피해액 산정 기준으로 옳은 것은?",["전문가의 감정가격","공인 감정가격","시중매매가격","감정서의 감정가액"],3,0,"ew20170923"],["ew20170923-76",3,"T114","2017-09-23",76,58,"화재로 인한 공구 및 기구의 소손 정도에 따른 손해율 중 틀린 것은?",["50% 이상 소손되고 그을음 및 수침오염 정도가 심한 경우 : 100%","손해정도가 다소 심한 경우 : 70%","손해정도가 보통인 경우 : 30%","오염·수침손의 경우 : 10%"],2,0,"ew20170923"],["ew20170923-77",3,"T128","2017-09-23",77,59,"화재현장조사서 중 화재현장 활동상황의 기재항목으로 틀린 것은?",["신고 및 초기조치","화재진압 활동","화재조사 활동","인명구조 활동"],3,0,"ew20170923"],["ew20170923-78",3,"T115","2017-09-23",78,67,"다음의 피해산정 대상들 중 최종잔가율이 10%인 것은?",["절삭공구","전기설비","옥내소화전","침대"],1,0,"ew20170923"],["ew20170923-79",3,"T111","2017-09-23",79,57,"화재현황조사서에 기입해야 할 항목이 아닌 것은?",["연소확대 사유","발화관련 기기","방화동기","보험가입 사항"],3,0,"ew20170923"],["ew20170923-80",3,"T104","2017-09-23",80,78,"화재피해조사 중 재산피해유형에 관한 설명으로 틀린 것은?",["소실피해 : 열에 의한 탄화, 용융, 파손 등의 피해","수손피해 : 소화활동으로 발생한 수손피해 등","기타피해 : 물품반출, 화재 중 발생한 폭발 등에 의한 피해도 포함.","영업피해 : 화재발생으로 영업을 하지 못해 발생한 영업손실"],4,0,"ew20170923"],["ew20170923-82",4,"T142","2017-09-23",82,69,"화재조사 및 보고규정상 용어의 정의 중 옳은 것은?",["발화열원이란 화재가 발생한 부위를 말한다.","조사관이란 화재조사업무를 수행하는 소방공무원을 말한다.","발화요인이란 발화에 관련된 불꽃 또는 열을 발생시킨 기기 또는 장치나 제품을 말한다.","연소확대물이란 연소가 확대되는데 있어 결정적 영향을 미친 가연물을 말한다."],4,0,"ew20170923"],["ew20170923-83",4,"T157","2017-09-23",83,73,"화재증거물수집관리규칙상 화재 현장에서의 증거물 수집, 보관 등에 관한 기준 중 틀린 것은?",["증거물을 수집할 때는 휘발성이 높은 것에서 낮은 순서로 진행하여야 한다.","증거물이 파손될 우려가 있는 경우에 충격금지 및 취급방법에 대한 주의사항을 증거물의 포장 내측에 적절하게 표기하여야 한다.","증거서류로 사본을 수집할 경우 원본과 대조한 다음 원본대조필을 하여야 하며, 원본대조를 할 수 없을 경우 제출자에게 원본과 같음을 확인 후 서명 날인을 받아서 영치하여야 한다.","증거물은 화재 증거 수집의 목적달성 후에는 관계인에게 반환하여야 한다. 다만, 관계인의 승낙이 있을 때에는 폐기할 수 있다."],2,0,"ew20170923"],["ew20170923-84",4,"T143","2017-09-23",84,78,"소방기본법령상 화재원인조사의 종류가 아닌 것은?",["연소상황 조사","발화원인 조사","재산피해 조사","소방시설 등 조사"],3,0,"ew20170923"],["ew20170923-85",4,"T147","2017-09-23",85,60,"제조물책임법상 손해배상을 지는 자가 손해배상책임을 면하는 기준 중 틀린 것은?",["제조업자가 해당 제조물을 공급하지 아니하였다는 사실을 입증한 경우","제조업자가 해당 제조물을 공급한 당시의 과학·기술수준으로는 결함의 존재를 발견할 수 없었다는 사실을 입증한 경우","제조물의 결함이 제조업자가 해당 제조물의 결함이 발생할 당시의 법령이 정하는 기준을 준수함으로써 발생한 사실을 입증한 경우","원재료나 부품의 경우에는 그 원재료나 부품을 사용한 제조물 제조업자의 설계 또는 제작에 관한 지시로 인하여 결함이 발생하였다는 사실을 입증한 경우"],3,0,"ew20170923"],["ew20170923-86",4,"T145","2017-09-23",86,59,"제조물책임법상 손해배상의 청구권은 제조업자가 손해를 발생시킨 제조물을 공급한 날부터 몇 년 이내에 행사하여야 하는가?",["3","5","7","10"],4,0,"ew20170923"],["ew20170923-88",4,"","2017-09-23",88,61,"경범죄 처벌법령상 충분한 주의를 하지 아니하고 건주물, 수풀, 그 밖에 불붙기 쉬운 물건 가까이에서 불을 피웠을 경우 부과될 수 있는 범칙금액은?",["5만원","8만원","10만원","20만원"],2,0,"ew20170923"],["ew20170923-89",4,"T140","2017-09-23",89,65,"화재조사 및 보고규정상 조사관의 책임으로 옳은 것은?",["조사기록 서류 등의 검토·분석 및 관리","조사요원 등의 지휘감독과 화재조사 집행","현장보존, 정보관리 및 관계기관에서의 협조","조사본부 운영 및 총괄에 관한 사항처리"],1,0,"ew20170923"],["ew20170923-90",4,"T155","2017-09-23",90,59,"형법상 업무상과실 또는 중대한 과실로 인하여 실화의 죄를 범한 자에 대한 벌칙 기준으로 옳은 것은?",["2년 이하의 금고 또는 700만원 이하의 벌금","3년 이하의 금고 또는 2000만원 이하의 벌금","5년 이하의 금고 또는 1500만원 이하의 벌금","7년 이하의 금고 또는 2000만원 이하의 벌금"],2,0,"ew20170923"],["ew20170923-92",4,"T156","2017-09-23",92,55,"실화책임에 관한 법률상 배상의무자에 손해 배상액 경감 청구가 있을 경우 법원이 손해배상액을 경감할 수 있는 고려 기준 중 틀린 것은? (단, 실화가 중대한 과실로 인한 것이 아닌 경우이다.)",["화재의 원인과 규모","피해자의 경제상태","배상의무자의 경제상태","피해 확대를 방지하기 위한 피해자의 노력"],4,0,"ew20170923"],["ew20170923-93",4,"","2017-09-23",93,76,"화재조사 및 보고규정상 화재증명원의 발급 기준 중 틀린 것은?",["소방서장은 민원인이 화재증명원의 발급을 신청하면 화재증명원발급대장에 기록을 한 후 화재증명원을 발급하여야 하며, 관공서, 공공기관·단체, 보험사에서 공문으로 발급을 요청 시 고용 발급하 수 있다.","소방서장은 화재피해자로부터 소방대가 출동하지 아니한 화재장소의 화재증명원 발급요청이 있는 경우에 조사관 또는 조사자로 하여금 사후 조사를 실시하게 할 수 있다.","민원인으로부터 화재증명원 교부신청을 받은 소방서장은 화재발생장소 관할지역에 관계없이 화재발생장소 관할소방서로부터 화재사실을 확인 받아 화재증명원을 교부할 수 있다.","사후 조사를 실시하게 하는 경우 민원인이 제출한 화재사후 조사의뢰서의 내용에 따라 사후조사는 현장이 보존되어 있지 않은 경우에도 실시하여야 한다."],4,0,"ew20170923"],["ew20170923-94",4,"T167","2017-09-23",94,76,"화재로 인한 재해보상과 보험가입에 관한 법률상 특수건물의 신체손해배상특약부 화재보험에 가입하지 아니한 자의 벌칙기준으로 옳은 것은?",["100만원 이하의 벌금","300만원 이하의 벌금","500만원 이하의 벌금","700만원 이하의 벌금"],3,0,"ew20170923"],["ew20170923-95",4,"","2017-09-23",95,66,"화재로 인한 재해보상과 보험가입에 관한 법률상 특수건물 중 소유자의 손해배상책임, 보험가입의 의무를 적용하지 아니하는 기준으로 틀린 것은?",["대한민국에 주둔하는 외국 군대가 소요하는 건물","대한민국에 파견된 외국의 대사·공사 또는 그 밖에 이에 준하는 사절이 소유하는 건물","군사용 건물과 외국인 소유 건물로서 총리령으로 정하는 건물","대한민국에 파견된 국제연합의 기관 및 그 직원(외국인만 해당)이 소유하는 건물"],3,0,"ew20170923"],["ew20170923-98",4,"T164","2017-09-23",98,70,"화재로 인한 재해보상과 보험가입에 관한 법률상 신체손해배상특약부화재보험에 가입하여야 하는 특수건물의 기준으로 옳은 것은?",["노래연습장업으로 사용하는 부분의 바닥면적의 합계가 1000m2 이상인 건물","학원으로 사용하는 부분의 바닥면적의 합계가 1000m2 이상인 건물","병원으로 사용하는 건물로서 연면적의 합계가 2000m2 이상인 건물","관광숙박업으로 사용하는 건물로서 연면적의 합계가 3000m2 이상인 건물"],4,0,"ew20170923"],["ew20170923-99",4,"T139","2017-09-23",99,60,"소방의 화재조사에 관한 법률상 화재조사를 하기 위한 관계 공무원의 출입 또는 조사를 거부·방해 또는 기피하는 자에 대한 벌칙 기준으로 옳은 것은?",["100만원 이하의 벌금","200만원 이하의 벌금","300만원 이하의 벌금","500만원 이하의 벌금"],3,0,"ew20170923"],["ew20170923-100",4,"","2017-09-23",100,71,"화재조사 및 보고규정상 화재건수의 결정 기준 중 틀린 것은?",["동일 소방대상물의 발화점이 2개소 이상 있는 누전점이 동일한 누전에 의한 화재는 각각 별건의 화재로 본다.","1건의 화재란 1개의 발화점으로부터 확대된 것을 말한다.","동일범이 아닌 각기 다른 사람에 의한 방화, 불장난은 동일 대상물에서 발화했더라도 각각 별건의 화재로 한다.","동일 소방대상물의 발화점이 2개소 이상 있는 지진, 낙뢰 등 자연현상에 의한 화재는 1건의 화재로 본다."],1,0,"ew20170923"],["ew20180915-2",0,"T022","2018-09-15",2,50,"샤프트공간의 개구가 상하로 동일 분포일 때 중성대의 높이는 몇 m 인가? (단, 샤프트공간의 높이는 H=100m, 온도는 30℃(303K)이고, 외기의 온도는 0℃(273K)로 한다.)",["46.1","47.1","48.1","49.1"],3,0,"ew20180915"],["ew20180915-4",0,"T001","2018-09-15",4,82,"화재 플럼(Fire Plume)에 의해 수직벽면에 생성되는 패턴이 아닌 것은?",["도넛형태 패턴","V 패턴","모래시계 패턴","U 패턴"],1,0,"ew20180915"],["ew20180915-5",0,"T009","2018-09-15",5,79,"폭발의 종류 중 화학적 폭발이 아닌 것은?",["산화 폭발","비등액체증기 폭발","분해 폭발","중합 폭발"],2,0,"ew20180915"],["ew20180915-6",0,"T003","2018-09-15",6,77,"목재의 타는 속도(연소속도)에 영향을 미치는 인자가 아닌 것은?",["목재의 수령","목재의 밀도","목재의 종류","표면적 대 질량의 비율"],1,0,"ew20180915"],["ew20180915-7",0,"","2018-09-15",7,78,"철재 구조물 용접 시 발생한 화재현장의 용접불티를 발견 및 수집하기 위한 장비로 옳은 것은?",["빗자루","삽","집게","자석"],4,0,"ew20180915"],["ew20180915-8",0,"T009","2018-09-15",8,76,"폭발 위력의 지표로 사용될 수 있는 자료가 아닌 것은?",["파편의 비행거리","무너진 벽의 종류와 구조","폭심부의 깊이","폭발 시간"],4,0,"ew20180915"],["ew20180915-9",0,"T024","2018-09-15",9,79,"화염확산에 대한 설명으로 틀린 것은?",["일반적으로 중력과 바람은 화염확산에 영향을 미친다.","훈소는 확산화염에 의한 연소과정이다.","벽면에서 화염 확산속도는 수평방향보다 수직방향이 빠르다.","인화성액체의 표면화염 확산속도는 부력의 영향으로 고체의 확산속도보다 빠르다."],2,0,"ew20180915"],["ew20180915-10",0,"T022","2018-09-15",10,63,"220V, 2A가 전선에 1분간 전기가 인가되었을 때 저항에 발생하는 열량은 몇 cal인가?",["105.6","440","6336","26400"],3,0,"ew20180915"],["ew20180915-11",0,"T001","2018-09-15",11,63,"V 패턴의 각도에 영향을 미치지 않는 것은?",["열방출률","가연물의 형태","환기의 효과","벽면의 열전도성"],4,0,"ew20180915"],["ew20180915-12",0,"","2018-09-15",12,87,"물리적 작용에 의한 소화방법이 아닌 것은?",["냉각소화","부촉매소화","제거소화","질식소화"],2,0,"ew20180915"],["ew20180915-13",0,"T024","2018-09-15",13,56,"화염에 대한 설명으로 틀린 것은?",["토치의 화염은 산소를 공급하면 짧아진다.","화염이 벽과 접하면 길어진다.","확산 화염의 색은 푸른색이다.","동일양의 가연물이 공급될 때 화염이 짧게 연소하면 온도가 높다."],3,0,"ew20180915"],["ew20180915-14",0,"T020","2018-09-15",14,76,"가연성 물질에 해당하는 것은?",["아르곤","일산화탄소","산화알루미늄","헬륨"],2,0,"ew20180915"],["ew20180915-15",0,"T019","2018-09-15",15,55,"구획실 화재의 연기에 대한 설명으로 틀린 것은?",["연기의 물리적 상은 고체, 액체, 기체가 모두 포함되어 있다.","동일 가연물의 조건에서 환기-지배형 화재는 연료-지배형 화재보다 연기의 발생량이 많다.","성화기 이후 연기의 색상을 확인하여 가연물을 추정할 수 있다.","구획실 화재의 연기는 가연성이다."],3,0,"ew20180915"],["ew20180915-16",0,"T023","2018-09-15",16,69,"연소의 특성에 대한 설명으로 틀린 것은?",["연소속도는 재료의 질량유속으로 정의되며, g/m2s으로 나타낸다.","일반적으로 표면에서의 질량유속은 5~50 g/m2s 범위에 있으며, 그 값이 5 이하인 것은 소화된다.","화염속도는 물적조건과 에너지조건인 농도, 압력, 온도보다 난류의 영향으로 가속된다.","연소속도는 화학양론비 부근에서 최소가 되고 연소상한계, 연소하한계로 갈수록 연소속도는 증가한다."],4,0,"ew20180915"],["ew20180915-17",0,"T010","2018-09-15",17,81,"가솔린의 연소범위(vol.%)가 1.4~7.6 일 때 위험도는?",["0.8","1.2","4.4","6.4"],3,0,"ew20180915"],["ew20180915-18",0,"T016","2018-09-15",18,90,"현장보존에 대한 설명으로 틀린 것은?",["통제선을 설치하였다면 별도로 통제인원을 배치할 필요가 없다.","통제선을 출입하기 위해서는 일관된 입구와 통로를 활용한다.","통제선의 입구에는 출입자 명부를 비치활용하도록 한다.","통제선 내부로 진입하는 자는 완장 등 표찰을 패용하여 진입 권한이 있음을 표시해야 한다."],1,0,"ew20180915"],["ew20180915-19",0,"T002","2018-09-15",19,74,"다음 중 가연성고체에서만 나타나는 연소형태는?",["분무연소","작열연소","확산연소","증발연소"],2,0,"ew20180915"],["ew20180915-20",0,"T007","2018-09-15",20,87,"분진폭발의 위험이 가장 낮은 것은?",["알루미늄 분말","강철 분말","티타늄 분말","생석회 분말"],4,0,"ew20180915"],["ew20180915-21",1,"T053","2018-09-15",21,54,"대기온도에 노출된 톱밥 입방체 크기(2r mm)에 따른 점화온도가 옳은 것은? (단, 오일 함유량은 0%라고 가정한다.)",["25.4(2r mm), 460℃","51(2r mm), 374℃","152(2r mm), 152℃","303(2r mm), 47℃"],3,0,"ew20180915"],["ew20180915-22",1,"T037","2018-09-15",22,68,"선박용 기관의 연속최대출력에 대한 설명으로 옳은 것은?",["주기관의 설계조건상 24시간 이상 연속 운전에서 낼 수 있는 안전 최대 출력","항해속력을 얻기 위하여 상용(商用)하는 출력","24시간 연속운전 중 2시간 동안 연속으로 운전 가능한 출력","항해속력을 확보하기 위해 해상여유(sea margin)를 포함한 출력"],1,0,"ew20180915"],["ew20180915-23",1,"T047","2018-09-15",23,66,"LPG탱크로리 가스누출 화재조사와 관련된 설명 중 틀린 것은?",["로리호스는 기밀시험을 통해 누출여부를 확인하고 손상부위를 조사한다.","높이검지봉은 검지봉 높이를 줄자로 정확한 높이와 구부러짐을 확인한다.","리미트 스위치는 전선연결을 확인하고, 실제 동작여부를 엔진시동과 연관하여 조사한다.","커플링은 비파괴시험(초음파, 침투탐상)으로 현장에서 확인하고, 시험편으로 수거 정밀 조사한다."],4,0,"ew20180915"],["ew20180915-24",1,"T045","2018-09-15",24,85,"차량 화재조사 중 화재조사자의 안전 및 조사가 용이한 장소로 적합하지 않은 것은?",["화재차량의 소유자가 신차(중고차)로 구입한 자동차판매영업소","화재차량의 소유자가 최근 차량검사 및 수리를 맡긴 자동차정비공장","화재가 발생한 고속도로의 갓길","소유자의 주차장 및 조사 가능한 주차장"],3,0,"ew20180915"],["ew20180915-25",1,"T047","2018-09-15",25,78,"액화석유가스의 안전관리 및 사업법 상 사고 사실을 시장에게 보고하여야 하는 사고로 틀린 것은?",["사람이 사망한 사고","사람이 중독되거나 부상당한 사고","20kg LPG 용기에서 가스가 누출된 사고","LNG 시설이 손괴되어 공급중단이 발생한 사고"],3,0,"ew20180915"],["ew20180915-26",1,"T056","2018-09-15",26,71,"가연물이 연소하기 위해서는 산소를 필요로 하는데 산소공급원이 아닌 것은?",["탄화칼슘","과산화수소","과염소산나트륨","질산"],1,0,"ew20180915"],["ew20180915-27",1,"T039","2018-09-15",27,77,"임야화재에 큰 영향을 미치는 주요 3요소가 아닌 것은?",["점화원","지형","연료","기후"],1,0,"ew20180915"],["ew20180915-28",1,"T048","2018-09-15",28,86,"전기설비의 사고 예방법으로 틀린 것은?",["전기설비를 과부하 상태로 운전을 금함","물기가 생기지 않도록 설비의 방수","무자격자에 의한 전기설비의 보수를 금함","급격한 온도변화가 있는 곳에 전기설비의 설치"],4,0,"ew20180915"],["ew20180915-29",1,"T048","2018-09-15",29,60,"전기화재에서 통전 입증방법으로 가장 적합한 것은?",["전원 측에서 부하 측으로 입증","부하 측에서 전원 측으로 입증","전원 측과 부하 측을 동시에 입증","임의로 선정하여 입증"],2,0,"ew20180915"],["ew20180915-30",1,"T051","2018-09-15",30,68,"연소의 수직 방향성의 상승속도는 수평 방향 속도보다 몇 배 정도인가?",["10","20","30","40"],2,0,"ew20180915"],["ew20180915-31",1,"T040","2018-09-15",31,61,"바람이 불 때 수관화의 연소형태로 옳은 것은?",["D형","U형","V형","W형"],3,0,"ew20180915"],["ew20180915-32",1,"T033","2018-09-15",32,82,"방화판정의 요건 중 방화를 의심할 수 있는 특징이 아닌 것은?",["여러 곳에서 발화","연소촉진물질의 존재","연쇄적인 화재","실화요인 존재"],4,0,"ew20180915"],["ew20180915-33",1,"T035","2018-09-15",33,50,"운손용 항공기에 고정된(fixed) 소화기장치(fire extinguishing system)를 갖추는 장소가 아닌 곳은?",["조리실(galley)","보조동력장치실(APU compartment)","화물칸(cargo compartment)","화장실(lavatories)"],1,0,"ew20180915"],["ew20180915-34",1,"T046","2018-09-15",34,72,"LPG 차량의 구성 부품 중 LPG 봄베의 밸브 색상에 대한 설명으로 옳은 것은?",["충전밸브 : 황색","액체 송출밸브 : 적색","기체 송출밸브 : 청색","충전, 액체 송출, 기체 송출밸브 : 청색"],2,0,"ew20180915"],["ew20180915-35",1,"T052","2018-09-15",35,69,"액체가연물에 의한 화재패턴으로 틀린 것은?",["포어 패턴(Pour pattern)","스플래시 패턴(Splash pattern)","틈새연소 패턴","크래이즈드 글라스(Crazed glass)"],4,0,"ew20180915"],["ew20180915-36",1,"T042","2018-09-15",36,72,"무염화원의 한 종류인 담뱃불에 대한 최초 가연물로 틀린 것은?",["종이","나일론","톱밥","면직류"],2,0,"ew20180915"],["ew20180915-37",1,"T036","2018-09-15",37,83,"미국방화협회(NFPA)에서 분류되고 있는 K급 화재의 설명으로 옳은 것은?",["수계소화방법이 권장된다.","일본에서는 D급 화재로 분류되어 있다.","주방에서 튀김 중 발생한 화재는 이에 포함된다.","국내의 경우 C급 화재로 분류되어 있다."],3,0,"ew20180915"],["ew20180915-38",1,"","2018-09-15",38,72,"위험물안전관리법령에 따른 혼합 적재가 가능한 위험물은?",["제2류위험물 + 제3류위험물","제3류위험물 + 제5류위험물","제1류위험물 + 제2류위험물","제2류위험물 + 제5류위험물"],4,0,"ew20180915"],["ew20180915-39",1,"T053","2018-09-15",39,67,"자연발화성 물질에 대한 특징으로 틀린 것은?",["다른 어떠한 화원을 주지 않아도 물질이 상온의 공기 속에서 자기 스스로 열을 낸다.","산화열은 공기가 고온이면서, 습도가 낮은 경우에 발열과 축적효과가 크다.","자연발열을 일으키는 원인은 분해열, 산화열, 흡착열, 중합열, 발효열로 구분한다.","물질의 자연발열속도와 열이 달아나는 일주 속도와의 사이가 평행이 깨지며 열이 쌓여가기 때문에 발생한다."],2,0,"ew20180915"],["ew20180915-40",1,"T056","2018-09-15",40,84,"수분 또는 물과 접촉하면 수소가스를 발생하고 반응열에 의해 폭발하기 쉬운 물질은?",["구리분말","석면","금속나트륨","철분말"],3,0,"ew20180915"],["ew20180915-41",2,"T074","2018-09-15",41,75,"액체 또는 고체 증거물의 수집 시 300mL 용량의 금속캔을 사용한다면 몇 mL 이상 채워져서는 아니 되는가?",["50","100","150","200"],4,0,"ew20180915"],["ew20180915-42",2,"T081","2018-09-15",42,83,"증거물의 수집에 대한 설명으로 틀린 것은?",["원본대조를 할 수 없을 경우 제출자에게 원본과 같음을 확인한 후 서명 날인을 받아서 영치하여야 한다.","사본을 수집할 경우 원본과 대조한 다음 원본대조필을 하여야 한다.","물리적 증거물 수집은 증거물의 증거능력을 유지·보존할 수 있도록 행한다.","증거서류를 수집함에 있어서 사본 영치를 원칙으로 한다."],4,0,"ew20180915"],["ew20180915-43",2,"T098","2018-09-15",43,72,"촉진제를 확인하기 위한 테스트 방법으로 적합한 것은?",["GC(Gas Chromatography)","SEM(Scanning Electron Microscope)","GFT(Gas Flammable Test)","TEM(Transmission Electron Microscope)"],1,0,"ew20180915"],["ew20180915-44",2,"T072","2018-09-15",44,80,"현장사진 촬영의 필요성에 대한 설명 중 틀린 것은?",["기록과 사진, 영상 모두 한계가 있으므로 문제가 해결될 때까지 현장을 보존하는 것이 가장 중요하다.","사진을 보는 사람이 실제적인 감각으로 느끼게 함으로서 그 때의 상황을 충분히 전달할 수 있는 것이 중요하다.","현장조사 시 실수로 빠트렸거나 수집이 불가능했던 많은 정보와 사실들을 사진을 통해 얻을 수 있다.","화재현장의 소손상황, 감식·감정의 대상이 되는 관계물건 등의 상황을 정확하게 기록하는 수단으로서 사진과 영상이 중요하다."],1,0,"ew20180915"],["ew20180915-45",2,"T070","2018-09-15",45,72,"표준렌즈에 대한 설명으로 옳은 것은?",["과장이 거의 없다.","객관적 표현이 우수하고 일그러짐이 있다.","피사체가 작게 찍히고 피사계 심도가 깊다.","사람의 눈에 가장 가깝고 180도 이상 화각을 촬영할 수 있다."],1,0,"ew20180915"],["ew20180915-46",2,"T079","2018-09-15",46,87,"물적증거의 종류에 해당하는 것은?",["관계자 진술","감정인 소견","유류 용기","증언"],3,0,"ew20180915"],["ew20180915-47",2,"T078","2018-09-15",47,71,"증거물 관리에 대한 설명으로 옳은 것은?",["어떠한 종류의 증거물이 발견되거나 조심스럽게 보존되었다면 완벽하게 관리되거나 문서로 기록되지 않더라도 증거로서 가치가 있다.","증거목록의 전달에 있어서 인수자의 서명과 전달일자와 시간만 기록되면 된다.","증거물의 파손을 최소화하기 위해서는 증거물을 취급하는 사람의 수를 최소화해야 한다.","여러 사람이 같은 범죄현장에서 증거를 찾고 있다면 각각 증거기록을 유지하는 것이 바람직하다."],3,0,"ew20180915"],["ew20180915-48",2,"T099","2018-09-15",48,40,"화재로 사망한 사람의 생활반응으로 틀린 것은?",["종창","피하출혈","피부탄화","염증성 발적"],3,0,"ew20180915"],["ew20180915-49",2,"T079","2018-09-15",49,65,"유류성분을 수집할 때 주변에 있는 바닥재나 플라스틱 등 비교샘플을 함께 수집하는 이유로 옳은 것은?",["바닥재나 플라스틱 등 다른 가연물의 연소성을 입증하기 위함","유류가 기화하기 전에 많은 양의 유류를 수집하기 위함","유류와 혼합된 물체의 질량 변화를 입증하기 위함","유류 성분이 주변 가연물로부터 추출된 것이 아니라는 것을 입증하기 위함"],4,0,"ew20180915"],["ew20180915-51",2,"T070","2018-09-15",51,53,"카메라에 내장된 노출계의 측광방식에 대한 설명 중 틀린 것은?",["평균측광은 파인더의 화면 전체의 노출값을 다 참고해서 노출을 측정하는 방식이다.","중앙부 중점 측광은 화면의 중심부를 70%정도, 변두리 쪽은 30%정도 비율로 측광하여 평균을 내는 방식으로 주 피사체를 중심부에 놓고 찍는 것을 전제로 하는 측광방식이다.","스팟측광은 화면의 일부만을 측광하는 방식으로 주 피사체의 정확한 노출을 측광할 수 있어 역광 촬영이나 콘트라스트가 강한 장면의 촬영 시에 사용된다.","다분할 측광은 화면을 여러 개로 분할하여 각각 측정하여 평균치를 내는 방식으로 너무 강한 빛이나 약한 빛이 측광되면 제외시켜 버리고 나머지 것으로 평균을 내는 방식이다."],3,0,"ew20180915"],["ew20180915-52",2,"T093","2018-09-15",52,82,"화상의 깊이에 다른 대표증상의 연결이 옳은 것은?",["1도 화상 - 탄화","2도 화상 - 수포","3도 화상 – 홍반","4도 화상 – 괴사"],2,0,"ew20180915"],["ew20180915-53",2,"T099","2018-09-15",53,71,"살아 있는 사람이 익사하거나 소사할 경우에 입에서 하얗고 빽빽한 점액성 거품이 부풀어 오르는 생활반응은?",["창상개구","미세포말","발적 종창","화상포"],2,0,"ew20180915"],["ew20180915-54",2,"T099","2018-09-15",54,59,"전신적 생활반응에 해당하는 것은?",["압박성 울혈","흡인 및 연하","속발성 염증","피하출혈"],3,0,"ew20180915"],["ew20180915-55",2,"T085","2018-09-15",55,47,"건강한 성인이 극심한 두통, 어지럼, 의식장애, 멀미, 구토 및 산소부족으로 인한 실신을 유발하는 혈중 일산화탄소 농도는?",["10~20%","20~30%","30~40%","40~50%"],3,0,"ew20180915"],["ew20180915-56",2,"T099","2018-09-15",56,60,"화재현장에서 사람의 생활반응으로 틀린 것은?",["화상을 입었다.","시반이 형성되었다.","기도 내에서 매가 발견되었다.","두개골 외판에 탄화가 일어났다."],4,0,"ew20180915"],["ew20180915-57",2,"T070","2018-09-15",57,55,"카메라 셔터속도가 렌즈구경의 관계에 대한 설명 중 옳은 것은?",["같은 빛의 세기에서 셔터시간을 늘려주면 렌즈구경은 커져야 한다.","같은 빛의 세기에서 셔터시간을 줄여주면 렌즈구경은 커져야 한다.","같은 빛의 세기에서 렌즈구경을 크게 하면 셔터속도는 느리게 해 주어야 한다.","같은 빛의 세기에서 렌즈구경을 작게 하면 셔터속도는 빠르게 해 주어야 한다."],2,0,"ew20180915"],["ew20180915-58",2,"","2018-09-15",58,67,"용융점이 높은 것에서 낮은 순서로 옳게 나열된 것은?",["스테인리스 → 텅스텐 → 아연 → 마그네슘 → 동","텅스텐 → 스테인리스 → 동 → 마그네슘 → 아연","텅스텐 → 스테인리스 → 마그네슘 → 동 → 아연","스테인리스 → 텅스텐 → 동 → 아연 → 마그네슘"],2,0,"ew20180915"],["ew20180915-59",2,"T097","2018-09-15",59,42,"화상사의 사망기전으로 틀린 것은?",["원발성 쇼크","속발성 쇼크","합병증","기도 폐색"],4,0,"ew20180915"],["ew20180915-60",2,"T090","2018-09-15",60,72,"유류 증거물의 인화점 시험방법으로서 주로 인화점이 93℃ 이하인 시료를 측정하는 데 사용되는 것은?",["태그 밀폐식","펜스키마텐스 밀폐식","클리브랜드 개방식","원자흡광분석"],1,0,"ew20180915"],["ew20180915-61",3,"T128","2018-09-15",61,64,"화재현장 조사서 화재건물 현황의 기재사항이 아닌 것은?",["건축물 현황","보험가입 현황","화재발생 후 상황","소방시설 및 위험물 현황"],3,0,"ew20180915"],["ew20180915-62",3,"","2018-09-15",62,74,"화재 피해조사 및 피해액 산정순서로 옳은 것은?",["화재현장 조사 → 피해정도 조사 → 기본현황 조사 → 재구입비 산정 → 피해액 산정","화재현장 조사 → 기본현황 조사 → 피해정도 조사 → 재구입비 산정 → 피해액 산정","기본현황 조사 → 피해정도 조사 → 화재현장 조사 → 재구입비 산정 → 피해액 산정","기본현황 조사 → 피해정도 조사 → 재구입비 산정 → 피해액 산정 → 화재현장 조사"],2,0,"ew20180915"],["ew20180915-64",3,"T102","2018-09-15",64,70,"철근콘크리트조 슬래브지붕 4층 건물의 1층에서 화재가 발생하여 1층 점포 300m2(바닥면적 기준)가 전소되고, 2층 벽면 1면에 100m2의 그을음 피해가 발생한 경우 소실 면적은 몇 m2인가?",["350","320","300","200"],3,0,"ew20180915"],["ew20180915-66",3,"T105","2018-09-15",66,80,"화재현장 조사서의 작성 시 유의사항 중 틀린 것은?",["관계자의 진술을 기재하지 않는다.","발화지점 및 화재원인 판정은 객관적인 증거자료를 첨부할 수 있다.","감식·감정 결과통지서, 참고문헌 등 참고자료를 첨부할 수 있다.","예상되는 사항 및 관련 조치사항 등도 기록할 수 있다."],1,0,"ew20180915"],["ew20180915-67",3,"T130","2018-09-15",67,65,"항공기, 선박, 철도차량, 특수작업용차량, 시중매매가격이 확인되지 아니하는 자동차에 대한 피해액 산정기준 중 틀린 것은?",["감정평가서가 있는 경우 감정평가서상의 현재가액에 손해율을 곱한 금액을 화재로 인한 피해액으로 한다.","감정평가서가 없는 경우 회계장부상의 현재가액에 손해율을 곱한 금액을 화재로 인한 피해액으로 한다.","감정평가서와 회계장부 모두 없는 경우에는 제조회사, 판매회사, 조합 또는 협회 등에 조회하여 구입가격 또는 시중거래가격을 확인하여 피해액을 산정한다.","수리가 가능한 경우에는 수리비를 피해액으로 한다."],4,0,"ew20180915"],["ew20180915-68",3,"T112","2018-09-15",68,65,"화재현장 조사서(임야화재, 기타화재, 피해액이 없는 화재 이외의 화재)의 화재원인 검토 항목이 아닌 것은?",["방화 가능성","인적 부주의 등","기름누출","기계적 요인"],3,0,"ew20180915"],["ew20180915-69",3,"T118","2018-09-15",69,71,"화재조사 및 보고규정에 따른 화재의 유형별 분류가 아닌 것은?",["임야화재","자동차·철도차량 화재","선박·항공기 화재","전기·화학 화재"],4,0,"ew20180915"],["ew20180915-70",3,"T117","2018-09-15",70,76,"예술품 및 귀중품의 화재피해액 산정기준 중 틀린 것은?",["감가공제를 하지 아니한다.","복수 전문가의 감정을 받거나 감정서 등의 금액을 피해액으로 인정한다.","공인감정기관에서 인정하는 금액을 화재로 인한 피해액으로 산정한다.","예술품 및 귀중품에 대한 그 가치를 손상하지 아니하고 원상태의 복원이 가능한 경우에는 피해액을 인정하지 아니한다."],4,0,"ew20180915"],["ew20180915-71",3,"T124","2018-09-15",71,66,"화재현장 출동보고서 기재사항 중 현장도착시 관찰·확인사항으로 옳은 것은?",["화재 각지시의 위치","이상한 소리, 특이한 냄새, 폭발 등 특이한 현상과 확인시의 위치","누설전류·가스누설 유무","진화작업 시 발화지점 부근의 물건이동, 도괴, 손괴상황 등"],2,0,"ew20180915"],["ew20180915-72",3,"T124","2018-09-15",72,77,"화재조사 및 보고규정에 따른 민원인이 제출한 화재사후 조사의뢰서의 내용에 따라 사후 조사를 실시한 후 작성을 생략할 수 있는 서류는?",["화재현황 조사서","화재피해 조사서","화재현장 조사서","화재현장 출동보고서"],4,0,"ew20180915"],["ew20180915-73",3,"T119","2018-09-15",73,47,"특수한 경우의 피해액 산정 우선 적용사항 기준 중 틀린 것은?",["중고구입기계장치 및 집기비품의 제작년도를 알 수 없는 경우 신품가액의 30~50%를 재구입비로 하여 피해액을 산정한다.","중고기계장치 및 중고집기비품의 시장거래가격이 신품가격보다 높을 경우 신품가액을 재구입비로 하여 피해액을 산정한다.","공구 및 기구, 집기비품, 가재도구를 일괄하여 피해액을 산정할 경우 재구입비의 50%를 피해액으로 한다.","재고자산의 상품 중 견본품, 전시품, 진열품에 대해서는 구입가의 30~50%를 피해액으로 한다."],4,0,"ew20180915"],["ew20180915-74",3,"T125","2018-09-15",74,62,"소방·방화시설 활용조사서 소화시설의 기재사항이 아닌 것은?",["소화기구","옥외소화전","연결송수관설비","물분무등소화설비"],3,0,"ew20180915"],["ew20180915-75",3,"T125","2018-09-15",75,60,"화재유형별 조사서(건축·구조물 화재)의 특정소방대상물의 분류항목이 아닌 것은?",["지하구","초고층시설","근린생활시설","문화집회 및 운동시설"],2,0,"ew20180915"],["ew20180915-76",3,"T119","2018-09-15",76,74,"재고자산의 화재피해액 산정 시 회계장부에 현재가액이 확인된 경우의 산정기준으로 옳은 것은?",["회계장부상 현재가액×손해율","재고자산의 출고가액×손해율","재고자산의 회전율×손해율","연간매출액÷손해율"],1,0,"ew20180915"],["ew20180915-77",3,"T121","2018-09-15",77,85,"화재발생종합보고서 작성 시 질문기록서의 작성을 생략할 수 있는 화재는?",["건축·구조물 화재","임야 화재","자동차 화재","선박 화재"],2,0,"ew20180915"],["ew20180915-78",3,"T114","2018-09-15",78,55,"영업시설의 화재로 인한 소손 정도에 따른 손해율이 40%인 경우는?",["영업시설의 일부를 교체 또는 수리하거나 도장 내지 도배가 필요한 경우","손상정도가 다소 심하여 상당부분 교체 내지 수리가 필요한 경우","불에 타거나 변형되고 그을음과 수침 정도가 심한 경우","부분적인 소손 및 오염의 경우"],1,0,"ew20180915"],["ew20180915-79",3,"T113","2018-09-15",79,50,"신축 후 20년 된 블록조 슬래브지붕의 주택에 화재가 발생하여 450m2가 소실된 경우의 화재피해액은? (단, 내용연수 50년, 신축단가 450천원, 손해율 70%이다.)",["96390천원","85050천원","56700천원","93200천원"],1,0,"ew20180915"],["ew20180915-80",3,"T113","2018-09-15",80,56,"잔존물 제거비의 계산 방법으로 옳은 것은?",["산정대상 피해액×10%","산정대상 피해액×20%","화재 재구입비×10%","화재 재구입비×20%"],1,0,"ew20180915"],["ew20180915-81",4,"T167","2018-09-15",81,73,"화재로 인한 재해보상과 보험가입에 관한 법률에 따른 특수건물의 소유자가 특약부화재보험에 가입하지 아니한 경우 최대 몇 만원 이하의 벌금에 처하는가?",["500","300","150","100"],1,0,"ew20180915"],["ew20180915-82",4,"T152","2018-09-15",82,75,"불을 놓아 사람이 주거로 사용하거나 사람이 현존하는 건조물, 기차, 전차, 자동차, 선박, 항공기 또는 광갱을 소훼한 자에 대한 죄명은?",["현주건조물 등에의 방화죄","현조건조물 등에의 방화죄","일반건조물 등에의 방화죄","공용건조물 등에의 방화죄"],1,0,"ew20180915"],["ew20180915-83",4,"","2018-09-15",83,66,"소방기본법에 따른 화재조사를 하기 위하여 소방서장의 보고 또는 자료 제출 명령을 위반하여 보고 또는 자료 제출을 하지 아니한 관계인에 대한 벌칙 기준으로 옳은 것은?",["20만원 이하의 과태료","200만원 이하의 과태료","300만원 이하의 벌금","5년 이하의 징역 또는 5000만원 이하의 벌금"],2,0,"ew20180915"],["ew20180915-86",4,"","2018-09-15",86,53,"화재조사 및 보고규정에 따른 건물의 화재 피해액 산정기준으로 옳은 것은?",["표준단가(m2당) × 소실면적 × [1-0.9 × 경과년수/내용년수] × 손해율","표준단가(m2당) × 소실면적 × [1-0.8 × 경과년수/내용년수] × 손해율","신축단가(m2당) × 소실면적 × [1-0.9 × 경과년수/내용년수] × 손해율","신축단가(m2당) × 소실면적 × [1-0.8 × 경과년수/내용년수] × 손해율"],4,0,"ew20180915"],["ew20180915-90",4,"T151","2018-09-15",90,48,"화재로 인한 재해보상과 보험가입에 관한 법률에 따른 한국화재보험협회가 보험계약을 체결할 때 또는 보험계약을 갱신할 때마다 해당 특수건물의 화재예방 및 소화시설의 안전점검을 대통령령으로 정하는 바에 따라 일정 기간 하지 않을 수 있는 대상기준 중 틀린 것은?",["산업안전보건법에 따라 공정안전보고서를 작성하는 건물로서 총리령으로 정하는 위험도가 낮은 특수건물","고압가스 안전관리법에 따라 안전성향상계획을 작성하는 건물로서 총리령으로 정하는 위험도가 낮은 특수건물","화재예방, 소방설치·유지 및 안전관리에 관한 법률에 따라 소방정밀점검을 받은 건물로서 총리령으로 정하는 위험도가 낮은 특수건물","안전점검 결과 총리령으로 정하는 화재위험도지수가 낮은 특수건물"],3,0,"ew20180915"],["ew20180915-92",4,"T154","2018-09-15",92,67,"형법에 따른 화재에 있어서 진화용의 시설 또는 물건을 은닉 또는 손괴하거나 기타 방법으로 진화를 방해한 자는 최대 몇 년 이하의 징역에 처하는가?",["3","5","7","10"],4,0,"ew20180915"],["ew20180915-93",4,"T143","2018-09-15",93,73,"소방기본법령에 따른 화재원인조사의 종류가 아닌 것은?",["연소상황 조사","발화원인 조사","인명피해 조사","소방시설 등 조사"],3,0,"ew20180915"],["ew20180915-94",4,"T165","2018-09-15",94,57,"화재로 인한 재해보상과 보험가입에 관한 법률에 따른 특약부화재보험의 보험금액 기준 중 틀린 것은?",["화재보험 : 특수건물의 시가에 해당하는 금액","손해배상책임을 담보하는 보험에 해당하는 부분 중 사망의 경우 : 피해자 1명마다 1억원 이상으로서 대통령령으로 정하는 금액","손해배상책임을 담보하는 보험에 해당하는 부분 중 부상의 경우 : 피해자 1명마다 사망자에 대한 보험금액의 범위에서 대통령령으로 정하는 금액","화재보험 시가의 결정에 관한 기준은 총리령으로 정함"],2,0,"ew20180915"],["ew20180915-95",4,"","2018-09-15",95,83,"화재조사 및 보고규정에 따른 화재범위가 2 이상의 관할구역에 걸친 화재의 경우의 화재 건수의 결정기준으로 옳은 것은?",["선착대개 소속된 소방서에서 1건의 화재로 한다.","2개 소방서에서 각각 1건의 화재로 한다.","발화 소방대상물의 소재지를 관할하는 소방서에서 1건의 화재로 한다.","화재피해범위가 가장 넓은 소방서에서 1건의 화재로 한다."],3,0,"ew20180915"],["ew20180915-96",4,"T173","2018-09-15",96,83,"화재에 대한 손해배상 책임이 없는 경우로 옳은 것은?",["화재로 타인의 생명을 해한 자","고의로 인한 화재로 타인의 재산에 손해를 가한 자","과실로 인한 화재로 타인의 재산에 손해를 가한 자","화재로 재산에 손해를 가한 미성년자가 그 행위에 대한 책임을 변식할 능력이 없는 자"],4,0,"ew20180915"],["ew20180915-97",4,"T140","2018-09-15",97,78,"화재조사 및 보고규정에 따른 조사본부장의 책임이 아닌 것은?",["조사요원 등의 지휘감독과 화재조사 집행","현장보존, 정보관리 및 관계기간에서의 협조","조사기록 서류 등의 분석 및 관리","조사본부 운영 및 총괄에 관한 사항처리"],3,0,"ew20180915"],["ew20180915-98",4,"T156","2018-09-15",98,54,"민법에 따른 불법행위 및 배상책임에 관한 기준 중 틀린 것은?",["고의 또는 과실로 인한 위법행위로 타인에게 손해를 가한 자는 그 손해를 배상할 책임이 있다.","배상의무자는 그 손해가 고의 또는 중대한 과실에 의한 것이고, 그 배상으로 인하여 배상자의 생계에 중대한 영향을 미치게 될 경우에는 법원에 그 배상액의 경감을 청구할 수 있다.","불법행위로 인한 손해배상의 청구권은 피해자나 그 법정대리인이 그 손해 및 가해자를 안 날로부터 3년간 이를 행사하지 아니하면 시효로 인하여 소멸한다.","도급인은 수급인이 그 일에 관하여 제삼자에게 가한 손해를 배상할 책임이 없다. 그러나 도급 또는 지시에 관하여 도급인에게 중대한 과실이 있는 때에는 그러하지 아니하다."],2,0,"ew20180915"],["ew20180915-99",4,"T159","2018-09-15",99,75,"화재조사 및 보고규정에 따른 건물의 동수 산정 기준 중 틀린 것은?",["주요구조부가 하나로 연결되어 있는 것은 1동으로 한다. 다만, 건널 복도 등으로 2이상의 동에 연결되어 있는 것은 그 부분을 절반으로 분리하여 각 동으로 본다.","건물의 외벽을 이용하여 실을 만들어 작업실 용도로 사용하고 있는 것은 주건물과 다른 동으로 본다.","구조에 관계없이 지붕 및 실이 하나로 연결되어 있는 것은 같은 동으로 본다.","목조 건물의 경우 격벽으로 방화구획이 되어 있는 경우 같은 동으로 한다."],2,0,"ew20180915"],["ew20180915-100",4,"T145","2018-09-15",100,67,"제조물책임법에 따른 손해배상의 청구권은 피해자 또는 그 법정대리인이 손해, 손해배상 책임을 지는 자를 모두 알게 된 날부터 몇 년간 행사하지 아니하면 시효의 완성으로 소멸하는가?",["3","5","7","10"],1,0,"ew20180915"],["ew20190427-2",0,"T006","2019-04-27",2,62,"벽의 두께 0.05m, 벽 양면의 온도는 각각 40℃와 20℃일 때 폴리우레탄 폼 벽체를 관통하는 단위면적당 열유동율은? (단, 열전도율 k=0.034 W/m이다.)",["0.136 W/m2","1.36 W/m2","13.6 W/m2","136 W/m2"],3,0,"ew20190427"],["ew20190427-3",0,"T019","2019-04-27",3,92,"화재 시 연기의 이동속도 및 특성에 대한 설명으로 옳지 않은 것은?",["연기 층의 두께는 연소가 진행됨에 따라 달라진다.","화재실에서 분출된 연기는 공기보다 가벼워 통로의 상부를 따라 유동한다.","연기는 발화층으로부터 위층으로 확산된다.","일반적으로 연기의 이동속도는 수평이동 속도가 수직이동 속도보다 빠르다."],4,0,"ew20190427"],["ew20190427-4",0,"T023","2019-04-27",4,70,"다음 중 산화반응에 대한 설명으로 옳은 것은?",["산소와 분리되는 반응","수소와 결합하는 반응","산화수가 감소하는 반응","전자수가 감소하는 반응"],4,0,"ew20190427"],["ew20190427-5",0,"T014","2019-04-27",5,85,"화재조사 및 보고규정상 조사본부장의 책임으로 옳지 않은 것은?",["조사요원 등의 지휘감독과 화재조사 집행","현장보존, 정보관리 및 관계기관에서의 협조","조사본부 운영 및 총괄에 관한 사항처리","조사기록 서류 등의 검토 분석 및 관리"],4,0,"ew20190427"],["ew20190427-6",0,"T010","2019-04-27",6,88,"가연성기체 중 위험성의 척도인 위험도가 가장 큰 것은?",["메탄","에탄","프로판","아세틸렌"],4,0,"ew20190427"],["ew20190427-7",0,"T012","2019-04-27",7,75,"소방기본법령상 화재조사를 위한 권리와 의무에 대한 설명으로 옳지 않은 것은?",["방화 또는 실화의 혐의가 있다고 인정되면 증거를 수집ㆍ보존하여 범죄수사에 협력의무가 있다.","관계인을 임의 동행하여 조사할 수 있다.","수사기관이 압수한 증거물에 대하여 조사할 수 있다.","수사기관에 체포된 피의자에 대하여 조사할 수 있다."],2,0,"ew20190427"],["ew20190427-8",0,"","2019-04-27",8,79,"다음 중 현장관찰 요령으로 옳지 않은 것은?",["소손상황을 관찰할 때는 연소가 강한곳으로부터 약한 방향으로 점차 이동하며 관찰한다.","소실, 연소, 붕괴된 부분에 대해서는 복원적인 관점에서 관찰한다.","현장에 남아 있는 물건의 일체는 관찰 대상의 것이므로 주의 깊게 관찰한다.","최후까지 연소된 부분 및 연소확대 경로를 유념해서 관찰한다."],1,0,"ew20190427"],["ew20190427-9",0,"T014","2019-04-27",9,82,"화재조사에 대한 조사관의 유의사항으로 옳지 않은 것은?",["과학적인 근거에 의한 조사에 중점을 두고 질문조사는 보조적인 방법으로 실시한다.","사건을 조사할 때는 팀을 구성하여 활동하는 것이 좋다.","지득한 비밀을 누설해서는 안된다.","조사관은 선입견을 피하고 현장에 관한 과도한 정보를 수집하면 안된다."],4,0,"ew20190427"],["ew20190427-10",0,"T007","2019-04-27",10,81,"다음 중 분진폭발의 위험성이 없는 것은?",["티타늄 분말","알루미늄 분말","아스피린 분말","시멘트 분말"],4,0,"ew20190427"],["ew20190427-11",0,"T008","2019-04-27",11,81,"각 구성 성분 가스의 폭발한계를 알면 혼합가스의 폭발한계를 구할 수 있는 법칙은?",["보일의 법칙","샤를의 법칙","아보가드로 법칙","르샤틀리에 법칙"],4,0,"ew20190427"],["ew20190427-12",0,"T007","2019-04-27",12,84,"다음 중 분진폭발(Dust Explosion)에 대한 설명으로 옳지 않은 것은?",["공기 중을 부유하고 있거나 퇴적된 상태인 분진의 폭발을 의미한다.","가스폭발이나 화약폭발과는 달리 착화에 필요한 에너지가 작다.","분진의 입경은 폭발의 최소착화에너지 및 화염전면의 이동속도에 영향을 미친다.","1차 폭발 후 부유된 가연성분진이 연소하면서 2차적 폭발이 일어날 수 있다."],2,0,"ew20190427"],["ew20190427-13",0,"T012","2019-04-27",13,76,"소방기본법령상 화재조사를 실시할 수 있는 자격으로 옳지 않은 것은?",["소방공무원 중 국가기술자격법에 따른 건축ㆍ위험물ㆍ전기ㆍ안전관리 분야 산업기사 이상의 자격을 취득한 자","소방공무원으로서 화재조사분야에서 1년 이상 근무한 자","소방교육기관에서 8주 이상 화재조사에 관한 전문교육을 이수한 자","국립과학수사연구원 또는 외국의 화재조사관련 기관에서 6주 이상 화재조사에 관한 전문교육을 이수한 자"],4,0,"ew20190427"],["ew20190427-14",0,"T018","2019-04-27",14,82,"다음의 구획실 화재에 대한 설명 중 옳은 것은?",["대부분 노출된 가연물 표면에 착화되어 가연물이 소진될 때까지 최고의 열방출을 보이는 것은 최성기이다.","유염착화에 이르기에는 온도가 낮거나 산소가 부족한 상황에서 연소가 소극적으로 지속되는 것을 롤오버(Rollover)라고 한다.","최성기에는 실내에 있는 산소를 거의 소비시키고 외부로부터 유입된 공기의 영향을 받는 가연물지배형 화재의 양상이 나타난다.","일반적으로 화염 전파 속도는 수평방향이 수직방향에 비하여 약 20배정도 빠르다."],1,0,"ew20190427"],["ew20190427-15",0,"T012","2019-04-27",15,88,"소방기본법령상 화재원인 및 피해조사의 권한이 없는 자는?",["소방청장","소방본부장","소방서장","소방진압대장"],4,0,"ew20190427"],["ew20190427-16",0,"T019","2019-04-27",16,78,"다음 중 연소생성물에 대한 설명으로 옳지 않은 것은?",["일반화재 시, 플래시오버 후에 산소가 부족한 조건이 되면 발생하는 연기는 검은색을 띤다.","일산화탄소는 연료지배형 화재보다 환기지배형 화재에서 많이 발생한다.","연기는 액체와 기체로 구성되며 고체는 포함되지 않는다.","폴리우레탄은 화재 시 시안화수소와 질소산화물 등의 유독성 기체를 발생시킨다."],3,0,"ew20190427"],["ew20190427-17",0,"T020","2019-04-27",17,80,"연소가 용이한 가연물의 조건으로 적합하지 않은 것은?",["산소와의 접촉 가능한 면적이 클 것","발열량이 클 것","활성화 에너지가 클 것","열전도율이 작을 것"],3,0,"ew20190427"],["ew20190427-18",0,"","2019-04-27",18,54,"화재현장에서 열에 의하여 소손된 전구에 대한 감식방법으로 옳은 것은?",["내부가 진공상태인 전구는 연화된 부분이 부풀어 오르거나 외부로 터져 나가는 형태로 변한다.","내부가 불활성가스로 충전된 전구는 일부가 연화되기 시작하면 외부의 압력 때문에 내부로 함목되는 형태로 변한다.","전선에 매달려있는 전구의 경우, 화재 당시의 방향을 신뢰할 수 없으므로 화재진행방향의 지표로서 사용하는 것을 피해야 한다.","전구의 필라멘트의 산화여부 및 전구내벽에 부착된 필라멘트 증기 등으로 화재당시 전구의 꺼짐과 켜짐은 확인할 수 없다."],3,0,"ew20190427"],["ew20190427-19",0,"T017","2019-04-27",19,78,"과학적인 화재 조사 방법의 순서로 옳은 것은?",["문제의 인식→문제의 정의→데이터 수집→데이터 분석→가설 수립→가설 검증→화재원인 결정","문제의 인식→문제의 정의→데이터 분석→데이터 수집→가설 수립→가설 검증→화재원인 결정","문제의 인식→데이터 수집→문제의 정의→데이터 분석→가설 수립→가설 검증→화재원인 결정","문제의 인식→문제의 정의→가설 수립→데이터 수집→데이터 분석→가설 검증→화재원인 결정"],1,0,"ew20190427"],["ew20190427-20",0,"","2019-04-27",20,79,"다음 중 요로드가가 145 이상인 요일류에 안료와 전색제 등을 혼합한 착색도료를 일컫는 용어로 옳은 것은?",["락카","페인트","에나멜","플라이머"],2,0,"ew20190427"],["ew20190427-21",1,"T037","2019-04-27",21,64,"선박의 전문용어에 대한 설명으로 옳지 않은 것은?",["고물보(Transom):선미가 네모난 보트의 선미 단면","도레이드 환기(Dorade vent):갑판 아래로 공기를 흡입하는 배플이 설치되어 물이 들어오지 못하도록 하는 갑판 상자 환기","방현재(Fender):구획실, 선체 또는 그러한 부분을 덮는 영구적 덮개","해치(Hatch):보트의 갑판에 있는 방수커버로 덮인 출입구"],3,0,"ew20190427"],["ew20190427-22",1,"T041","2019-04-27",22,70,"다음 중 산불의 직접진화 전술이 아닌 것은?",["일렬 진화","협력 진화","맞불 진화","측면 진화"],3,0,"ew20190427"],["ew20190427-23",1,"T039","2019-04-27",23,76,"우리나라의 경우 산불이 가장 많이 발생하는 시간대로 옳은 것은?",["09시-11시","14시-16시","17시-19시","21시-23시"],2,0,"ew20190427"],["ew20190427-24",1,"T050","2019-04-27",24,61,"정전용량 40[uF]인 대전된 도체의 정전에너지가 80[J]일 때, 도체에 가해진 대전전위는 몇 [V]인가?",["1000","2000","3000","4000"],2,0,"ew20190427"],["ew20190427-25",1,"T061","2019-04-27",25,80,"폭발 현장에서 수집한 배경정보를 바탕으로 폭발 전ㆍ후 사고 경위를 표로 만든 후 인과관계이론과 일치여부를 추론하여 최적이론을 설정하는 분석은?",["손상채턴 분석","구조물 분석","열료과 상관분석","타임라인 분석"],4,0,"ew20190427"],["ew20190427-26",1,"T044","2019-04-27",26,74,"다음 중 차량의 시동 점화 시 전류 흐름 순서를 바르게 나열한 것은?",["점화스위치→배터리→시동모터→점화코일→배전기→고압케이블→스파크 플러그","점화스위치→시동모터→배터리→점화코일→배전기→고압케이블→스파크 플러그","점화스위치→배터리→시동모터→배전기→점화코일→고압케이블→스파크 플러그","점화스위치→시동모터→점화코일→배터리→배전기→고압케이블→스파크→플러그"],1,0,"ew20190427"],["ew20190427-27",1,"T036","2019-04-27",27,85,"항공기 화재에서 가연성 금속 화재의 분류(class)로 옳은 것은?",["Class A","Class B","Class C","Class D"],4,0,"ew20190427"],["ew20190427-28",1,"T047","2019-04-27",28,47,"20℃의 프로판가스의 증기압을 압력게로 측정하였더니 7.4kgf/cm2이었다. 이 압력을 절대압력으로 환산하면 약 몇 kPa인가?",["627","727","827","927"],3,0,"ew20190427"],["ew20190427-29",1,"T056","2019-04-27",29,66,"탄화칼슘이 물과 반응할 때 생성되는 가연성 기체는?",["C2H4","C3H8","C2H2","CH4"],3,0,"ew20190427"],["ew20190427-30",1,"T051","2019-04-27",30,57,"화재의 진행과정 중 독립된 발화로 오인할 수 있는 연소형태를 생성시킬 수 있는 불씨 이동의 요인으로 옳지 않은 것은?",["소락물에 의한 경우","대류에 의한 불티의 이동","독립된 장소에 착화하는 행위","압력에 의한 경우"],3,0,"ew20190427"],["ew20190427-31",1,"","2019-04-27",31,86,"다음 중 각 용어에 대한 설명으로 옳지 않은 것은?",["실화 : 부주의, 우발적 사고 등으로 인하여 발생한 화재","조사 : 화재원인을 규명하고 화재로 인한 피해를 산정하기 위한 자료의 수집, 관계자 등에 대한 질문 등 일련의 해동","방화 : 주거에 사용되거나 현존하는 건조물 기타 일정한 물건에 고의적으로 불을 지르는 범죄행위","화재 : 사람의 의도에 따라 우연에 의해 발생하는 연소현장"],4,0,"ew20190427"],["ew20190427-32",1,"T042","2019-04-27",32,81,"다음 중 담뱃불에 대한 설명으로 옳지 않은 것은?",["산소농도 16% 이하에서도 연소가 진행되며, 수직상태보다 수평상태에서 빨리 연소된다.","중심부 온도는 약 700~900℃이다.","무염화원으로 분류되며, 이동이 가능한 점화원이다.","담뱃불은 풍속 1.5m/sec일 때 최적상태로 연소한다."],1,0,"ew20190427"],["ew20190427-33",1,"T046","2019-04-27",33,71,"다음 중 구형의 밸브 몸통을 갖고 있으며 유체의 입구와 출구 중심선이 일직선상에 있고 밸브를 통과하는 유체의 흐름이 S자 모양으로 되어 있는 밸브의 명칭으로 옳은 것은?",["볼밸브","게이트밸브","체크밸브","글로우브밸브"],4,0,"ew20190427"],["ew20190427-34",1,"T046","2019-04-27",34,53,"LPG 자동차에서 기화기(Vaporizer)의 구성부품에 해당하지 않는 것은?",["에어 엘리먼트","압력 조정 스크루","진공 다이어프램","솔레노이드 밸브"],1,0,"ew20190427"],["ew20190427-35",1,"T061","2019-04-27",35,74,"화재현장에서 발생하는 소음으로서 목격자들이 폭발로 오인할 수 있는 것이 아닌 것은?",["화재 시 콘크리트 폭렬에 의한 소음","화재 열기에 의한 스프레이캔, 방향제캔 등의 파열 소음","화재 시 전선피복이 손상되며 발생하는 전기적 합선의 소음","개방된 용기의 변형시 발생하는 소음"],4,0,"ew20190427"],["ew20190427-36",1,"T033","2019-04-27",36,88,"방화를 의심할 수 있는 경우와 가장 거리가 먼 것은?",["외부침입흔적이 발견되는 경우","다른 범죄의 증거가 발견되는 경우","1개의 발화부만 존재하는 경우","액체가연물의 연소흔적이 관찰되는 경우"],3,0,"ew20190427"],["ew20190427-37",1,"T060","2019-04-27",37,58,"다음 중 파라핀계탄화수소에 대한 설명으로 옳지 않은 것은?",["상온, 상압에서 메탄, 에탄, 프로판, 부탄은 이상으로 존재한다.","펜탄은 이성질체가 3개이다.","탄소-탄소간의 결합은 단일공유결합이다.","탄소수가 증가함에 따라 비점이 낮아진다."],4,0,"ew20190427"],["ew20190427-38",1,"T060","2019-04-27",38,60,"다음 중 층류화염에 해당하는 것은?",["모닥불의 불꽃","양초의 불꽃","화재현장 개구부로 솟는 불꽃","20kg LPG 용기에서 분출되고 있는 가스의 불꽃"],2,0,"ew20190427"],["ew20190427-39",1,"T061","2019-04-27",39,84,"다음 중 화재조사에 있어 화재 현장에 대한 관찰사항으로 옳지 않은 것은?",["현장의 보험가입여부","현장의 위치 및 주변상황","현장의 연소 진행형태","현장의 소손상황"],1,0,"ew20190427"],["ew20190427-40",1,"T048","2019-04-27",40,57,"침과 평판전극사이에서 잘 발생되며, 전압의 상승에 의해 코로나의 발광부가 전극 간을 이어서 발광이 일어나는 방전형식으로 옳은 것은?",["글로우코로나","브러쉬코로나","스트리머코로나","임펄스코로나"],3,0,"ew20190427"],["ew20190427-41",2,"","2019-04-27",41,73,"화재현장 지문감식(지문현출) 사례로 가장 거리가 먼 것은?",["그을음이 고스란히 내려앉은 물체의 표면","방화범이 매개물로 사용한 생활정보지의 연소 잔해","지문을 감추기 위해 사용한 라텍스 장갑의 외측","방화에 사용하고 주변에 버린 휘발유 용기의 표면"],3,0,"ew20190427"],["ew20190427-42",2,"T082","2019-04-27",42,89,"화재조사 및 보고규정에 따라 화재현장을 보존하기 위한 방법으로 옳지 않은 것은?",["소방활동구역의 관리는 수사기관과 상호협조하여야 한다.","소방활동구역은 로프 등으로 범위를 한정하고 경고판을 부착한다.","소방활동구역으로 설정하여 출입을 통제한다.","소방활동구역을 설정할 경우 범위는 최대한 넓게 설정하여야 한다."],4,0,"ew20190427"],["ew20190427-43",2,"T088","2019-04-27",43,67,"NFPA921의 타임라인(Time Line)을 작성할 때 구성요소로 옳지 않은 것은?",["실제시간(Hard Time)","추정시간(Soft Time)","상대시간(Relative Time)","수지분석시간(Fault Tree Time)"],4,0,"ew20190427"],["ew20190427-44",2,"T097","2019-04-27",44,63,"다음 중 자ㆍ타살 및 사고사의 감별법에 대한 설명으로 옳지 않은 것은?",["진짜 손상의 가능성에 대해서는 항상 염두에 두어야 하는데 다수의 타살 현장이 화재에 의해서 숨겨지기 때문이다.","가짜 손상의 경우 깊은 조직에서 출혈을 관찰할 수 없으며, 위치는 대개의 경우 암시적이다.","열에 의해 고도로 손상된 부위에서도 심부조직을 검사하여 판독이 가능하다.","열이 가해진 피부는 고도로 수축되고 균열되는 경우를 종종 보게 된다."],3,0,"ew20190427"],["ew20190427-45",2,"T084","2019-04-27",45,87,"화재현장에서 관계자에 대한 질문 및 녹음에 관한 설명으로 옳지 않은 것은?",["피질문자를 배려하여 충분히 안정된 상태에서 진술할 수 있는 장소를 선택한다.","화재현장에서 질문할 경우에는 이해관계인들을 모두 참석시킨 후에 진행해야 한다.","피질문자의 이해관계에 의하여 허위진술을 하는 경우가 있음을 염두에 둔다.","녹음된 진술내용은 진술조서에 첨부하여 입증자료로 사용할 수 있다."],2,0,"ew20190427"],["ew20190427-46",2,"T071","2019-04-27",46,79,"화재증거물 사진 촬영 시 피사계의 심도를 깊게 하기 위한 방법으로 가장 옳은 것은?",["렌즈의 조리개를 좁힌다.","렌즈의 조리개를 넓힌다.","카메라의 셔터 스피드를 길게 한다.","카메라의 셔터 스피드를 짧게 한다."],1,0,"ew20190427"],["ew20190427-47",2,"T095","2019-04-27",47,74,"다음의 유류 중 자연발화 가능성이 가장 높은 것은?",["엔진유","대두유","기어유","스핀들류"],2,0,"ew20190427"],["ew20190427-48",2,"T081","2019-04-27",48,87,"화재증거물수집관리규칙에 따라 화재조사기관이 화재현장의 CCTV 영상물에 나타나는 사람의 이미지를 제공할 수 있는 기관으로 옳지 않은 것은?",["경찰서","고등검찰","대법원","보험회사"],4,0,"ew20190427"],["ew20190427-49",2,"T094","2019-04-27",49,87,"연소범위(폭발범위)에 영향을 미치는 요인에 대한 설명으로 가장 거리가 먼 것은?",["압력이 높아지면 하한 값은 크게 변하지 않으나 상한 값은 높아진다.","온도가 높아질수록 연소범위는 좁아진다.","고온ㆍ고압의 경우 연소범위는 더욱 넓어진다.","혼합기를 이루는 공기의 산소농도가 높을수록 연소범위가 넓어진다."],2,0,"ew20190427"],["ew20190427-50",2,"T097","2019-04-27",50,85,"사망자 부검을 위해 사용하는 장비로 가장 거리가 먼 것은?",["X선 촬영기","컴퓨터 단층 촬영기(CT)","적외선 분광광도계","자기공명영상장비(MRI)"],3,0,"ew20190427"],["ew20190427-51",2,"T082","2019-04-27",51,89,"화재현장 보존을 위한 소방대원의 역할 및 주의사항에 대한 설명으로 옳지 않은 것은?",["잔화 정리하는 동안 남아있는 증거물이 훼손될 수 있으므로 주의하여야 한다.","화재현장에 있는 설비, 기구 또는 시설의 손잡이를 돌리거나 작동 스위치를 켜는 것을 자제하여야 한다.","화재현장에서 휘발유나 경유로 작동되는 도구 및 설비를 사용하는 것은 자제하는 것이 좋다.","화재현장에 대한 접근은 화재조사관만으로 한정한다."],4,0,"ew20190427"],["ew20190427-52",2,"T093","2019-04-27",52,57,"화상의 손상범위를 결정짓는 인자로 옳지 않은 것은?",["가해진 온도","열의 노출기간","피부의 구성","열을 배출하는 체표면의 능력"],3,0,"ew20190427"],["ew20190427-53",2,"T074","2019-04-27",53,90,"화재증거물수집관리규칙상의 증거물 수집용기에 대한 설명 중 옳지 않은 것은?",["용기는 취급할 제품에 의한 용매의 작용에 투과성이 없어야 한다.","주석 도금캔 내부에 녹이 있는 것은 사용하지 말아야 한다.","주석 도금캔은 세척하여 여러번 사용가능하다.","양철 용기는 돌려 막는 스크루 뚜껑만 아니라 밀어 막는 금속 마개를 갖추어야 한다."],3,0,"ew20190427"],["ew20190427-54",2,"T074","2019-04-27",54,78,"화재증거물수집관리규칙상의 증거물 시료용기로 적합하지 않은 것은?",["주석 도금 캔(CAN)","유리병","아크릴 병","양철 캔(CAN)"],3,0,"ew20190427"],["ew20190427-55",2,"T070","2019-04-27",55,85,"화재현장에서 역광 촬영을 하고자 한다. 다음 중 카메라 측광방식으로 가장 적합한 것은?",["스팟측광","중앙부 중점 측광","평균측광","다분할 측광"],1,0,"ew20190427"],["ew20190427-56",2,"T070","2019-04-27",56,85,"화재현장의 사진촬영방법으로 가장 옳은 것은?",["어두운 실내 촬영 시 스트로브나 플래시를 사용한다.","군중 또는 인물사진 등의 사진은 절대로 촬영하지 않는다.","발화지점과 인접한 영역에 있는 방이라도 손상이 없으면 촬영하지 않는다.","증거로서 가치가 있는 물건은 현장보다는 연구실로 가지고 가서 촬영한다."],1,0,"ew20190427"],["ew20190427-57",2,"T080","2019-04-27",57,79,"액체 촉진제의 물리적 특성에 대한 설명 중 옳은 것은?",["액체 촉진제는 액체 상태로만 발견될 수 있다.","액체 촉진제는 대부분의 내부 마감재 및 기타 화재 잔해에 쉽게 흡수된다.","일반적으로, 액체 촉진제는 물과 접촉했을 때 물 아래로 가라앉는다.","액체 촉진제가 다공성 물질에 흡수되었을 때는 잔존 가능성이 매우 낮다."],2,0,"ew20190427"],["ew20190427-58",2,"T098","2019-04-27",58,64,"GC-MS 분석에서 탄소수 4개(C4)에서 7개(C7)가 검출된 경우 추정할 수 있는 성분으로 가장 옳은 것은?",["휘발유","경유","등류","중유"],1,0,"ew20190427"],["ew20190427-59",2,"T085","2019-04-27",59,83,"화재로 인하여 사망에 이른 사체에 관한 설명으로 가장 거리가 먼 것은?",["일산화탄소가 헤모글로빈과 결합함으로써 체내 산소의 공급이 차단되어 사망한다.","일산화탄소를 흡입으로 인하여 사망하면 암전색의 시반이 나타난다.","기도, 폐 등의 호흡기에서 발견되는 그을음은 화재 당시 생존해 있었음을 나타내는 증거가 될 수 있다.","일산화탄소를 흡입한 것으로 화재 당시 생존해 있었음에 대한 증거가 될 수 있다."],2,0,"ew20190427"],["ew20190427-60",2,"T087","2019-04-27",60,73,"화재로 사망한 사체에 대한 설명으로 옳지 않은 것은?",["사망이후에는 혈액이 모세형관의 표면장력에 의해 몸의 위쪽으로 모인다.","표피와 함께 진피까지 침범되는 화상을 2도 화상이라고 한다.","원발성 쇼크로 급격히 사망한 경우 전형적인 화재자의 소견을 보이지 않을 수도 있다.","손바닥이나 발바닥에서 보이는 과도한 그을음은 화재당시 피해자가 활동한 것을 의미한다."],1,0,"ew20190427"],["ew20190427-61",3,"T128","2019-04-27",61,63,"화재조사 및 보고규정에 따른 화재현장조사서 작성 시 화재건물 현황의 기재사항이 아닌 것은?",["건축물 현황","보험가입 현황","소방시설 및 위험물 현황","화재발생 후 상황"],4,0,"ew20190427"],["ew20190427-62",3,"T112","2019-04-27",62,57,"화재조사 구분에 따른 화재원인조사의 범위에 해당하는 것은?",["화재진압 중 발생한 사망자 및 부상자","열에 의한 탄화, 용융, 파손","피난경로, 피난상의 장애요인","화재로 인한 사망자 및 부상자"],3,0,"ew20190427"],["ew20190427-63",3,"T126","2019-04-27",63,53,"화재조사 및 보고규정에 따른 화재건수의 결정에 대한 내용으로 틀린 것은?",["1건의 화재란 1건의 발화지점에서 확대된 것으로 발화부터 진화까지를 말한다.","접지점이 동일한 누전에 의한 화재는 동일 소방대상물의 발화점이 2개소 이상 있더라도 1건의 화재로 한다.","지진, 낙뢰 등 자연현상에 의한 다발화재는 동일 소방대상물의 발화점이 2개소 이상 있더라도 1건의 화재로 한다.","화재점위가 2개소 이상의 관할구역에 걸친 화재에 대해서는 발화 소방대상물의 소재지를 관할하는 소방서에서 1건의 화재로 한다."],2,0,"ew20190427"],["ew20190427-64",3,"T114","2019-04-27",64,49,"화재피해로 인한 기계장치의 소손정도에 따른 손해율 기준 중 옳지 않은 것은?",["프레임 및 주요부품이 소손되고 굴곡변형으로 수리가 불가능한 경우 : 100%","프레임 및 주요부품 수리하여 재사용 가능하나 소손정도가 심한 경우 : 50~60%","화염의 영향으로 부품(주요부품이 아닌 일반부품)의 교체가 필요하고, 그을음 및 수침으로 인한 오염의 정도가 심하여 전반적으로 Overhaul이 필요한 경우 : 30~40%","화염의 영향으로 다소 적게 받았으나 그을음 및 수침오염 정도가 심하여 일부 부품교체와 분해조립이 필요한 경우 : 5~10%"],4,0,"ew20190427"],["ew20190427-65",3,"T114","2019-04-27",65,76,"화재피해액 산정에 있어서 공구ㆍ기구의 소손정도에 따른 손해율이 10%에 해당하는 것은?",["손해정도가 보통인 경우","손해정도가 다소 심한 경우","오염ㆍ수침손의 경우","50%이상 소손되고 그을음 및 수침오염 정도가 심한 경우"],3,0,"ew20190427"],["ew20190427-66",3,"T130","2019-04-27",66,66,"항공기 및 선박의 현재시가를 정하는 방법으로 옳은 것은?",["구입시의 가격","구입시의 가격에서 사용기간 감가액을 뺀 가격","재구입 가격","재구입 가격에서 사용기간 감가액을 뺀 가격"],2,0,"ew20190427"],["ew20190427-67",3,"T115","2019-04-27",67,70,"모델하우스 또는 가설건물 등 일정기간 존치하는 건물에 있어서는 실제 존치할 기간을 내용연수로 하여 피해액을 산정한다. 이 경우 존치기간 종료일 현재의 최종 잔가율은?",["10%","20%","30%","40%"],2,0,"ew20190427"],["ew20190427-68",3,"","2019-04-27",68,30,"화재조사 및 보고규정에 따라 방화ㆍ방화의심 조사서를 작성 시 기재사항이 아닌 것은?",["방화도구","방화피해사항","방화자 인적사항","도착 시 초기상황"],2,0,"ew20190427"],["ew20190427-69",3,"T116","2019-04-27",69,85,"화재 당시에 피해물의 재구입비에 대한 현재가의 비율로, 화재 당시 피해물에 잔존하는 경제적 가치의 정도를 나타내는 용어로 옳은 것은?",["잔가율","손해율","감가상각","경년감가율"],1,0,"ew20190427"],["ew20190427-70",3,"T102","2019-04-27",70,62,"치장벽돌조 슬래브지붕 2층 건물의 2층에서 발화되어 바닥면적 20m2가 전소되었고, 인근시멘트벽돌조 슬래브지붕 3층 건물 3층에 비화로 인하여 바닥 2m2와 벽면 1면의 3m2가 그을린 경우의 소실면적은 몇 m2인가?",["25","21","20","9"],2,0,"ew20190427"],["ew20190427-71",3,"T125","2019-04-27",71,52,"화재조사 및 보고규정상 화재유형별 조사서 서식 중 철도차량 발화지점에 해당되지 않는 것은?",["객실(좌석)","바퀴","화장실","엔진룸"],4,0,"ew20190427"],["ew20190427-72",3,"T124","2019-04-27",72,44,"화재조사 및 보고규정상 화재현황조사서의 첨부서류가 아닌 것은?",["화재현장출동보고서","화재유형별조사서","화재피해조사서","방화ㆍ방화의심 조사서"],1,0,"ew20190427"],["ew20190427-73",3,"T103","2019-04-27",73,77,"화재조사 및 보고규정에 따른 화재증명원 발급에 대한 설명 중 옳은 것은?",["화재증명원 발급시 재산피해내역을 금액으로 기재한다.","이해당사자가 아닌 자가 화재증명원의 발급을 신청하면 화재증명원을 발급하여서는 아니 된다.","사후조사를 할 경우 발화장소 및 발화지점의 현장이 보존되어 있지 않아도 일단 조사를 한다.","소방대가 출동하지 아니한 화재장소에 화재증명원 발급요청이 있는 경우 사후조사를 할 수 있다."],4,0,"ew20190427"],["ew20190427-74",3,"T120","2019-04-27",74,72,"화재조사 및 보고규정에 따른 화재조사 서류작성 및 보고요령으로 옳지 않은 것은?",["화재상황보도는 최초보고, 중간보고, 최종보고로 구분한다.","최종보고는 화재종료 직후 최초보고, 중간보고를 취합하여 보고한다.","최초보고는 선착대가 화재현장 도착 즉시 현장지휘관 책임 하에 화재규모, 인명피해 발생여부, 건물구조 개요, 정확한 재산피해 내역을 보고한다.","중간보고는 최초보고 후 화재상황 진전에 따라 연소 확대 여부, 인명구조 및 진화활동상황, 재산피해내역 및 화재원인 등을 수시로 보고한다. 단 규명되지 아니한 화재원인 및 피해내역은 추정 보고할 수 있다."],3,0,"ew20190427"],["ew20190427-75",3,"T108","2019-04-27",75,82,"화재조사 및 보고규정에 따른 관할구역내에서 발생한 화재에 대하여 작성해야 하는 서류로 옳지 않은 것은?",["화재발생종합보고서","질문기록서","화재현장 출동보고서","범죄사실 보고서"],4,0,"ew20190427"],["ew20190427-76",3,"T107","2019-04-27",76,49,"화재로 인한 기계장치의 피해액 산정기준에 해당하지 않는 것은?",["감정평가서에 의한 피해액 산정","간이평가방식","실질적ㆍ구체적 방식","수리비에 의한 방식"],2,0,"ew20190427"],["ew20190427-79",3,"","2019-04-27",79,64,"아파트 502호에서 화재가 최초 발생하여 602호와 702호에 연소 확대되었다. 화재현장에 출동한 화재조사관은 502호, 602호, 702호에 발생한 재산피해를 조사하여 피해액을 산정하였다. 하지만 며칠 뒤 아파트와 인접한 단독주택 소유자가 아파트 화재로 인해 주택외벽과 창문 등에 피해를 입었다며 소방기관의 피해조사내용에 이의를 제기하였다. 이 때 해당 단독주택 소유자가 소방기관에 제출하여야 하는 서류는?",["화재피해 조사서","화재증명원","재산피해신고서","화재증명원 신청서"],3,0,"ew20190427"],["ew20190427-80",3,"T113","2019-04-27",80,55,"화재로 인한 건물, 부대설비, 기계장치 등의 잔존물 내지 유해물 또는 폐기물을 제거하거나 처리하는 비용은 화재피해액의 몇 % 범위내에서 인정된 금액으로 산정하는가?",["5%","10%","20%","15%"],2,0,"ew20190427"],["ew20190427-81",4,"T155","2019-04-27",81,71,"형법상, 과실로 인하여 사람이 주거로 사용하거나 사람이 현존하는 건조물, 기차, 전차 또는 광갱을 소훼한 자에 대한 벌금기준으로 옳은 것은?",["1500만원 이하의 벌금","2500만원 이하의 벌금","3500만원 이하의 벌금","4500만원 이하의 벌금"],1,0,"ew20190427"],["ew20190427-82",4,"","2019-04-27",82,77,"화재조사 및 보고규정에 따른 조사의 원칙에 대한 설명으로 옳은 것은?",["물적 증거를 통한 과학적인 방법을 통해 합리적인 사실의 규명을 원칙으로 한다.","인적 증언을 통한 개연성에 근거한 사실 추론을 원칙으로 한다.","관계자 등에 대한 질문사항은 녹음하여 그 증거를 확보함을 원칙으로 한다.","경찰관의 수사자료를 근거로 조사를 실시함을 원칙으로 한다."],1,0,"ew20190427"],["ew20190427-83",4,"T148","2019-04-27",83,82,"과도한 문어발식 콘센트 사용으로 인하여 발생한 전기화재로 인하여, 구입한 지 5년 된 세탁기가 소손되었다. 이 소손에 대하여 제조물책임법령상 손해배상책임에 관한 설명으로 옳은 것은?",["세탁기 설계상 결함으로 손해배상 책임은 세탁기 설계자가 부담한다.","세탁기 개발과정상의 결함으로 손해배상 책임은 제품 개발자가 부담한다.","세탁기 소유자의 사용상 문제로 손해배상 책임은 발생하지 않는다.","세탁기 제조상 결함으로 손해배상책임은 세탁기 제조사가 부담한다."],3,0,"ew20190427"],["ew20190427-84",4,"","2019-04-27",84,84,"소방기본법령상 소방용수시설의 사용금지 행위로 옳지 않은 것은?",["소방용수시설을 점검, 정비, 보수하기 위하여 사용하는 행위","정당한 사유없이 소방용수시설을 사용하는 행위","정당한 사유없이 손상ㆍ파괴, 철거 또는 그 밖의 방법으로 소방용수시설의 효용을 해치는 행위","소방용수시설의 정당한 사용을 방해하는 행위"],1,0,"ew20190427"],["ew20190427-85",4,"T144","2019-04-27",85,83,"소방기본법령에 따른 화재피해조사의 조사범위에 포함되지 않는 것은?",["소화활동 중 사용된 물로 인한 피해","소방활동 중 발생한 사망자 및 부상자","연기, 물품반출, 화재로 인한 폭발 등에 인한 피해","소화활동으로 발생한 영업 손실 피해"],4,0,"ew20190427"],["ew20190427-86",4,"T139","2019-04-27",86,69,"소방기본법에 따른 화재의 조사에 대한 기준 중 틀린 것은?",["소방서장은 화재의 원인 및 피해 등에 대한 조사를 하여야 한다.","화재조사를 하는 관계 공무원이 화재조사를 수행하면서 알게 된 비밀을 누설한 경우 과태료에 처한다.","소방서장은 화재조사에 필요한 경우 관계인에 대하여 자료제출을 명할 수 있다.","화재조사를 하는 소방공무원이 관계인의 정당한 업무를 방해한 경우 벌금에 처한다."],2,0,"ew20190427"],["ew20190427-87",4,"T142","2019-04-27",87,68,"화재조사 및 보고규정에 따른 화재원인을 밝히기 위한 감식의 정의로 옳은 것은?",["과학적 방법에 의한 실험의 결과로 화재원인을 밝히는 것","조사관의 경험을 통해 화재원인을 유추하는 것","관계자들의 회의를 통하여 화재원인을 결정하는 것","주로 시각에 의한 종합적인 판단으로 화재의 사실관계를 명확하게 규명하는 것"],4,0,"ew20190427"],["ew20190427-88",4,"T149","2019-04-27",88,40,"화재로 인한 재해보상과 보험가입에 관한 법률상 부상등급 1급의 보험금액으로 옳은 것은?",["1000만원","3000만원","5000만원","1억원"],2,0,"ew20190427"],["ew20190427-89",4,"","2019-04-27",89,81,"보일러, 고압가스 기타 폭발성 있는 물건을 파열시켜 사람의 생명, 신체 또는 재산에 대하여 위험을 발생시키는 범죄명은?",["폭발성물건파열죄","현주건조물방화죄","가스방류죄","폭발물사용죄"],1,0,"ew20190427"],["ew20190427-90",4,"T149","2019-04-27",90,64,"화재로 인한 재해보상과 보험가입에 관한 법률상 부상등급 3급에 해당하는 부상으로 옳은 것은?",["상박고 분쇄성 골절","화상ㆍ좌창ㆍ최사창 등으로 연부조직의 손상이 심한 부상(몸 표면의 9퍼센트 이상의 부상을 말한다.)","상박골 경부 골절","척추체 분쇄성 골절"],3,0,"ew20190427"],["ew20190427-91",4,"T139","2019-04-27",91,59,"소방의 화재조사에 관한 법률상 정당한 사유없이 화재 조사를 실시하는 관계 공무원의 출입 또는 조사를 거부ㆍ방해 또는 기피한 자에 대한 벌칙기준으로 옳은 것은?",["100만원 이하의 벌금","200만원 이하의 벌금","300만원 이하의 벌금","500만원 이하의 벌금"],3,0,"ew20190427"],["ew20190427-92",4,"T142","2019-04-27",92,53,"화재조사 및 보고규정에서 정의하는, 발화열원에 의하여 불이 붙고 이 물질을 통해 제어하기 힘든 화세로 발전한 가연물을 무엇이라 하는가?",["발화지점","최초착화물","발화요인","연소확대물"],2,0,"ew20190427"],["ew20190427-93",4,"T156","2019-04-27",93,62,"실화책임에 관한 법률에 대한 설명으로 옳은 것은?",["실화자에게 중대한 과실이 있을 때 한하여 적용한다.","배상의무자 및 피해자의 경제상태를 고려하여 배상액을 경감할 수 있다.","경과실이 있을 때에는 손해배상을 면책한다.","피해자보다 실화자의 보호를 우선시한다."],2,0,"ew20190427"],["ew20190427-94",4,"T173","2019-04-27",94,40,"민법에서 규정하고 있는 불법행위에 의한 손해배상청구권이 성립하기 위한 조건으로 옳지 않은 것은?",["행위자의 고의ㆍ과실","행위자의 책임능력","행위자의 경제능력","행위자의 긴급피난 여부"],3,0,"ew20190427"],["ew20190427-95",4,"T156","2019-04-27",95,60,"실화책임에 관한 법률상 손해배상액 경감의 고려사항으로 옳지 않은 것은?",["화재의 원인과 규모","소화수에 의한 수손 피해의 정도","배상의무자 및 피해자의 경제상태","피해 확대를 방지하기 위한 실화자의 노력"],2,0,"ew20190427"],["ew20190427-96",4,"T163","2019-04-27",96,69,"화재조사 및 보고규정에 따른 화재상황보고 기준 중 옳지 않은 것은?",["최초보고는 선착대가 화재현장 도착즉시 현장지휘관 책임하에 화재의 규모, 인명피해 발생여부, 건물구조 개요 등을 보고한다.","중간보고는 최초보고 후 화재상황의 진전에 따라 연소확대여부, 인명구조활동상황, 진화활동 상황, 재산피해내역 및 화재원인 등을 수시로 보고하여야 한다.","중간보고 시 규명되지 아니한 화재원인 및 피해내역은 추정 보고할 수 있다.","최종보고는 화재종료 후 5일 이내에 취합보고 하여야 한다."],4,0,"ew20190427"],["ew20190427-98",4,"","2019-04-27",98,76,"다음 중 소방기본법령상 소방용수시설이 아닌 것은?",["저수조","급수탑","소화전","고가수조"],4,0,"ew20190427"],["ew20190427-99",4,"T164","2019-04-27",99,60,"화재로 인한 재해보상과 보험가입에 관한 법률상의 특수건물로 옳은 것은?",["학원으로 사용하는 부분의 바닥면적 합계가 1000제곱미터 이상인 건물","바닥면적 합계가 1500제곱미터 이상인 병원","관광숙박업으로 사용하는 부분의 바닥면적합계가 2000제곱미터 이상인 숙박업소","식품위생법령상 단란주점으로 사용하는 부분의 바닥면적 합계가 2000제곱미터 이상인 단란주점"],4,0,"ew20190427"],["ew20190427-100",4,"T153","2019-04-27",100,63,"불을 놓아 공용 또는 공익에 공하는 건조물, 기차, 전차, 자동차, 선박, 항공기 또는 광갱을 소훼한 자에 대한 죄명은?",["현주건조물 등에의 방화죄","일반물건 등에의 방화죄","일반건조물 등에의 방화죄","공용건조물 등에의 방화죄"],4,0,"ew20190427"],["ew20190921-1",0,"T013","2019-09-21",1,84,"화재조사 기자재 중 안전장비에 포함되지 않는 것은?",["손전등","안전고리","안전화","보호용 장갑"],1,0,"ew20190921"],["ew20190921-2",0,"T005","2019-09-21",2,77,"화재현장 금속기둥에서 보이는 만곡현상을 관찰하여 화염의 방향을 판단할 때 먼저 검사해야 할 사항이 아닌 것은?",["비교하는 기둥들이 유사한 하중을 받고 있는 것인지를 검사한다.","비교하는 기둥들의 설치각도가 직각을 이루고 있는지를 검사한다.","비교하는 기둥들이 같은 재질과 두께로 만들어진 것인지를 검사한다.","화재현장의 하중을 받는 구조물들은 화염을 먼저 받게 되는 면의 반대 방향으로 기울어지는 만곡을 검사한다."],4,0,"ew20190921"],["ew20190921-3",0,"T024","2019-09-21",3,65,"화염의 확산에 대한 설명으로 틀린 것은?",["순방향 확산은 전방의 연료를 화염이 직접 접촉하기 때문에 빠르게 일어난다.","경사트렌치 내에서의 하향 확산과 같은 급속한 확산 효과를 트렌치 효과라 한다.","역방향 확산은 화염이 전방의 연료를 가열하는 데 제한적으로 느리게 일어난다.","경사면 화재확산은 화염 윗부분의 가연성 표면에 대한 예열, 전도, 대류, 복사에 의한 복합적인 효과가 일어난다."],2,0,"ew20190921"],["ew20190921-4",0,"T002","2019-09-21",4,71,"분해연소를 하는 가연물은?",["숯","목재","코크스","파라핀"],2,0,"ew20190921"],["ew20190921-5",0,"T023","2019-09-21",5,90,"연소현상에 대한 설명으로 옳은 것은?",["철에 녹이 스는 것은 연소반응의 일종이다.","종이가 누렇게 변색되는 것은 연소반응이다.","연소는 빛과 열을 수반하는 급격한 산화반응이다.","니크롬선을 사용한 전열기에 전기가 인가되었을 때 니크롬선이 빛과 열을 내는 것은 연소반응이다."],3,0,"ew20190921"],["ew20190921-7",0,"T019","2019-09-21",7,53,"흡입 시 기도의 알칼리성 조직을 중화시켜 기도의 부종 또는 경련으로 사망에 이르게 하는 연소생성물은?",["불화수소(HF)","일산화탄소(CO)","염화수소(HCI)","시안화수소(HCN)"],3,0,"ew20190921"],["ew20190921-8",0,"T015","2019-09-21",8,91,"방화죄가 성립하지 않은 것은?",["사람이 현존하는 집에 불을 놓아 재산피해 발생","공용으로 사용되는 차량에 불을 놓아 사망사고 발생","자기 소유의 차량에 불을 놓아 주변으로 화재를 확대시킴","쓰레기 소각 중 불티에 의한 화재가 발생하여 재산피해 발생"],4,0,"ew20190921"],["ew20190921-9",0,"T024","2019-09-21",9,61,"액체연료의 기상(氣象) 화염 확산에 대한 일반적인 속도는?",["1~2cm/s","10~20cm/s","1~2m/s","10~20m/s"],3,0,"ew20190921"],["ew20190921-10",0,"T005","2019-09-21",10,74,"물질의 융점으로 옳은 것은?",["납:327℃","구리:1540℃","파라핀:660℃","알루미늄:54℃"],1,0,"ew20190921"],["ew20190921-11",0,"T003","2019-09-21",11,65,"발화부 주변의 일반적인 연소현상에 대한 설명으로 틀린 것은?",["발화부를 향해 소락되거나 도괴된다.","발화부와 가까울수록 탄화심도가 깊다.","목재표면에 발생하는 균열은 발화부와 가까울수록 골이 넓고 굵어진다.","발화부는 비교적 밝은 색을 띠며 발화부와 멀어질수록 어두운 빛을 나타낸다."],3,0,"ew20190921"],["ew20190921-12",0,"T009","2019-09-21",12,75,"메탄가스가 밀폐공간에서 완전연소되어 폭발할 경우에 대한 설명으로 틀린 것은?",["압력이 증가한다.","에너지가 생성된다.","충격파가 초음속인 폭연이다.","반응물과 생성물의 몰수가 같다."],3,0,"ew20190921"],["ew20190921-13",0,"T020","2019-09-21",13,82,"가연물의 가연성이 높아지는 조건이 아닌 것은?",["발열량이 클 것","열전도율이 클 것","산소와의 친화력이 클 것","활성화 에너지가 적을 것"],2,0,"ew20190921"],["ew20190921-14",0,"T001","2019-09-21",14,71,"수직면과 수평면 모두에서 나타나는 3차원 화재패턴은?",["V 패턴","Pour 패턴","U 패턴","잘린 원추 패턴"],4,0,"ew20190921"],["ew20190921-15",0,"T014","2019-09-21",15,86,"화재조사 시 관계자에 대한 질문 요령으로 틀린 것은? (단, 관계자란 화재조사 및 보고규정상 용어의 정의에 따른다.)",["일문일답 형식으로 계통적 순서에 따라 질문하고 청취한다.","관계자의 진술내용을 신속하게 기록하며, 상황에 따라서는 녹음(녹취)도 필요하다.","허위진술을 방지하기 위해 질문을 시작할 때 상대방의 성명, 연령, 주소 등을 청취하고 기재한다.","발화원인과 관계가 있는 것 같은 사항에 대한 질문에 대해서는 상대방에게 예비지식을 주면서 질문한다."],4,0,"ew20190921"],["ew20190921-16",0,"","2019-09-21",16,71,"소방기본법령상 보일러 등의 위치, 구조 및 관리와 화재예방을 위하여 불의 사용에 있어서 지켜야 하는 사항을 위반한 것에 해당하는 것은?",["실내 보일러가 콘크리트바닥 위에 설치됨","보일러와 벽, 천장 사이의 거리는 0.3미터를 유지하여 설치됨","등유 탱크가 보일러 본체로부터 수평거리 1.2미터의 거리에 설치됨","가스보일러가 설치된 장소에는 가스누설경보기가 설치됨"],2,0,"ew20190921"],["ew20190921-17",0,"","2019-09-21",17,80,"화재조사 및 보고규정상 화재인명 피해조사에 대한 사상자 분류기준으로 옳은 것은?",["경상자는 입원치료를 필요로 하지 않은 부상자도 포함","화재로 인하여 5일 이내 사망한 자를 당해 사망자로 포함","중상자는 전치 10주 이상의 입원치료를 필요로 하는 부상자","경상자는 전치 10주 이하의 입원치료를 필요로 하는 부상자"],1,0,"ew20190921"],["ew20190921-18",0,"T011","2019-09-21",18,85,"가연물의 최소착화에너지에 영향을 미치는 요인에 대한 설명으로 옳은 것은?",["입력이 높을수록 최소착화에너지는 높아진다.","온도가 높을수록 최소착화에너지는 낮아진다.","가연물의 종류에 관계없이 최소착화에너지는 일정하다.","혼합된 공기의 산소농도에 관계없이 최소착화에너지는 일정하다."],2,0,"ew20190921"],["ew20190921-19",0,"T001","2019-09-21",19,61,"액체가연물에 의해 발생하는 화재패턴에 관한 설명으로 틀린 것은?",["연소 시 증발잠열에 의해 도넛패턴이 발생한다.","레인보우 이펙트가 관찰된다면 액체가연물을 사용한 고의적 착화로 판단한다.","고스트 마크는 플래시 오버와 같은 강력한 화재열기 속에서도 발생할 수 있으므로 주의를 요한다.","포어패턴은 액체가연물이 바닥에 뿌려진 경우 뿌려진 부분과 뿌려지지 않은 부분의 탄화경계 흔적을 말한다."],2,0,"ew20190921"],["ew20190921-20",0,"T013","2019-09-21",20,57,"소방기본법령상 소방본부에서 갖추어야 할 화재조사 장비 및 시설 중 추가 권장 장비가 아닌 것은?",["고속카메라세트","접점저항계","직류전압전류계","적외선열상카메라"],4,0,"ew20190921"],["ew20190921-21",1,"T045","2019-09-21",21,88,"자동차 화재조사를 위해 수집해야 할 자료로 가장 거리가 먼 것은?",["구입 및 개조 후 부착한 장치의 유무 및 자료","자동차검사시의 정기점검 정비 기록부","자동차 차량검사증 및 차량상풍명","피해자의 운전경력 증명서"],4,0,"ew20190921"],["ew20190921-23",1,"T033","2019-09-21",23,87,"방화가 의심되는 특징으로 옳지 않은 것은?",["여러 곳에서 독립적인 발화흔적","화재현장의 타 범죄 발생증거 및 연소촉진물의 존재","귀중품 반출 및 동일건물에서의 재차화재","화재발생 시 관계인 부재"],4,0,"ew20190921"],["ew20190921-24",1,"T054","2019-09-21",24,51,"다음 중 연소범위가 가장 넓은 것은?",["에틸렌","암모니아","메탄","프로판"],1,0,"ew20190921"],["ew20190921-25",1,"T053","2019-09-21",25,67,"자연발화가 발생하기 용이한 조건으로 옳지 않은 것은?",["주변 온도가 높을수록 자연발화가 용이하다.","충분한 산소 공급을 위해 더미를 바닥에 넓게 깔아 놓은 형태일 때 자연발화가 용이하다.","지속적인 온도 상승이 발화에 이를 때까지 충분한 반응물질이 있어야 한다.","식물성 기름은 다공성 물질에 흡착되었을 경우 자연발화가 용이하다."],2,0,"ew20190921"],["ew20190921-26",1,"T061","2019-09-21",26,79,"화재현장 보존이 중요시되는 이유가 아닌 것은?",["화재의 발화지점을 판정하는데 주요한 증거가 되기 때문이다.","원활한 피해복구를 위해 보존해야 한다.","화재현장 훼손은 물증의 증거적 가치를 손상시키기 때문이다.","화재의 원인과 책임 소재를 판정하기 위한 증거가 되기 때문이다."],2,0,"ew20190921"],["ew20190921-27",1,"T054","2019-09-21",27,58,"메탄 4g을 완전연소시키면 이산화탄소 몇 mol이 생성되는가?",["2","1","0.5","0.25"],4,0,"ew20190921"],["ew20190921-28",1,"T051","2019-09-21",28,72,"다음 중 화재 열기로 인하여 탄화균열이 발생하는 물질은?",["금속재","목재","석재","유리"],2,0,"ew20190921"],["ew20190921-29",1,"","2019-09-21",29,65,"가스계량기의 측정원리에 의한 분류 중 산업용으로 사용되는 추측식 가스계량기로 옳은 것은?",["터빈형","드럼(drum)형","회전식(루트식)","막식(다이어프램식)"],1,0,"ew20190921"],["ew20190921-30",1,"T038","2019-09-21",30,63,"선박화재의 현장기록에 대한 설명으로 틀린 것은?",["선박화재의 현장기록에 대한 요건은 일반적으로 구조물과 차량에 대한 것과 거의 모든 부분에서 다른 특수성을 갖는다.","선박화재의 현장기록은 가능한 한 선박이 현장의 제 위치에 있을 때 조사되어야 한다.","화재가 발생한 선박이 현 위치에서 손상되었는지, 화재 이후 위치가 바뀌었는지 확인하여야 한다.","선박화재의 현장기록은 폐기물처리장, 수리시설, 정박지, 소형 선박수리소 등에서 일부를 기록해야 하는 경우가 있을 수 있다."],1,0,"ew20190921"],["ew20190921-31",1,"T042","2019-09-21",31,88,"다음 중 담뱃불에 의해 착화가 가능한 물질은?",["유리(glass)","폴리에틸렌","톱밥","아크릴"],3,0,"ew20190921"],["ew20190921-33",1,"T039","2019-09-21",33,79,"우리나라 임야화재의 발생 건수가 가장 많은 계절은?",["봄","여름","가을","겨울"],1,0,"ew20190921"],["ew20190921-34",1,"T056","2019-09-21",34,66,"화재조사 시 나타날 수 있는 나트륨의 연소 특징으로 옳은 것은?",["화재초기의 불꽃색은 보라색이다.","출화 부근에 남아 있는 물을 리트머스 시험지로 조사하면 산성을 나타낼 가능성이 크다.","나트륨이 연소되고 남은 표면에는 끈적끈적한 흰색의 수산화나트륨이 남아있을 수 있다.","물을 강하게 분해하여 다량의 아세틸렌을 발생시켜 공기와 접촉하여 폭발적으로 연소한다."],3,0,"ew20190921"],["ew20190921-35",1,"T045","2019-09-21",35,62,"내연기관 자동차의 구동방식에 의한 분류에 속하지 않는 것은?",["AW CAR","FR CAR","RR CAR","AR CAR"],4,0,"ew20190921"],["ew20190921-36",1,"","2019-09-21",36,62,"성냥의 연소현상에 대한 설명으로 틀린 것은?",["성냥의 발화구조는 성냥개비의 두약 부분과 용기의 측약 부분이 서로 마찰 시 먼저 측약 부분의 적린이 발화하고 그 발화에너지에 의해 두약 부분이 폭발적으로 연소하는 구조이다.","성냥의 연소온도는 불꽃의 상태에 따라 다르지만 발화한 시점에서 500℃. 정상연소 불꽃에서 1500~1800℃이며, 치화상태(맹렬한 연소상태)에서 최고온도는 두약 부분이 700℃이다.","성냥의 발화온도는 일반적으로 100~200℃이며, 제조사별로 크게 차이가 없어 일정하다.","일반적으로 성냥 1개비의 연소시간은 수직상방향에서 평균 43초, 대각선 상방향에서 35초 정도가 소요되는 것으로 알려져 있다."],3,0,"ew20190921"],["ew20190921-37",1,"T038","2019-09-21",37,79,"선박용 기자재의 특성으로 옳지 않은 것은?",["내진성, 내식성","유지보수 용이성","가연성","선체운동에 대한 충분한 적응성"],3,0,"ew20190921"],["ew20190921-38",1,"T034","2019-09-21",38,83,"방화의 동기별 유형에서 방화로 분류되지 않는 것은?",["피로로 인한 과실","밤죄 전ㆍ후 증거인멸","보험사기 등 경제적 이득","정신질환"],1,0,"ew20190921"],["ew20190921-39",1,"T041","2019-09-21",39,65,"다음 수종 중 내화력이 가장 강한 수종은?",["소나무","아까시나무","벚나무","동백나무"],4,0,"ew20190921"],["ew20190921-40",1,"T049","2019-09-21",40,84,"전기다리미에 200V의 전압을 가했더니 3A의 전류가 흘렀다. 이 때 전기다리미가 소비하는 전력은 몇 W인가?",["150","300","400","600"],4,0,"ew20190921"],["ew20190921-41",2,"T069","2019-09-21",41,87,"화재현장의 증거물에 대한 사진 촬영 방법으로 옳지 않은 것은?",["발견 당시의 모습 그대로 촬영해야 한다.","현장에서 수거의 절차가 명확하도록 촬영해야 한다.","사진의 원본성이 유지되어야 한다.","필요 시 촬영하기 좋은 위치로 이동시켜 촬영한다."],4,0,"ew20190921"],["ew20190921-42",2,"T084","2019-09-21",42,76,"화재조사 및 보고규정상 질문기록서에 기입할 내용으로 틀린 것은?",["화재발생 일시 및 장소","질문일시 및 질문장소","답변자의 주민등록번호(외국인의 경우, 외국인등록번호)","화재번호"],3,0,"ew20190921"],["ew20190921-43",2,"T081","2019-09-21",43,78,"화재조사 및 보고규정상 화재조사서류에 대한 설명으로 옳지 않은 것은?",["화재조사서류 작성 시 소실정도는 전소, 반소, 부분소, 즉소로 구분한다.","화재조사서류 작성은 화재에 필요한 정보자료를 얻고자 하는 데 있다.","화재조사서류는 화재조사의 결과를 기록하는 문서이다.","화재조사서류는 민ㆍ형사상 유력한 증거자료로 활용될 수 있다."],1,0,"ew20190921"],["ew20190921-44",2,"T088","2019-09-21",44,80,"타임라인과 마인드매핑에 대한 설명으로 옳지 않은 것은?",["상대적시간은 추정을 근거로 한다.","타임라인은 증거와 정보의 조합이고, 마인드매핑은 사건이 일어난 시간의 재구성이다.","타임라인의 정확성은 가설의 신뢰도를 높여 준다.","마인드매핑은 수집된 정보를 바탕으로 객관적 사실을 조합하는 과정이다."],2,0,"ew20190921"],["ew20190921-45",2,"","2019-09-21",45,78,"다음 중 목재 탄화물에 관한 설명으로 거리가 먼 것은?",["탄화심도는 종종 화재의 지속시간을 측정하는데 사용된다.","탄화심도는 탄화 블리스터(Blister)의 중앙에서 측정된다.","탄화속도는 목재가 열원을 향하는 방향에 영향을 받지 않는다.","엘리게이터(alligator)는 목재 탄화패턴의 하나다."],3,0,"ew20190921"],["ew20190921-46",2,"T069","2019-09-21",46,89,"화재현장 촬영 시의 유의사항으로 옳지 않은 것은?",["각 방위별로 출화의 방향성에 착안하여 구조물의 형태를 확인하여 촬영한다.","발화건물과 인접 도로 및 주변 건물과 경계선을 파악하여 촬영한다.","높은 곳에서 전체적으로 연소 확대 상황을 관찰하면서 촬영한다.","너무 많은 사진 자료는 혼란을 야기하므로 사진 촬영은 발화대상물에만 초점을 맞추어 촬영한다."],4,0,"ew20190921"],["ew20190921-47",2,"T075","2019-09-21",47,77,"화재현장 증거물의 오염을 야기하는 행위에 대한 설명으로 틀린 것은?",["수집과정에서 조사자의 잘못된 취급","현장통제 미흡으로 야기되는 불특정인의 현장출입","연소되거나 탄화된 물체와의 이질적 혼합","촉진제 확인을 위한 밀봉조치로 환기 불량"],4,0,"ew20190921"],["ew20190921-48",2,"T080","2019-09-21",48,83,"화재현장에서 증거물을 수집하는 방법으로 옳은 것은?",["고체 촉진제 증거물을 수집할 경우 유리병은 적당하지 않다.","유사한 액체증거물을 수집할 경우 하나의 용기를 사용한다.","휘발성 증거물을 수집할 경우 일반 비닐봉지(폴리에틸렌)를 사용한다.","액체증거물을 보관하는 경우 용기를 완전히 밀봉해야 한다."],4,0,"ew20190921"],["ew20190921-49",2,"T087","2019-09-21",49,87,"사후에 혈액이 중력의 작용으로 몸의 저부에 있는 모세혈관 내로 침강하여 외 표피층에 착색이 되어 나타나는 현상은?",["매(煤)","시반(屍班)","부종(浮腫)","울혈(鬱血)"],2,0,"ew20190921"],["ew20190921-50",2,"T093","2019-09-21",50,88,"화상에 대한 설명으로 틀린 것은?",["화염에 의한 손상은 화상으로 볼 수 있으나 복사열에 의한 손상은 화상으로 볼 수 없다.","넓은 의미로 볼 때 고열이 피부에 작용하여 일어나는 국소적 및 전신적 장애를 화상이라 한다.","뜨거운 기체나 액체에 의한 손상을 탕상이라고 하며, 이 또한 화상으로 볼 수 있다.","화상이나 탕상으로 인한 사망을 일반적으로 화상사라고 한다."],1,0,"ew20190921"],["ew20190921-51",2,"T097","2019-09-21",51,68,"화상성 쇼크라고도 하며 화상을 입고 나서 상당시간 경과한 후에 증상이 발현되어 2~3일 후에 사망하게 되는 경우를 지칭하는 용어로 옳은 것은?",["속발성 쇼크","자극성 쇼크","원발성 쇼크","저체액성 쇼크"],1,0,"ew20190921"],["ew20190921-52",2,"T077","2019-09-21",52,81,"화재증거물수집관리규칙상의 증거물 수집 시 주의사항에 대한 설명으로 옳지 않은 것은?",["증거물의 소손 또는 소실 정도가 심하여 증거물의 일부분 또는 전체가 유실될 우려가 있는 경우는 증거물을 밀봉하여야 한다.","증거물을 수집할 때는 휘발성이 높은 것에서 낮은 순서로 진행해야 한다.","증거물의 수집 장비는 증거물의 종류 및 형태에 따라 적절한 구조의 것이어야 한다.","증거물이 파손될 우려가 있는 경우에는 충격금지 및 취급방법에 대한 주의사항을 증거물의 포장 내측에 적절하게 표기하여야 한다."],4,0,"ew20190921"],["ew20190921-53",2,"T093","2019-09-21",53,86,"다음 중 화상의 위험도에 대한 설명으로 옳지 않은 것은?",["어린이는 같은 정도의 범위라도 어른보다 더 위험하다.","국소적인 화상의 경우가 화상면적이 넓은 경우보다 더 치명적이다.","노인은 회복이 지연되거나 합병증이 일어나기 쉽다.","주요 장기에 질환이 있는 경우 정상인보다 위험하다."],2,0,"ew20190921"],["ew20190921-54",2,"T095","2019-09-21",54,86,"인화성액체(촉진제)에 대한 설명으로 옳지 않은 것은?",["화재현장에서 인화성액체가 발견되었다면, 방화 외의 다른 가능성을 배제한다.","탐지견은 인화성액체를 감지하는 데 도움을 줄 수 있다.","인화성액체의 확인을 위해 대조시료를 채취한다.","일반적으로 가솔린, 등유, 경유, 시너 등이 촉진제로 사용된다."],1,0,"ew20190921"],["ew20190921-55",2,"T085","2019-09-21",55,53,"일반적으로 건강한 성인의 경우 혈액 내 일산화탄소 포화도의 생리학적 영향으로 옳지 않은 것은?",["10~20% : 약한 두통, 피부혈관의 팽창","20~30% : 극심한 두통, 과도한 맥박","30~40% : 어지럼, 의식장애, 구토","40~50% : 호흡정지, 사망"],4,0,"ew20190921"],["ew20190921-56",2,"T078","2019-09-21",56,88,"화재현장 증거물의 수집 기본원칙에 대한 설명으로 틀린 것은?",["맨손으로 만지지 말고 일회용 장갑을 착용하여 오염을 최소화한다.","증거물에 부착된 오염물질을 강제로 털어 내거나 떼어 내려고 하지 않도록 한다.","증거물 수집은 가능한 한 빨리 수거하도록 한다.","다른 곳에서 발견된 동일한 물질은 같은 용기에 넣어 수거한다."],4,0,"ew20190921"],["ew20190921-57",2,"T070","2019-09-21",57,76,"사진촬영 시 노출 및 초점에 대한 설명으로 옳지 않은 것은?",["화재현장은 기본적으로 자연적 광량이 충분하여 초점을 맞추기가 쉽다.","화재가 발생한 구조물에 대하여 노출설정이 잘못되면 현장설명이 달라질 수도 있다.","조리개의 값을 높일 경우 피사계 심도를 낮게 촬영할 수 있다.","조리개의 값을 낮출수록 밝은 사진을 촬영할 수 있다."],1,0,"ew20190921"],["ew20190921-58",2,"T077","2019-09-21",58,87,"화재증거물수집관리규칙상 증거물의 포장, 보관, 이동에 대한 설명으로 옳지 않은 것은?",["증거물의 포장은 보호상자를 사용하여 포괄 포장함을 원칙으로 한다.","수집일시, 증거물번호, 수집장소 등 일련의 정보를 기재하여 부착한다.","증거물 보관ㆍ이동시 증거 관리가 변경되었을 때는 기타 사항을 기재한다.","증거물의 보관은 전용실 또는 전용함에 보관해야 한다."],1,0,"ew20190921"],["ew20190921-59",2,"T069","2019-09-21",59,73,"화재현장 촬영 시 주의 사항으로 가장 거리가 먼 것은?",["발화지점뿐만 아니라 전체 화재현장을 촬영한다.","연소가 약한 곳에서 강한 곳으로 이동하며 촬영한다.","화재건물의 4방향에서 촬영한다.","화재건물 내부에서 외부로 이동하며 촬영한다."],4,0,"ew20190921"],["ew20190921-60",2,"T069","2019-09-21",60,56,"화재현장 사진촬영 요령에 대한 설명으로 옳지 않은 것은?",["소손현장의 전경을 촬영한다.","발굴 전의 발화지점 부근을 촬영한다.","관계자의 진술 내용에 맞추어 중점적으로 촬영한다.","복원 후의 상황을 촬영한다."],3,0,"ew20190921"],["ew20190921-61",3,"T116","2019-09-21",61,63,"화재조사 및 보고규정상 재구입비에 대한 설명으로 옳은 것은?",["화재 당시의 피해물과 같거나 비슷한 것을 재건축(설계감리비 포함) 또는 재취득하는데 필요한 금액","피해물의 종류, 손상 상태 및 정도에 따라 피해액을 적정화시키기 위한 보정 금액","피해물의 경제적 내용연수가 다한 경우와 동일한 가치 물품의 재구입비","화재 당시에 피해물의 재구입비에 대한 현재가의 비율로 환산한 금액"],1,0,"ew20190921"],["ew20190921-62",3,"T123","2019-09-21",62,53,"화재피해 대상 건물의 경과연수를 산정할 때, 재건축비의 50% 미만의 비용으로 개ㆍ보수한 이력이 있는 건축물의 경과연수 산정기준으로 옳은 것은?",["최초 건축년도를 기준으로 경과연수를 산정한다.","개ㆍ보수한 시점을 기준으로 경과연수를 산정한다.","최초 건축년도를 기준으로 한 경과연수와 개ㆍ보수한 때를 기준으로 한 경과연수를 합산 평균하여 경과연수를 산정한다.","최초 건축비용과 개ㆍ보수 당시 소요비용을 각각 산정하여 합산한다."],1,0,"ew20190921"],["ew20190921-63",3,"T124","2019-09-21",63,86,"화재조사 및 보고규정 상 화재현장에 출동한 소방대원 중 119안전센터 등의 선임자가 작성ㆍ입력하는 보고서는?",["질문기록서","화재피해조사서","화재현장조사서","화재현장 출동보고서"],4,0,"ew20190921"],["ew20190921-64",3,"T109","2019-09-21",64,75,"화재조사 및 보고규정상 긴급상황보고에 해당하는 화재조사 결과의 보고기한으로 옳은 것은? (단, 화재의 정확한 조사를 위하여 조사기간이 필요한 때는 제외한다.)",["화재 인지로부터 15일 이내","화재 인지로부터 30일 이내","화재 인지로부터 50일 이내","화재 인지로부터 60일 이내"],2,0,"ew20190921"],["ew20190921-65",3,"T106","2019-09-21",65,70,"화재현장 조사서의 발화열원의 분류 항목에 포함되는 것은?",["부주의","전기적 요인","가스누출(폭발)","폭발물, 폭죽"],4,0,"ew20190921"],["ew20190921-66",3,"T113","2019-09-21",66,68,"화재로 인한 부대설비의 피해액을 산정하는 공식은?",["건물신축단가×소실면적×설비종류별×재설비비율×[1-(0.8×경과년수/내용연수)]×손해율","건물신축단가×소실면적×설비종류별×재설비비율×[1-(0.8×내용년수/경과연수)]×손해율","건물신축단가×소실면적×설비종류별×재설비비율×[1-(0.9×경과년수/내용연수)]×손해율","건물신축단가×소실면적×설비종류별×재설비비율×[1-(0.9×내용년수/경과연수)]×손해율"],1,0,"ew20190921"],["ew20190921-67",3,"T113","2019-09-21",67,57,"화재피해액 산정 방법으로 틀린 것은?",["잔존물제거:화재피해액×20%","재고자산:회계장부상 현재가액×손해율","구축물:회계장부상 구축물가액×손해율","기타:피해당시의 현재가를 재구입비로 하여 피해액을 산정"],1,0,"ew20190921"],["ew20190921-68",3,"","2019-09-21",68,82,"화재조사 및 보고규정상 용어의 정의로 틀린 것은?",["발화지점:열원과 가연물이 상호작용하여 화재가 시작된 지점","연소확대물:연소가 확대되는데 있어 결정적 영향을 미친 가연물","화재현장:화재가 발생하여 소방대 및 관계자 등에 의해 소화활동이 행하여지고 있는 장소","감식:화재와 관계되는 모든 현상에 대하여 필요한 실험을 행하고 그 결과를 근거로 화재원인을 밝히는 자료를 얻는 것"],4,0,"ew20190921"],["ew20190921-69",3,"T125","2019-09-21",69,63,"화재유형별조사서(임야화재)의 작성에 대한 설명으로 틀린 것은?",["논밭두렁의 화재는 들불에 속한다.","묘지에서 발생한 화재는 들불에 속한다.","피해사랑 중 산림피해면적은 헥타르(ha)로 기재한다.","산불화재 시 소유주체에 따라 국유림, 공유림, 사유림으로 구분한다."],3,0,"ew20190921"],["ew20190921-71",3,"T106","2019-09-21",71,70,"화재조사 및 보고규정상 화재현장 조사서의 발화요인 분류에 해당하지 않는 것은?",["전기적 요인","기계적 요인","부주의","담뱃불"],4,0,"ew20190921"],["ew20190921-72",3,"T116","2019-09-21",72,44,"잔가율 및 현재가를 구하는 공식으로 틀린 것은?",["현재가=재구입비-잔가율","잔가율=100%-감가수정율","잔가율=(재구입비-감가수정액)/재구입비","잔가율=1-(1-최종잔가율)×(경과연수/내용연수)"],1,0,"ew20190921"],["ew20190921-73",3,"T114","2019-09-21",73,47,"건물의 소손 정도에 따른 손해율 산정 시 천장, 벽, 바닥 등 내부마감재 들이 소실된 경우의 손해율은 얼마인가? (단, 공장, 창고는 제외한다.)",["20%","40%","60%","80%"],2,0,"ew20190921"],["ew20190921-74",3,"T108","2019-09-21",74,83,"화재조사 및 보고규정상 소방서장이 화재조사서류(사진포함)를 문서로 기록하고 전자기록 등의 보존방법에 따라 보존하여야 하는 기간은?",["2년","5년","10년","영구보존"],4,0,"ew20190921"],["ew20190921-75",3,"T107","2019-09-21",75,52,"화재로 인한 간이평가방식의 피해액 산정에 있어 건물과 별도로 내부영업시설에 대하여 피해액을 산정해야 하는 경우, 자동차 및 트레일러 제조업종 영업시설 자산의 내용연수는?",["3년","6년","9년","12년"],3,0,"ew20190921"],["ew20190921-76",3,"T131","2019-09-21",76,76,"치외법권지역 등 조사권을 행사할 수 없는 경우의 조사서류 작성에 대한 설명으로 옳은 것은?",["화재현장 출동보고서만 작성한다.","화재현장 출동보고서, 질문기록서, 화재발생 종합보고서를 모두 작성한다.","치외법권지역은 조사권을 행사할 수 없으므로 보고서를 작성하지 않아도 된다.","조사 가능한 내용만 조사하여 화재발생 종합보고서 내지 화재현장조사서 중 해당서류를 작성한다."],4,0,"ew20190921"],["ew20190921-77",3,"T113","2019-09-21",77,70,"스프링클러 설비의 m2당 설치단가가 10000원이다. 1층 500m2, 2층 400m2, 3층 100m2에 설치된 설비가 소실된 경우 재설비 금액은?",["1000000원","10000000원","15000000원","20000000원"],2,0,"ew20190921"],["ew20190921-78",3,"T111","2019-09-21",78,81,"화재현황조사서 기재사항이 아닌 것은?",["발화열원","방화동기","발화관련 기기","화재발생 장소 및 유형"],2,0,"ew20190921"],["ew20190921-79",3,"T124","2019-09-21",79,54,"화재현장 출동보고서 작성 시 기재사항이 아닌 것은?",["동원인력","현장도착시 발견사항","소방대 이외의 강제적인 진입흔적","도착하여 처음 실행한 일의 지점 및 유형"],1,0,"ew20190921"],["ew20190921-80",3,"T125","2019-09-21",80,74,"건축ㆍ구조물 화재의 화재유형별 조사서 작성에 대한 설명으로 옳은 것은?",["연소 확대범위는 발화층으로 한정한다.","특정소방대상물의 분류 중 교정시설은 제외한다.","장소의 시설용도 분류 중 단독주택은 제외한다.","건물상태는 사용중, 철거중, 공가, 공사중으로 나눈다."],4,0,"ew20190921"],["ew20190921-81",4,"","2019-09-21",81,70,"화재로 인한 재해보상과 보험가입에 관한 법률에서 외국인 등의 소유 건물에 대한 특례에 해당하는 건물로 옳지 않은 것은?",["대한민국에 주둔하는 외국 군대가 소유하는 건물","대한민국에 파견된 외국의 대사ㆍ공사가 소유하는 건물","군사용 건물과 외국인 소유 건물로서 행정안전부장관령으로 정하는 건물","대한민국에 파견된 국제연합의 기관 및 그 직원(외국인만 해당한다.)이 소유하는 건물"],3,0,"ew20190921"],["ew20190921-84",4,"T147","2019-09-21",84,59,"제조물책임법에서 규정하는 손해배상책임을 지는 자의 배상책임 면책 기준 중 옳지 않은 것은?",["제조업자가 해당 제조물을 공급하지 아니하였다는 사실을 입증한 경우","제조업자가 해당 제조물을 공급한 당시의 과학ㆍ기술수준으로는 결함의 존재를 발견할 수 없었다는 사실을 입증한 경우","제조물 결함이 제조업자가 해당 제조물의 결함이 발생할 당시의 법령이 정하는 기준을 준수함으로써 발생한 사실을 입증한 경우","원재료나 부품의 경우에는 그 원재료나 부품을 사용한 제조물 제조업자의 설계 또는 제작에 관한 지시로 인하여 결함이 발생하였다는 사실을 입증한 경우"],3,0,"ew20190921"],["ew20190921-85",4,"T154","2019-09-21",85,67,"형법상의 진화방해에 명시된 “진화용의 시설 또는 물건”에 대한 설명 중 옳은 것은?",["처음부터 소방용으로 제작되지 않아도 된다.","진화용 시설 또는 물건은 누구의 소유이건 그 소유관계를 불문한다.","일반통신시설은 진화용 시설 또는 물건에 포함된다.","소방자동차는 진화용 시설 또는 물건에 속하지 않는다."],2,0,"ew20190921"],["ew20190921-86",4,"","2019-09-21",86,65,"국가배상법상 국가공무원의 위법행위로 인하여 제3자에게 발생한 손해를 국가가 배상한 후 해당 공무원에게 행사하는 구상권에 관한 설명으로 옳은 것은?",["해당 공무원에게 고의 또는 중대한 과실이 있는 경우에 구상권을 행사할 수 있다.","해당 공무원에게 고의 또는 중대한 과실이 있는 경우라도 인적피해가 없으면 구상권을 행사할 수 없다.","해당 공무원에게 고의 또는 중대한 과실이 없어도 금전적 손실이 발생하면 구상권을 행사할 수 있다.","해당 공무원에게 고의 또는 중대한 과실이 있으면 피해자 및 그 대리인은 그 공무원에게 구상권을 행사할 수 있다."],1,0,"ew20190921"],["ew20190921-87",4,"T156","2019-09-21",87,40,"실화책임에 관한 법률의 적용범위에 대하여 올바르게 기술한 것은?",["실화로 인하여 화재가 발생한 경우 화재건물 부분에 대한 손해배상 청구에 한하여 적용한다.","실화로 인하여 화재가 발생한 경우 간접적 피해를 제외한 직접적 피해 부분에 대한 손해배상 청구에 한하여 적용한다.","실화로 인하여 화재가 발생한 경우 연소로 인한 부분에 대한 손해배상청구에 한하여 적용한다.","실화로 인하여 화재가 발생한 경우 화재피해 부분에 대한 손해배상청구에 한하여 적용한다."],3,0,"ew20190921"],["ew20190921-88",4,"T159","2019-09-21",88,71,"화재조사 및 보고규정에 따른 건물의 동수 산정 기준 중 옳지 않은 것은?",["구조에 관계없이 지붕 및 실이 하나로 연결되어 있는 것은 같은 동으로 본다.","목조 또는 내화조 건물의 경우 격벽으로 방화구획이 되어 있는 경우는 다른 동으로 한다.","독립된 건물과 건물 사이에 차광막, 비막이 등의 덮개를 설치하고 그 밑을 통로 등으로 사용하는 경우는 다른 동으로 한다.","내화조 건물의 옥상에 목조 또는 방화구조 건물이 별도 설치되어 있는 경우는 다른 동으로 한다. 다만, 이들 건물이 기능상 하나인 경우는 같은 동으로 한다."],2,0,"ew20190921"],["ew20190921-89",4,"T168","2019-09-21",89,72,"화재로 인한 재해보상과 보험가입에 관한 법률의 내용으로 옳지 않은 것은?",["한국화재보험협회는 사단법인으로 한다.","특수건물의 소유자는 특약부화재보험계약을 2년 마다 갱신하여야 한다.","특수건물의 소유자는 손해배상책임에 관하여는 이 법에서 규정한 것 외에는 민법에 따른다.","소방청장은 협회의 업무 중 화재예방 및 소화시설에 대한 안전점검 업무에 관하여 감독상 필요한 명령을 할 수 있다."],2,0,"ew20190921"],["ew20190921-92",4,"T143","2019-09-21",92,69,"소방기본법 시행규칙에 따른 화재원인조사의 종류로 옳지 않은 것은?",["연소상황 조사","인명피해 조사","피난상황 조사","소방시설 등 조사"],2,0,"ew20190921"],["ew20190921-93",4,"T138","2019-09-21",93,84,"소방기본법에 따라 소방서장이 화재조사 결과 방화 또는 실화의 혐의가 있다고 인정하는 때 지체 없이 그 사실을 알려야 할 대상은?",["시ㆍ도지사","관할 구청장","소방청장","관할 경찰서장"],4,0,"ew20190921"],["ew20190921-94",4,"T165","2019-09-21",94,53,"「화재로 인한 재해보상과 보험가입에 관한 법률」에서 특수건물 소유자가 가입하는 보험금액으로 옳지 않은 것은?",["화재보험의 경우 특수건물의 시가(時價)에 해당하는 금액","손해배상책임을 담보하는 보험 중 사망의 경우 피해자 1명마다 1억원 이상으로서 대통령령으로 정하는 금액","손해배상책임을 담보하는 보험 중 부상의 경우 피해자 1명마다 사망자에 대한 보험금액의 범위에서 대통령령으로 정하는 금액","손해배상책임을 담보하는 보험 중 제물에 대한 손해가 발생한 경우 화재 1건마다 1억원 이상으로서 국민의 안전 및 특수건물의 화재위험성 등을 고려하여 대통령령으로 정하는 금액"],2,0,"ew20190921"],["ew20190921-96",4,"T142","2019-09-21",96,72,"화재조사 및 보고규정에서 사용하는 용어의 정의 중 옳은 것은?",["“발화열원”이란 화재가 발생한 부위를 말한다.","“조사관”이란 화재조사업무를 관리하는 소방공무원을 말한다.","“발화요인”이란 발화에 관련한 불꽃 또는 열을 발생시킨 기기 또는 장치나 제품을 말한다.","“연소확대물”이란 연소가 확대되는데 있어 결정적 영향을 미친 가연물을 말한다."],4,0,"ew20190921"],["ew20190921-97",4,"T142","2019-09-21",97,58,"화재에 의한 재산피해로 볼 수 없는 것은?",["가구가 열로 탄화되었다.","옷감이 소화용수로 젖어 사용하지 못한다.","온수배관이 폭발되어 텔레비전이 파손되었다.","도자기가 반출되던 중 표면이 파손되었다."],3,0,"ew20190921"],["ew20190921-98",4,"T165","2019-09-21",98,68,"화재로 인한 재해보상과 보험가입에 관한 법률상 특수건물 화재 발생 시 소유자의 손해배상책임의 한계로 옳은 것은?",["배상은 과실이 있는 경우에만 해당한다.","그 건물의 화재로 인하여 다른 사람이 사망하거나 부상을 입었을 때에는 과실이 없는 경우에도 그 손해를 배상할 책임이 있다.","특약부화재보험에 부가하여 화재 이외에 풍재ㆍ수재 또는 건물의 무너짐 등으로 인한 손해를 담보하는 보험에 가입할 수 없다.","특수건물 소유자의 손해배상책임에 관하여는 화재로 인한 재해보상과 보험가입에 관한 법률에 규정하는 것 이외에는 상법에 따른다."],2,0,"ew20190921"],["ew20190921-99",4,"T158","2019-09-21",99,65,"화재조사 및 보고규정에 따른 화재의 유형에 대한 구분으로 옳지 않은 것은?",["건축ㆍ구조물 화재","위험물ㆍ가스제조소 등 화재","산림화재","기타화재"],3,0,"ew20190921"],["ew20190921-100",4,"T140","2019-09-21",100,44,"화재조사 및 보고규정상 조사본부의 설치운영에 관한 사항으로 옳지 않은 것은?",["조사본부 설치ㆍ운영 시 소방서 조사요원은 소방본부 조사업무를 지원하여야 한다.","조사관은 소방본부 및 소방서의 화재조사업무를 담당한다.","조사본부장은 화재현장 지휘자들로부터 화재조사에 관련된 필요정보를 인수받아 조사의 원활한 수행을 기하도록 하여야 한다.","조사본부장은 소방행정상 필요한 경우와 외부기관으로부터 조사내용의 발표 요청이 있는 경우에는 특별한 사유가 없는 한 그 내용을 발표한다."],1,0,"ew20190921"],["ew20200606-1",0,"T018","2020-06-06",1,84,"다음 중 A급 화재에서만 발생할 수 있는 위험현상으로 옳은 것은?",["보일 오버(boil over)","슬롭 오버(slop over)","플레임 오버(flame over)","프로스 오버(froth over)"],3,0,"ew20200606"],["ew20200606-2",0,"T010","2020-06-06",2,80,"가솔린의 연소범위(vol%)가 1.4~7.6일 때 위험도로 옳은 것은? (단, 소수 둘째자리에서 반올림할 것)",["0.8","1.2","4.4","6.4"],3,0,"ew20200606"],["ew20200606-3",0,"","2020-06-06",3,78,"화재현장의 관찰 방법으로 틀린 것은?",["소실 붕괴된 부분에서는 복원적인 관점에서 관찰한다.","발화원인이 될 수 있는 가연물에 유의하여 조사한다.","건물 구조재 수용품 등의 소실 상황을 통하여 연소의 방향을 고려한다.","소손 및 탄화 정도가 강한 부분에서 약한 부분으로 이동하며 관찰한다."],4,0,"ew20200606"],["ew20200606-4",0,"T016","2020-06-06",4,76,"다음 중 화재현장 출입금지구역의 범위를 확대하여야 할 이유로 옳지 않은 것은?",["진화 후에 행방불명자를 확인한 경우","구조물 등이 광범위하게 소손되어 바닥에 연소 낙하물이나 퇴적물이 많이 쌓인 경우","건물 전체가 소손된 상황으로 연소 진행방향이 확인되지 않을 때","발화지점 부근의 목격상황에 대한 진술이 제각기 달라 발화지점이 불명확할 때"],1,0,"ew20200606"],["ew20200606-5",0,"T013","2020-06-06",5,63,"소방기본법령상 화재조사전담부서에서 갖추어야 할 발굴 장비로 옳지 않은 것은?",["전동그라인더","슈미트해머","다용도 칼","빗자루"],2,0,"ew20200606"],["ew20200606-6",0,"T020","2020-06-06",6,74,"다음 중 가연성 물질에 해당하는 것은?",["아르곤","산화알루미늄","일산화탄소","헬륨"],3,0,"ew20200606"],["ew20200606-7",0,"","2020-06-06",7,74,"화재조사 및 보고규정상 건물의 동수 산정방법에 관한 설명 중 옳은 것은?",["목조 또는 내화조 건물이 격벽으로 방화구획되어 있는 경우 2개의 동으로 본다.","구조에 관계없이 지붕 및 실이 하나로 연결되어 있는 것은 2개의 동으로 본다.","건물의 외벽을 이용하여 실을 만들어 헛간, 작업실 및 사무실 등의 용도로 사용하고 있는 것은 주건물과 1동으로 본다.","독립된 건물과 건물 사이에 차광막, 비막이 등의 덮개를 설치하고 그 밑을 통로 등으로 사용하는 경우는 동일동으로 본다."],3,0,"ew20200606"],["ew20200606-8",0,"T009","2020-06-06",8,81,"다음 중 폭발 위력의 지표로 사용될 수 있는 자료로 옳지 않은 것은?",["파편의 비행거리","무너진 벽의 종류와 구조","폭발 시점","폭심부의 크기 및 깊이"],3,0,"ew20200606"],["ew20200606-9",0,"","2020-06-06",9,87,"이산화탄소 소화약제의 주된 소화효과로 옳은 것은?",["냉각효과","질식효과","부촉매효과","억제효과"],2,0,"ew20200606"],["ew20200606-10",0,"T016","2020-06-06",10,91,"다음 중 화재현장에서 확보해야하는 화재현장의 관계자의 특징으로 가장 거리가 먼 것은?",["화상을 입었거나 의류가 타버린 자","의류가 물에 젖어 있거나 오손되어 있는 자","현장부근에 말쑥한 정장차림의 구경하고 있는 자","가재도구를 집어 들고 있거나 물건을 반출하고 있는 자"],3,0,"ew20200606"],["ew20200606-11",0,"T016","2020-06-06",11,88,"다음 중 발굴이 끝난 후의 화재 전 상황으로 복원하는 요령으로 옳지 않은 것은?",["형체가 소실되어 배치가 불가능한 것은 대용품을 사용하되, 대용품이라는 것이 인식되도록 한다.","관계인을 입회시켜 복원상황을 확인시킨다.","잔존물이 파손되지 않도록 잦은 위치이동은 하지 않는다.","불명확한 것은 예측을 통하여 복원한다."],4,0,"ew20200606"],["ew20200606-12",0,"T013","2020-06-06",12,88,"소방기본법령상 “화재조사전담부서의 설치, 운영 등”의 조항에 명시된 내용으로 옳지 않은 것은?",["화재조사자의 포상","화재조사자의 자격","화재조사전담부서장의 업무","화재조사에 필요한 장비 및 시설"],1,0,"ew20200606"],["ew20200606-13",0,"T001","2020-06-06",13,83,"다음 중 화재플럼(Fire Plume)에 의해 수직벽면에 생성되는 패턴으로 옳지 않은 것은?",["V 패턴","모래시계 패턴","도넛형태 패턴","U 패턴"],3,0,"ew20200606"],["ew20200606-14",0,"T018","2020-06-06",14,70,"다음의 건물 구획실 화재에 대한 설명 중 옳은 것은?",["일반적으로 최성기의 구획실 화재 온도는 500~600℃까지 도달한다.","연기의 이동은 소화작용에서 발생하는 부력에 의존한다.","환기지배형 화재에서는 CO와 연기의 발생량이 많아진다.","대부분의 구획실과 건물은 최성기에서 연료지배형이 된다."],3,0,"ew20200606"],["ew20200606-15",0,"T027","2020-06-06",15,73,"화재 시 발생하는 박리 현상(spalling)의 원인에 대한 설명으로 옳은 것은?",["콘크리트에 포함된 수분의 증발 및 팽창","철근 또는 철망 및 주변 콘크리트 간의 불균일한 수축","콘크리트 혼합물과 골재 간의 균일한 팽창","화재에 노출된 표면과 슬래브 내장재 간의 균일한 팽창"],1,0,"ew20200606"],["ew20200606-16",0,"T018","2020-06-06",16,79,"다음의 구획실 화재 성장단계에 대한 설명 중 옳은 것은?",["초기→플래시오버→쇠퇴기→최성기→자유연소 순으로 진행된다.","자유연소단계는 환기지배형 연소이며 복사열에 의해 확산된다.","플래시오버 현상은 최성기 전에 주로 발생한다.","최성기는 연료지배형 연소단계이며, 접염방식으로 확산된다."],3,0,"ew20200606"],["ew20200606-17",0,"T018","2020-06-06",17,66,"다음 중 환기지배형 화재에 대한 설명으로 옳은 것은?",["대부분 화재 초기에 발생한다.","연료공급에 좌우된다.","환기량이 크다.","불완전연소에 가깝다."],4,0,"ew20200606"],["ew20200606-18",0,"T003","2020-06-06",18,74,"목재 균열흔의 종류로 옳지 않은 것은?",["고소흔","열소흔","완소흔","강소흔"],1,0,"ew20200606"],["ew20200606-19",0,"T006","2020-06-06",19,76,"전도 열전달 형태와 관계되는 법칙으로 적합한 것은?",["퓨리에(Fourier)의 법칙","플랭크(Planck)의 법칙","뉴튼(Newton)의 법칙","피크(Fick)의 법칙"],1,0,"ew20200606"],["ew20200606-20",0,"T014","2020-06-06",20,85,"다음 중 화재조사자가 유의해야 할 사항으로 옳은 것은?",["관계자 또는 목격자의 진술에 근거하여 주관적 방법으로 접근한다.","정확한 화재조사를 위해서는 개인의 권리를 침해할 수도 있다.","조사결과에 대한 보안 유지와 언론보도에 신중해야 한다.","타 조사기관 상호간에는 비밀을 유지하여야 한다."],3,0,"ew20200606"],["ew20200606-21",1,"","2020-06-06",21,85,"가스사고 형태별 분류에 해당하지 않는 것은?",["폭발","질식","중독","재질 불량"],4,0,"ew20200606"],["ew20200606-22",1,"","2020-06-06",22,68,"발화요인 분류 중 화학적 요인에 해당되지 않는 것은?",["역화","혼촉발화","자연발화","금수성 물질이 물과 접촉"],1,0,"ew20200606"],["ew20200606-23",1,"T048","2020-06-06",23,73,"전선의 소선 일부가 끊어져 발생하는 국부적인 저항치 증가 현상으로 나타나는 전기화재 현상에 해당하는 것은?",["트래킹","아산화동","반단선","그래파이트"],3,0,"ew20200606"],["ew20200606-24",1,"T034","2020-06-06",24,75,"방화에 사용되는 촉진제로 거리가 먼 것은?",["아세톤","시너","톨루엔","수산화나트륨"],4,0,"ew20200606"],["ew20200606-25",1,"T060","2020-06-06",25,54,"플라스틱의 일반적인 연소특성으로 틀린 것은?",["폴리염화비닐은 연소되면 염화수소 가스가 발생한다.","열가소성 플라스틱에는 아미노수지, 페놀수지, 에폭시수지 등이 있다.","플라스틱은 일반적으로 저분자 물질과 달리 온도에 따른 상변화가 명확하지 않다.","열경화성 플라스틱은 화염에 노출되면 표면이 고체 숯과 같이 되는 경향 때문에 내부로의 연소확대가 지연된다."],2,0,"ew20200606"],["ew20200606-26",1,"T041","2020-06-06",26,78,"상대습도별 산불발생위험도에 대한 설명으로 틀린 것은?",["상대습도가 60% 이상이면 산불이 매우 발생하기 쉽다.","상대습도가 40~50%면 산불이 발생하기 쉽고 연소 진행이 빠르다.","상대습도가 50~60%면 산불이 발생할 수 있으나 연소 진행이 느리다.","상대습도가 40% 이하면 산불 발생 시 진화가 곤란할 정도로 연소 진행이 빠르다."],1,0,"ew20200606"],["ew20200606-27",1,"T053","2020-06-06",27,72,"유연탄의 자연발화 위험성에 대한 설명으로 틀린 것은?",["주변온도가 높을수록 산화반응이 촉진된다.","괴상은 분말상보다 자연발화를 일으키기 쉽다.","채탄 직후의 석탄은 자연발화의 위험이 크다.","자연발화는 저탄장 등에 대량으로 쌓아둔 곳에서 일어나기 쉽다."],2,0,"ew20200606"],["ew20200606-28",1,"T036","2020-06-06",28,86,"나무, 천, 종이 및 가구와 같은 가연성 물질의 화재 분류(class)는?",["Class A","Class B","Class C","Class D"],1,0,"ew20200606"],["ew20200606-29",1,"T057","2020-06-06",29,75,"물질의 상태에 대한 설명으로 옳은 것은?",["물의 증발잠열은 80cal/g이다.","분자는 액체 상태일 떄 가장 자유롭게 운동할 수 있다.","온도 변화없이 상태 변화를 위해 필요한 열을 잠열이라 한다.","액체상태에서 열을 흡수하여 에너지가 증가하면 고체상태가 된다."],3,0,"ew20200606"],["ew20200606-30",1,"T035","2020-06-06",30,62,"항공기의 열전대 화재경고장치(thermocouple fire warning system) 중 배선시스템의 구성요소가 아닌 것은?",["감지 회로(detector circuit)","알람 회로(alarm circuit)","단락 회로(short circuit)","시험 회로(test circuit)"],3,0,"ew20200606"],["ew20200606-31",1,"T044","2020-06-06",31,71,"차량 충전장치와 시동장치에 대한 설명으로 틀린 것은?",["충전장치는 교류발전기(alternator), 레귤레이터(regulator)로 구성되며, 시동장치에는 스타터가 있다.","정류기 내에 있는 다이오드가 과전류 등으로 인해 그 기능을 잃은 경우, 다이오드가 소실되는 경우가 있다.","챠콜 캐니스터의 보디(body)는 금속재가 많은 점에서 2차적으로 착화하여도 연소되지 않으므로 관찰이 용이하다.","배터리 단자는 납 또는 납 합금으로 되어있어 화재열로 용이하게 녹아버리므로, 화재감식 시 배터리배선 터미널부의 용융 등도 확인한다."],3,0,"ew20200606"],["ew20200606-32",1,"T041","2020-06-06",32,51,"임황(林況)과 산불과의 관계에 대한 설명으로 옳은 것은?",["활엽수는 침엽수보다 산불위험성이 높다.","동령림은 이령림보다 산불위험성이 높다.","혼효림은 단순림보다 산불위험성이 높다.","수종별로 비교하면 음수는 양수보다 산불위험성이 높다."],2,0,"ew20200606"],["ew20200606-34",1,"T064","2020-06-06",34,54,"유류성분 감정기구인 가스크로마토그래피 분석의 장점으로 틀린 것은?",["물질이 유사한 여러 성분의 혼합계 분리에 매우 유효하다.","현장조사 시 휴대 및 가스 포집이 간편하며 성분판별이 가능하다.","가스 상태로 분석하기 때문에 조작도 간단하고 시간도 빠르다.","각 성분을 검출하여 그 양을 전기적인 신호로 기록계에 저장하고 도형적으로 기록함으로써 분석결과가 객관적이다."],2,0,"ew20200606"],["ew20200606-35",1,"T043","2020-06-06",35,71,"미소화원과 유염화원의 특징으로 옳은 것은?",["유염화원이 무염화원보다 에너지량(열량)이 적다.","유염화원은 무염화원보다 연소 확대에 필요한 시간이 짧다.","유염화원은 가연물과 접촉 시 바로 착화할 가능성이 무염화원보다 적다.","무염화원의 연소흔적은 깊이 탄 것은 보이지 않으며 연소범위가 넓은 경향을 보인다."],2,0,"ew20200606"],["ew20200606-36",1,"T034","2020-06-06",36,82,"방화의 주요 동기가 아닌 것은?",["실수","복수심","경제적 이익","범죄은폐"],1,0,"ew20200606"],["ew20200606-37",1,"T042","2020-06-06",37,69,"다음 중 담뱃불 접촉에 의한 물질의 착화 가능성이 가장 낮은 것은?",["톱밥류","마른 건초류","구겨진 신물지류","가솔린 증기"],4,0,"ew20200606"],["ew20200606-39",1,"T044","2020-06-06",39,73,"차량 배터리의 내부에서 화원이 될 가능성이 있는 원인에 속하지 않는 것은?",["외부 단자의 이완","과충전에 의한 과열","과충전에 의한 용단스파크불꽃","배터리 전해액 부족에 의한 내부 쇼트"],1,0,"ew20200606"],["ew20200606-40",1,"T033","2020-06-06",40,80,"방화행위의 입증요소로 틀린 것은?",["방화재료의 입수 경위가 밝혀져야 한다.","방화를 한 장소 및 소훼물이 있어야 한다.","방화의 수단과 방법이 실현가능하여야 한다.","방화의 수단이 가능한지 추상적으로 검토되어야 한다."],4,0,"ew20200606"],["ew20200606-41",2,"T084","2020-06-06",41,84,"관계자에게 질문할 경우 유의해야 하는 사항으로 틀린 것은?",["질문자는 자기신분을 밝힌다.","피질문자에 대한 선입견을 배제한다.","관계자에는 초기소화자, 피난자, 출동한 소방관도 포함된다.","실체적 진실을 밝히기 위해서는 어느 정도의 유도질문이나 상대방의 감정을 도발하는 질문기법도 필요하다."],4,0,"ew20200606"],["ew20200606-42",2,"T070","2020-06-06",42,77,"비디오카메라에 대한 설명으로 틀린 것은?",["목격자, 소유자 거주인, 혐의자와의 면담에서 사용할 수 있다.","비디오카메라의 장점은 보는 각도를 점차 이동하며 화재현장을 나타내는 것이다.","주밍-인(zooming-in)이나 과장확대기법을 적극적으로 사용한다.","가장 큰 장점으로 점진적으로 시각의 움직임에 의해 화재현장을 보여주는 능력이 있다."],3,0,"ew20200606"],["ew20200606-43",2,"T094","2020-06-06",43,77,"연소범위에 영향을 미치는 요인에 대한 설명으로 틀린 것은?",["온도가 높아질수록 연소범위는 좁아진다.","고온ㆍ고압의 경우 연소범위는 더욱 넓어진다.","압력이 높아지면 하한값은 크게 변하지 않으나 상한값은 높아진다.","혼합기를 이루는 공기의 산소농도가 높을수록 연소범위는 넓어진다."],1,0,"ew20200606"],["ew20200606-44",2,"T098","2020-06-06",44,52,"가스크로마토그래피(GC) 분석을 위한 용매추출법 중 잔류물을 추출하기 위한 용액으로 틀린 것은?",["크실렌","η-펜탄","이황화탄소","η-헥산"],1,0,"ew20200606"],["ew20200606-45",2,"T085","2020-06-06",45,59,"화재사 또는 흡연과 관련된 CO-Hb의 농도에 관한 설명으로 맞는 것은?",["일반적으로 비흡연자의 CO-Hb 농도는 0.01%이다.","40% 이상의 CO-Hb 농도는 CO자체만으로 사망할 수 있는 수치이다.","일반적으로 하루 두갑 이상 흡연하는 사람의 CO-Hb 농도는 3~8%이다.","40%이하의 CO-Hb 농도는 산소 부족, 심정지 또는 열화상으로 사망할 수 있다."],2,0,"ew20200606"],["ew20200606-46",2,"T092","2020-06-06",46,78,"냉온수기 자동온도 조절장치에서 절연체의 오염에 의한 트래킹 화재가 발생한 경우 수거하여야 할 증거물로 맞는 것은?",["응축기","시즈히터","압축기","서모스탯"],4,0,"ew20200606"],["ew20200606-47",2,"T069","2020-06-06",47,77,"화재현장 사진촬영에 대한 설명으로 틀린 것은?",["현장사진은 자료 확보를 위하여 충분하게 촬영한다.","연소 및 탄화된 형태를 조사자 시각에서 객관화하여 촬영한다.","발화건물 내부 촬영 시 소실된 부분을 국부적으로 촬영한다.","불필요한 피사체(인물 등) 촬영 금지, 접사 촬영 시 배경막 설치 후 촬영한다."],3,0,"ew20200606"],["ew20200606-48",2,"T071","2020-06-06",48,38,"화재증거물 사진의 촬영 및 유의사항에 관한 설명으로 틀린 것은?",["화재증거물은 오물을 제거하고 나서 찍는다.","접사로 촬영하는 경우 셔터스피드를 이용해 피사계 심도를 조절한다.","접사 촬영이 필요할 경우 매크로렌즈(접사용) 및 링스트로보 등을 활용한다.","피사계 심도는 어느 정해진 시간 동안에 초점이 맞는 가장 멀리 있는 사물과 가장 가까이 있는 사물의 거리이다."],2,0,"ew20200606"],["ew20200606-49",2,"","2020-06-06",49,80,"물리적 증거물의 감정 및 시험에 대한 설명으로 틀린 것은?",["발화 지점, 화재 특정 원인, 화재 확산에 기여한 요인 판별","물리적 증거물의 화학 조성을 확인하기 위한 감정 및 시험","물리적 증거물의 작동이나 오작동 또는 고장을 판단하기 위하여 설계가 충분한지 여부를 판별","실험실이나 다른 시험기관이 수행할 수 있는 특정 실험방법 및 제한사항에 관계없이 공정성을 위해 화재조사관 단독으로 감정 및 시험 실시"],4,0,"ew20200606"],["ew20200606-50",2,"T093","2020-06-06",50,63,"화상의 위험도에 큰 영향을 미치는 인자는?",["심도(沈度)","온도(溫度)","질병(疾病)","범위(範圍)"],4,0,"ew20200606"],["ew20200606-51",2,"T076","2020-06-06",51,86,"화재 증거물의 수송으로 권장할 만한 가장 적절한 방법은?",["직접운반","제3자 전달","우편배송","화물로의 배송"],1,0,"ew20200606"],["ew20200606-52",2,"T092","2020-06-06",52,78,"전기기기 또는 구성품에 대한 증거물 수집 방법으로 틀린 것은?",["전기적 증거물이 발견된 상태를 가능한 한 그대로 보존해야 한다.","제품 내 전기적 특이점이 발견된다면 해당 부분만 수거하는 것이 효과적이다.","일부 남은 전선 피복을 검사 할 수 있도록 가능한 전선을 길게 수집해야 한다.","전기기기를 전체적으로 제거하는 것이 불가능한 경우 제자리에 안전하게 놓는 것이 좋다."],2,0,"ew20200606"],["ew20200606-53",2,"T081","2020-06-06",53,31,"화재증거물수집관리규칙에 포함되는 내용이 아닌 것은?",["증거물의 포장","증거물 감정 절차","증거물의 상황기록","초상권 및 개인정보 보호"],2,0,"ew20200606"],["ew20200606-54",2,"T069","2020-06-06",54,66,"화재증거물수집관리규칙상 현장사진 및 비디오 촬영 시 유의사항에 대한 설명으로 틀린 것은?",["최초 도착하였을 때의 원상태를 그대로 촬영하고 진압 순서에 따라 촬영","현장사진 및 비디오 촬영할 때에는 연소확대 경로 및 증거물 기록에 대한 번호표와 화살표를 표시 후에 촬영","증거물을 촬영할 때에는 그 소재와 상태가 명백히 나타나도록 하며, 필요에 따라 구분이 용이하게 번호표 등을 넣어 촬영","화재현장의 특정한 증거물 등을 촬영함에 있어서는 그 길이, 폭 등을 명백히 하기 위하여 측정용 자 또는 대조 도구를 사용하여 촬영"],1,0,"ew20200606"],["ew20200606-55",2,"T096","2020-06-06",55,58,"열에 의한 재성형이 불가능한 합성 고분자 화합물의 종류로 맞는 것은?",["테프론","폴리에틸렌","멜라민수지","폴리아크릴로니트릴"],3,0,"ew20200606"],["ew20200606-56",2,"T075","2020-06-06",56,74,"화재현장에서 수집된 증거물의 오염에 관한 설명으로 맞는 것은?",["물리적 증거물 대부분의 오염은 운반하는 과정에서 발생한다.","증거물 보관용기는 오염지역에서 떨어진 곳에 보관하여야 한다.","증거물의 오염방지를 위하여 화재조사관의 맨손으로 직접 수집하는 것이 원칙이다.","증거물 용기는 개봉상태로 유지하며, 실험실에서 조사를 마친 후 봉인되어야 한다."],2,0,"ew20200606"],["ew20200606-57",2,"T074","2020-06-06",57,68,"증거물 수집용기 중 유리병의 장점이 아닌 것은?",["휘발성 액체의 증발을 방지한다.","내부의 증거물 확인이 용이하다.","장기 저장 시 증거물의 악화를 줄여 준다.","크기가 다양하여 많은 양을 저장할 수 있다."],4,0,"ew20200606"],["ew20200606-58",2,"T091","2020-06-06",58,53,"일반적인 방화 현장에서 나타나는 패턴이 아닌 것은?",["U형 패턴","독립연소 패턴","포어(pour) 패턴","트레일러(trailer) 패턴"],1,0,"ew20200606"],["ew20200606-59",2,"T078","2020-06-06",59,83,"화재현장의 증거물 시료 채취 시 유의사항으로 아닌 것은?",["가급적 증거물 전체를 수집 또는 채취","동일한 물질이 있었을 때는 채취하지 않고 내용만 기술","감정의뢰서에 증거물을 수집, 채취한 경과와 사건개요를 기술","채취된 증거물의 물질이 상이할 때에는 서로 섞이지 않도록 분리하여 채취, 보관"],2,0,"ew20200606"],["ew20200606-60",2,"T099","2020-06-06",60,80,"화재 당시 살아있었음을 나타내는 생활반응으로 맞는 것은?",["시반이 없다.","머리가 그을렸다.","기도에 매연이 부착되었다.","피부가 진피까지 탄화되었다."],3,0,"ew20200606"],["ew20200606-62",3,"T123","2020-06-06",62,58,"건물의 일부를 개수 또는 보수한 경우에 있어서의 경과연수의 산정 기준 적용에 관한 설명으로 틀린 것은?",["재설치비의 50%미만 개ㆍ보수한 경우 : 최초 설치연도 기준","재설치비의 50%이상 개ㆍ보수한 경우 : 최초 설치연도 기준","재설치비의 80%이상 개ㆍ보수한 경우 : 개ㆍ보수한 때를 기준으로 하여 경과연수를 산정","재설치비의 50~80% 미만을 각각 개ㆍ보수한 경우 : 최초 설치연도를 기준으로 한 경과연수와 개ㆍ보수한 때를 기준으로 한 경과연수를 합산하고 평균하여 경과연수를 산정"],2,0,"ew20200606"],["ew20200606-63",3,"T119","2020-06-06",63,50,"재고자산의 상품 중 견본품, 전시품, 진열품에 대한 화재피해액 산정 시 우선 적용사항으로 맞는 것은?",["시장거래가격으로 산정한다.","구입가의 50%로 일괄 산정한다.","구입가의 50~80%를 피해액으로 한다.","구입가에 감가수정한 가격으로 산정한다."],3,0,"ew20200606"],["ew20200606-64",3,"T126","2020-06-06",64,78,"화재조사 및 보고규정 상 화재건수를 결정할 때 1건의 화재 결정으로 틀린 것은?",["동일 대상물에서 발화점이 2개소이며, 누전점이 동일한 화재","동일 대상물에서 발화점이 3개소로서 낙뢰에 의한 다발화재","동일 대상물에서 발화점이 4개소로서 지진에 의한 다발화재","각기 다른 사람에 의한 방화나 불장난으로 동일 대상물에서 발화한 화재"],4,0,"ew20200606"],["ew20200606-65",3,"T119","2020-06-06",65,41,"재고자산의 화재 피해액 산정에 관한 사항으로 맞는 것은?",["판매 및 일반관리비의 미실현 이익 내지 미실현 비용을 포함한다.","재고자산 중 반제품은 구입 후 사용하지 않고 보관중인 소모품을 의미한다.","재고자산은 구입비용 자체가 피해액이 되므로 감가공제는 하지 않는다.","재고자산의 구입비에는 운반비 등 구입경비와 판매비용은 포함하지 않는다."],3,0,"ew20200606"],["ew20200606-66",3,"T121","2020-06-06",66,81,"화재발생종합보고서 작성 시 질문기록서 작성을 생략할 수 있는 대상으로 맞는 것은?",["선박 화재","자동차 화재","건축ㆍ구조물 화재","전봇대 화재"],4,0,"ew20200606"],["ew20200606-67",3,"T122","2020-06-06",67,61,"화재조사 및 보고규정 상 화재피해액 산정기준으로 틀린 것은?",["차량은 전부손해의 경우 시중매매가격으로 한다.","임야의 입목은 전부손해의 경우 감정가격으로 한다.","미술공예품은 전부손해의 경우 감정가격으로 한다.","기타피해 물품은 피해당시의 현재가를 재구입비로 하여 피해액을 산정한다."],2,0,"ew20200606"],["ew20200606-68",3,"T111","2020-06-06",68,53,"화재현황조사서에 명시된 발화요인으로 맞는 것은?",["불꽃, 불티","작동기기","담뱃불, 라이터불","교통사고"],4,0,"ew20200606"],["ew20200606-69",3,"T126","2020-06-06",69,76,"화재범위가 2이상의 관할구역에 걸친 화재에 대한 설명으로 맞는 것은?",["출동하여 진압한 소방서에서 1건의 화재로 한다.","관할 소방서장과 출동한 소방서장과 협의하여 정한다.","발화 소방대상물의 소재지를 관할하는 소방서에서 1건의 화재로 한다.","발화 소방대상물의 소재지를 관할하는 소방서와 출동한 소방서에서 각각 1건의 화재로 한다."],3,0,"ew20200606"],["ew20200606-70",3,"T127","2020-06-06",70,81,"화재 현장조사서에 첨부할 도면의 작성에 대한 설명으로 틀린 것은?",["도면작성에 있어서는 방의 배치와 출입구, 개구부의 상황을 위주로 한다.","거리측정은 기둥의 중심에서 다른 기둥의 중심까지로 기준점을 통일한다.","도면(평면도, 입체도)은 측정치를 기준으로 하여 축척에 맞춰서 작성한다.","화재조사관은 화재현장에 대한 이해도를 높이기 위해 화재의 유형과 규모에 관계없이 3차원 형식의 도면을 반드시 작성하여야 한다."],4,0,"ew20200606"],["ew20200606-71",3,"T108","2020-06-06",71,79,"화재조사서류 중 화재발생종합보고서의 보존기간으로 맞는 것은?",["5년","10년","영구","준영구"],3,0,"ew20200606"],["ew20200606-72",3,"T114","2020-06-06",72,53,"화재피해액 산정에 있어 상당부분 교체 내지 수리가 필요한 경우의 손해율로 맞는 것은?",["20%","40%","60%","80%"],3,0,"ew20200606"],["ew20200606-73",3,"T105","2020-06-06",73,81,"화재현장조사서 작성 시 유의사항 중 틀린 것은?",["관계자 진술은 주관적인 것이므로 기재하지 않는다.","필요한 경우 예상되는 사항 및 관련 조치사항 등도 기록할 수 있다.","발화지점 및 화재원인 판정은 객관적인 증거자료(사진, 기타서류 등)를 첨부할 수 있다.","필요한 경우 감식ㆍ감정 결과통지서, 전기배선도, 연구자료, 재현실험 결과, 참고문헌 등 참고자료를 첨부할 수 있다."],1,0,"ew20200606"],["ew20200606-74",3,"T113","2020-06-06",74,56,"지은지 10년된 아파트에서 화재가 발생하여 100m2가 소실되었다. 화재피해액은 약 얼마인가? (단, 내용연수 50년, 신축단가 670천원/m2, 손해율 40%이다.)",["21862천원","22512천원","26661천원","28891천원"],2,0,"ew20200606"],["ew20200606-75",3,"T120","2020-06-06",75,73,"화재발생종합보고서에서 화재 발생 시 모든 경우에 작성되어야 할 조사서는?",["화재현황조사서","화재유형별조사서","방화ㆍ방화의심조사서","화재피해(인명ㆍ재산)조사서"],1,0,"ew20200606"],["ew20200606-76",3,"T115","2020-06-06",76,55,"화재피해액 산정에 관한 설명으로 맞는 것은?",["최종잔가율은 건물, 부대설비, 가재도구의 경우 20%, 기타의 경우 10%로 한다.","화재피해액을 산정하기 위한 피해면적은 화재피해를 입은 건물의 바닥면적을 말한다.","화재로 인한 건물의 피해액은 화재피해 대상 건물과 동일한 구조, 용도, 질, 규모의 건물 재건축비에서 손해율을 곱한 금액이 된다.","간이평가방식에 의한 부대설비의 피해액 산정에 있어 전등 및 전열설비 등 기본적 전기설비만 설치되어 있어도 별도로 부대시설 피해액을 산정한다."],1,0,"ew20200606"],["ew20200606-77",3,"T104","2020-06-06",77,78,"화재조사 및 보고규정상 화재로 인한 재산피해의 범위가 아닌 것은?",["연기에 의한 그을음 피해","화재로 인한 영업손실의 피해","소화활동으로 발생한 수손피해","열에 의한 탄화, 용융, 파손 피해"],2,0,"ew20200606"],["ew20200606-78",3,"T115","2020-06-06",78,51,"화재피해액 산정 시 중고로 구입한 기계장치 및 집기비품으로서 그 제작년도를 알 수 없을 경우 그 상태에 따라 신품가액 대비 잔가율로 정할 수 있는 비율은?",["30% 내지 50%","30% 내지 60%","20% 내지 50%","20% 내지 60%"],1,0,"ew20200606"],["ew20200606-79",3,"T124","2020-06-06",79,73,"화재현장 출동보고서의 기재항목이 아닌 것은?",["발화지점 판정","출동대원 및 응답자","현장도착시 발견사항","도착하여 처음 실행한 일의 지점 및 유형"],1,0,"ew20200606"],["ew20200606-80",3,"T112","2020-06-06",80,75,"화재현장조사서 작성 시 화재원인 검토와 관련된 내용 중 필수 검토항목이 아닌 것은?",["방화 가능성","전기적 요인","인적 부주의","관련 조치사항"],4,0,"ew20200606"],["ew20200606-81",4,"T141","2020-06-06",81,71,"소방기본법령에서 규정하고 있는 화재조사 전담부서의 장이 소속 소방공무원 가운데 소방청장이 실시하는 화재조사에 관한 시험에 합격한 자가 없는 경우, 화재조사를 실시하게 할 수 있는 소방공무원의 기준으로 옳은 것은?",["소방교육기관에서 10주 이상 화재조사에 관한 전문교육을 이수한 자","국립과학수사연구원에서 10주 이상 화재조사에 관한 전문교육을 이수한 자","외국의 화재조사 관련 기관에서 10주 이상 화재조사에 관한 전문교육을 이수한 자","「국가기술자격법」에 따른 건축ㆍ위험물ㆍ전기ㆍ안전관리(가스ㆍ소방ㆍ소방설비ㆍ전기안전ㆍ화재감식평가 종목에 한한다)분야 산업기사 이상의 자격을 취득한 자"],4,0,"ew20200606"],["ew20200606-82",4,"T140","2020-06-06",82,76,"화재조사 및 보고규정상 조사본부의 설치운영에 관한 사항 중 옳지 않은 것은?",["조사본부장은 화재조사 업무를 관장하는 과장으로 한다.","조사관은 소방본부 및 소방서의 화재조사업무를 담당한다.","조사본부장은 조사종료 후 7일 이내에 예외 없이 조사내용을 발표해야 한다.","본부장 또는 서장은 조사본부의 기능이 완료되었을 경우 이를 해체한다."],3,0,"ew20200606"],["ew20200606-83",4,"T141","2020-06-06",83,80,"소방기본법령상 화재조사 전담부서의 장이 관장하는 업무가 아닌 것은?",["화재조사의 발전과 조사요원의 능력향상에 관한 사항","화재조사를 위한 장비의 관리운영에 관한 사항","화재조사의 총괄ㆍ조정","화재조사에 관한 시험의 응시자격 결정"],4,0,"ew20200606"],["ew20200606-84",4,"T156","2020-06-06",84,80,"화재로 인한 손해의 배상의무자가 법원에 손해배상액의 경감을 청구할 수 있는 경우로 옳은 것은?",["고의에 인한 화재인 경우","중대한 과실로 인한 실화인 경우","경미한 과실로 인한 실화인 경우","악의적인 방화로 인한 화재인 경우"],3,0,"ew20200606"],["ew20200606-85",4,"T158","2020-06-06",85,80,"화재조사 및 보고규정에서 6가지로 규정한 화재 유형이 아닌 것은?",["건축ㆍ구조물 화재","위험물ㆍ가스제조소 등 화재","공원화재","선박ㆍ항공기화재"],3,0,"ew20200606"],["ew20200606-86",4,"T145","2020-06-06",86,69,"제조물 책임법에 따르면 손해배상의 청구권은 제조업자가 손해를 발생시킨 제조물을 공급한 날부터 몇 년 이내에 행사하여야 하는가? (단, 원칙적인 경우에 한한다.)",["3년","5년","10년","15년"],3,0,"ew20200606"],["ew20200606-87",4,"T151","2020-06-06",87,42,"화재로 인한 재해보상과 보험가입에 관한 법률의 설명으로 틀린 것은?",["보험금 청구권 중 손해배상책임을 담보하는 보험의 청구권은 압류할 수 없다.","“손해보험회사”란 손해배상법에 따른 화재보험업의 허가를 받은 자를 말한다.","대한민국에 주둔하는 외국군대가 소유하는 건물은 특수건물소유자의 손해배상책임에 적용되지 않는다.","손해보험회사는 대통령령으로 정하는 바에 따라 협회의 설립과 운영에 필요한 비용을 출연하여야 한다."],2,0,"ew20200606"],["ew20200606-89",4,"T148","2020-06-06",89,52,"제조물 책임법상 제조업자에 해당하는 자로 옳지 않은 것은?",["제조물의 제조ㆍ가공을 업으로 하는 자","제조물의 유통을 업으로 하는 자","제조물의 수입을 업으로 하는 자","제조물에 성명ㆍ상호ㆍ상표 등을 사용하여 자신을 제조업자로 오인하게 할 수 있는 표시를 한 자"],2,0,"ew20200606"],["ew20200606-90",4,"T173","2020-06-06",90,62,"미성년자가 타인에게 손해를 가한 경우에 그 행위의 책임을 변식할 지능이 없는 때에는 배상의 책임이 없다. 이 경우 민법상 미성년자임을 판단하는 연령과 그 산정방법으로 옳은 것은?",["14세 미만, 출생일 산입","18세 미만, 출생일 불산입","19세 미만, 출생일 산입","20세 미만, 출생일 불산입"],3,0,"ew20200606"],["ew20200606-91",4,"T143","2020-06-06",91,61,"소방기본법령상 화재원인조사 중 발화원인 조사의 점위에 해당하지 않은 것은?",["화재가 발생한 과정","화재의 연소경로","화재가 발생한 지점","불이 붙기 시작한 물질"],2,0,"ew20200606"],["ew20200606-92",4,"T167","2020-06-06",92,71,"화재로 인한 재해보상과 보험가입에 관한 법률상 특약부화재보험을 가입하지 않은 특수건물 소유자의 벌칙으로 옳은 것은?",["200만원 이하의 벌금","300만원 이하의 벌금","400만원 이하의 벌금","500만원 이하의 벌금"],4,0,"ew20200606"],["ew20200606-93",4,"T156","2020-06-06",93,81,"실화책임에 관한 법률상 배상의무자가 법원에 손해배상액의 경감을 청구할 경우 법원이 손해배상액의 경감을 고려하는 사정이 아닌 것은?",["화재의 원인과 규모","피해의 대상과 정도","연소 및 피해 확대의 원인","화재피해자의 직업"],4,0,"ew20200606"],["ew20200606-94",4,"T157","2020-06-06",94,78,"화재 현장에서의 증거물이 법정에 제출되는 경우, 증거로서의 가치를 상실하지 않도록 준수해야 하는 적법한 절차에 관한 사항으로 옳은 것은?",["관련 법규 및 지침에 규정된 일반적인 원칙과 절차를 준수한다.","화재조사에 필요한 증거 수집은 화재피해자의 피해를 최대화하도록 하여야 한다.","화재의 증거물을 획득할 때에는 어떠한 장비도 사용해서는 아니된다.","최종적으로 법정에 제출되는 화재증거물은 증거의 훼손 방지를 위하여 항상 사본을 제출한다."],1,0,"ew20200606"],["ew20200606-95",4,"T164","2020-06-06",95,69,"화재보험법령상 손해보험회사가 운영하는 특약부화재보험에 가입 하여야 하는 특수건물의 기준으로 옳은 것은?",["노래연습장업으로 사용하는 부분의 바닥면적의 합계가 1000m2이상인 건물","학원으로 사용하는 부분의 바닥면적의 합계가 1000m2이상인 건물","병원급 의료기관으로 사용하는 건물로서 연면적의 합계가 2000m2이상인 건물","관광숙박업으로 사용하는 건물로서 연면적의 합계가 3000m2이상인 건물"],4,0,"ew20200606"],["ew20200606-96",4,"","2020-06-06",96,78,"소방기본법상 화재, 재난ㆍ재해, 그 밖의 위급한 상황이 발생한 현장에 소방활동구역을 정하여 소방활동에 필요한 사람으로서 대통령령으로 정하는 사람 외에는 그 구역에 출입하는 것을 제한할 수 있는 자는?",["시ㆍ도지사","행정안전부장관","시장ㆍ군수","소방대장"],4,0,"ew20200606"],["ew20200606-97",4,"T152","2020-06-06",97,75,"승객이 있는 기차에 불을 놓은 경우에 해당되는 죄는 무엇인가?",["현주건조물등에의 방화","공용건조물등에의 방화","일반건조물등에의 방화","일반물건에의 방화"],1,0,"ew20200606"],["ew20200606-99",4,"T136","2020-06-06",99,82,"화재조사관이 화재원인 및 피해조사활동을 개시하는 시점으로 옳은 것은?",["화재사실을 인지하는 즉시","현장에 소방차량이 도착함과 동시","화재가 진압되고 즉시","관할 경찰서의 조사허가 즉시"],1,0,"ew20200606"],["ew20200606-100",4,"","2020-06-06",100,38,"소방서장 등은 불이 번지는 것을 막기 위하여 필요할 때에는 불이 번질 우려가 있는 소방대상물을 일시적으로 사용하거나 그 사용의 제한 또는 소방활동에 필요한 처분을 할 수 있다. 다음 중 이러한 처분을 방해한 자에 대한 벌칙으로 옳은 것은?",["3년이하 징역 또는 3천만원 이하의 벌금","5년이하 징역 또는 5천만원 이하의 벌금","1년이하 징역 또는 500만원 이하의 벌금","300만원 이하의 벌금"],1,0,"ew20200606"],["ew20200926-1",0,"T017","2020-09-26",1,73,"다음은 화재조사의 과학적인 방법론이다. 순서에 맞게 배열한 것은?",["문제인식 → 문제정의 → 가설 설정 → 자료 수집 → 자료 분석 → 가설 검증 → 최종 가설선택","문제정의 → 문제인식 → 자료 수집 → 자료 분석 → 가설 설정 → 가설 검증 → 최종 가설선택","문제정의 → 문제인식 → 자료 수집 → 자료 분석 → 가설 검증 → 가설 설정 → 최종 가설선택","문제인식 → 문제정의 → 자료 수집 → 자료 분석 → 가설 설정 → 가설 검증 → 최종 가설선택"],4,0,"ew20200926"],["ew20200926-2",0,"T019","2020-09-26",2,68,"화재와 연소에 대한 설명으로 옳지 않은 것은?",["화재란 사람의 의도에 반하거나 고의에 의해 발생하는 연소현상으로서 소화시설등을 사용하여 소화할 필요가 있는 것을 말한다.","연소란 가연성 물질이 산소와 결합하여 열과 빛을 내며 급속히 산화되어 형질이 변경되는 화학반응을 말한다.","연기란 연소 및 열분해에 의한 생성물로서 공기 중에 부유하고 육안으로 보이는 기체의 집단을 말한다.","연기 입자의 크기는 연소조건에 따라 차이는 있지만, 무염연소의 경우에는 약 1㎛, 유염연소의 경우에는 약 1~5㎛의 것이 대부분을 차지한다."],3,0,"ew20200926"],["ew20200926-3",0,"T016","2020-09-26",3,88,"발화지점으로 추정되는 위치에서 발화원, 발화물질 등 연소된 물건을 현장발굴하는 방법에 대한 설명으로 옳지 않은 것은?",["발굴은 가능한 삽과 같은 것을 사용한다.","발굴한 물건 중 복원할 필요가 있는 것은 번호 또는 표식을 부착해 정리해 둔다.","발굴은 위에서 아래로 실시한다.","발굴한 연소된 물건은 가능한 그 위치를 옮기지 않는다. 불가피하게 이동하는 경우에는 복원가능한 조치를 한다."],1,0,"ew20200926"],["ew20200926-4",0,"T005","2020-09-26",4,82,"연소에 따른 금속의 산화작용으로 옳지 않은 것은?",["온도가 높을수록, 노출 시간이 짧을수록 산화의 효과가 많이 나타난다.","철이나 강철이 화재에서 산화되었을 때, 처음에는 푸르스름하고 흐린 회색이 된다.","스테인리스 스틸이 심하게 산화되면 흐린 회색을 띠게 된다.","구리는 열에 노출되면 어두운 적색이나 흑색 산화물을 만든다."],1,0,"ew20200926"],["ew20200926-5",0,"T014","2020-09-26",5,62,"소방대(선착대)의 연소상황조사 내용에 포함되지 않는 것은?",["소화활동중의 특이한 연소상황(색, 냄새 등)","주수위치 및 주수효과의 상황","피해소방대상물의 소손면적, 동수, 이재 세대의 상황","사상자 및 사상된 장소의 상황"],3,0,"ew20200926"],["ew20200926-6",0,"T017","2020-09-26",6,74,"화재조사 전 준비의 내용으로 가장 거리가 먼 것은?",["조사관은 사고의 날짜, 요일 및 시간을 정확하게 판단해야 한다.","사고가 발생한 뒤 흐른 시간은 조사 계획에 영향을 줄 수 있다.","사건의 사실 및 환경은 현장 조사 후 확인하여야 한다.","사고와 조사 사이에 시간이 많이 지연될 경우 기존문서와 정보를 검토하는 것이 더 중요하다."],3,0,"ew20200926"],["ew20200926-7",0,"T009","2020-09-26",7,86,"화학적 폭발에 대한 설명 중 옳은 것은?",["산소 농도가 낮을수록 폭발 위력이 크다.","압력이 높을수록 폭발의 위력이 적다.","입자가 작을수록 폭발의 위력이 적다.","혼합비율이 화학양론비에 가까울수록 위력이 크다."],4,0,"ew20200926"],["ew20200926-8",0,"","2020-09-26",8,83,"일반 주택화재의 발화지점을 판정할 때 활용되는 정보로 가장 거리가 먼 것은?",["화재패턴","산소 농도","목격자 진술","전기합선 지점 분석"],2,0,"ew20200926"],["ew20200926-9",0,"T001","2020-09-26",9,72,"화재가 나타내는 V패턴의 설명으로 옳지 않은 것은?",["불꽃과 대류 또는 복사열에 의해서 생성된다.","연소가 진행될 때 수직으로 된 벽면에 나타난다.","패턴이 나타내는 각도가 넓으면 연소의 속도가 느리다.","발화지점이 아닌 곳에서도 생성될 수 있다."],3,0,"ew20200926"],["ew20200926-10",0,"","2020-09-26",10,79,"유류화재 발생 시 포소화약제를 유류표면에 발포하면 재착화가 일어나지 않으나 분말소화약제에 비해 소화시간이 긴 단점을 가지고 있다. 이와 같은 단점을 보완하기 위하여 분말소화약제와 함께 사용이 가능한 포소화약제로 가장 적절한 것은?",["수성막포소화약제","단백포소화약제","알코올형포소화약제","합성계면활성제포소화약제"],1,0,"ew20200926"],["ew20200926-11",0,"","2020-09-26",11,83,"여러 동의 인접한 건물이 소손되어 있는 화재현장에서 발화건물 판정을 위한 일반적인 조사요령에 관한 설명으로 옳지 않은 것은?",["화재현장 전체의 연소방향은 가급적 낮은 쪽에서 높은 쪽을 바라보며 파악한다.","각 건물의 연소방향은 타다 멈춘 부분 또는 연속강약이 명확한 부분부터 파악한다.","타서 허물어진 부분을 보고 연소방향을 추정할 수 있다.","복수의 건물이 소손되어 있으면 인접동간격, 외벽구조, 개구부상황 등으로부터 연소상황을 파악한다."],1,0,"ew20200926"],["ew20200926-12",0,"T006","2020-09-26",12,67,"물질의 연소와 관련이 있는 열관성(Thermal inertia)을 식으로 옳은 것은? (단, k는 열전도, ρ는 밀도, c는 열용량이다.)",["c/kρ","kc/ρ","ρc/k","kρc"],4,0,"ew20200926"],["ew20200926-13",0,"T001","2020-09-26",13,62,"V패턴의 각도에 영향을 미치지 않는 것은?",["열방출률","가연물의 형태","환기의 효과","벽면의 열전도성"],4,0,"ew20200926"],["ew20200926-14",0,"T001","2020-09-26",14,76,"화재패턴 중 붕괴된 침대 스프링에 대한 설명으로 옳은 것은?",["스프링의 붕괴된 부위와 붕괴되지 않은 부위를 비교하여 화염의 방향을 추정할 때 붕괴된 부위 방향을 화재의 진행방향으로 판단할 수 있다.","화재이전 부터 침대 위에 무거운 것이 올려져 있다면 화염의 방향과 상관없이 붕괴될 수 있으며, 소락몰에 의한 영향은 없다.","무거운 것이 올려져 있지 않다면 스프링은 붕괴되지 않는다.","화재이후에도 붕괴되지 않고 남아있는 스프링은 붕괴된 스프링과 같이 탄성을 잃어버린다."],1,0,"ew20200926"],["ew20200926-15",0,"T017","2020-09-26",15,89,"소방기관이 화재조사를 수행하는 근본적인 목적으로 옳은 것은?",["유사화재의 재발 방지와 피해 경감을 위한 자료로 활용","출화원인 규명으로 사법처리 근거 자료로 활용","인적, 물적 피해사항 조사를 통한 통계 자료로 활용","법률관계에 수반된 증거보전 자료로 활용"],1,0,"ew20200926"],["ew20200926-16",0,"T024","2020-09-26",16,73,"화염 충돌에 의한 화재확산에 대한 설명으로 옳지 않은 것은?",["구획공간에서 연료가 있는 위치에 따라 화염의 길이가 달라진다.","구획공간에서 연료의 위치가 벽과 구석(corner)에 있을 때 화염의 길이는 구석이 더 길다.","화염의 높이가 천장보다 클 때는 화염이 천장을 따라 확장된다.","천장에 의해서 화염이 잘려질 때 화염의 전체길이는 자유 화염높이보다 작아진다."],4,0,"ew20200926"],["ew20200926-17",0,"T026","2020-09-26",17,60,"탄화알루미늄이 상온에서 물과 반응할 경우 생성되는 가연성 기체는?",["수소","아세틸렌","메탄","프로판"],3,0,"ew20200926"],["ew20200926-18",0,"","2020-09-26",18,59,"공기의 비중을 1이라 했을 때 다음 중 비중이 가장 큰 가스는?",["수소","부탄","프로판","메탄"],2,0,"ew20200926"],["ew20200926-19",0,"T018","2020-09-26",19,64,"구획실 화재에서 플래시오버를 일으키는 화재의 최소 크기와 환기구 높이의 관계에 대한 설명으로 옳은 것은?",["화재의 최소 크기는 환기구의 높이의 제곱근에 비례한다.","화재의 최소 크기는 환기구의 높이의 제곱에 비례한다.","화재의 최소 크기는 환기구의 높이의 세제곱근에 비례한다.","화재의 최소 크기는 환기구의 높이의 세제곱에 비례한다."],1,0,"ew20200926"],["ew20200926-20",0,"T012","2020-09-26",20,89,"화재조사의 책임과 권한에 대한 설명으로 옳은 것은?",["소방서장은 관계보험사가 그 화재원인과 피해상황을 조사하고자 할 때에는 이를 허용해서는 안된다.","소방서장은 화재의 원인 및 피해 등에 대한 조사를 소화활동 후에 실시하여야 한다.","과실로 인한 위법행위로 타인에게 손해를 가한 자는 그 손해를 배상할 책임이 없다.","소방서장은 화재조사를 위하여 필요한 경우에는 수사에 지장을 주지 아니하는 범위에서 그 피의자 또는 압수된 증거물에 대한 조사를 할 수 있다."],4,0,"ew20200926"],["ew20200926-21",1,"T043","2020-09-26",21,86,"무염화원이 아닌 것은?",["담뱃불","그라인더 불티","모기향","촛불"],4,0,"ew20200926"],["ew20200926-22",1,"","2020-09-26",22,63,"다음 중 염소(CI)성분을 포함하고 있는 가스는?",["암모니아","아세틸렌","포스겐","시안화수소"],3,0,"ew20200926"],["ew20200926-23",1,"T034","2020-09-26",23,89,"계획적인 방화로 분류되지 않는 것은?",["정신이상에 의한 방화","이익목적에 의한 방화","정치적 목적에 의한 방화","원환에 의한 방화"],1,0,"ew20200926"],["ew20200926-24",1,"T037","2020-09-26",24,77,"선박에서 인접하는 구획 사이를 2개의 분리된 격벽이나 갑판으로 격리시키는 구역을 무엇이라 하는가?",["A급 구획","B급 구획","코퍼댐(cofferdam)","제연벽"],3,0,"ew20200926"],["ew20200926-25",1,"T055","2020-09-26",25,73,"산화에틸렌 90%와 메탄 10%가 혼합되어 있는 경우 폭발하한계로 옳은 것은? (단, 메탄의 연소범위는 5~15vol.%, 산화에틸렌의 연소범위는 3~80vol.%이다.)",["1.79 vol.%","3.13 vol.%","32 vol.%","55.81 vol.%"],2,0,"ew20200926"],["ew20200926-26",1,"T049","2020-09-26",26,63,"임의의 도선에 흐르는 전류에 의한 자계의 세기 단위로 옳은 것은?",["[V·T/cm2]","[V·T/M]","[A·T/cm2]","[A·T/m]"],4,0,"ew20200926"],["ew20200926-27",1,"T055","2020-09-26",27,60,"다음 폭발 중 기상폭발에 해당하는 것이 아닌 것은?",["가스폭발","분진폭발","분무폭발","수증기폭발"],4,0,"ew20200926"],["ew20200926-28",1,"T033","2020-09-26",28,76,"방화의 직접적 단서가 될 수 없는 것은?",["도화선","색다른 촉진제","비정상적인 연료하중","출입문의 잠김 상태"],4,0,"ew20200926"],["ew20200926-29",1,"T053","2020-09-26",29,87,"다음 중 자연발화성 물질의 자연발화를 촉진시키는 데 영향을 주지 않는 것은?",["표면적이 넓고 발열량이 클 것","열전도율이 클 것","주위온도가 높을 것","반응성이 클 것"],2,0,"ew20200926"],["ew20200926-30",1,"T041","2020-09-26",30,86,"산불진화 시 열 스트레스 손상으로 가장 거리가 먼 것은?",["열 경련","탈수 피로","열 발작","혼수상태"],4,0,"ew20200926"],["ew20200926-31",1,"","2020-09-26",31,78,"성냥의 나무개비에 침투시켜 연소 후 탄화시키는 약제는?",["곰팡이 방지제","표백제","염색제","인풀제"],4,0,"ew20200926"],["ew20200926-32",1,"T054","2020-09-26",32,73,"pH=3인 수용액의 [H+]는 pH=5인 수용액의 [H+]의 몇 배인가?",["0.01","10","100","1000"],3,0,"ew20200926"],["ew20200926-33",1,"T040","2020-09-26",33,75,"임야화재 시 수관화의 특징으로 옳은 것은?",["중심부의 화염온도는 2500℃이다.","주변의 연기온도는 1500℃이다.","바람이 강할 때 연소속도는 7km/h이다.","임야화재 연소 중에 수십 m의 상승기류가 발생한다."],4,0,"ew20200926"],["ew20200926-34",1,"T046","2020-09-26",34,74,"LPG차량엔진의 구성 부품 중 봄베에 부착된 충전밸브, 기체 송출밸브 및 액체 송출밸브의 색상을 순서대로 바르게 나열한 것은?",["녹색, 적색, 황색","녹색, 황색, 적색","황색, 녹색, 적색","황색, 적색, 녹색"],2,0,"ew20200926"],["ew20200926-35",1,"T046","2020-09-26",35,45,"차량용 LPG 기화기(Vaporizer)의 설명 중 옳은 것은?",["1차 감압실은 봄베로부터 전달된 액체 LPG를 0.8kg/cm2으로 감압 및 기화하여 2차 감압실로 보낸다.","고정 조정 스크루는 공회전 상태에서 스크루를 돌려 공회전 상태의 CO 또는 HC의 농도를 조절한다.","1차 압력조정 스크루는 1차 감압실의 LPG 압력을 0.8kg/cm2으로 저장하기 위한 스크루이다.","저속차단 솔레노이드밸브는 LPG가 액체상태에서 기체로 될 때 주위로부터 기화열을 흡수하여 동결시키는 현상을 방지하기 위한 장치이다."],2,0,"ew20200926"],["ew20200926-36",1,"T033","2020-09-26",36,86,"방화의 특징으로 옳지 않은 것은?",["2개 이상의 독립된 발화개소가 식별된 경우","덕트나 배관용 파이프홀을 통해 다른 층이나 다른 방실로 화재가 확산되는 경우","용도별로는 주택 및 차량에 대한 방화가 많음","휘발류, 시너 등을 사용하는 경우가 많아 화재확산이 매우 빠름"],2,0,"ew20200926"],["ew20200926-37",1,"T048","2020-09-26",37,66,"전기화재 발생과정에 대한 설명 중 옳지 않은 것은?",["코드의 접촉불량 시 접촉저항의 증가로 줄열에 의한 화재 발생","고압 변압기의 충전부에서 누설 방전으로 절연이 파괴되어 화재 발생","코일의 층간 단락으로 저항이 증가하여 전류가 감소되며 화재 발생","물 없는 전기온수기를 통전 방치하여 주변 가연물에서 화재 발생"],3,0,"ew20200926"],["ew20200926-38",1,"T044","2020-09-26",38,87,"차량이 충돌 또는 추돌하는 경우, 누출된 연료 및 오일의 점화로 인해 화재로 이어져 인명사고가 발생하는 경우가 있다. 동 경우, 발화원인으로 작용할 수 없는 것은?",["차량 파손에 동반된 전선의 단락에 의한 전기적 발열","차량 파손에 동반된 고온의 충격 마찰열","차량 파손에 동반된 엔진 표면 및 배기계통의 고온 열면","차량의 파손에 동반된 냉각수의 분출"],4,0,"ew20200926"],["ew20200926-39",1,"T035","2020-09-26",39,89,"항공기에서 이상적인 화재감지장치(fire detection system)의 특징이 아닌 것은?",["화재가 계속되는 동안 계속 지시해야 한다.","화재가 다시 발생하는 경우 다시 정확히 지시해야 한다.","조종실에서 감지기장치를 시험 시 소요되는 전력은 많아야 한다.","취급에서 노출에 견딜 수 있도록 견고해야 한다."],3,0,"ew20200926"],["ew20200926-40",1,"T033","2020-09-26",40,70,"방화의 일반적인 판단요소로 가장 거리가 먼 것은?",["국부적인 발화흔적","무단침입과 흔적","범죄흔적","이상 연소현상"],1,0,"ew20200926"],["ew20200926-41",2,"T097","2020-09-26",41,80,"화재사의 사인과 그 내용이 올바르게 연결된 것은?",["화상사: 화재에 따른 현상에 의해 신경을 자극해서 정신 또는 신체가 충격을 받아 사망한 것","질식사: 화재 시 발생한 일산화탄소 등 유독가스가 혈액의 산소공급을 막아 조직의 산소 결핍으로 사망한 것","소사: 화재로 인하여 화염 등 고열이 피부에 작용하여 화상을 입은 후 그 상황에서 2차적인 조건에 의해 사망한 것","쇼크사: 화재로 인한 화상과 더불어 화염에 의해 불에 타서 사망하거나 일산화탄소에 의한 유독가스 중독과 산소결핍에 의한 질식 등이 합병되어 사망한 것"],2,0,"ew20200926"],["ew20200926-42",2,"T085","2020-09-26",42,78,"화재로 사망한 사람의 생활반응으로 틀린 것은?",["일산화탄소의 중독으로 사망한 경우 암적색 시반이 나타난다.","분신자살자는 혈중 일산화탄소 농도가 전혀 나오지 않는 경우도 있다.","흡연자의 경우, 평소에도 비흡연자보다 높은 수준의 일산화탄소 농도가 나타난다.","사망에 이르는 혈중 일산화탄소의 농도는 10~80%까지 개개인마다 차이가 있다."],1,0,"ew20200926"],["ew20200926-43",2,"T068","2020-09-26",43,61,"화재현장에서의 현장임장 및 증거물 수집활동의 법적근거가 아닌 것은?",["형사소송법 제218조 영장에 의하지 아니한 압수","형사소송법 제216조 영장에 의하지 아니한 강제처분","형사소송법 제308조 제2항 위법수집증거 배제원칙","범죄수사규칙 제8장제2절, 제124조, 제125조 범죄현장과 증거보존, 유류물 등의 압수"],3,0,"ew20200926"],["ew20200926-44",2,"T075","2020-09-26",44,81,"증거물 오염이 가중되는 시기로 맞는 것은?",["보관할 때","이송할 때","수집할 때","발견했을 때"],3,0,"ew20200926"],["ew20200926-45",2,"","2020-09-26",45,64,"화재현장에서 화재조사자의 의무가 아닌 것은?",["화재원인과 피해 조사를 위한 출입 검사의무","화재원인과 피해조사 시 경찰공무원과의 협력의무","증거물과 피의자에 대한 조사를 수행함에 있어 경찰의 수사를 방해하지 않아야 할 의무","방화, 실화 등 범죄의 혐의가 있는 경우 관할 경찰서장에게 알리고 필요한 증거를 수집 보존할 의무"],1,0,"ew20200926"],["ew20200926-46",2,"T090","2020-09-26",46,74,"인화점 측정을 위한 장비가 아닌 것은?",["Pensky-Martens","Tag Closed Cup","Cleveland Open Cup","Scanning Electron Microscope"],4,0,"ew20200926"],["ew20200926-47",2,"","2020-09-26",47,70,"훈소가 가능한 물질에 해당하는 것은?",["종이","스티로폼","나일론섬유","플라스틱"],1,0,"ew20200926"],["ew20200926-48",2,"T091","2020-09-26",48,64,"화재로 발생한 열에 의해 유리창이 파손되는 원인에 대한 설명으로 맞는 것은?",["열을 받는 유리가 녹으면서 깨진다.","유리면의 온도차에 의한 응력으로 깨진다.","유리를 구성하는 규소의 열분해에 의해 깨진다.","화재가 발생한 실내의 높아진 압력에 의해 깨진다."],2,0,"ew20200926"],["ew20200926-49",2,"","2020-09-26",49,63,"아파트의 주방에서 가스폭발로 20대 여성이 둔상을 입었다. 둔상은 폭발효과에 의한 부상의 4가지 유형 중 어느 것인가?",["열효과에 의한 부상","지진효과에 의한 부상","파편효과에 의한 부상","압력파효과에 의한 부상"],3,0,"ew20200926"],["ew20200926-50",2,"T072","2020-09-26",50,76,"화재조사를 위한 사진촬영의 중요성에 해당하지 않는 것은?",["사실의 묘사성","진술의 신뢰성","기억의 환기성","증거의 조작성"],4,0,"ew20200926"],["ew20200926-51",2,"T096","2020-09-26",51,59,"플라스틱 증거물에 관한 설명으로 맞는 것은?",["열가소성 물질은 용해되고 흘러서 화재 확대의 원인이 된다.","폴리우레탄 같은 열가소성 물질은 탄화물질을 형성하지 않는다.","탄화수소계의 기본적인 고체 가연물인 플라스틱의 약 90%는 열경화성이다.","PVC와 같은 열경화성 물질은 가열되면 용융, 변형, 그리고 드롭다운 패턴이 형성된다."],1,0,"ew20200926"],["ew20200926-52",2,"T071","2020-09-26",52,54,"카메라 촬영에 있어 피사계심도 조절 방법으로 틀린 것은?",["피사계심도를 얕게 하는 방법으로 렌즈구경을 개방한다.","피사계심도를 깊게 하는 방법으로 촬영거리를 가깝게 한다.","피사계심도를 얕게 하는 방법으로 초점거리가 더 긴 렌즈를 사용한다.","피사계심도를 깊게 하는 방법으로 초점거리가 더 짧은 렌즈를 사용한다."],2,0,"ew20200926"],["ew20200926-53",2,"T097","2020-09-26",53,50,"화재와 관련된 사망자 분석으로 틀린 것은?",["피는 열의 영향으로 귀, 코, 입에서 스며나올 수 있다.","화재로 인한 희생자는 모두 사망시간을 측정해야 한다.","화재로 인한 희생자는 모두 일산화탄소 포화상태를 측정해야 한다.","사체 외부에서 발견된 피는 사망하기 전에 신체적 외상을 입었다는 것을 나타낸다."],2,0,"ew20200926"],["ew20200926-54",2,"T069","2020-09-26",54,90,"화재현장의 사진촬영 기법에 대한 설명으로 틀린 것은?",["발화지점을 중심으로 연소 확산된 상황을 촬영","화재대상물과 주위의 위치관계를 알 수 있도록 촬영","가능한 소실된 현장을 국소적으로만 자세하게 촬영","외부 촬영 시 먼 곳에서 화재대상물 전면을 담아낼 수 있는 위치에서 촬영"],3,0,"ew20200926"],["ew20200926-55",2,"T080","2020-09-26",55,88,"가연성액체 증거보관용기의 설명으로 틀린 것은?",["가연성액체 증거를 온전하게 보존해야 한다.","가연성액체 증거의 오염과 변화를 예방해야 한다.","가연성액체 증거의 기화를 막기 위해 밀봉이 되어서는 안 된다.","가연성액체 증거의 물리적 상태, 특징, 파괴성, 휘발성을 고려하여 선택한다."],3,0,"ew20200926"],["ew20200926-56",2,"T092","2020-09-26",56,62,"화재조사에서 전기설비 및 구성부품의 증거물 수집 시 유의사항으로 맞는 것은?",["전체 전기 기기나 전기 제품을 있는 그대로 수집해야 한다.","전선의 한쪽 끝에는 태그를 붙여 회로 장치 등의 내용을 표시한다.","전선 피복의 검사가 용이하도록 가능한 전선을 짧게 수집해야 한다.","증거물이 발견되면 다른 구성부품과의 혼란 방지를 위해 신속히 이동시킨다."],1,0,"ew20200926"],["ew20200926-57",2,"T098","2020-09-26",57,51,"가스크로마토그래피법을 통해 분리된 각 원소들에 대한 상세한 분석을 수행하는 장비로 맞는 것은?",["Mass Spectrometer","Tag Closed Tester","X-ray Fluorescence","Infrared Spectrophotometer"],1,0,"ew20200926"],["ew20200926-58",2,"T080","2020-09-26",58,75,"액체 연소촉진제의 물리적 증거 수집 시 고려사항으로 틀린 것은?",["흡수성 물질(밀가루 등)은 실험실로 옮겨서 추출하는 것이 좋다.","액체 연소촉진제는 다공성 물질 안에 갇혔을 때 다공성 물질 안에 존재할 가능성이 높으므로 주의 깊게 확인한다.","액체 연소촉진제는 대부분 구조부, 내부 마감재 및 기타 화재 잔해에 쉽게 흡수됨으로 물질 내부에 흡수되었는지 확인한다.","모든 액체 연소촉진제는 물보다 가벼워 물과 접촉 시 그 위에 뜨므로 기름띠를 확인하는 것만으로도 액체 연소촉진제가 있었는지를 알아낼 수 있다."],4,0,"ew20200926"],["ew20200926-59",2,"T088","2020-09-26",59,70,"타임라인에서 상대적 시간에 포함되는 것은?",["완전소화시간","목격된 지속시간","신고가 접수된 시간","알람의 설정과 작동시간"],2,0,"ew20200926"],["ew20200926-60",2,"T084","2020-09-26",60,85,"화재현장에서 질문 내용의 녹음 방법으로 맞는 것은?",["진술 거부 시 유도심문을 한다.","질문은 길게 하고 간결한 답변을 요구한다.","사전에 녹음사실을 알리고 임의적 진술을 확보한다.","관계자의 심리적 상태를 고려하여 화재로부터 2~3일 후 면담을 한다."],3,0,"ew20200926"],["ew20200926-61",3,"T115","2020-09-26",61,73,"피해물의 경제적 내용연수가 다한 경우 잔존하는 가치의 재구입비에 대한 비율을 무엇이라 하는가?",["잔가율","손해율","최종잔가율","보정률"],3,0,"ew20200926"],["ew20200926-62",3,"T110","2020-09-26",62,78,"화재피해 조사서(인명) 작성 시 기재사항이 아닌 것은?",["사상부위","사상시 위치·행동","사상전 상태","사상자 가족 인적사항"],4,0,"ew20200926"],["ew20200926-63",3,"T103","2020-09-26",63,49,"화재조사 및 보고규정상 사후조사에 대한 설명으로 맞는 것은?",["사후조사는 발화장소 및 발화지점의 현장이 보존되어 있는 경우에만 조사를 한다.","사후조사의 경우에도 화재현장 출동보고서를 반드시 작성하여야 한다.","사후조사의 경우 화재발생종합보고서는 화재조사 및 보고규정 별지 제3호 서식이 아닌 별도의 서식에 의해 작성한다.","소방대가 출동하지 아니한 화재장소의 화재증명원 발급요청이 있는 경우, 조사관이 판단하여 사후조사를 실시한 후 보고서를 작성한다."],1,0,"ew20200926"],["ew20200926-64",3,"T131","2020-09-26",64,82,"화재조사 및 보고규정상 화재조사 활동의 개시시점으로 맞는 것은?",["화재사실 인지와 동시","화재현장 도착과 동시","화재진화 활동과 동시","화재진화 작업종료와 동시"],1,0,"ew20200926"],["ew20200926-65",3,"T114","2020-09-26",65,70,"공구 및 기구의 소손정도에 따른 손해율로 틀린 것은?",["오염·수침손의 경우 : 10%","손해정도가 보통인 경우 : 20%","손해정도가 다소 심한 경우 : 50%","50% 이상 소손되고 그을음 및 수침오염 정도가 심한 경우 : 100%"],2,0,"ew20200926"],["ew20200926-66",3,"T124","2020-09-26",66,61,"화재조사 및 보고규정상 화재현장출동 보고서의 작성을 생략할 수 있는 경우는?",["항구에 메어둔 선박에서 화재가 발생하여 조사하는 경우","건축물이 아닌 야외 공터의 쓰레기 화재에 대해 조사한 경우","소방대가 화재현장에 출동하였고, 재산피해가 경미한 경우","소방대가 출동하지 않은 화재현장에 대해 민원인이 사후조사를 의뢰하였고, 현장이 보존되어 사후조사를 실시한 경우"],4,0,"ew20200926"],["ew20200926-67",3,"T106","2020-09-26",67,85,"화재현장조사서 작성 시 발화원인 판정의 방법으로 틀린 것은?",["재현실험의 데이터나 각종 문헌 등을 인용한다.","제조물 관련 화재의 경우, 경험에 기초하여 주관적 증명이 가능하도록 한다.","난해한 전문용어나 어려운 이론을 열거하는 것은 피하고 논리적 표현을 사용한다.","질문조사서 등의 서류로부터 사실인용과 합리적·과학적인 논리전개가 중심이 된다."],2,0,"ew20200926"],["ew20200926-68",3,"T115","2020-09-26",68,67,"모델하우스 또는 가설건물 등 일정기간 존치하는 건물에 있어서는 실제 존치할 기간을 내용연수로 하여 피해액을 산정한다. 이 경우 존치기간 종료일 현재의 최종잔가율은 얼마인가?",["10%","20%","30%","40%"],2,0,"ew20200926"],["ew20200926-69",3,"","2020-09-26",69,75,"화재원인 분류에서 화학적 요인에 해당하지 않는 것은?",["자연발화","혼촉발화","물리적 폭발","금수성물질과 물의 접촉"],3,0,"ew20200926"],["ew20200926-70",3,"T104","2020-09-26",70,75,"화재피해조사 중 재산피해 유형에 관한 설명으로 틀린 것은?",["수손피해: 소화활동으로 발생한 수손피해 등","소실피해: 열에 의한 탄화, 용융, 파손 등의 피해","영업피해: 화재발생으로 영업을 하지 못해 발생한 영업손실","기타피해: 연기, 물품반출, 화재 중 발생한 폭발 등에 의한 피해 등"],3,0,"ew20200926"],["ew20200926-71",3,"T105","2020-09-26",71,88,"화재조사서류 작성상의 유의사항으로 틀린 것은?",["필요한 서류가 첨부되어야 한다.","원칙적으로 평이하고 알기 쉬운 문장으로 작성토록 노력한다.","오자, 탈자 등이 없도록 글자 하나라도 가볍게 보아서는 안 된다.","화재유형별 조사서는 화재의 유형에 관계없이 동일 양식에 기재하여야 한다."],4,0,"ew20200926"],["ew20200926-72",3,"T114","2020-09-26",72,61,"화재피해액을 산정할 때 손해율의 적용할 때 손해율을 구분하는 기준은?",["내용연수","경년감가율","최종잔가율","화재로 인한 피해정도"],4,0,"ew20200926"],["ew20200926-73",3,"T115","2020-09-26",73,57,"내용연수가 30년이고 경과연수가 15년인 건물의 잔가율은 얼마인가?",["30%","40%","50%","60%"],4,0,"ew20200926"],["ew20200926-74",3,"T124","2020-09-26",74,83,"다음 중 작성자가 다른 화재조사 서류는?",["질문기록서","화재현장조사서","화재피해조사서","화재현장 출동보고서"],4,0,"ew20200926"],["ew20200926-76",3,"T115","2020-09-26",76,62,"화재 등으로 인한 피해액 산정에 있어 최종잔가율 20% 적용이 아닌 것은?",["건물","부대설비","비품","가재도구"],3,0,"ew20200926"],["ew20200926-77",3,"T101","2020-09-26",77,69,"화재조사 및 보고규정에서 소실정도를 구분할 때 전소에 대한 설명으로 틀린 것은?",["반소 보다 소실비율이 높다.","일반적으로 건물의 경우 70% 이상 소실된 것을 의미한다.","소실비율은 소실된 건물의 바닥면적을 기준으로 한다.","소실정도가 70%미만인 경우에 잔존부분을 보수하여도 재사용이 불가능한 것은 전소에 해당한다."],3,0,"ew20200926"],["ew20200926-78",3,"T123","2020-09-26",78,47,"영업시설의 피해액 산정 시에 개·보수한 때를 기준으로 경과연수를 산정하는 것은 재 설치비의 몇 %이상 개·보수한 경우인가?",["50","60","70","80"],4,0,"ew20200926"],["ew20200926-79",3,"T111","2020-09-26",79,60,"화재현황 조사서의 기재사항이 아닌 것은?",["건물상태","화재발생장소","화재원인","발화관련기기"],1,0,"ew20200926"],["ew20200926-80",3,"T115","2020-09-26",80,49,"철거건물에 대한 피해액 산정 시의 최종잔가율로 맞은 것은?",["5%","10%","15%","20%"],4,0,"ew20200926"],["ew20200926-81",4,"T167","2020-09-26",81,82,"화재로 인한 재해보상과 보험가입에 관한 법률상 특수건물에 대하여 손해보험회사가 운영하는 특약부화재보험에 가입하지 아니한 자의 벌칙 기준으로 옳은 것은?",["100만원 이하의 벌금","300만원 이하의 벌금","500만원 이하의 벌금","700만원 이하의 벌금"],3,0,"ew20200926"],["ew20200926-82",4,"T139","2020-09-26",82,55,"소방기본법상 화재조사를 하기 위한 관계 공무원의 출입 또는 조사를 거부·방해 또는 기피하는 자에 대한 벌칙 기준으로 옳은 것은?",["100만원 이하의 벌금","200만원 이하의 벌금","300만원 이하의 벌금","500만원 이하의 벌금"],3,0,"ew20200926"],["ew20200926-84",4,"T138","2020-09-26",84,86,"소방청장, 소방본부장 또는 소방서장이 방화(放火) 또는 실화(失火)의 혐의가 있어서 수사기관이 이미 피의자를 체포하였거나 증거물을 압수하였을 때에 화재조사를 위하여 피의자 또는 압수된 증거물에 대한 조사를 하는 경우에 대한 설명으로 옳은 것은?",["필요할 때는 언제나 조사할 수 있으며 수사기관은 항상 화재조사에 협조하여야 한다.","수사기관의 수사가 종료된 후부터 조사를 실시할 수 있다.","수사에 지장을 주지 아니하는 범위에서 조사를 할 수 있으며 수사기관은 신속한 화재조사를 위하여 특별한 사유가 없으면 조사에 협조하여야 한다.","원칙적으로 조사할 수 없으나, 인명피해 등 사회적 문제가 야기된 경우에는 조사할 수 있다."],3,0,"ew20200926"],["ew20200926-85",4,"T168","2020-09-26",85,69,"화재로 인한 재해보상과 보험가입에 관한 법률에 따르면 특수건물의 소유권이 변경된 경우 소유권을 취득한 날부터 며칠 이내에 특약부화재보험에 가입하여야 하는가?",["즉시","10일","20일","30일"],4,0,"ew20200926"],["ew20200926-86",4,"T133","2020-09-26",86,82,"화재조사 및 보고규정상 화재의 소실정도가 반소인 기준으로 옳은 것은?",["건물의 30%이상 70%미만이 소실된 것","건물의 40%이상 60%미만이 소실된 것","건물의 50%이상 70%미만이 소실된 것","건물의 50%이상 80%미만이 소실된 것"],1,0,"ew20200926"],["ew20200926-88",4,"T147","2020-09-26",88,73,"제조물책임법상 제조업자의 손해배상 면책 규정으로 옳지 않은 것은?",["제조업자가 해당 제조물을 공급하지 아니하였다는 사실을 입증한 경우","제조물의 결함이 제조업자의 제조물 공급 당시 법령기준을 준수함에 따라 발생하였다는 사실을 입증한 경우","제조물을 공급한 당시의 과학·기술 수준으로는 결함의 존재를 발견할 수 없었다는 사실을 입증한 경우","제조업자가 결함 있는 제조물을 공급한 후 3년이 경과한 경우"],4,0,"ew20200926"],["ew20200926-89",4,"T164","2020-09-26",89,64,"화재로 인한 재해보상과 보험가입에 관한 법령에 따라 특약부화재보험을 가입하여야 하는 특수건물 중 아파트는 기본적으로 몇 층 이상이어야 하는가?",["7층","11층","16층","층수에 관계없이 모든 아파트"],3,0,"ew20200926"],["ew20200926-90",4,"T146","2020-09-26",90,67,"제조물 책임법상 제조상의 결함에 해당되는 것은?",["제조업자가 합리적인 대체설계(代替設計)를 채용하였더라면 피해나 위험을 줄이거나 피할 수 있었음에도 대체설계를 채용하지 아니하여 해당 제조물이 안전하지 못하게 된 경우를 말한다.","제조업자가 제조물에 대하여 제조상·가공상의 주의의무를 이행하였는지에 관계없이 제조물이 원래 의도한 설계와 다르게 제조·가공됨으로써 안전하지 못하게 된 경우를 말한다.","제조업자가 합리적인 설명·지시·경고 또는 그 밖의 표시를 하였더라면 해당 제조물에 의하여 발생할 수 있는 피해나 위험을 줄이거나 피할 수 있었음에도 이를 하지 아니한 경우를 말한다.","제조업자가 물류·유통과정에서 발생할 수 있는 위험을 인지하지 못하여 제조물의 파손을 초래한 경우를 말한다."],2,0,"ew20200926"],["ew20200926-91",4,"T155","2020-09-26",91,55,"형법상 업무상과실 또는 중대한 과실로 인하여 실화의 죄를 범한 자에 대한 벌칙 기준으로 옳은 것은?",["2년 이하의 금고 또는 700만원 이하의 벌금","3년 이하의 금고 또는 2000만원 이하의 벌금","5년 이하의 금고 또는 1500만원 이하의 벌금","7년 이하의 금고 또는 2000만원 이하의 벌금"],2,0,"ew20200926"],["ew20200926-92",4,"","2020-09-26",92,58,"화재로 인한 재해보상과 보험가입에 관한 법령상 특약부화재보험의 설명으로 옳은 것은?",["장애가 남은 것이란 정상기능의 5분의 2 이상을 상실한 경우를 말한다.","제대로 못쓰게 된 것이란 정상기능의 5분의 4이상을 상실한 경우를 말한다.","뚜렷한 장애가 남은 것이란 정상기능의 5분의 3이상을 상실한 경우를 말한다.","항상 보호 또는 수시 보호를 받아야 하는 기간은 의사가 판정하는 노동능력 상실기간을 기준으로 하여 타당한 기간으로 정한다."],4,0,"ew20200926"],["ew20200926-94",4,"T142","2020-09-26",94,77,"화재조사 및 보고규정상 용어의 정의 중 옳은 것은?",["발화열원이란 화재가 발생한 부위를 말한다.","화재조사관이란 화재조사업무를 위탁한 보험회사 직원을 말한다.","발화요인이란 발화에 관련된 불꽃 또는 열을 발생시킨 기기 또는 장치나 제품을 말한다.","연소확대물이란 연소가 확대되는데 있어 결정적 영향을 미친 가연물을 말한다."],4,0,"ew20200926"],["ew20200926-95",4,"T173","2020-09-26",95,64,"민법에서 규정하는 불법행위에 대한 설명으로 틀린 것은?",["과실로 인한 위법행위로 타인에게 손해를 가한 자는 그 손해를 배상할 책임이 있다.","타인의 신체, 자유 또는 명예를 해하거나 기타 정신상고통을 가한 자는 재산 이외의 손해에 대하여도 배상할 책임이 있다.","심신상실 중에 타인에게 손해를 가한 자는 배상의 책임이 있다.","태아는 손해배상의 청구권에 관하여는 이미 출생한 것으로 본다."],3,0,"ew20200926"],["ew20200926-96",4,"","2020-09-26",96,67,"소방기본법에 의한 화재, 재난·재해 그 밖의 위급한 상황이 발생한 현장에서 그 현장에 있는 사람으로 하여금 사람을 구출하는 일 또는 불을 끄거나 불이 번지지 아니하도록 하는 일을 방해한 자에 대한 벌칙은?",["5년이하의 징역 또는 3천만원 이하의 벌금","5년이하의 징역 또는 5천만원 이하의 벌금","3년이하의 징역 또는 1천500만원 이하의 벌금","3년이하의 징역 또는 1천만원 이하의 벌금"],2,0,"ew20200926"],["ew20200926-97",4,"T153","2020-09-26",97,71,"공용건조물 등에의 방화죄 대상물이 아닌 것은?",["건조물","자동차","임야","광갱"],3,0,"ew20200926"],["ew20200926-98",4,"T157","2020-09-26",98,60,"화재증거물수집관리규칙에 따른 증거물 시료용기의 기준 중 옳은 것은?",["주석 도금캔(CAN)은 2회 사용 후 반드시 폐기한다.","양철 용기는 돌려 막는 스크루 뚜껑만 아니라 밀어 막는 금속 마개를 갖추어야 한다.","코르크마개, 클로로프렌 고무, 마분지, 합성 코르크마개 또는 플라스틱 물질(PTFE포함)은 시료와 직접 접촉되어서는 안 된다.","유리병의 코르크 마개는 휘발성 액체에 사용하여야 한다. 만일 제품이 빛에 민감하다면 짙은 색깔의 시료병을 사용한다."],2,0,"ew20200926"],["ew20200926-100",4,"T145","2020-09-26",100,64,"제조물책임법에 따른 손해배상의 청구권은 제조업자가 손해를 발생시킨 제조물을 공급한 날부터 몇 년 이내에 행사하여야 하는가?",["3","5","7","10"],4,0,"ew20200926"],["ew20210307-1",0,"T011","2021-03-07",1,77,"정전기의 발생을 예방하기 위한 방법으로 틀린 것은?",["접지시설을 한다.","공기를 이온화시킨다.","공기 중의 상대습도를 70% 이상으로 한다.","대전을 방지하기 위하여 비전도성물질을 사용한다."],4,0,"ew20210307"],["ew20210307-2",0,"T009","2021-03-07",2,67,"증기운 형성물질 중 비점 이상의 온도지만 가압하여 액화된 물질로 열전달 및 확산이 증발을 제한하는 특징을 갖는 물질은?",["벤젠","액화암모니아","액화천연가스","액화석유가스"],1,0,"ew20210307"],["ew20210307-3",0,"T018","2021-03-07",3,73,"플래시 오버에 대한 설명으로 가장 거리가 먼 것은?",["환기 지배 연소로 전환된다.","열방출율 곡선이 급격히 상승한다.","주요 열전달 방식은 대류로 전환된다.","플래시오버 단계는 해당 화재실의 화염이 최성기로 성장하게 되는 화재의 단계를 의미한다."],3,0,"ew20210307"],["ew20210307-4",0,"","2021-03-07",4,58,"화재조사 및 보고규정상 화재피해조사의 범위 중 재산피해 내용으로 틀린 것은?",["수손피해","연소 확대물","물품반출","열에 의한 탄화"],2,0,"ew20210307"],["ew20210307-5",0,"T027","2021-03-07",5,54,"연소박리와 소화수박리에 대한 설명 중 틀린 것은?",["박리의 분포는 연소박리가 집중되어 있고, 소화수 박리는 산재되어 있다.","표면의 거칠기는 연소박리가 크고, 소화수 박리는 작다.","박리면적은 연소박리가 작고, 소화수 박리는 크다.","박리면은 연소박리가 거칠고, 소화수 박리는 평탄하며 윤기가 난다."],1,0,"ew20210307"],["ew20210307-6",0,"T015","2021-03-07",6,82,"방화의 식별에서 일반적인 방화의 가능성이 있는 경우로 가장 거리가 먼 것은?",["화재가 건물의 구조, 가연물 등에 비해 급격히 확산된 경우","최초 발화지점에서 유류 등 연료물질을 사용한 흔적이 있는 경우","연소기구를 중심으로 연소 확대가 진행된 흔적이 있는 경우","출입문, 창 등에 강제로 진입한 흔적이 있는 경우"],3,0,"ew20210307"],["ew20210307-7",0,"T013","2021-03-07",7,72,"소방기본법령상 소방본부(거점소방서 포함)의 화재조사전담부서에서 갖추어야 할 장비 및 시설 중 화재조사분석실은 몇 m2 이상의 실을 보유하여야 하는가?",["10m2 이상","20m2 이상","30m2 이상","40m2 이상"],3,0,"ew20210307"],["ew20210307-8",0,"T004","2021-03-07",8,70,"화재현장의 파괴된 유리 분석에 대한 설명으로 옳은 것은?",["열에 의해 깨진 유리의 단면에는 리플마크가 관찰된다.","열에 의해 깨진 유리의 표면을 관찰하면 월러라인을 식별할 수 있다.","열에 의해 깨진 유리는 방사형 파손흔적이 관찰된다.","유리 단면을 관찰하면 열 또는 충격에 의한 원인을 구분할 수 있다."],4,0,"ew20210307"],["ew20210307-9",0,"T009","2021-03-07",9,54,"수류탄 폭발에 대한 분류로 옳은 것은?",["화학적 폭발 - 집중 폭발","화학적 폭발 - 확산 폭발","물리적 폭발 - 확산 폭발","물리적 폭발 - 집중 폭발"],1,0,"ew20210307"],["ew20210307-10",0,"T024","2021-03-07",10,84,"화염의 색이 백적색일때 불꽃의 온도는?",["약 350℃","약 800℃","약 1300℃","약 1500℃"],3,0,"ew20210307"],["ew20210307-11",0,"T010","2021-03-07",11,78,"공기 중에서 폭발범위가 가장 넓은 물질은?",["수소","메탄","아세틸렌","암모니아"],3,0,"ew20210307"],["ew20210307-12",0,"T005","2021-03-07",12,85,"구획된 건축물 내 화재 발생 시 나타나는 화재패턴에 대한 설명으로 옳은 것은?",["금속재의 만곡부는 지상을 향해 휘거나 뒤틀린 형태를 나타낸다.","열을 많이 받은 부분일수록 박리현상이 발생할 가능성이 낮다.","벽지에 나타나는 연소형태를 통하여 화염의 이동경로를 추정하는 것은 불가능하다.","천장 내부에서 착화된 경우 화재의 발견이 늦기 때문에 천장 바깥쪽보다 안쪽의 소실정도가 약하게 나타난다."],1,0,"ew20210307"],["ew20210307-13",0,"T019","2021-03-07",13,72,"연기에 대한 설명으로 틀린 것은?",["고층건물에서 연기를 이동시키는 주요 추진력은 굴뚝효과이다.","건물 내에서 연기의 수평방향 확산속도는 약 0.5m/s이다.","알코올이 연소될 경우에 연기의 색은 진한 검정색을 띤다.","연기는 공기 중에 부유하고 있는 고체 또는 액체의 미립자다."],3,0,"ew20210307"],["ew20210307-14",0,"T026","2021-03-07",14,60,"물과 접촉 시 가연성 기체를 발생하지 않고 발열반응으로 인하여 주변의 가연물을 발화시키는 물질은?",["칼륨","산화칼슘","인화알루미늄","탄화칼슘"],2,0,"ew20210307"],["ew20210307-15",0,"T001","2021-03-07",15,62,"연소흔적의 주요 생성원인 중 증발연소로 인하여 나타나는 액체가연물의 흔적으로 옳은 것은?",["포어 패턴(Pour pattern)","도넛 패턴(doughnut pattern)","스플래시 패턴(splash pattern)","레인보우 이펙트(rainbow effect)"],2,0,"ew20210307"],["ew20210307-16",0,"T024","2021-03-07",16,59,"드래프트 효과를 저해하는 요인이 아닌 것은?",["통 내에 그을음이 많이 쌓여 단면적이 감소되는 경우","균열이나 파손된 곳으로 외부의 찬 공기가 들어오는 경우","연통의 수직거리가 수평거리의 1.5배 이상인 경우","굴곡이 적거나 구부러지지 않아 통기저항이 적은 경우"],4,0,"ew20210307"],["ew20210307-17",0,"T017","2021-03-07",17,67,"소방기본법령에 근거한 화재조사의 시작시점에 해당하는 것은?",["화재진압 후 실시","화재발생과 동시에 실시","화재신고 접수와 동시에 실시","화재발생 징후 포착과 동시에 실시"],3,0,"ew20210307"],["ew20210307-18",0,"T022","2021-03-07",18,40,"12mm의 합판이 25kW/m2의 열유속을 받고 있을 때 점화시간(초)은? (단, 표면 열손실이 없는 이상적인 경우라 가정하고, 실온:20℃, 합판의 물성치는 점화온도: 250℃, 열전도도: 0.15×10-3kW/m·K, 밀도: 640kg/m3, 비열:2.9kJ/kg·K이다.)",["약 15","약 19","약 23","약 30"],2,0,"ew20210307"],["ew20210307-19",0,"T016","2021-03-07",19,82,"화재현장에서 수집된 각 증거물이 주는 정보를 연관되는 것끼리 연결해 놓은 것으로 전체적인 그림을 그리는 과정은?",["PERT 차트","타임라인(Time ilne)","Hopkinson의 상승근법","마인드맵핑(Mind mapping)"],4,0,"ew20210307"],["ew20210307-20",0,"T013","2021-03-07",20,60,"소방기본법령상 화재조사전담부서에서 갖추어야 할 장비 및 시설 중 소방서에서 갖추어야 하는 감식용 기기에 해당되지 않는 것은?",["절연저항계","실체현미경","멀티테스터기","디지털 온도·습도계"],4,0,"ew20210307"],["ew20210307-21",1,"T045","2021-03-07",21,80,"차량 화재조사 중 화재조사자의 안전 및 조사가 용이한 장소가 아닌 것은?",["화재가 발생한 고속도로의 갓길","소유자의 주차장 및 조사 가능한 주차장","화재차량의 소유자가 최근 차량검사 및 수리를 맡긴 자동차정비공장","화재차량의 소유자가 신차(중고차)로 구입한 자동차판매영업소"],1,0,"ew20210307"],["ew20210307-22",1,"T035","2021-03-07",22,70,"항공기 소화기장치의 일상정비에 포함된 항목이 아닌 것은?",["전선의 교체","배출관의 누출시험","소화기 용기의 검사와 보급","카트리지의 장·탈장과 재장착"],1,0,"ew20210307"],["ew20210307-23",1,"T042","2021-03-07",23,83,"무염화원의 한 종류인 점화원으로 담뱃불에 대한 설명으로 틀린 것은?",["대표적인 무염화원이다.","이동이 가능한 점화원이다.","담배 완제품은 자연발화가 가능하다.","흡연자는 화인을 제공할 수 있는 개연성이 있다."],3,0,"ew20210307"],["ew20210307-24",1,"T038","2021-03-07",24,66,"선박 화재의 직접적인 발화원으로 가장 거리가 먼 것은?",["아크","접지","정전기","전기화열"],2,0,"ew20210307"],["ew20210307-25",1,"T048","2021-03-07",25,74,"콘센트에 물기, 기름때 등과 같은 오염물질이 유입되어 전기화재의 점화원으로서 발생할 수 있는 현상으로 옳은 것은?",["트래킹","과부하","반단선","접촉불량"],1,0,"ew20210307"],["ew20210307-26",1,"T047","2021-03-07",26,56,"LPG(액화석유가스)의 기본 성질로서 옳은 것은?",["기화 및 액화가 어렵다.","액화하면 부피가 커진다.","연소 시 다량의 공기가 필요하다.","중기는 공기보다 가볍고 물보다 무겁다."],3,0,"ew20210307"],["ew20210307-27",1,"T039","2021-03-07",27,72,"임야화재에 큰 영향을 미치는 주요 3요소가 아닌 것은?",["지형","연료","기후","점화원"],4,0,"ew20210307"],["ew20210307-28",1,"T043","2021-03-07",28,47,"미소화원에 의한 출화 증명에 해당하지 않는 것은?",["무염화원과 구분","가연물 종류의 확인","훈소의 지속과 발염","정확한 출화개소의 판단"],1,0,"ew20210307"],["ew20210307-29",1,"T044","2021-03-07",29,62,"차량화재 발화지점 판정의 유의사항으로 틀린 것은?",["차체 강판의 소손에 의한 변색의 차이를 자세히 관찰하여 출화개소를 판정하되 회색이 암청색보다 높은 온도에서 소손된 경우이다.","타이어로 출화개소를 추정하는 경우 앞, 뒤 바퀴 타이어 4개의 소손상태를 비교하여 타이어 중 가장 소손이 심한 개소가 출화개소에 가까운 경우가 많다.","연료, 오일 등에 대한 연소 확대를 고려하여 판정했을 때 차량 하부에서 상부로 소손이 연결되어 연소 확대된 부분이 출화개소에 가까운 경우가 많다.","차량 하부의 소손이 여러 곳에서 국부적으로 일어나 있을 경우, 각각 소손부에서 상부로 타 올라감을 조사할 필요가 있다."],1,0,"ew20210307"],["ew20210307-30",1,"T055","2021-03-07",30,46,"프로판(C3H8)의 연소상한계는 9.5vol%이고, 하한계는 2.1vol%인 경우, 연소에 필요한 최소산소농도(MOC)의 값(vol%)은?",["8.1","10.5","15.1","20.5"],2,0,"ew20210307"],["ew20210307-31",1,"T033","2021-03-07",31,58,"방화판정을 위한 10대 요건에 포함되지 않는 것은?",["귀중품 반출 등","수선 중의 화재","휴일 또는 주말 화재","화재로 인한 건물의 손상"],4,0,"ew20210307"],["ew20210307-32",1,"T048","2021-03-07",32,52,"발화부 판단 방법으로 옳은 것은?",["아크매핑","비파괴검사","감정물 분해검사","가스크로마토그래피"],1,0,"ew20210307"],["ew20210307-33",1,"T034","2021-03-07",33,71,"생후 첫 성장기에 부모의 사랑을 받지 못해 무의식 속에서 모성이 주는 따뜻함과 안정감을 애타게 원하는 본능에서 불을 통해 만족하는 방화범은?",["남근기 방화범","구강기 방화범","잠복기 방화범","항문기 방화범"],2,0,"ew20210307"],["ew20210307-35",1,"T052","2021-03-07",35,49,"최초 발화 물질에 대한 설명 중 틀린 것은?",["표면적 대 질량 비율이 높은 가연물에는 먼지, 섬유 및 종이 등이 있다.","최초 발화 물질의 표면적 대 질량 비율이 높은 경우에는 열원의 강도와 지속성 특징이 덜 중요하다.","동일한 발화 온도라도 가연물의 표면적 대질량 비율이 높을수록 해당 열원은 가연물을 인화시키기 위해 생성 에너지가 작아진다.","표면적 대 질량 비율이 극도로 높은 경우, 기체와 증기는 높은 열에너지원에 의해서만 발화될 수 있다."],4,0,"ew20210307"],["ew20210307-36",1,"T055","2021-03-07",36,67,"인화성 촉진제인 휘발유의 위험도로 옳은 것은? (단, 휘발유의 연소범위는 1.4vol.%~7.6vol.% 이다.)",["0.82","4.43","6.20","6.43"],2,0,"ew20210307"],["ew20210307-37",1,"","2021-03-07",37,85,"화학물질의 혼합발화와 관련하여 감식요령으로 틀린 것은?",["물질의 성질, 취급의 상황, 장소의 환경조건에 대하여 조사한다.","혼합 물질의 재현실험은 실시하지만 단독 물질의 발화 여부 실험은 하지 않는다.","혼합발화에 의한 화재는 혼합한 물질 자체가 연소하므로 증거가 소실되는 경우가 있다.","화재가 난 곳에서 존재하는 물질에 대하여 성분, 성질, 형상, 양을 관계자의 진술과 문헌·자료 등을 기초로 조사한다."],2,0,"ew20210307"],["ew20210307-38",1,"T041","2021-03-07",38,62,"강한 가도의 산불이 예상되는 연료조건 중 가장 거리가 먼 것은?",["다수의 사다리 연료가 존재할 때","비정상적으로 낮은 연료습도가 형성될 떼","고추휘발성 기름을 포함한 연료상이 존재할 때","많은 양의 가는 죽은 연료가 계곡부에 존재할 때"],4,0,"ew20210307"],["ew20210307-39",1,"T052","2021-03-07",39,73,"최소발화에너지와 압력과의 관계를 설명한 것으로 옳은 것은?",["발화에너지는 압력과 관계없다.","압력이 클수록 최소발화에너지는 증가한다.","압력이 클수록 최소발화에너지는 감소한다.","압력과 관계없이 최소발화에너지는 일정하다."],3,0,"ew20210307"],["ew20210307-40",1,"T049","2021-03-07",40,29,"저항 R=30Ω, 커패시터 C=400μF, 인덕터 L=40mH인 값을 갖는 R-L-C 직렬 회로에서 공진주파수는?",["39.8Hz","50.8Hz","60.8Hz","120.8Hz"],1,0,"ew20210307"],["ew20210307-41",2,"T079","2021-03-07",41,76,"물리적 증거물 수집방법 결정요인에 대한 설명으로 가장 거리가 먼 것은?",["휘발성 : 액체 및 기체 증거물은 쉽게 증발될 수 있으므로 물리적 증거물이 증발되는 정도를 고려하여 증거물 수집방법을 결정한다.","파손성 : 물리적 증거물이 부서지거나, 손상되거나 변하는 정도 등 증거물의 파손성을 고려하여 증거물 수집방법을 결정한다.","물리적 상태 : 물리적 증거물의 상태가 고체, 액체, 또는 기체인지 물리적 상태를 반드시 확인하여 증거물 수집방법을 결정한다.","물리적 특성 : 물리적 증거물의 위치, 가격, 사용가능 여부 등 물리적 특성을 조사관이 파악하여 증거물 수집방법을 결정한다."],4,0,"ew20210307"],["ew20210307-42",2,"T088","2021-03-07",42,82,"타임라인(Time Line)의 설명으로 틀린 것은?",["타임라인은 화재사건의 관계를 보여준다.","타임라인은 화재사건에 관련된 것을 시간적인 순서로 나타낸 것이다.","타임라인은 실제시간이 없이 추정시간으로 구성되기 때문에 정확성이 결여된다.","타임라인은 화재사건이 일어나기 이전, 동안, 이후로 구성될 수 있다."],3,0,"ew20210307"],["ew20210307-43",2,"T092","2021-03-07",43,57,"전기 과부하 증거물에서 나타나는 현상 또는 형태로 옳은 것은?",["헤일로(halo)","포인터 및 화살","슬리빙(sleeving)","엘리게이터(alligator)"],3,0,"ew20210307"],["ew20210307-44",2,"T080","2021-03-07",44,72,"화재현장 증거물 형태에 따른 수집방법으로 옳은 것은?",["알코올은 물과 접촉했을 때 물 위에 뜬다.","액체촉진제는 비다공성 물질에서 채집하기가 용이하다.","액체 증거물은 살균한 솜이나 거즈패드로도 수집할 수 있다.","액체촉진제는 내부 마감재 및 화재 잔해에 쉽게 흡수되지 않는다."],3,0,"ew20210307"],["ew20210307-45",2,"","2021-03-07",45,64,"용융점이 높은 것에서 낮은 순서로 옳게 나열된 것은?",["스테인리스 → 텅스텐 → 동 → 아연 → 마그네슘","스테인리스 → 텅스텐 → 아연 → 마그네슘 → 동","텅스텐 → 스테인리스 → 마그네슘 → 동 → 아연","텅스텐 → 스테인리스 → 동 → 마그네슘 → 아연"],4,0,"ew20210307"],["ew20210307-46",2,"T068","2021-03-07",46,73,"형사소송법 체계상 사진이나 비디오 등 영상물에 대한 법적 증명력을 부여하는 권한을 가진 자로 옳은 것은?",["검사","법관","변호사","피해자"],2,0,"ew20210307"],["ew20210307-47",2,"T082","2021-03-07",47,79,"화재현장 물적 증거물 보존에 대한 설명 중 틀린 것은?",["화재현장 전체를 물적 증거로 생각해야하고 보호 보존되어야 한다.","화재현장에서 물적 증거물의 보존책임은 전적으로 화재조사자에게 있다.","보존상태를 게을리하면 물적 증거물은 파손, 오염, 분실되거나 불필요하게 되는 경우가 발행하기도 한다.","현장지휘관 또는 화재조사자는 불필요하고 인가되지 않은 사람의 침입에 대한 보안을 철저히 하여 화재현장 출입을 제한할 필요가 있다."],2,0,"ew20210307"],["ew20210307-48",2,"T071","2021-03-07",48,73,"피사계 심도를 깊게 하기 위한 방법으로 옳은 것은?",["조리개를 넓힌다.","조리를 좁힌다.","셔터 스피드를 길게 한다.","셔터 스피드를 짧게 한다."],2,0,"ew20210307"],["ew20210307-49",2,"T092","2021-03-07",49,74,"화재현장에서 전기 관련 물적 증거물 수집방법에 대한 설명 중 틀린 것은?",["전기 제품의 경우, 중요 부품 위주로 수집한다.","전선은 가급적 남아 있는 피복까지 검사할 수 있도록 길게 수집하도록 한다.","전기 제품에 대한 분해조사 또는 수집과 이송은 증거물의 발견 당시 상태를 유지하도록 최선을 다해야 한다.","전기설비나 구성부품의 수집 전에 전원의 차단여부를 확인해야 하며 증거물이 발견된 상태 그대로 보존하여야 한다."],1,0,"ew20210307"],["ew20210307-50",2,"T074","2021-03-07",50,66,"화재 증거물 수집 용기 중 유리병에 대한 설명 중 틀린 것은?",["가격이 저렴하고 쉽게 구할 수 있는 장점이 있다.","액체와 고체 촉진제를 장기간 보관할 수 없는 단점이 있다.","유리병은 액체와 고체 촉진제 증거물을 수집하는데 이용 된다.","많은 양의 촉진제 증거물을 수집할 때는 고무로 봉인하지 않는 것이 중요하다."],2,0,"ew20210307"],["ew20210307-51",2,"T093","2021-03-07",51,62,"3도 화상에 대한 설명으로 옳은 것은?",["피하지방을 포함한 피부 전층이 침범되는 화상으로, 외견상 건조하고 회백색을 띠며 수포가 발생하지 않는다.","표피에만 국한되어 나타나고, 모세혈관의 충혈로 인해 종창과 더불어 홍반만 관찰된다.","표피와 함께 진피까지 침범되는 화상으로, 수포가 발생하고 같이 발생하는 홍반은 사후 혈액침하가 일어나도 사라지지 않는다.","피부 및 그 아래의 조직이 탄화되는 것으로 뜨거운 액체에 의한 탕상에서는 보지 못한다."],1,0,"ew20210307"],["ew20210307-52",2,"T072","2021-03-07",52,76,"현장사진 촬영의 필요성에 대한 설명 중 틀린 것은?",["기록과 사진, 영상 모두 한계가 있으므로 문제가 해결될 때까지 현장을 보존하는 것이 가장 중요하다.","사진을 보는 사람이 실제적인 감각으로 느끼게 함으로서 그 때의 상황을 충분히 전달할 수 있는 것이 중요하다.","현장조사 시 실수로 빠트렸거나 수집이 불가능했던 많은 정보와 사실들을 사진을 통해 얻을 수 있다.","화재현장의 소손상황, 감식·감정의 대상이 되는 관계물건 등의 상황을 정확하게 기록하는 수단으로서 사진과 영상이 중요하다."],1,0,"ew20210307"],["ew20210307-53",2,"T069","2021-03-07",53,79,"화재증거물수집관리규칙상 현장 사진 및 비디오 촬영 시 유의사상으로 틀린 것은?",["화재상황을 추정할 수 있는 대상물의 형상은 면밀히 관찰 후 자세히 촬영할 필요 없다.","현장사진 및 비디오 촬영할 때에는 연소확대 경로 및 증거물 기록에 대한 번호표와 화살표를 표시 후에 촬영한다.","증거물을 촬영할 때는 그 소재와 상태가 명백히 나타나도록 하며, 필요에 따라 구분이 용이하게 번호표 등을 넣어 촬영한다.","화재현장의 특정한 증거물 등을 촬영함에 있어서는 그 길이, 폭 등을 명백히 하기 위하여 측정용 자 또는 대조도구를 사용하여 촬영한다."],1,0,"ew20210307"],["ew20210307-54",2,"T076","2021-03-07",54,83,"물리적 증거물의 수송 및 보관에 관한 내용 중 틀린 것은?",["휘발성 증거물을 다룰 때 극한 온도의 영향으로부터 보호되어야 한다.","휘발성 증거물을 보관할 때에는 냉장보관 하는 것이 좋다.","증거물 보관실은 따뜻하고 햇빛이 잘 드는 곳이 좋다.","물리적 증거물의 운반은 화재조사관이 직접 운반하는 것이 원칙이다."],3,0,"ew20210307"],["ew20210307-55",2,"T093","2021-03-07",55,54,"외부에서 열이 가해지면 열에 의한 손상의 범위를 결정하는 사항으로 가장 거리가 먼 것은?",["가연물의 양","가해진 온도","열이 가해진 시간","과다한 열을 배출하는 체표면의 능력"],1,0,"ew20210307"],["ew20210307-56",2,"T090","2021-03-07",56,68,"유류 증거물의 인화점 시험방법으로서 주로 인화점이 93℃ 이하인 시료를 측정하는 데 사용되는 것으로 옳은 것은?",["태그 밀폐식","원자흡광분석","클리브랜드 개방식","펜스키마텐스 밀폐식"],1,0,"ew20210307"],["ew20210307-57",2,"T085","2021-03-07",57,57,"일산화탄소 중독으로 사망한 시체 소견으로 가장 거리가 먼 것은?",["선홍색 시반이 나타난다.","손톱의 경우 청자색을 띤다.","질식사의 일반적 소견이 나타난다.","유동성 혈액, 조직의 울혈이 나타난다."],2,0,"ew20210307"],["ew20210307-58",2,"T069","2021-03-07",58,79,"화재감식을 위한 사진 촬영 시 유의사항 중 틀린 것은?",["작은 물건을 촬영할 때에는 표식을 사용한다.","촬영하는 목적을 충분히 이해하고 나서 촬영한다.","화재감식 현장에서 사용한 장비가 사진에 나오도록 촬영한다.","좁은 방에서 많은 물건을 사진 1매로 찍고자 할 때에는 일반적으로 광각렌즈를 사용한다."],3,0,"ew20210307"],["ew20210307-59",2,"T088","2021-03-07",59,72,"증거의 시간적 역할에 대한 설명으로 옳은 것은?",["깨져 바닥에 쏟아진 유리창의 아랫면에 그을음이 부착되어 있지 않다면 화재 이후 창문이 깨졌다는 것을 의미한다.","화재현장에서 발견된 소사체에서 생활반응이 발견된다면 피해자는 화재 이전 사망한 상태였다는 것을 알 수 있다.","화재와 폭발이 일어난 현장에서 멀리까지 비산된 유리창의 파편에 그을음이 부착되어 있다면 화재가 먼저 일어나 이로 인해 폭발이 발생한 것으로 볼 수 있다.","타이어 흔적 위로 족적이 찍혀 있다면 이러한 증거는 차량이 지나가기 전에 누군가 걸어갔다는 것을 증명해 주는 역할을 한다."],3,0,"ew20210307"],["ew20210307-60",2,"T075","2021-03-07",60,69,"증거수집 과정에서 오염이 발생할 수 있는 요인에 대한 설명 중 가장 거리가 먼 것은?",["대부분 증거물의 오염은 수집 중에 야기된다.","증거물 수집 시 새로운 장갑을 항상 사용하여야 한다.","증거물의 오염은 액체 및 고체 촉진제 수집시 더욱 확실시 된다.","수집 중 오염을 줄이기 위해 증거물 보관 용기의 뚜껑 등을 수집기구로 사용하여서는 안 된다."],4,0,"ew20210307"],["ew20210307-61",3,"T111","2021-03-07",61,49,"화재조사 및 보고규정상 화재현황 조사서에 기입해야 할 항목 중 틀린 것은?",["기상상황","소방시설 현황","피해 및 인명구조","화재발생 일 시 및 장소"],2,0,"ew20210307"],["ew20210307-62",3,"T115","2021-03-07",62,60,"화재조사 및 보고규정상 피해산정 대상들 중 최종잔가율이 10%인 것은?",["침대","전기설비","절삭공구","옥내소화전"],3,0,"ew20210307"],["ew20210307-63",3,"T120","2021-03-07",63,60,"화재조사 및 보고규정상 화재피해 건물의 동수 산정 중 틀린 것은?",["주요구조부가 하나로 연결되어 있는 것과 건널 복도 등으로 2이상의 동에 연결되어 있는 것은 1동으로 한다.","독립된 건물과 건물 사이에 차광막, 비막이 등의 덮개를 설치하고 그 밑을 통로 등으로 사용하는 경우는 다른 동으로 한다.","건물의 외벽을 이용하여 실을 만들어 헛간, 목욕탕, 작업실, 사무실 및 기타 건물 용도로 사용하고 있는 것은 주건물과 같은 동으로 본다.","목조 또는 내화조 건물의 경우 격벽으로 방화구획이 되어 있는 경우 같은 동으로 한다."],1,0,"ew20210307"],["ew20210307-64",3,"T118","2021-03-07",64,50,"화재조사 및 보고규정상 화재유형별 조사서 작성 대상 화재가 아닌 것은?",["임야 화재","기타 화재","건축·구조물 화재","위험물·가스제조소 화재"],2,0,"ew20210307"],["ew20210307-65",3,"T101","2021-03-07",65,62,"화재조사 및 보고규정상 화재의 소실정도에 대한 설명으로 옳은 것은?",["국소란 건물의 50% 이상 70% 미만이 소실된 것을 말한다.","부분소란 전소, 반소화재에 해당되지 아니하는 것을 말한다.","전축·구조물화재의 소실정도는 전소, 반소, 부분소, 즉소 4종류로 구분한다.","전소란 건물의 70% 이상(바닥면적에 대한 비율을 말한다.)이 소실되었거나 또는 그미만이라도 잔존부분을 보수하여도 재사용이 불가능 한 것을 말한다."],2,0,"ew20210307"],["ew20210307-66",3,"T102","2021-03-07",66,65,"난로의 과열로 인해 화재가 발생하여 바닥 5m2와 한쪽 벽 3m2만 소실되었을 경우, 화재피해조사서(재산피해) 작성 시 소실면적은?(2023년 03월 08일 변경된 규정 적용됨)",["1.6m2","2m2","5m2","8m2"],3,0,"ew20210307"],["ew20210307-67",3,"T116","2021-03-07",67,50,"화재 당시 피해물에 잔존하는 경제적 가치의 정도로써 비율로 표시되는 잔가율의 산정식으로 틀린 것은?",["90%-감가수정율","현재가(시가)/재구입비","(재구입비-감가수정액)/재구입비","1-(1-최종잔가율)×경과년수/내용년수"],1,0,"ew20210307"],["ew20210307-68",3,"T128","2021-03-07",68,50,"화재조사 및 보고규정상 화재현장 조사서 작성항목 중 화재건물 현황 작성내용으로 명시되지 않은 것은?",["보험가입 현황","화재발생전 상황","화재진압 활동 현황","소방시설 및 위험물 현황"],3,0,"ew20210307"],["ew20210307-69",3,"T110","2021-03-07",69,71,"화재조사 및 보고규정상 사상자 및 부상정도에 관한 설명으로 틀린 것은?",["병원치료를 필요로 하지 않고 단순하게 연기를 흡입한 사람은 경상에서 제외한다.","3주 이상 입원치료를 필요로 하는 부상은 중상으로 기재한다.","화재현장에서 부상을 당한 후 입원치료를 필요로 하지 않는 경우 부상으로 기재하지 않는다.","화재현장에서 부상을 당한 후 정확히 72시간 이내에 사망하였다면 이는 사망으로 보고서에 기재하여야 한다."],3,0,"ew20210307"],["ew20210307-70",3,"T122","2021-03-07",70,64,"동물 및 식물의 피해액 산정방법으로 틀린 것은?",["정원은 구축물로 분류한다.","시중매매가격을 화재로 인한 피해액으로 한다.","동물 및 식물의 종류에 따라 구입가격의 50~80%를 피해액으로 한다.","화분은 가재도구 또는 영업용 집기비품으로 분류한다."],3,0,"ew20210307"],["ew20210307-71",3,"","2021-03-07",71,68,"화재조사 및 보고규정상 화재피해 조사 및 피해액 산정순서로 옳은 것은?",["화재현장 조사 → 피해정도 조사 → 기본현황 조사 → 재구입비 산정 → 피해액 산정","화재현장 조사 → 기본현황 조사 → 피해정도 조사 → 재구입비 산정 → 피해액 산정","기본현황 조사 → 피해정도 조사 → 화재현장조사 → 재구입비 산정 → 피해액 산정","기본현황 조사 → 피해정도 조사 → 재구입비 산정 → 피해액 산정 → 화재현장조사"],2,0,"ew20210307"],["ew20210307-72",3,"T104","2021-03-07",72,74,"화재피해액 산정기준에서의 화재피해액 산정대상으로 옳은 것은?",["특허권","인적손해","영업이익","애완동물"],4,0,"ew20210307"],["ew20210307-73",3,"T131","2021-03-07",73,77,"화재조사 및 보조규정상 조사본부장의 책임에 명시되지 않는 것은?",["조사기록 서류 등의 분석 및 관리","조사본부 운영 및 총괄에 관한 사항처리","조사요원 등의 지휘감독과 화재조사 집행","현장보존, 정보관리 및 관계기관에서의 협조"],1,0,"ew20210307"],["ew20210307-74",3,"T124","2021-03-07",74,80,"화재현장에 출동한 119안전센터 등의 선임자에 의해 화재현장 상황에 대하여 기술한 것으로 초기 화재상황 파악에 귀중한 자료가 되는 보고서로 옳은 것은?",["질문기록서","화재피해조사서","화재현장조사서","화재현장 출동보고서"],4,0,"ew20210307"],["ew20210307-75",3,"","2021-03-07",75,70,"피해물로 인해 장래에 얻을 수익액에서 당해 수익을 얻기 위해 지출되는 제반 비용을 공제하는 방법에 의하는 손해액 산정방법으로 옳은 것은?",["정액법","수익환원법","복성식 평가법","매매사례비교법"],2,0,"ew20210307"],["ew20210307-76",3,"T104","2021-03-07",76,79,"화재조사 및 보고규정상 화재피해조사의 범위에 명시되지 않은 것은?",["영업상의 손실","연기에 의한 피해","소화활동으로 발생한 수손피해","열에 의한 탄화, 용융, 파손 등에 피해"],1,0,"ew20210307"],["ew20210307-77",3,"T116","2021-03-07",77,68,"내용연수에 대한 설명으로 가장 거리가 먼 것은?",["내용연수란 고정자산 등을 사용할 수 있는 기간을 말한다.","내용연수는 물리적 내용연수와 경제적 내용연수로 구분된다.","화재피해액 산정에 있어서 보통 경제적 내용연수를 적용하게 된다.","경제적 내용연수에 비해 물리적 내용연수가 더 짧은 것이 보통이다."],4,0,"ew20210307"],["ew20210307-78",3,"T121","2021-03-07",78,81,"화재조사 및 보고규정상 질문기록서 작성을 생략할 수 있는 화재로 옳은 것은?",["임야화재","건축·구조물 화재","자동차·철도차량 화재","위험물·가스제조소등 화재"],1,0,"ew20210307"],["ew20210307-79",3,"T130","2021-03-07",79,50,"항공기, 선박, 철도차량, 특수작업용차량, 시중매매가격이 확인되지 아니하는 자동차에 대한 피해에 산정기준 중 틀린 것은?",["수리가 가능한 경우에는 수리비를 피해액으로 한다.","감정평가서가 없는 경우 회계장부상의 현재가액에 손해율을 곱한 금액을 화재로 인한 피해액으로 한다.","감정평가서가 있는 경우 감정평가서상의 현재가액에 손해율을 곱한 금액을 화재로 인한 피해액으로 한다.","감정평가서와 회계장부 모두 없는 경우에는 제조회사, 판매회사, 조합 또는 협회 등에 조회하여 구입가격 또는 시중거래가격을 확인하여 피해액을 산정한다."],1,0,"ew20210307"],["ew20210307-80",3,"T108","2021-03-07",80,77,"화재조사 및 보고규정상 화재조사에 필요한 서류의 서식이 아니 것은?",["화재현황조사서","화재현장조사서","화재유형별조사서","건축용도별 조사서"],4,0,"ew20210307"],["ew20210307-81",4,"","2021-03-07",81,54,"경범죄 처벌법상의 처벌 대상이 아닌 경우는?",["정당한 사유 없이 소방용수시설을 사용한 사람","있지 아니한 범죄나 재해사실을 공무원에게 거짓으로 신고한 사람","충분한 주의를 하지 아니하고 휘발유 그 밖에 불이 옮아 붙기 쉬운 물건 가까이에서 불씨를 사용한 사람","지진 등으로 인한 화재가 발생하였을 때에 현장에 있으면서도 정당한 이유 없이 공무원이 도움을 요청하여도 도움을 주지 아니한 사람"],1,0,"ew20210307"],["ew20210307-83",4,"T154","2021-03-07",83,53,"형법상 화재에 있어서 진화용의 시설 또는 물건을 은닉 또는 손괴하거나 기타 방법으로 진화를 방해한 자는 몇 년 이하의 징역에 처하는가?",["3","5","7","10"],4,0,"ew20210307"],["ew20210307-85",4,"T149","2021-03-07",85,49,"화재로 인한 재해보상과 보험가입에 관한 법령상 화재로 인한 부상 발생 시 보험금액과 상해부위의 연결이 틀린 것은?",["1천만원 - 슬개 인대 파열","1200만원 - 손목 손배뼈 골절","1500만원 - 위팔뼈목 골절","3천만원 - 척추체 분쇄성 골절"],3,0,"ew20210307"],["ew20210307-86",4,"","2021-03-07",86,74,"화재조사 및 보고규정상 화재증명원 발급에 대한 설명 중 옳은 것은?",["보험사에서 공문으로 발급을 요청시 공용 발급할 수 없다.","화재증명원 발급 시 재산피해 및 인명피해에 대해 조사 중인 경우에는 발급할 수 없다.","화재증명원 발급 시 재산피해내역은 금액과 피해물건을 함께 기재한다.","화재피해자로부터 소방대가 출동하지 아니한 화재장소의 화재증명원 발급요청이 있는 경우 조사관으로 하여금 사후 조사를 실시하게 할 수 있다."],4,0,"ew20210307"],["ew20210307-87",4,"T156","2021-03-07",87,68,"실화의 특수성을 고려하여 실화자에게 중대한 과실이 없는 경우 그 손해배상액의 경감에 관한 「민법」 제765조의 특례를 정함을 목적으로 하는 법률은?",["소방기본법","실화책임에 관한 법률","화재예방, 소방시설 설치·유지 및 안전관리에 관한 법률","화재로 이한 재해 보상과 보험가입에 관한 법률"],2,0,"ew20210307"],["ew20210307-88",4,"T173","2021-03-07",88,70,"민법상 불법행위에 관한 설명으로 틀린 것은?",["타인의 생명을 해한 자는 피해자의 직계존속에 대하여는 재산상의 손해 없는 경우에는 손해배상의 책임이 없다.","고의 또는 과실로 인한 위법행위로 타인에게 손해를 가한 자는 그 손해를 배상할 책임이 있다.","미성년자가 타인에게 손해를 가한 경우에는 그 행위의 책임을 변식할 지능이 없는 때에는 배상의 책임이 없다.","타인의 신체, 자유 또는 명예를 해하거나 기타 정신상고통을 가한 자는 재산 이외의 손해에 대하여도 배상할 책임이 있다."],1,0,"ew20210307"],["ew20210307-89",4,"T168","2021-03-07",89,71,"화재로 인한 재해보상과 보험가입에 관한 법령상 보험가입의 의무에 관한 설명으로 틀린 것은?",["특수건물의 소유자는 특약부화재보험에 관한 계약을 매년 갱신하여야 한다.","특수건물의 소유자는 특약부화재보험에 부가하여 건물의 무너짐 등으로 인한 손해를 담보하는 보험에 가입할 수 있다.","특수건물의 소유자는 특수건물의 소유권이 변경된 경우 그 소유권을 취득한 날부터 10일 이내에 특약부화재보험에 가입하여야 한다.","금융위원회는 보험가입 의무자가 그 보험에 가입하지 아니한 경우에는 관계 행정기관에 가입 의무자에 대한 인·허가의 취소 등 필요한 조치를 할 것을 요청할 수 있다."],3,0,"ew20210307"],["ew20210307-90",4,"T157","2021-03-07",90,76,"화재증거물수집관리규칙상 증거물 수집관리 등에 관한 설명으로 틀린 것은?",["화재증거물의 포장은 보호상자를 사용하며 개별 포장은 지양한다.","화재증거물은 기술적, 절차적인 수단을 통해 진정성, 무결성이 보존되어야 한다.","최종적으로 법정에 제출되는 화재증거물의 원본성이 보장되어야 한다.","화재조사요원 등은 화재발생시 신속히 현장에 가서 화재조사에 필요한 현장사진 및 비디오 촬영을 반드시 하여야 한다."],1,0,"ew20210307"],["ew20210307-91",4,"T164","2021-03-07",91,56,"화재로 인한 재해보상 보험가입에 관한 법령상 유통산업발전법에 의한 대규모점포는 사용하는 부분의 바닥면적의 합계가 몇 제곱미터이상인 경우 특수건물에 해당하는가?",["1천","2천","2천5백","3천"],4,0,"ew20210307"],["ew20210307-93",4,"T142","2021-03-07",93,71,"화재조사 및 보고규정상 ‘최종잔가율’의 용어 정의로 옳은 것은?",["고정자산을 경제적으로 사용할 수 있는 일정 비율","화재 당시에 피해물의 재구입비에 대한 현재가의 비율","피해물의 경제적 내용연수가 다한 경우 잔존하는 가치의 재구입비에 대한 비율","피해물의 손상상태 및 정도에 따라 피해액을 최종적으로 적정화 시키는 비율"],3,0,"ew20210307"],["ew20210307-95",4,"T174","2021-03-07",95,71,"형사소송법상 검사 또는 사법경찰관이 피의자를 신문하기 전 고지사항으로 틀린 것은?",["일체의 진술을 하지 아니하거나 개개의 질문에 대하여 진술하지 아니할 수 있다는 것","진술을 하지 아니하더라도 불이익을 받지 아니한다는 것","신문을 받을 때에는 변호인을 참여하게 하는 등 변호인의 조력을 받을 수 있다는 것","진술을 거부할 권리를 포기하고 행한 진술을 법정에서 유죄의 증거로 사용될 수 없다는 것"],4,0,"ew20210307"],["ew20210307-96",4,"","2021-03-07",96,70,"소방기본법령상 화재발생 빈도와 화재조사의 중요성을 감안하여 시·도 소방본부장이 권역별로 별도로 지정한 소방서로 옳은 것은?",["권역소방서","거점소방서","선입소방서","지정소방서"],2,0,"ew20210307"],["ew20210307-97",4,"T163","2021-03-07",97,75,"화재조사 및 보고규정상 화재조사 활동 중 소방본부장 또는 소방서장이 소방청장에게 긴급상황을 보고하여야 할 화재로 틀린 것은?",["정부미 도정공장 화재","발전소 및 변전소의 화재","이재민 150명 발생된 화재","재산피해 30억원 추정되는 화재"],4,0,"ew20210307"],["ew20210307-99",4,"","2021-03-07",99,67,"소방기본법령상 손실보상심의위원회(이하 ‘보상위원회’라 한다)에 관한 설명으로 틀린 것은?",["위촉되는 위원의 임기는 3년으로 하며, 연임할 수 없다.","보상위원회의 사무를 처리하기 위하여 보상위원회에 간사 1명을 둔다.","보상위원회는 위원장 1명을 포함하여 5명 이상 7명 이하의 위원으로 구성한다.","고등교육법에 따른 학교에서 행정학을 가르치는 부교수 이상으로 5년 이상 재직한 사람은 보상위원회 위원이 될 수 있다."],1,0,"ew20210307"],["ew20210307-100",4,"T152","2021-03-07",100,67,"형법상 시청을 방화한 경우, 방화 시 민원인들이 시청 내에 있었다면 어떤 범죄가 성립하는가?",["일반물건에의 방화죄","공용건조물 등에의 방화죄","현주건조물 등에의 방화죄","일반건조물 등에의 방화죄"],3,0,"ew20210307"],["ew20210515-1",0,"T009","2021-05-15",1,77,"화재가 발생한 후 현장에 놓여 있던 가정용 LPG 용기가 가열되어 폭발이 발생하였을 때, 이 폭발의 원인으로 옳은 것은?",["확산 폭발","물리적 폭발","응상 폭발","화학적 폭발"],2,0,"ew20210515"],["ew20210515-2",0,"","2021-05-15",2,73,"화재조사 및 보고규정상 화재조사 활동 중 소방청장에게 긴급상황을 보고해야 하는 화재 중 중요화재에 해당되지 않는 것은?",["이재민 100명 이상 발생화재","외국공관 및 그 사택의 화재","관공서, 학교, 문화재, 지하철 등 공공건물 및 시설의 화재","관광호텔, 고층건물, 지하상가, 시장, 백화점 등의 화재"],2,0,"ew20210515"],["ew20210515-4",0,"T024","2021-05-15",4,88,"고체 위의 화염확산에 대한 설명 중 틀린 것은?",["고체에서의 화염 확산 속도는 연료의 두께와 관련이 없다.","얇은 연료 위의 순방향 화염은 상향 화염확산으로 일어난다.","같은 물질일수록 두께가 얇은 연료가 화염확산 속도가 빠르다.","크기가 같은 목재와 폴리우레탄폼에 대한 화염확산 속도는 폴리우레탄폼이 빠르다."],1,0,"ew20210515"],["ew20210515-5",0,"T003","2021-05-15",5,61,"목재 표면의 균열흔 중 홈이 반월형의 모양으로 높아지며, 특히 대규모 건물화재에서 볼 수 있는 것은?",["강소흔","약소흔","열소흔","완소흔"],3,0,"ew20210515"],["ew20210515-6",0,"T016","2021-05-15",6,92,"화재조사 및 보고규정상 소방활동구역의 설정 및 현장보존에 대한 설명 중 틀린 것은?",["소방활동구역의 관리는 수사기관과 상호 협조해야 한다.","소방활동구역의 표시는 로프 등으로 범위를 한정하고 경고판을 부착한다.","소방활동구역의 설정은 최대한의 범위로 한다.","소방서장 등은 소화활동시 현장물건 등의 이동 또는 파괴를 최소화하여 원활한 화재조사활동이 이루어질 수 있도록 현장보존에 노력해야 한다."],3,0,"ew20210515"],["ew20210515-7",0,"T012","2021-05-15",7,87,"소방기본법령상 화재조사를 하는 관계공무원이 관계인의 정당한 업무를 방해하거나 화재조사를 수행하면서 알게 된 비밀을 다른 사람에게 누설하였을 때의 벌칙기준으로 옳은 것은?",["100만원 이하의 벌금","150만원 이하의 벌금","200만원 이하의 벌금","300만원 이하의 벌금"],4,0,"ew20210515"],["ew20210515-8",0,"","2021-05-15",8,66,"자동화재탐지설비 및 시각경보장치의 화재안전기준상 감지기를 설치하지 아니하는 장소로 명시되지 않은 것은?",["복도","헛간","목욕실","프레스공장"],1,0,"ew20210515"],["ew20210515-9",0,"T001","2021-05-15",9,70,"V자 화재패턴에 대한 설명으로 옳은 것은?",["V자 패턴의 각은 환기에 영향을 받는다.","V자 패턴의 각은 열방출룰에 영향을 받지 않는다.","V자 패턴의 각은 가연물의 형상에 영향을 받지 않는다.","V자 각이 큰 것은 화재의 성장속도가 느렸다는 증거이며 V각이 작은 경우는 화재의 성장속도가 빨랐다는 증거이다."],1,0,"ew20210515"],["ew20210515-10",0,"T010","2021-05-15",10,79,"연소범위가 2.5~81vol%인 아세틸렌의 위험도로 옳은 것은?",["0.27","12.7","31.4","38.8"],3,0,"ew20210515"],["ew20210515-11",0,"T007","2021-05-15",11,75,"분진폭발을 가스폭발과 비교할 때 분진폭발의 특징으로 옳은 것은?",["연소시간이 짧다.","불완전연소를 일으키기 어렵다.","연소속도가 빠르다.","최소발화에너지가 크다."],4,0,"ew20210515"],["ew20210515-12",0,"T003","2021-05-15",12,82,"목재의 탄화심도 측정 시 유의사항 중 틀린 것은?",["측정 기구는 목재와 직각으로 삽입하여 측정한다.","게이지로 측정된 깊이 외에 소실된 부분의 깊이를 더하여 비교하여야 한다.","탄화된 요철 부위 중 철(凸) 부위를 택하여 측정한다.","탄화되지 않은 곳까지 삽입될 수 있으므로 송곳과 같은 날카로운 측정 기구를 사용한다."],4,0,"ew20210515"],["ew20210515-13",0,"T008","2021-05-15",13,65,"프로판 50vol%, 메탄 30vol%, 수소 20vol%의 조성으로 혼합된 가연성연료가 공기 중에 존재한다고 할 때 이 연료가스의 연소하한계(LFL)는? (단, 프로판의 LFL은 2.1vol%, 메탄의 LFL은 5vol%, 수소의 LFL은 4vol% 이다.)",["약 2.27vol%","약 2.87vol%","약 3.97vol%","약 4.07vol%"],2,0,"ew20210515"],["ew20210515-14",0,"T006","2021-05-15",14,53,"열전달에 대한 설명 중 틀린 것은?",["열전달 방식 중 가장 빠른 것은 복사이다.","유체의 가장 높은 곳에 열원이 있다면 대류는 발생하지 않는다.","유체인 원유를 보관하는 탱크에서 보일오버(Boil over)현상의 주요 열전달 메커니즘은 대류에 의한 것이다.","천정부 열기층을 살펴보면 구획실 화재에서 고온부와 저온부의 순환이 일어나지 않는다는 것을 알 수 있다."],3,0,"ew20210515"],["ew20210515-15",0,"T014","2021-05-15",15,91,"화재현장 조사를 할 때 유의해야 할 사항 중 틀린 것은?",["보도기관 등 대외발표를 신중하게 할 것","화재현장 출입 시 신분을 명확히 밝힐 것","화재 조사 시 피해자 또는 관계자를 정중하게 대할 것","화재관계자의 민사상 다툼에 대해 직무와 관련하여 적극적으로 개입할 것"],4,0,"ew20210515"],["ew20210515-16",0,"T014","2021-05-15",16,92,"화재현장에서 화재감식요원의 마음가짐과 가장 거리가 먼 것은?",["선입견을 가지고 현장 사물을 관찰한다.","현장에 대해서는 항상 겸손하게 생각한다.","불필요한 전문용어의 사용으로 자신의 의견을 과대포장하는 행위를 하지 말아야 한다.","감식결과는 누구에게 유리하거나 불리함을 고려하지 않고, 과학적이고 논리적인 근거에 의해서 말해야한다."],1,0,"ew20210515"],["ew20210515-17",0,"T024","2021-05-15",17,79,"비가연성 재료로 구획된 방의 각 위치에 동일한 방법으로 동일한 가연물에 착화하여 동일한 시간이 경과된 후의 모습을 관찰하였을 때의 설명으로 옳은 것은?",["화염의 길이는 모두 동일하다.","한 개의 벽과 접한 화염의 길이가 가장 길다.","벽과 접하지 않은 방 중앙 화염의 길이가 가장 길다.","두 개의 벽이 만나는 코너와 접한 화염의 길이가 가장 길다."],4,0,"ew20210515"],["ew20210515-18",0,"T023","2021-05-15",18,74,"연소 현상 중 완전연소에 대한 설명으로 옳은 것은?",["산소의 공급이 불충분한 상태에서의 연소현상이다.","연소 시 다량의 가연성 가스의 공급이 완전연소의 원인이 된다.","탄화수소가 완전연소하면 이산화탄소와 수증기가 생성된다.","환기가 제대로 되지 않은 상태에서의 실내에 가스기구를 사용하는 경우에 발생한다."],3,0,"ew20210515"],["ew20210515-19",0,"T020","2021-05-15",19,87,"가연물별 분류에 따른 화재와 색상이 옳은 것은?",["금속화재 - 무색","유류화재 - 백색","일반화재 - 황색","전기화재 – 빨간색"],1,0,"ew20210515"],["ew20210515-20",0,"T001","2021-05-15",20,83,"액체가연물이 연소되면서 발생되는 열에 의해 가열되어 주변으로 튀거나, 액체를 뿌릴 때 바닥 면에 액체 방울이 튄 것처럼 연소하는 패턴으로 옳은 것은?",["포어 패턴(pour pattern)","고스트 마크(ghost mark)","도넛 패턴(doughnut pattern)","스플래쉬 패턴(splash pattern)"],4,0,"ew20210515"],["ew20210515-21",1,"","2021-05-15",21,60,"혼합해도 폭발 또는 발화 위험과 가장 거리가 먼 것은?",["아세틸렌 + 아세톤","염소산칼륨 + 유황","과산화나트륨 + 알루미늄분","금속나트륨 + 에틸알콜"],1,0,"ew20210515"],["ew20210515-22",1,"T033","2021-05-15",22,62,"방화의 일반적인 특징으로 틀린 것은?",["피해범위가 대체로 넓다.","동기로는 원한이나 보복 등 정신적인 요인에 기인하는 경우가 많다.","우발적이기 보다는 계획적으로 발생하는 경우가 많다.","재산보다는 인명을 대상으로 하는 경우가 많다."],3,0,"ew20210515"],["ew20210515-23",1,"","2021-05-15",23,78,"화재나 폭발에 대한 가설로부터 의견을 개진할 때에 조사관이 세우는 확신 수준으로서 '상당히 근거 있음(Probable)'은 가설이 진실일 가능성이 얼마 이상인 경우에 해당하는가?",["20% 이상","30% 이상","40% 이상","50% 이상"],4,0,"ew20210515"],["ew20210515-24",1,"T054","2021-05-15",24,44,"표준상태 0℃, 1기압에서 메탄(CH4) 3.2kg을 이상기체 상태방정식으로 계산하면 부피는? (단, 기체상수(R) : 0.082 L·atm/mol·K, 탄소 원자량 : 12, 수소 원자량 : 1로 계산한다.)",["223.8 L","447.7 L","2238.6 L","4477.2 L"],4,0,"ew20210515"],["ew20210515-25",1,"T033","2021-05-15",25,87,"방화로 의심할 수 있는 경우가 아닌 것은?",["출입문이 잠겨 있는 경우","촉진제의 용기가 발견된 경우","외부침입 흔적이 발견된 경우","다른 범죄의 증거가 발견된 경우"],1,0,"ew20210515"],["ew20210515-26",1,"T041","2021-05-15",26,85,"산불의 강도를 가중시키는 지형으로 틀린 것은?",["평지","굴뚝지형","가파른 경사","연료온도를 증가시키는 사면"],1,0,"ew20210515"],["ew20210515-27",1,"T045","2021-05-15",27,89,"자동차 본체의 주요장치에 포함되지 않는 것은?",["연료장치","점화장치","윤활장치","방향지시장치"],4,0,"ew20210515"],["ew20210515-28",1,"T039","2021-05-15",28,81,"산불화재 확산에 영향을 미치는 요인으로 가장 거리가 먼 것은?",["풍속","수종","점화원","경사도"],3,0,"ew20210515"],["ew20210515-29",1,"T064","2021-05-15",29,71,"석유류의 연소특성에 대한 설명 중 틀린 것은?",["휘발성이 낮은 중질유는 미세한 크기로 미립화하여 분무연소한다.","휘발유, 등유는 증기비중이 공기보다 크기 때문에 증발한 증기는 낮은 곳에 체류한다.","원유탱크의 화재가 장시간 지속되면 고온층이 형성되어 유류화재의 위험한 현상들이 나타날 수 있다.","대부분의 석유류가 포함되어 있는 제4류 위험물은 인화점이 높고, 연소하한계가 높아서 화재위험성이 크다."],4,0,"ew20210515"],["ew20210515-30",1,"T042","2021-05-15",30,63,"담뱃불의 착화가능성에 대한 설명으로 옳은 것은?",["가솔린의 착화점은 430~550℃로서 담뱃불의 표면에서 발생되는 열로 착화가 용이하다.","도시가스는 탄화수소의 혼합물로 조성되어 있으며, 주성분인 수소의 착화점이 585℃로서 담뱃불의 표면에서 발생되는 열로 인해 착화가 용이하다.","면제품(방석, 이불, 의류 등)은 무염착화 후 무염연소를 계속하며 가연물이나, 조연재, 공기 유입 등의 연소조건이 갖추어지면 유염연소로 이어진다.","발포스티로폼은 담뱃불이 접촉되면 쉽게 용융되어 착화가 용이하다."],3,0,"ew20210515"],["ew20210515-31",1,"","2021-05-15",31,55,"가스 연소 현상에서 역화(Flash Back)의 원인으로 가장 거리가 먼 것은?",["가스 압력이 낮은 경우","노즐구경이 너무 큰 경우","코크가 충분히 열리지 않은 경우","부식으로 인하여 염공이 커진 경우"],2,0,"ew20210515"],["ew20210515-32",1,"T045","2021-05-15",32,79,"자동차화재의 특성에 대한 설명으로 옳은 것은?",["차량화재의 조사는 특별한 전문지식이 없어도 화재조사가 가능하다.","차량화재는 대체로 전소가 되지 않기 때문에 발화지점 및 발화원인이 조사가 용이하다.","차량화재는 연료, 시트 등 화재비중이 낮고, 외기와 밀폐된 상태인 환기 지배형의 화재특성을 보인다.","개방된 공간에 존치되는 환경적인 특수성으로 인해 사회적인 불만을 가진 사람 등이 불특정한 방법으로 방화를 할 수 있다."],4,0,"ew20210515"],["ew20210515-33",1,"T055","2021-05-15",33,66,"분진폭발을 일으킬 가능성이 없는 것은?",["목분","산화규소 분말","마그네슘 분말","폴리에틸렌 분말"],2,0,"ew20210515"],["ew20210515-34",1,"T048","2021-05-15",34,55,"세탁기 화재 시 확인해야 할 조사요점으로 가장 거리가 먼 것은?",["배수모터의 이상 유무","마그네트론의 발열 여부","세탁기 내부 배선의 단락 여부","기동용 콘덴서의 절연열화 상태"],2,0,"ew20210515"],["ew20210515-35",1,"T037","2021-05-15",35,74,"선박의 구획 및 일반배치에 대한 설명 중 틀린 것은?",["선수부, 화물창, 기관실, 선미부로 크게 구분된다.","코퍼댐(cofferdam)을 두어 기관실 및 선수구역을 안전구역에서 제외한다.","원유 운반선, 액화가스 운반선에서는 화물창 전후방에 코퍼댐(cofferdam)을 둔다.","구획은 수밀격벽으로 막혀 물이 드나들 수 없는 하나의 독립된 공간을 뜻한다."],2,0,"ew20210515"],["ew20210515-36",1,"T035","2021-05-15",36,61,"항공기 화재방지계통(fire protection system)에서 “Fixed”의 정의에 대한 설명 중 틀린 것은?",["물 소화기를 계통 내에 영구적으로 장착하는 것을 말한다.","휴대용 소화기를 계통 내에 영구적으로 장착하는 것을 말한다.","할론(halon) 소화기를 계통 내에 영구적으로 장착하는 것을 말한다.","외부 소방시설을 연결하는 장치를 계통 내에 영구적으로 장착하는 것을 말한다."],4,0,"ew20210515"],["ew20210515-37",1,"T064","2021-05-15",37,83,"석유류를 사용한 방화현장에서 수거한 증거물로부터 화재원인 물질을 밝혀내기 위해 사용하는 가장 일반적인 분석기기로 옳은 것은?",["원소분석기","질량분석기","이온교환수지","가스크로마토그래피"],4,0,"ew20210515"],["ew20210515-38",1,"T049","2021-05-15",38,56,"어떤 도체의 단면을 0.5초간에 0.032C 의 전하가 이동했을 때, 흐르는 전류(I)의 크기는?",["16mA","32mA","64mA","128mA"],3,0,"ew20210515"],["ew20210515-39",1,"T050","2021-05-15",39,70,"정전기 대전현상에 대한 설명 중 옳은 것은?",["분출대전이란 분체, 액체, 기체가 단면적이 작은 개구부에서 분출 시 대전되는 현상","충돌대전이란 물체가 마찰을 일으킬 때 대전되는 현상","마찰대전이란 상화 밀착된 물체가 분리될 때 대전되는 현상","유도대전이란 액체류가 배관 내부 이송할 때 대전되는 현상"],1,0,"ew20210515"],["ew20210515-40",1,"T061","2021-05-15",40,74,"발화원인 판정 시 발화가능성이 있는 시설이나 기구에 대한 주의사항 중 틀린 것은?",["사전 지식이 없는 복잡한 기기나 장치에 대해서는 조사관이 직접 검사한다.","가능성에 대해서는 하나씩 짚어가며 검사를 해야 하고, 배제해 나가는 것을 원칙으로 한다.","탄화된 증거물들은 쉽게 부서지며 잊어버리기 쉬우므로 손을 대기 전에 사진 등으로 채증을 먼저 해야 한다.","발화하였다고 의심되는 기기나 장치가 이동이 가능한 경우에는 복잡한 현장에서 보다 안정적인 실험실로 옮겨 조심스럽게 분해하는 것을 권장한다."],1,0,"ew20210515"],["ew20210515-41",2,"T071","2021-05-15",41,53,"피사계 심도(Depth of field)에 대한 설명으로 틀린 것은?",["피사계 심도가 깊어지면 상세하게 보는데 걸리는 시간이 단축된다.","초점거리가 주어진 렌즈에서는 f-stop이 클수록 피사계 심도가 깊어질 것이다.","피사계 심도는 촬영하는 사물까지의 거리, 렌즈 구경 및 사용하는 렌즈의 초점 거리에 따라 달라진다.","피사계 심도는 어느 정해진 시간 동안에 초점이 맞는 가장 멀리 있는 사물과 가장 가까이 있는 사물의 거리이다."],1,0,"ew20210515"],["ew20210515-42",2,"T072","2021-05-15",42,83,"화재조사현장 사진촬영의 필요성과 가장 거리가 먼 것은?",["현장조사 시 실수로 빠트린 정보와 사실들을 얻을 수 있다.","사진을 보는 사람이 실제적인 감각으로 느끼게 할 수 있다.","촬영한 사진은 글로 자세한 설명을 해야만 알 수 있다.","사진을 통해 화재현장의 소손상황, 감식·감정 대상의 물건 등을 정확하게 기록할 수 있다."],3,0,"ew20210515"],["ew20210515-43",2,"T069","2021-05-15",43,83,"화재현장 사진 촬영 시 유의사항으로 틀린 것은?",["화재현장 사진은 화재조사자의 의도를 이해하여 촬영한다.","중요한 증거 물건은 표지, 번호표 등으로 명확하게 표시한다.","주변 인물, 발굴용기구 등을 중점적으로 촬영하여야 한다.","화재현장 사진은 수정하기가 불가능하므로 촬영에 심혈을 기울인다."],3,0,"ew20210515"],["ew20210515-44",2,"T097","2021-05-15",44,60,"화재로 인한 사망에 대한 설명으로 옳은 것은?",["폐부종과 염증은 자극적인 가스에 노출되었음을 나타내는 증거다.","시간이 지날수록 사후강직은 심해지고 관절과 근육은 뻣뻣해 진다.","화재현장의 희생자는 주로 이산화탄소 때문에 사망한다.","사망 후 근육조직의 화학적인 변화로 굳는 것을 시반이라고 한다."],1,0,"ew20210515"],["ew20210515-45",2,"T091","2021-05-15",45,74,"열에 의해 생성된 유리의 파손 형태에 대한 설명으로 옳은 것은?",["깨진 유리의 단면에 리플마크가 형성된다.","길고 구불구불한 불규칙 형태의 금을 형성한다.","직선으로 구성된 거미줄 모양의 선을 형성한다.","날카로운 예각으로 구성된 삼각형의 금을 형성한다."],2,0,"ew20210515"],["ew20210515-46",2,"","2021-05-15",46,59,"화재현장에서 사체가 완전 탄화된 채 발견되었을 경우 신원확인 조사방법 중 가장 신뢰할 수 있는 것은?",["DNA 검사","소지품 검사","지문감식","X-ray 검사"],4,0,"ew20210515"],["ew20210515-47",2,"T095","2021-05-15",47,58,"증거물의 수집에 관한 고려사항으로 가장 옳은 것은?",["고체 표본을 수집할 때 용기에 가득 채운다.","등유와 같은 탄화수소계 액체 위험물은 물과 쉽게 혼합된다.","경유와 같이 흔히 사용되는 화재 촉진제 증기는 공기보다 더 가볍다.","화재 촉진제로 사용되는 휘발유와 같은 인화성 액체는 상온에서 자연발화하지 않는다."],4,0,"ew20210515"],["ew20210515-48",2,"T084","2021-05-15",48,88,"화재관련자들로부터의 정보수집에 대한 방법으로 틀린 것은?",["목격자로부터 목격경위, 목격위치, 목격상황에 대하여 청취하여야 한다.","소방관계자로부터 출동당시의 화세 및 확산경로에 대한 정보를 수집하여야 한다.","부상을 입은 피해자에게는 정보를 수집하지 않는다.","관리자로부터 건물의 구조, 발화범위 내의 물건, 화기시설 등에 대하여 질문하여야 한다."],3,0,"ew20210515"],["ew20210515-49",2,"T092","2021-05-15",49,71,"열가소성 도체 절연체가 도체의 열로 인해 연화되고 늘어나는 현상으로 옳은 것은?",["헤일로(halo)","포인터 및 화살","슬리빙(sleeving)","엘리게이터(alligator)"],3,0,"ew20210515"],["ew20210515-51",2,"T084","2021-05-15",51,77,"화재조사 및 보고규정상 질문기록서에 기재되어야 하는 사항 중 틀린 것은?",["화재대상과의 관계를 기재한다.","어떻게 해서 알게 되었는지를 기재한다.","화재번호 및 화재발생 일시, 장소를 기재한다.","출입문 상태 및 소방대 건물 진입방법을 기재한다."],4,0,"ew20210515"],["ew20210515-53",2,"T080","2021-05-15",53,81,"액체촉진제의 특성 중 틀린 것은?",["모든 액체촉진제는 물과 접촉 시 물위에 뜬다.","액체 표본 채취 시 살균한 거즈패드를 사용할 수 있다.","액체촉진제는 다공성 물질 안에 갇혔을 때 지속성이 매우 높다.","액체촉진제는 구조부, 내부마감재, 기타 화재 잔해에 쉽게 흡수된다."],1,0,"ew20210515"],["ew20210515-55",2,"T074","2021-05-15",55,76,"화재증거물수집관리규칙상 증거물 시료용기 중 유리병으로 휘발성 액체를 수집할 경우 마개로 사용할 수 없는 것은?",["유리 마개","코르크 마개","금속 스크루 마개","폴리테트라플루오로에틸렌(PTEE) 마개"],2,0,"ew20210515"],["ew20210515-56",2,"T099","2021-05-15",56,65,"전신적 생활반응에 해당하는 것은?",["피하출혈","속발성 염증","압박성 울혈","흡인 및 연하"],2,0,"ew20210515"],["ew20210515-57",2,"T075","2021-05-15",57,81,"증거 수집과정에서 오염에 대한 설명으로 틀린 것은?",["액체 및 고체 촉진제는 화재조사관의 장갑에 흡수될 수도 있다.","물리적 증거물에 대한 대부분의 오염은 수집하는 과정에서 발생한다.","액체나 고체 촉진제 증거물 수집 시 일회용 비닐장갑을 착용해야 한다.","증거물의 오염을 막기 위해 증거 보관 용기 자체를 수집도구로 사용해서는 안된다."],4,0,"ew20210515"],["ew20210515-58",2,"T088","2021-05-15",58,86,"화재발생 전·후에 이루어진 사람의 행동이나 기계적인 작동 상황 등을 시간의 흐름 순으로 전개하여 사건을 분석하는 기법은?",["검증","타임라인","PERT 차트","마인드매핑(Mind mapping)"],2,0,"ew20210515"],["ew20210515-59",2,"T082","2021-05-15",59,49,"화재현장의 증거를 보호하기 위한 방법으로 가장 거리가 먼 것은?",["관계지역을 폴리스라인 테이트프로 격리한다.","해당지역의 정밀조사를 위하여 방수포로 덮어 놓는다.","직접 분사 기구의 사용은 증거 손상의 우려가 있으므로 금지해야 한다.","추가 조사가 필요한 지역에 증거를 나타내는 숫자 표시나 경고표지를 사용할 수 있다."],3,0,"ew20210515"],["ew20210515-60",2,"T081","2021-05-15",60,79,"화재증거물수집관리규칙상 화재증거물 수집에 관한 내용으로 명시되지 않은 것은?",["증거서류를 수집함에 있어서 보조적으로 원본을 영치한다.","증거물 수집 목적이 인화성 액체 성분 분석인 경우에는 인화성 액체 성분의 증발을 막기 위한 조치를 행하여야 한다.","증거물의 소손 또는 소실 정도가 심하여 증거물의 일부분 또는 전체가 유실될 우려가 있는 경우는 증거물을 밀봉하여야 한다.","증거물이 파손될 우려가 있는 경우에 충격금지 및 취급방법에 대한 주의사항을 증거물의 포장 외측에 적절하게 표기하여야 한다."],1,0,"ew20210515"],["ew20210515-61",3,"T107","2021-05-15",61,40,"가재도구 화재피해액 산정기준의 간이평가방식 중 주택종류별 가중치는?",["10%","20%","30%","40%"],1,0,"ew20210515"],["ew20210515-62",3,"T124","2021-05-15",62,50,"화재조사 및 보고규정상 화재현황조사서의 첨부서류로 명시되지 않은 것은?",["화재현장 조사서","화재유형별조사서","화재현장출동보고서","소방방화시설 활용 조사서"],3,0,"ew20210515"],["ew20210515-63",3,"","2021-05-15",63,53,"화재피해액 산정에 있어서 건물화재 피해 설명으로 옳은 것은?",["기와 등으로 지붕을 잇기 직전의 방화구조건물에서 발생한 화재","슬래브의 콘크리트를 부어넣은 시점 이후의 내화건물에서 발생한 화재","오래된 차량을 개조해서 이동용 점포 등으로 이용하고 있는 것이 소손된 화재","해체 중의 건물에서 벽, 바닥 등의 주체구조부의 해체가 시작된 시점에서 발생한 화재"],2,0,"ew20210515"],["ew20210515-64",3,"T113","2021-05-15",64,75,"화재조사 및 보고규정상 화재피해액 산정기준 중 틀린 것은?",["건물 : 신축단가×소실면적×[1-(0.8×경과연수/내용연수)]×손해율","철거건물 : 재건축비×[1-(0.8×잔여내용연수/내용연수)]×손해율","집기비품 : 회계장부상 현재가액×손해율","공구·기구 : 회계장부상 현재가액×손해율"],2,0,"ew20210515"],["ew20210515-66",3,"T125","2021-05-15",66,80,"화재조사 및 보고규정상 소방·방화시설 활용조사서의 작성항목으로 명시되지 않은 것은?",["경보설비","전기설비","소화시설","피난설비"],2,0,"ew20210515"],["ew20210515-67",3,"T124","2021-05-15",67,77,"화재조사 및 보고규정상 화재현장출동보고서의 보존기간으로 옳은 것은?",["3년","5년","10년","영구보존"],4,0,"ew20210515"],["ew20210515-68",3,"T112","2021-05-15",68,59,"화재조사 및 보고규정상 화재원인조사 내용으로 틀린 것은?",["피난상황조사","연소상황조사","화재진압상황조사","소방·방화시설 등 조사"],3,0,"ew20210515"],["ew20210515-69",3,"T110","2021-05-15",69,87,"화재조사 및 보고규정상 화재피해조사서[인명]에서 사성정도를 사망, 중상, 경상으로 분류하여 작성할 때 중상의 정의로 옳은 것은?",["입원치료를 필요로 하지 않은 부상","1주 이상의 입원치료를 필요로 하는 부상","2주 이상의 입원치료를 필요로 하는 부상","3주 이상의 입원치료를 필요로 하는 부상"],4,0,"ew20210515"],["ew20210515-71",3,"T114","2021-05-15",71,77,"화재피해액산정 매뉴얼에 따른 손해율 30%에 해당하는 피해 정도는?",["오염·수침손의 경우","손해정도가 보통인 경우","손해정도가 다소 심한 경우","50% 이상 소손되거나, 수침오염 정도가 심한 경우"],2,0,"ew20210515"],["ew20210515-73",3,"T131","2021-05-15",73,76,"화재조사 및 보고규정상 치외법권지역 화재조사 보고서 작성에 대한 설명으로 옳은 것은?",["조사 가능한 내용만 조사하여 화재현황조사서만 작성한다.","치외법권지역은 조사권을 행사할 수 없으므로 보고서를 작성하지 않아도 된다.","화재현장출동보고서, 질문기록서, 화재발생종합보고서를 반드시 작성하여야 한다.","치외법권지역은 조사권을 행사할 수 없는 경우는 조사 가능한 내용만 조사하여 해당 보고서를 작성한다."],4,0,"ew20210515"],["ew20210515-74",3,"T111","2021-05-15",74,88,"화재조사 및 보고규정상 화재현황 조사서의 작성에 대한 설명으로 틀린 것은?",["부동산은 재산피해 금액을 천원단위로 기재한다.","재산피해는 부동산과 동산으로 구분하여 기재한다.","인명구조는 구조와 유도대피로 구분하여 기재한다.","건축물의 소실정도는 전소, 반소 2종류로 구분한다."],4,0,"ew20210515"],["ew20210515-75",3,"","2021-05-15",75,47,"화재피해액 산정에 있어서 피해액을 산정하는 방법에 관한 설명으로 옳은 것은?",["유실수 등에 있어 수확기간에 있는 경우에는 매매사례비교법으로 산정한다.","차량, 예술품, 귀중품, 귀금속 등의 피해액산정에는 복성식평가법을 사용한다.","유실수의 육성기간에 있는 경우에는 복성식평가법을 사용한다.","사고로 인한 피해액을 산정하는 방버으로 수익환원법을 사용한다."],3,0,"ew20210515"],["ew20210515-76",3,"T116","2021-05-15",76,34,"화재 당시에 피해물의 재구입비에 대한 현재가에 비율을 구하는 식으로 틀린 것은?",["100% - 감가수정율","(현재시가 – 감가수정액)/경과연수","(재구입비 – 감가수정액)/재구입비","1-(1-최종잔가율)×경과연수/내용연수"],2,0,"ew20210515"],["ew20210515-77",3,"T126","2021-05-15",77,83,"화재조사 및 보고규정상 화재 건수의 결정 및 관할구역에 관한 사항으로 명시되지 않은 것은?",["화재범위가 2이상의 관할구역에 걸친 화재에 대해서는 발화 소방대상물의 소재지를 관할하는 소방서에서 2건의 화재로 한다.","동일범이 아닌 각기 다른 사람에 의한 방화, 불장난은 동일 대상물에서 발화했더라도 각각 별건의 화재로 한다.","동일 소방대상물의 발화점이 2개소 이상 있는 누전점이 동일한 누전에 의한 화재는 1건의 화재로 한다.","동일 소방대상물의 발화점이 2개소 이상 있는 지진, 낙뢰 등 자연현상에 의한 다발화재는 1건의 화재로 한다."],1,0,"ew20210515"],["ew20210515-78",3,"T116","2021-05-15",78,67,"화재조사 및 보고규정상 피해물의 종류, 손상 상태 및 정도에 따라 피해액을 적정화시키는 일정한 비율을 의미하는 용어로 옳은 것은?",["손해율","최종손해율","잔가율","최종잔가율"],1,0,"ew20210515"],["ew20210515-79",3,"","2021-05-15",79,62,"부동산의 재산피해신고서에 포함되는 항목으로 명시되지 않은 것은?",["피해년월일","건축물의 용도","수선·개축한 부분","선박의 소실부위"],4,0,"ew20210515"],["ew20210515-80",3,"T122","2021-05-15",80,81,"화재조사 및 보고규정상 화재로 인한 전부손해의 경우 시중매매가격으로 산정할 수 있는 대상이 아닌 것은?",["동물","식물","자동차","골동품"],4,0,"ew20210515"],["ew20210515-81",4,"T151","2021-05-15",81,58,"화재로 인한 재해보상과 보험가입에 관한 법률상 손해보험회사가 한국화재보험협회의 설립허가를 받으려는 경우 금융위원회에 제출하여야 하는 서류로 틀린 것은?",["정관","사업방법서","임원의 명단","창립총회 의사록"],3,0,"ew20210515"],["ew20210515-83",4,"","2021-05-15",83,48,"소방기본법령상 화재조사에 관한 전문교육과정의 교육과목 중 소양교육 과목으로 명시되지 않은 것은?",["국정시책","기초소양","기초전기","심리상담기법"],3,0,"ew20210515"],["ew20210515-84",4,"T173","2021-05-15",84,69,"민법상 타인의 생명을 해한 자의 손해배상 책임 대상으로 명시되지 않은 것은?",["피해자의 형제","피해자의 배우자","피해자의 직계존속","피해자의 직계비속"],1,0,"ew20210515"],["ew20210515-86",4,"T140","2021-05-15",86,77,"화재조사 및 보고규정상 대형화재·중요화재 및 특수화재 등이 발생하여 조사를 위하여 필요할 경우 조사본부를 설치운영 할 수 있는데 이 때 조사본부장의 책임으로 명시되지 않은 것은? (단, 그 밖의 조사본부 운영 및 총괄에 관한 사항은 제외한다.)",["현장보존","화재조사 집행","정보관리","화재피해금액 신고"],4,0,"ew20210515"],["ew20210515-87",4,"T148","2021-05-15",87,59,"제조물 책임법에 대한 내용으로 틀린 것은?",["동일한 손해에 대하여 배상할 책임이 있는 자가 2인 이상인 경우에는 연대하여 그 손해를 배상할 책임이 있다.","제조물책임법에 따른 손해배상책임을 배제하거나 제한하는 특약은 유효한 것이 원칙이다.","제조물의 결함으로 인한 손해배상책임에 관하여 제조물책임법에 규정된 것을 제외하고는 민법에 따른다.","일반적으로 손해배상의 청구권은 제조업자가 손해를 발생시킨 제조물을 공급한 날부터 10년 이내에 행사하여야 한다."],2,0,"ew20210515"],["ew20210515-89",4,"T141","2021-05-15",89,75,"소방기본법령상 화재조사를 실시할 수 없는 자는? (단, 시험은 소방청장이 실시하는 화재조사에 관한 시험을 말한다.)",["국립과학수사연구원에서 8주 이상 화재조사에 관한 전문교육을 이수한 자로서 시험에 합격한 자","소방교육기관에서 8주 이상 화재조사에 관한 전문교육을 이수한 자로서 시험에 합격한 자","시험에 합격한 자가 없는 경우 소방공무원 중 화재감식평가산업기사 이상의 자격을 취득한 자","시험에 합격한 자가 없는 경우 소방공무원으로서 화재조사분야에서 6개월간 근무한 자"],4,0,"ew20210515"],["ew20210515-90",4,"T156","2021-05-15",90,80,"실화책임에 관한 법률상 실화가 중대한 과실로 인한 것이 아닌 경우 그로 인한 손해배생의무자가 법원에 손해배상액 경감 청구 시 고려사항으로 명시되지 않은 것은? (단, 그 밖에 손해배상액을 결정할 때 고려사항은 제외한다.)",["화재의 규모","피해확대의 원인","실화자의 전과사실","배상의무자의 경제상태"],3,0,"ew20210515"],["ew20210515-93",4,"","2021-05-15",93,87,"소방기본법령상 시·도지사로부터 소방활동의 비용을 지급받을 수 있는 경우로 옳은 것은?",["화재 또는 구조·구급 현장에서 물건을 가져간 사람","소방대장을 도와서 화재현장에서 불을 끄는 일을 한 사람","소방대상물에 화재, 재산·재해, 그 밖의 위급한 상황이 발생한 경우 그 관계인","고의 또는 과실로 화재 또는 구조·구급 활동이 필요한 상황을 발생시킨 사람"],2,0,"ew20210515"],["ew20210515-94",4,"T159","2021-05-15",94,70,"화재조사 및 보고규정상 건물의 동수 산정 기준으로 틀린 것은?",["건널 복도 등으로 2이상의 동에 연결되어 있는 것은 그 부분을 절반으로 분리하여 각 동으로 본다.","건물의 외벽을 이용하여 실을 만들어 작업실 용도로 사용하고 있는 것은 주건물과 다른 동으로 본다.","구조에 관계없이 지붕 및 실이 하나로 연결되어 있는 것은 같은 동으로 본다.","목조 건물의 경우 격벽으로 방화구획이 되어 있는 경우 같은 동으로 한다."],2,0,"ew20210515"],["ew20210515-95",4,"T174","2021-05-15",95,52,"사법경찰관이 피의자를 심문하기 전에 알려주어야 하는 사항과 가장 거리가 먼 것은?",["일체의 진술을 하지 아니할 수 있다는 것","신문을 받을 때 변호인의 조력을 받을 수 있다는 것","진술을 하지 않은 경우에 불이익을 받을 수 있다는 것","진술을 거부할 권리를 포기하고 행한 진술은 법정에서 유조의 증거로 사용될 수 있다는 것"],3,0,"ew20210515"],["ew20210515-96",4,"T167","2021-05-15",96,81,"화재로 인한 재해보상과 보험가입에 관한 법률상 특수건물의 특약부화재보험에 가입하지 아니한 자의 벌칙 기준으로 옳은 것은? (단, 산업재해보상보험 가입 대상이 아님)",["300만원 이하의 벌금","500만원 이하의 벌금","700만원 이하의 벌금","1000만원 이하의 벌금"],2,0,"ew20210515"],["ew20210515-97",4,"","2021-05-15",97,58,"소방기본법령상 소방서장이 화재조사를 하기 위하여 관계인에게 보고 또는 자료 제출을 명했을 때 이를 위반하여 보고 또는 제출을 하지 아니한 자에 대한 과태료 기준으로 옳은 것은?",["200만원 이하의 과태료","300만원 이하의 과태료","500만원 이하의 과태료","1000만원 이하의 과태료"],1,0,"ew20210515"],["ew20210515-98",4,"T147","2021-05-15",98,54,"제조물 책임법상 손해배상책임을 지는 지가 손해배상책임을 면하기 위하여 입증하여야 할 사항으로 명시되지 않은 것은?",["제조업자가 해당 제조물을 공급하지 아니하였다는 사실","제조업자가 해당 제조물을 공급한 당시의 과학·기술 수준으로는 결함의 존재를 발견할 수 없었다는 사실","제조물의 결함이 제조업자가 해당 제조물을 제조한 당시의 법령에서 정하는 기준을 준수함으로써 발생하였다는 사실","원재료나 부품의 경우에는 그 원재료나 부품을 사용한 제조물 제조업자의 설계 또는 제작에 관한 지시로 인하여 결함이 발생하였다는 사실"],3,0,"ew20210515"],["ew20210515-100",4,"T135","2021-05-15",100,75,"화재조사 및 보고규정상 운행 중인 차량, 선박 및 항공기에서 발생한 화재의 조사책임으로 명시된 것은?",["소화활동을 행한 소방본부장 또는 소방서장","화재신고를 최초 접수한 소방본부장 또는 소방서장","차량, 선박 및 항공기 등록지를 관할하는 소방본부장 또는 소방서장","소화활동을 행한 장소를 관할하는 소방본부장 또는 소방서장"],4,0,"ew20210515"],["ew20210912-1",0,"T014","2021-09-12",1,59,"화재조사 및 보고규정상 조사본부 설치운영에 관한 사항 중 틀린 것은?",["조사본부장은 현장보존의 책임이 있다.","조사본부 설치운영시 소방본부 조사요원은 소방서 조사업무를 지원하여야 한다.","조사관은 소방본부 및 소방서의 화재조사 업무를 담당하고, 조사요원 지휘 감독의 책임이 있다.","조사본부장은 화재현장 지휘자로부터 화재조사에 관련된 필요정보를 인수받아 조사의 원활한 수행을 기하도록 하여야 한다."],3,0,"ew20210912"],["ew20210912-2",0,"T014","2021-09-12",2,89,"화재조사자의 자세로 틀린 것은?",["과학적이고 주관적인 조사를 해야 한다.","특이한 화재현상에 대하여는 관계지식을 최대한 활용하여야 한다.","소방기본법에 따라 부여된 권리와 의무를 초과해서는 안된다.","직무를 이용하여 개인의 민사관계에 관여해서는 안된다."],1,0,"ew20210912"],["ew20210912-3",0,"T006","2021-09-12",3,67,"복사체에서 절대온도의 차이가 두 배 높아지면 해당물질로부터 복사에 의한 열전달류은 몇 배가 되는가?",["2","4","16","32"],3,0,"ew20210912"],["ew20210912-4",0,"T012","2021-09-12",4,93,"소방기본법령상 화재조사에 관한 설명으로 틀린 것은?",["소방서장은 화재가 발생하였을 때에는 화재조사를 하여야 한다.","소방공무원과 국가경찰공무원은 화재조사를 할 때에 서로 협력하여야 한다.","화재조사를 하는 관계 공무원은 권한을 표시하는 증표를 지니고 이를 관계인에게 보여 주어야 한다.","화재조사를 하는 관계 공무원은 화재조사를 수행하면서 알게 된 비밀에 대해 인터뷰해도 된다."],4,0,"ew20210912"],["ew20210912-5",0,"T009","2021-09-12",5,69,"비등액체팽창증가폭발(BLEVE)에 대한 설명으로 틀린 것은?",["인화성 액체에서만 일어날 수 있는 현상이다.","저장용기의 크기와 관계없이 일어날 수 있는 현상이다.","가압상태에서 비점이상 온도의 액체를 저장하는 용기와관련된 폭발이다.","저장용기 내에 존재하는 물질의 상호이상반응에 의해서도 발생이 가능한 현상이다."],1,0,"ew20210912"],["ew20210912-6",0,"","2021-09-12",6,80,"조사인원 중 전문 인력에 관한 설명으로 틀린 것은?",["기계공학자는 전문인력으로 부적합하다.","특이화재의 경우 전문 인력의 도움을 받을 수 있다.","전문 인력을 데려오면 이해관계의 출동을 피해야 한다.","어떤 부분에 대한 훈련을 받았거나 받지 않았다는 사실이 특정 전문가의 자격에 영향을 끼친다는 뜻은 아니다."],1,0,"ew20210912"],["ew20210912-7",0,"T009","2021-09-12",7,67,"폭발 위력의 지표로 사용될 수 있는 자료와 거리가 가장 먼 것은?",["폭심부의 깊이","파편의 비행거리","깨진 유리창의 단면","무너진 벽의 종류와 구조"],3,0,"ew20210912"],["ew20210912-8",0,"","2021-09-12",8,75,"유류화재와 관련된 용어의 설명으로 틀린 것은?",["인화점은 외부로부터 에너지를 받아서 착화 가능한 최저온도","발화점은 외부로부터 점화에너지 공급 없이 주변의 열에 의해 물질 스스로 착화되는 최저온도","증기밀도는 공기의 분자량을 가연성 물질의 분자량으로나눈 값","연소점은 화염이 꺼지지 않고 지속되는 최저온도."],3,0,"ew20210912"],["ew20210912-9",0,"T020","2021-09-12",9,74,"MEK(메틸에틸케톤)으로 인한 화재 분류로 옳은 것은?",["A급화재","B급화재","C급화재","D급화재"],2,0,"ew20210912"],["ew20210912-10",0,"T014","2021-09-12",10,89,"화재조사관의 현장안전관리에 관한 내용으로 틀린 것은?",["조사관은 활동 시에 화재 진압 인력과 협력해야 한다.","조사관은 화재현장 지휘관에게 알리지 않고 건물 내 다른 곳으로 이동해서는 안 된다.","화재가 진압된 건물에서 조사를 수행할 때 불이 다시 날 수 있다는 것을 염두에 두어야 한다.","화재가 완전히 진압되기 전에 조사관은 지휘관의 허가를 받지 않아도 건물에 들어가 조사를 할 수 있다."],4,0,"ew20210912"],["ew20210912-11",0,"","2021-09-12",11,85,"화재조사 및 보고규정상 화재현황조사서에 관한 사항 중틀린 것은?",["연소확대물, 연소확대 사유를 기록한다.","온도, 습도와 같은 기상상황은 기록하지 않는다.","발화열원, 발화요인, 최초착화물 등 화재원인을 기록한다.","동원인력 사항을 기록할 때 잔불감시 인력에 대한 사항을 기록한다."],2,0,"ew20210912"],["ew20210912-12",0,"T016","2021-09-12",12,81,"화재증거물수집관리규칙상 증거물의 포장ㆍ보관ㆍ이동에 관한 설명으로 옳은 것은?",["증거물의 포장은 보호상자를 사용하여 일괄 포장함을 원칙으로 한다.","화재 증거물은 관계인의 승낙에 관계없이 폐기할 수 있다.","증거물은 화재증거 수집 목적 달성 후 관계인에게 반환하지 않고 3년간 보관하여야 한다.","증거물의 반환 또는 폐기까지 화재조사자 또는 이와 동일한 자격 및 권한을 가진 자의 책임 하에 행해져야한다."],4,0,"ew20210912"],["ew20210912-13",0,"T016","2021-09-12",13,87,"증거물 수집 용기와 시료의 적응성을 연결한 것으로틀린 것은?",["비닐 백 : 액체","종이상자 : 고체","금속캔 : 고체, 액체","유리병 : 고체, 액체"],1,0,"ew20210912"],["ew20210912-14",0,"","2021-09-12",14,84,"화재상황보고에 대한 설명으로 틀린 것은?",["최종보고는 화재종료직후 최초보고 및 중간보고를취합하여 보고한다.","중간보고 시 화재 원인이 규명되지 않았을 때는 보고하지 않는다.","중간보고는 화재상황 진전에 따라 연소확대여부,인명구조 활동상황 등을 수시로 보고한다.","화재상황 최초보고는 선착대가 화재현장 도착즉시 현장지휘관의 책임 하에 화재규모, 인명피해발생여부 등을 보고한다."],2,0,"ew20210912"],["ew20210912-15",0,"T002","2021-09-12",15,88,"대표적으로 숯, 코크스 등이 연소되는 현상으로 산소와 접하게 되는 물질의 연소로 화염이 없이 표면에서 나타나는 연소의 형태는?",["분해연소","표면연소","확산연소","혼합연소"],2,0,"ew20210912"],["ew20210912-17",0,"T010","2021-09-12",17,84,"가연성기체 중 위험성의 척도인 위험도가 가장 큰 것은?",["메탄","에탄","프로판","아세틸렌"],4,0,"ew20210912"],["ew20210912-18",0,"T009","2021-09-12",18,75,"폭발현상에 관한 설명으로 틀린 것은?",["기체나 액체의 팽창, 상변화 등의 물리적 현상이 압력발생의 원인이 되어 발생하는 폭발을 물리적폭발이라 한다.","물질의 분해, 연소 등으로 압력이 상승하는 것이 원인이 되어 발생하는 폭발을 화학적 폭발이라 한다.","알루미늄 분진이 공기 중에 부유된 상태에서 일어나는폭발은 화학적 폭발에 해당한다.","폭연은 화연전파속도가 미반응 매질 속에서 음속보다큰 속도로 이동하는 폭발현상이다."],4,0,"ew20210912"],["ew20210912-19",0,"T003","2021-09-12",19,68,"탄화심도 측정방법으로 옳은 것은?",["뾰족한 기구보다 끝이 뭉툭한 것이 좋다.","탄화심도 측정 시 갈라진 틈 안을 측정한다.","비교 측정 시 다른 측정 기구를 사용하는 것이 좋다.","각각의 측정 도구를 집어넣을 때 압력을 조금씩다르게 하는 것이 중요하다."],1,0,"ew20210912"],["ew20210912-20",0,"T004","2021-09-12",20,55,"유리의 파단면 분석에 관한 설명으로 옳은 것은?",["강화유리 자발파괴(Spontaneous Breakage)형태는 쌍을 이루는 8각형의 파편이 발견된다.","충격에 의한 파괴유리의 충격방향을 확인하기 위해서는 동심원파단면의 월러라인(Wallner Line)을 확인하는 것이 효과적이다.","재료가 여러 번의 외력에 의하여 순차적으로 분리되었을때는 동반하여 발생하는 분리선을 관찰하며 외력의 작용순서를 알 수 있다.","폭발로 인한 압력에 의해 많은 파편들이 폭발의 중심부로부터 멀리 비산되는데, 화재이후 폭발이 발생하였다면, 멀리 비산된 파편에 그을음이 부착될 수 없다."],3,0,"ew20210912"],["ew20210912-21",1,"T037","2021-09-12",21,54,"선박방화구조기준상 용어의 설명으로 틀린 것은?",["주수직구역격벽이란 선체, 선루 및 갑판실을 주수직구역으로 구분하는 격벽을 말한다.","주수평구역이란 선체, 선루 및 갑판실이 A급구획의갑판으로 구분된 구역으로서 해당 구역의 높이가 10미터를 초과하지 아니하는 구역을 말한다.","방화댐퍼란 통풍용 덕트에 설치된 장치로서, 평상시에는덕트 내에 공기가 흐를 수 있도록 열려 있다가 화재 시에는 연기 및 고온의 가스 전파를 차단하기 위하여 덕트 내의 공기의 흐름을 막을 수 있도록 폐쇄하는 장치이다.","기관구역이란 특정기관구역과 추진기관, 보일러, 내연기관, 주요전기설비, 냉동기, 감요(減搖)장치, 송풍기및 공기조화기기가 있는 장소, 급유장소 그 밖에 이와 유사한 장소와 이들 장소에 이르는 트렁크를 말한다."],3,0,"ew20210912"],["ew20210912-22",1,"T064","2021-09-12",22,65,"유류를 이용한 자살 방화 현장의 특징 중 틀린 것은?",["유류와 사용한 용기가 존재한다.","연소면적이 좁고 탄화심도가 깊다.","우발적이기보다는 계획적으로 실행한다.","급격한 연소 확대로 연소의 방향성 식별이 어렵다"],2,0,"ew20210912"],["ew20210912-23",1,"T042","2021-09-12",23,75,"담뱃불 화재 현장의 주요 감식사항이 아닌 것은?",["발화에 충분한 축열조건","발화지점을 넓게 탄화된 흔적","흡연행위가 있었다는 것을 증명","담뱃불에 의해 착화될 수 있는 가연물"],2,0,"ew20210912"],["ew20210912-24",1,"T043","2021-09-12",24,81,"다음 발화원인 중 미소화원이 아닌 것은?",["담뱃불","용접불티","절삭 불티","가스레인지 불꽃"],4,0,"ew20210912"],["ew20210912-25",1,"T044","2021-09-12",25,78,"자동차 점화장치의 전류 흐름 순서로 옳은 것은?",["점화스위치 → 점화코일 → 배터리 → 시동모터 → 배전기 → 고압케이블 → 스파크 플러그","점화스위치 → 배터리 → 시동모터 → 점화코일 → 배전기 → 고압케이블 → 스파크 플러그","점화스위치 → 시동모터 → 점화코일 → 배터리 → 배전기 → 고압케이블 → 스파크 플러그","점화스위치 → 고압케이블 → 배전기 → 시동모터 → 점화코일 → 배터리 → 스파크 플러그"],2,0,"ew20210912"],["ew20210912-26",1,"T046","2021-09-12",26,68,"일반적으로 산소, 수소, 질소, 아르곤 등의 압축가스 용기의 안전장치에 적합한 밸브는?",["파열판식 안전밸브","스프링식 안전밸브","가용전(가용합금식) 안전밸브","스프링식과 파열판식의 2중 안전밸브"],1,0,"ew20210912"],["ew20210912-27",1,"T042","2021-09-12",27,79,"사람이 버린 담배꽁초에 의해 화재가 발생하였을 때추정되는 선행 발화원인은?",["휴지","담배꽁초","쓰레기통","사람의 부주의 행위"],4,0,"ew20210912"],["ew20210912-29",1,"T045","2021-09-12",29,79,"일반화재와 구별되어야 하는 차량화재의 특수성에 대한 설명 중 틀린 것은?",["차량은 동력기계 계통, 전기전자 계통, 연료공급 계통, 배기계통 등 기구의 복잡성이 있다.","연료, 시트 등 화재 하중이 낮고, 외기에 개방된 상태인환기 지배형 화재의 특성을 보인다.","다양한 부착물 및 이의 변ㆍ개조가 용이하므로, 이러한 구조적 특수성에 의한 화재위험성에 노출되어 있다고 볼 수 있다.","차량은 개방된 공간에 존치되는 특수성에 의해 사회적 불만이나 주차불만을 가진 자가 불특정한방법으로 방화할 개연성이 높다고 볼 수 있다."],2,0,"ew20210912"],["ew20210912-31",1,"T046","2021-09-12",31,64,"고압가스 안전관리법령상 가스 종류에 따른 용기외면 도색이 바르게 연결된 것은?",["수소 - 백색","아세틸렌 - 갈색","액화석유가스 - 회색","액화암모니아 - 주황색"],3,0,"ew20210912"],["ew20210912-32",1,"","2021-09-12",32,55,"열전도성, 밀도 및 비열의 곱으로 정의되며 물질에 가해지는 에너지에 대한 물질의 반응을 설명하는데 사용되는 용어는?",["발화성","열관성","유동성","전열성"],2,0,"ew20210912"],["ew20210912-33",1,"","2021-09-12",33,47,"화학결합에 대한 설명으로 틀린 것은?",["전자쌍이 균등하게 공유되어 있지 않은 공유결합을 비극성 공유결합이라고 한다.","이온 결합은 두 이온 사이의 거리가 짧고, 두 이온의 전하량이 클수록 결합력이 강하다.","수소 분자처럼 두 원자가 한 쌍 또는 그 이상의 전자쌍을 공유함으로서 형성되는 결합을 공유결합이라고 한다.","이온화합물의 물리적 형태는 반대로 하전된 이온이 규칙적으로 배열된 결정성으로서 화합물의 양이온과 음이온의 전하량의 합은 0이다."],1,0,"ew20210912"],["ew20210912-34",1,"T051","2021-09-12",34,63,"탄화된 목재에서 공통적으로 나타나는 탄화흔과 균열흔의특성으로 틀린 것은?",["무염연소는 목재의 표면에 따라 광범위하게 전파된다.","불에 오래도록 강하게 탈수록 탄화의 깊이는 깊다.","탄화모양을 형성하고 있는 패인 골이 깊을수록 소손이 강하다.","탄화모양을 형성하고 있는 패인 골의 폭이 넓을수록 소손이 강하다."],1,0,"ew20210912"],["ew20210912-35",1,"T035","2021-09-12",35,59,"항공기 보조동력장치(APU)의 소화용기(container) 내용물이과도한 열로 인하여 외부로 배출 시 나타나는 지시는?",["배출밸브(discharge valve)가 열린다.","조종실에 경고등이 들어온다.","온도방출지시기(thermal dischare indicator)의 Yellow Disk가 없다.","온도방출지시기(thermal dischare indicator)의 Red Disk가 없다."],4,0,"ew20210912"],["ew20210912-36",1,"T040","2021-09-12",36,69,"임야화재에서 화염진행 방향에 따른 분류가 아닌 것은?",["수직화재","전진화재","후진화재","횡진화재"],1,0,"ew20210912"],["ew20210912-37",1,"","2021-09-12",37,77,"위험물안전관리법령상 제1류 산화성 고체에 명시되지 않은 것은?",["질산염류","염소산염류","과염소산염류","질산에스테르류"],4,0,"ew20210912"],["ew20210912-38",1,"T054","2021-09-12",38,47,"pH12인 수산화나트륨 수용액 50㎖를 중화시키기 위하여농도를 알 수 없는 염산 10㎖를 사용하였다면 이 염산의 농도는?",["0.01 N","0.02 N","0.05 N","0.1 N"],3,0,"ew20210912"],["ew20210912-39",1,"T039","2021-09-12",39,75,"임야화재에 영향을 주는 3대 중요 요소가 아닌 것은?",["기후","지형","가연물","점화원"],4,0,"ew20210912"],["ew20210912-40",1,"T034","2021-09-12",40,64,"방화의 행위방법 중 직접착화에 의해 발생한 화재의 특이점으로 옳은 것은?",["인화물질을 이용한 경우 그 용기를 화재장소에서 먼 곳에 감춘다.","착화행위 직후 화염이 확대되고 대부분 한 곳에 집중적으로 착화시킨다.","비교적 착화가 용이한 부분에 착화시키므로 훈소 또는 회화 현상이 많이 식별된다.","방화범의 의류에 촉진제가 부착되는 경우가 있다."],4,0,"ew20210912"],["ew20210912-41",2,"T074","2021-09-12",41,83,"화재증거물수집관리규칙상 증거물 시료용기 중 양철 캔(CAN)에 관한 설명으로 틀린 것은?",["양철 캔과 그 마개는 청결하고 건조해야 한다.","사용하기 전에 캔의 상태를 조사해야 하며 누설이나녹이 발견될 때에는 사용할 수 없다.","양철 캔은 기름에 견딜 수 있는 디스크를 가진 스크루 마개 또는 누르는 금속마개로 밀폐될 수 있으며, 이러한 마개는 재사용이 가능하다.","양철 캔은 적합한 양철판으로 만들어야 하며, 프레스를 한 이음매 또는 외부 표면에 용매로 송진 용제를 사용하여 납땜을 한 이음매가 있어야 한다."],3,0,"ew20210912"],["ew20210912-42",2,"T098","2021-09-12",42,64,"가솔린(Gasoline)을 GC-MS로 분석할 경우 검출되는 성분이 아닌 것은?",["톨루엔","크실렌","알킨벤젠","멜라민"],4,0,"ew20210912"],["ew20210912-43",2,"T082","2021-09-12",43,86,"화재현장 및 물리적 증거물의 보존에 대한 책임이있는 자가 아닌 것은?",["소방관","화재조사관","경찰관","제조사 직원"],4,0,"ew20210912"],["ew20210912-44",2,"T084","2021-09-12",44,81,"화재조사관이 관계자 진술을 확보하고자 할 때 유의사항으로 틀린 것은?",["인터뷰하는 동안 입수한 정보의 질을 평가해야 한다.","인터뷰의 목적은 유용하고 정확한 정보를 수집하기위함이다.","인터뷰는 화재가 완전히 진압된 뒤 천천히 진행한다.","증인은 사고에 대한 직접적인 목격자가 아니라도화재에 대한 정보를 제공할 수 있다."],3,0,"ew20210912"],["ew20210912-45",2,"T093","2021-09-12",45,69,"피부화상을 조직손상 깊이에 따라 분류할 때, 2도 화상에 대한 설명으로 옳은 것은?",["국부적인 화상으로 표피와 함께 진피까지 손상된 화상을말하며 열에 의한 손상이 많다.","모세혈관의 충혈로 인하여 종창과 더불어 홍반만 보이기때문에 홍반성 화상이라고 한다.","부스럼 딱지 또는 생체 내의 피부조직이나 세포가 죽는응고성 괴사에 빠지므로 괴사성 화상이라고도 한다.","화열에 의한 국부적인 피부충혈과 부어오르는 발적현상은 살아있는 사람에게 나타나고 사체에는 화열을 작용시켜도 이와 같은 현상은 나타나지 않는다."],1,0,"ew20210912"],["ew20210912-46",2,"T099","2021-09-12",46,58,"화재사의 생활반응으로 틀린 것은?",["화상","안구의 점상 출혈","선홍색 시반 출현","그을음의 흡입 흔적"],2,0,"ew20210912"],["ew20210912-47",2,"T080","2021-09-12",47,53,"콘크리트 바닥과 같은 다공성 물질에 흡수된 액체 촉진제증거물을 수집할 때 흡수성 물질을 콘크리트 표면에 바르고유지시키는 시간으로 옳은 것은?",["1 ~ 2시간","3 ~ 5분","5 ~ 10분","20 ~ 30분"],4,0,"ew20210912"],["ew20210912-48",2,"T069","2021-09-12",48,77,"화재현장 사진 촬영에 대한 설명으로 틀린 것은?",["가능하다면 진행되고 있는 화재를 촬영한다.","건물은 가능한 여러 각도와 외부 각도에서 많은 사진을 찍어야 한다.","현재 현장의 위치를 확실히 하기 위해 외부 사진을촬영해 두어야 한다.","군중 속의 사람을 촬영하는 것은 인권침해의 우려가 있어 촬영해서는 안된다."],4,0,"ew20210912"],["ew20210912-50",2,"","2021-09-12",50,55,"콘크리트와 같은 표면에 뿌려진 인화성액체 잔류물수거 시 사용하는 물질과 거리가 가장 먼 것은?",["석회","규조토","밀가루","베이킹파우더"],4,0,"ew20210912"],["ew20210912-51",2,"T092","2021-09-12",51,82,"냉온수기의 자동온도 조절장치에서 절연체의 오염에 의한 트래킹 화재가 발생한 경우 수거해야 할 증거물로 옳은 것은?",["응축기(Condenser)","압축기(Compressor)","서모스탯(Thermostat)","과부하 계전기(Overload relay)"],3,0,"ew20210912"],["ew20210912-52",2,"T091","2021-09-12",52,75,"가연성 액체가 살포된 수평재에서 발견되는 패턴이 아닌 것은?",["V 패턴","포어 패턴","스플래시 패턴","도넛 패턴"],1,0,"ew20210912"],["ew20210912-53",2,"T069","2021-09-12",53,67,"화재증거물수집관리규칙상 명시된 현장사진 및 비디오촬영에 관한 내용으로 옳은 것은?",["최초 도착하였을 때 원상태를 그대로 촬영한다.","화재조사 진행순서와 상관없이 신속히 촬영한다.","증거물을 촬영할 때는 구분이 용이하도록 반드시 번호표 등을 넣어 촬영한다.","연소확대 경로 기록 시 번호표와 화살표는 생략한다."],1,0,"ew20210912"],["ew20210912-54",2,"T070","2021-09-12",54,75,"디지털카메라의 고유 기능으로 받아들인 빛을 증폭하여감도를 높이거나 낮춰주는 기능은?",["줌 기능","EV 쉬프트","ISO 조절기능","화이트 밸런스"],3,0,"ew20210912"],["ew20210912-55",2,"T081","2021-09-12",55,42,"화재증거물수집관리규칙상 촬영한 사진으로 증거물과 서류를 작성할 때 현장 및 감정사진 작성방법에 관한 설명으로 틀린 것은?",["화재발생 일시를 기재한다.","사진 촬영한 방위를 표기한다.","화재현장 증거물 및 감정사진을 첨부하고 하단에 제목과 설명을 기재한다.","형사사건 및 재판상 증거자료로 활용될 수 있으므로주의를 기울여 촬영한다."],1,0,"ew20210912"],["ew20210912-56",2,"","2021-09-12",56,61,"0.3%의 농도에서 즉시 사망할 수 있으며 질소성분을 가지고 있는 합성수지, 동물의 털, 인조견 등의 섬유가불완전 연소 시 발생하는 맹독성 가스로 옳은 것은?",["암모니아","포스겐","염화수소","시안화수소"],4,0,"ew20210912"],["ew20210912-57",2,"T077","2021-09-12",57,78,"화재증거물수집관리규칙상 수집한 증거물을 이송할 때포장하고 기록ㆍ부착 하여야 하는 상세정보가 아닌 것은?",["수집장소 및 수집자","소유자 및 관리자 성명","증거물 내용 및 봉인자","수집일시 및 증거물 번호"],2,0,"ew20210912"],["ew20210912-58",2,"T099","2021-09-12",58,69,"화재현장에서 수집된 증거의 해석으로 틀린 것은?",["화재현장에서 발견된 소사체에서 생활반응이 있을경우 피해자는 화재 이전 사망한 상태였다는 것을알 수 있다.","깨져 바닥에 쏟아진 유리창의 내측에 그을음이 부착되어 있지 않다면 화재이전 창문이 먼저 깨졌다는 것을 의미한다.","화재현장 내부의 전기배선 끝단이 합리적인 이유 없이절단된 경우 현장조사를 방해하기 위한 행위로 추정해볼 수 있다.","타이어 흔적 위로 족적이 찍혀 있다면 이러한 증거는 차량이 지나간 후 에 누군가 걸어갔다는 것을 증명해주는 역할을 한다."],1,0,"ew20210912"],["ew20210912-59",2,"T091","2021-09-12",59,69,"화재현장에 있는 벽면이나 철판 등에 발생하는 백화현상에 대한 설명으로 옳은 것은?",["한번 부착된 그을음은 없어지지 않는다.","그을음이 부착되었다가 열에 의해 연소한 흔적이다.","열에 의해 가열되었다가 급속히 냉각된 흔적이다.","훈소로 발생한 가연성 증기가 응축하면서 부착된흔적이다."],2,0,"ew20210912"],["ew20210912-60",2,"T076","2021-09-12",60,50,"화재증거물 보관에 대한 설명으로 옳은 것은?",["증거물은 밝은 곳에 보관한다.","휘발성 물질은 냉장 보관한다.","냉동 보관된 물질은 물리적 테스트에 도움을 준다.","수분이 포함된 금속물질은 견고하게 밀폐시켜산화를 방지한다."],2,0,"ew20210912"],["ew20210912-61",3,"T122","2021-09-12",61,76,"화재조사 및 보고규정상 화재 피해액 산정 대상이 전부손해인 경우 시중매매가격을 화재로 인한 피해액으로 산정하지 않는 것은?",["차량","동물","식물","골동품"],4,0,"ew20210912"],["ew20210912-62",3,"T121","2021-09-12",62,85,"화재조사 및 보고규정상 질문기록서의 작성을 생략할 수있는 화재는?",["전봇대 화재","건축ㆍ구조물 화재","선박 · 항공기 화재","자동차ㆍ철도차량 화재"],1,0,"ew20210912"],["ew20210912-63",3,"T124","2021-09-12",63,79,"화재현장출동보고서의 작성자에 대한 설명으로 틀린 것은?",["보고서의 작성자는 화재현장에 출동한 소방공무원으로 한정한다.","원칙적으로 일반대원보다 선착대의 대장을 작성자로한다.","구조대원 또는 구급대원은 작성자가 될 수 없다.","화재현장에 출동한 소방대원이 실제로 관찰ㆍ확인한 연소상황이나 정보를 직접 기재한다."],3,0,"ew20210912"],["ew20210912-64",3,"T109","2021-09-12",64,82,"화재조사 및 보고규정상 조사활동 중 소방본부장 또는 소방서장이 소방청장에게 긴급상황을 보고하여야할 화재가 아닌 것은?",["정부미 도정공장의 화재","발전소 및 변전소의 화재","이재민 100명 이상 발생한 화재","재산피해가 30억원으로 추정되는 화재"],4,0,"ew20210912"],["ew20210912-65",3,"","2021-09-12",65,60,"화재피해액 산정 시 유의사항으로 틀린 것은?",["모델하우스에 대한 최종잔가율은 20%이다.","문화재로 지정되었거나 보존가치가 높은 건물의경우 전문가의 감정에 의한 가격을 현재가로 한다.","집기비품, 가재도구를 일괄하여 피해액을 산정할 경우재구입비의 60%를 피해액으로 한다.","중고구입기계장치 및 집기비품의 제작년도를 알 수 없는 경우 신품가액의 30 ~ 50%를 재구입비로 하여피해액을 산정한다."],3,0,"ew20210912"],["ew20210912-66",3,"T127","2021-09-12",66,76,"화재현장조사보고서 작성에 필요한 도면 작성방법으로틀린 것은?",["도면작성에 있어서 방의 배치와 출입구, 개구부의상황을 위주로 한다.","거리측정은 기둥의 하단에서 다른 기둥의 상단까지로 기준점을 통일한다.","도면(평면도, 입체도)은 측정치를 기준으로 하여 축척에맞춰서 작성한다.","방 배치가 복잡한 건물은 기준으로 한 점을 정하고그 점을 기준으로 사방으로 넓히면서 측정하면비교적 이해하기 쉽다."],2,0,"ew20210912"],["ew20210912-67",3,"T114","2021-09-12",67,71,"주택화재로 사용 중이던 냉장고가 수침손을 입었으나성능에 별다른 지장이 없는 경우 적용하는 손해율(%)은?",["5","10","15","20"],2,0,"ew20210912"],["ew20210912-68",3,"T108","2021-09-12",68,81,"화재조사 및 보고규정상 관할구역 내에서 발생한 화재에대하여 작성하여야 하는 서류가 아닌 것은?",["질문기록서","범죄사실보고서","화재발생종합보고서","화재현장출동보고서"],2,0,"ew20210912"],["ew20210912-70",3,"T116","2021-09-12",70,82,"화재조사 및 보고규정상 화재 당시에 피해물의 재구입비에대한 현재가의 비율을 뜻하는 용어는?",["잔가율","손해율","감가상각","경년감가율"],1,0,"ew20210912"],["ew20210912-71",3,"T125","2021-09-12",71,70,"화재조사 및 보고규정상 위험물 가스ㆍ제조소등 화재의 화재유형별 조사서 내용 중 위험물제조소 등에 포함되지않는 것은?",["옥외저장소","주유취급소","이동탱크저장소","액화석유가스제조시설"],4,0,"ew20210912"],["ew20210912-73",3,"T117","2021-09-12",73,72,"예술품 및 귀중품의 화재피해액 산정기준으로 틀린 것은?",["감가공제를 하지 아니한다.","복수의 전문가 감정을 받거나 감정서 등의 금액을피해액으로 인정한다.","공인감정기관에서 인정하는 금액을 화재로 인한 피해액으로 산정한다.","예술품 및 귀중품에 대한 그 가치를 손상하지 아니하고원상태의 복원이 가능한 경우에는 피해액을 인정하지아니한다."],4,0,"ew20210912"],["ew20210912-74",3,"","2021-09-12",74,74,"화재조사 및 보고규정상 방화ㆍ방화의심조사서 작성 시기재항목이 아닌 것은?(단, 참고사항은 제외한다.)",["방화동기","방화도구","처벌법규","도착 시 초기상황"],3,0,"ew20210912"],["ew20210912-76",3,"T115","2021-09-12",76,49,"내용연수가 40년인 일반 공장에서 준공 후 15년이 지나서 화재가 발생하였을 때 잔가율(%)은?",["20","30","50","70"],4,0,"ew20210912"],["ew20210912-77",3,"T113","2021-09-12",77,41,"철거건물에 대한 화재피해액을 산정하는 계산식은?",["재건축비×[0.1+(0.8×잔여내용연수/내용연수)]","재건축비×[0.1+(0.9×잔여내용연수/내용연수)]","재건축비×[0.2+(0.8×잔여내용연수/내용연수)]","재건축비×[0.2+(0.9×잔여내용연수/내용연수)]×손해율"],3,0,"ew20210912"],["ew20210912-78",3,"T105","2021-09-12",78,78,"화재현장조사서 작성에 대한 설명으로 틀린 것은?",["입회인의 설명내용과 조사원의 관찰ㆍ확인 사실은 구분하지 않고 작성한다.","현장조사서에는 주관적 판단이나 조사자가 의도하는결론으로 유도하지 않는다.","작성자는 현장조사를 직접 행한 자로 한정하고 다른 사람이 대신하여 작성하는 것은 인정되지 않는다.","현장조사서의 기재는 조사자의 의사나 판단이 개입되지않도록 현장상황이나 소손물건 등을 객관적으로 가능한있는 그대로 표현하는 것이 좋다."],1,0,"ew20210912"],["ew20210912-79",3,"T113","2021-09-12",79,51,"화재조사 및 보고규정상 화재피해액 산정기준으로 틀린 것은?",["재고자산의 산정기준은 「회계장부상 현재가액 × 손해율」의 공식에 의한다.","영업시설의 산정기준은 「화재피해액 × 10%」의 공식에 의한다.","기계장치 및 선박ㆍ항공기 산정기준은 「감정평가서또는 회계장부상 현재가액 × 손해율」의 공식에 의한다.","부대설비의 산정기준은 「건물신축단가 × 소실면적 × 설비종류별 재설비 비율×[1-(0.8×경과년수/내용연수)] × 손해율」의 공식에 의한다."],2,0,"ew20210912"],["ew20210912-80",3,"T111","2021-09-12",80,69,"화재조사 및 보고규정상 명시된 화재현황조사서의 기상상황에 해당하지 않는 것은?",["온도","기상특보","기압","풍향 및 풍속"],3,0,"ew20210912"],["ew20210912-81",4,"T151","2021-09-12",81,49,"화재로 인한 재해보상과 보험가입에 관한 법령상 한국화재보험협회의 업무에 명시되지 않은 것은?(단, 그 밖에 금융위원회의 인가를 받은 업무는 제외한다.)",["화재예방 및 소화시설에 대한 안전점검","소방기술정보를 보급하여 화재예방 도모","화재예방과 소화시설에 관한 자료의 조사ㆍ연구 및 계몽","화재보험에 있어서의 소화설비(消火設備)에 따른 보험요율의 할인등급에 대한 사정(査定)"],2,0,"ew20210912"],["ew20210912-82",4,"T167","2021-09-12",82,74,"화재로 인한 재해보상과 보험가입에 관한 법령상 특약부화재보험에 가입하지 아니한 특수건물의 소유자에게 주어지는 벌칙은?",["500만원 이하의 벌금","1000만원 이하의 벌금","1500만원 이하의 벌금","1년 이하의 징역 또는 1천만원 이하의 벌금"],1,0,"ew20210912"],["ew20210912-83",4,"T164","2021-09-12",83,69,"화재로 인한 재해보상과 보험가입에 관한 법령상특수건물의 기준으로 옳은 것은?",["음악산업진흥에 관한 법률에 따른 노래연습장업으로 사용하는 부분의 바닥면적의 합계가 1천m2 이상인 건물","관광진흥법에 따른 관광숙박업으로 사용하는 건물로서연면적의 합계가 3천m2 이상인 건물","학원의 설립ㆍ운영 및 과외교습에 관한 법률에 따른학원으로 사용하는 부분의 바닥면적의 합계가 1천m2이상인 건물","의료법에 따른 병원급 의료기관으로 사용하는 건물로서 연면적의 합계가 2천m2 이상인 건물"],2,0,"ew20210912"],["ew20210912-84",4,"T157","2021-09-12",84,76,"화재증거물수집관리규칙상 증거물에 대한 조치로 틀린 것은?",["증거물 수집 목적이 인화성 액체 성분분석인 경우에는인화성 액체 성분의 증발을 막기 위한 조치를 행하여야한다.","증거물의 보관은 전용실 또는 전용함 등 변형이나파손될 우려가 없는 장소에 보관한다.","증거물은 화재증거 수집의 목적달성 후 관계인의 승낙이있을 때에는 폐기할 수 있다.","발화원인의 판정에 관계가 있는 개체에 대해서는 증거물과 이격되어 있거나 연소되지 않은 상황이라면기록을 남기지 않을 수 있다."],4,0,"ew20210912"],["ew20210912-85",4,"","2021-09-12",85,65,"국가배상법령상의 내용으로 틀린 것은?",["외국인이 피해자인 경우에는 해당 국가와 상호 보증이있을 때에만 적용한다.","생명ㆍ신체의 침해로 인한 국가배상을 받을 권리는 양도할 수 있다.","손해배상의 소송은 배상심의회에 배상신청을 하지아니하고도 제기할 수 있다.","국가나 지방자치단체는 공무원이 직무를 집행하면서고의 또는 과실로 법령을 위반하여 타인에게 손해를 입힌 경우에 그 손해를 배상하는 것이 원칙이다."],2,0,"ew20210912"],["ew20210912-86",4,"T157","2021-09-12",86,54,"화재증거물수집관리규칙상 증거물 보관ㆍ이동 시 책임자가 전 과정에 대하여 입증할 수 있도록 작성하여야 하는 사항으로 명시되지 않은 것은?",["증거물 운반일자, 운반자","증거물 발신일자, 발신자","증거물 수신일자, 수신자","증거물 최초상태, 개봉일자, 개봉자"],1,0,"ew20210912"],["ew20210912-87",4,"T142","2021-09-12",87,75,"화재조사 및 보고규정상 최종잔가율의 정의로 옳은 것은?",["피해물의 내용연수에 대한 사용연수의 비율","화재 당시에 피해물의 재구입비에 대한 현재가의 비율","피해물의 종류, 손상 상태 및 정도에 따라 피해액을 적정화시키는 일정한 비율","피해물의 경제적 내용연수가 다한 경우 잔존하는 가치의 재구입비에 대한 비율"],4,0,"ew20210912"],["ew20210912-88",4,"","2021-09-12",88,58,"경범죄 처벌법령상 범칙행위를 한 사람으로서 범칙자에 해당하는 사람은?",["나이가 18세 이상인 사람","피해자가 있는 행위를 한 사람","범칙행위를 상습적으로 하는 사람","죄를 지은 동기나 수단 및 결과를 헤아려 볼 때구류처분을 하는 것이 적절하다고 인정되는 사람"],1,0,"ew20210912"],["ew20210912-89",4,"","2021-09-12",89,78,"경범죄 처벌법령상 즉결심판 대상자에게 발부하는 즉결심판출석통지서에 기재하는 사항이 아닌 것은?",["위반 내용 및 적용 법조문","즉결심판 대상자의 인적사항","즉결심판을 위한 출석의 일시 및 장소","지방법원, 지원 또는 시ㆍ군법원의 판사이름"],4,0,"ew20210912"],["ew20210912-90",4,"T148","2021-09-12",90,81,"제조물 책임법의 제정목적이 아닌 것은?",["제조업자의 이익증진","피해자의 보호를 도모","국민생활의 안전 향상","국민경제의 건전한 발전"],1,0,"ew20210912"],["ew20210912-91",4,"T156","2021-09-12",91,55,"실화책임에 관한 법률상 손해배상액 경감청구가 있을경우 고려사항으로 명시되지 않은 것은? (단, 그 밖에 손해배상액을 결정할 때 고려할 사항은 제외한다.)",["화재의 원인과 규모","소화수에 의한 수손 피해의 정도","배상의무자 및 피해자의 경제상태","피해 확대를 방지하기 위한 실화자의 노력"],2,0,"ew20210912"],["ew20210912-94",4,"T173","2021-09-12",94,70,"민법상 불법행위로 인한 배상의 책임 기준으로 틀린 것은?",["공동불법행위의 책임과 관련하여 교사자나 방조자는 공동행위자로 본다.","과실로 인한 심신상실을 초래한 경우 타인에게 손해를가한 자는 배상의 책임이 없다.","미성년자가 타인에게 손해를 가한 경우에 그 행위의 책임을 변식할 지능이 없는 때에는 배상의 책임이 없다.","타인의 생명을 해한 자는 피해자의 직계존속, 직계비속 및 배우자에 대하여는 재산상의 손해없는 경우에도 손해배상의 책임이 있다."],2,0,"ew20210912"],["ew20210912-95",4,"T152","2021-09-12",95,63,"형법상 현주건조물 등에의 방화로 사람을 사망에 이르게 한 경우의 벌칙은?",["2년 이상의 징역","3년 이상의 징역","무기 또는 5년 이상의 징역","사형, 무기 또는 7년 이상의 징역"],4,0,"ew20210912"],["ew20210912-97",4,"T138","2021-09-12",97,83,"소방기본법령상 화재의 조사에 관한 사항으로 틀린 것은?",["소방공무원과 경찰공무원은 화재조사를 할 때에 서로 협력하여야 한다.","화재조사 결과 실화 혐의가 있다고 인정하면 소방청장에게 보고하여 경찰부서에 통보할지 여부를 결정한다.","수사기관에서 실화의 혐의로 압수한 증거물이 화재조사를 위하여 필요한 경우, 수사에 지장을 주지 않는 범위에서 압수된 증거물에 대한 조사를 할 수 있다.","수사기관에 방화혐의로 체포된 피의자가 화재조사를 위하여 필요한 경우, 수사에 지장을 주지 않는 범위에서피의자를 조사할 수 있다."],2,0,"ew20210912"],["ew20210912-98",4,"T139","2021-09-12",98,77,"소방기본법령상 명시된 화재조사를 하는 관계공무원이 관계인의 정당한 업무를 방해하거나 화재조사를 수행하면서알게된 비밀을 다른 사람에게 누설한 자의 경우의 벌칙기준은?",["300만원 이하의 벌금","500만원 이하의 벌금","700만원 이하의 벌금","1천만원 이하의 벌금"],1,0,"ew20210912"],["ew20210912-99",4,"","2021-09-12",99,77,"소방기본법령상 소방자동차 전용구역에 관한 설명으로틀린 것은?",["전용구역 방해행위를 한 자는 300만원 이하의 과태료에처한다.","소방자동차 전용구역 노면표지 도료의 색채는 황색을기본으로 한다.","소방자동차 전용구역에 물건 등을 쌓는 등의 방해해위를 하여서는 아니 된다.","세대수가 100세대 이상인 아파트의 건축주는 소방자동차 전용구역을 설치하여야 한다."],1,0,"ew20210912"],["ew20220305-2",0,"T017","2022-03-05",2,64,"화재조사 시 조사관이 분석한 데이터를 토대로 화재확산, 발화점의 규명, 화재 원인 등에 대한 가설을 만들어 내는 과정은?",["주관적 추론","연역적 추론","귀납적 추론","객관적 추론"],3,0,"ew20220305"],["ew20220305-3",0,"T006","2022-03-05",3,55,"폴리우레탄폼 벽체를 관통하는 단위면적당 열유동률은 약 몇 W/m2인가? (단, 폴리우레탄폼의 열전도율은 0.034W/mㆍK이며, 벽의 두께는 0.05m, 벽 양면의 온도는 각각 50℃와 20℃이다.)",["15.3","20.4","24.5","28.9"],2,0,"ew20220305"],["ew20220305-4",0,"T001","2022-03-05",4,79,"화재 플럼(Fire Plume)에 의해 수직벽면에 생성되는 패턴이 아닌 것은?",["V 패턴","U 패턴","모래시계 패턴","레인보우 이펙트 패턴(Rainbow Effect Pattern)"],4,0,"ew20220305"],["ew20220305-5",0,"T023","2022-03-05",5,71,"물질의 환원반응에 관한 설명 중 틀린 것은?",["산소를 잃는 반응이다.","전자를 얻는 반응이다.","수소와 결합하는 반응이다.","산화수가 증가하는 반응이다."],4,0,"ew20220305"],["ew20220305-6",0,"T014","2022-03-05",6,90,"화재현장에서 조사자의 자세로 틀린 것은?",["개인의 민사관계에 적극 관여하여야 한다.","부당하게 개인의 권리를 침해하고 자유를 제한하지 않도록 한다.","기술적으로 타당성에 입각하여 조사하여야 한다.","화재조사는 물적 증거를 객체로 하여 과학적 방법으로 합리적으로 사실을 규명하여야 한다."],1,0,"ew20220305"],["ew20220305-7",0,"T012","2022-03-05",7,86,"소방기본법령상 화재조사의 책임과 권한에 관한 사항으로 옳은 것은?",["소방청장, 소방본부장 또는 소방서장은 화재조사를 위하여 관계인에게 자료 제출을 명할 수 없다.","소방청장, 소방본부장 또는 소방서장은 수사기관이 방화(放火)의 혐의가 있어서 이미 피의자를 체포하였을 때에 그 피의자에 대하여 조사할 수 없다.","화재조사를 하는 관계 공무원은 화재조사를 수행하면서 알게 된 비밀을 언론에 알려야 한다.","소방본부장이나 소방서장은 화재조사 결과 방화 또는 실화의 혐의가 있다고 인정하면 지체 없이 관할 경찰서장에게 그 사실을 알려야 한다."],4,0,"ew20220305"],["ew20220305-8",0,"","2022-03-05",8,42,"가정용 LPG 보일러 배관에서 LPG가 누출되어 폭발이 발생하였다. 발화원인으로서 화재의 4요소 중 가장 집중해서 조사하여야 하는 것은?",["점화원","가연물","산소 농도","자립연쇄반응"],2,0,"ew20220305"],["ew20220305-9",0,"T018","2022-03-05",9,79,"구획실 화재 현상에 관한 설명 중 틀린 것은?",["플레임오버나 롤오버는 플래시오버에 선행하는 것이 일반적이다.","플레임오버나 롤오버 이후에는 반드시 플래시오버가 일어난다.","화재가 성장하면서 복사열이 화재를 지배하게 한다.","환기지배형화재의 경우에는 고온 가스층에 미연소 열분해물과 일산화탄소의 수치가 증가한다."],2,0,"ew20220305"],["ew20220305-10",0,"T003","2022-03-05",10,76,"목재의 탄화모양과 형상에 대한 설명 중 틀린 것은?",["탄화된 골은 폭이 좁고 얕다.","표면은 요철부가 많고 거칠어진다.","표면이 박리와 회화(恢化)를 반복한다.","연소가 계속되면 타서 가늘게 되고 박리되어 소실되어 간다."],1,0,"ew20220305"],["ew20220305-11",0,"T003","2022-03-05",11,55,"발화부 주변의 일반적인 연소현상에 대한 설명 중 틀린 것은?",["발화부를 향해 소락(燒落)되거나 도괴된다.","발화부와 가까울수록 탄화심도가 깊다.","목재표면에 발생하는 균열은 발화부와 가까울수록 골이 넓고 굵어진다.","발화부는 비교적 밝은 색을 띠며 발화부와 멀어질수록 어두운 빛을 나타낸다."],3,0,"ew20220305"],["ew20220305-12",0,"T024","2022-03-05",12,70,"얇은 고체 가연물에서 정방향 화염확산에 관한 설명 중 틀린 것은?",["얇은 고체가연물에서의 정방향 화염 확산은 위로 퍼지는 화염 확산에서 발생한다.","커튼 위로 화염이 퍼지거나 종이 위로 화염이 퍼지는 것이 대표적인 예이다.","화염확산 속도가 역방향 화염 확산보다 느리기 때문에 가연물이 활발하게 타는 지역이 매우 짧다.","얇은 고체가연물은 빨리 발화되지만 빨리 연소되기 때문에 가연물 두께에 따른 화염 확산 속도의 변화 추이를 만드는 것이 불가능하다."],3,0,"ew20220305"],["ew20220305-14",0,"T011","2022-03-05",14,83,"가연물의 최소착화에너지에 영향을 미치는 요인에 대한 설명으로 옳은 것은?",["압력이 높을수록 최소착화에너지는 높아진다.","온도가 높을수록 최소착화에너지는 낮아진다.","가연물의 종류에 관계없이 최소착화 에너지는 일정하다.","혼합된 공기의 산소농도에 관계없이 최소 착화에너지는 일정하다."],2,0,"ew20220305"],["ew20220305-17",0,"T010","2022-03-05",17,62,"메탄의 연소범위로 옳은 것은?",["4.0~75 vol%","5.0~15 vol%","2.1~9.5 vol%","6.7~36vol%"],2,0,"ew20220305"],["ew20220305-18",0,"T001","2022-03-05",18,70,"인화성 액체 가연물의 연소에 의한 화재패턴이 아닌 것은?",["제트패턴(Z Pattern)","포어패턴(Pour Pattern)","도넛패턴(Doughnut Pattern)","고스트마크패턴(Ghost Mark Pattern)"],1,0,"ew20220305"],["ew20220305-20",0,"T009","2022-03-05",20,81,"BLEVE 현상에 대한 설명으로 옳은 것은?",["압력유, 윤활유 등 유기물이 공기중에 분무된 상태에서 폭발하는 현상","저장탱크에서 유출된 대량의 가연성가스가 대기중에 떠다니다가 점화원과 접촉시 폭발하는 현상","혼합가스가 폭발범위에서 점화될 때 음속보다 빠른 연소속도로 이동하며 충격파를 수반하는 현상","가스저장탱크 주변화재시 저장탱크가 가열되어 탱크 내의 액화가스가 급격히 증발 팽창하여 탱크가 폭발하는 현상"],4,0,"ew20220305"],["ew20220305-21",1,"T044","2022-03-05",21,68,"차량의 점화장치의 전류 흐름 순서를 바르게 나열한 것은?",["점화스위치→배터리→시동모터→점화코일→배전기→고압케이블→스파크 플러그","점화스위치→시동모터→배터리→점화코일→배전기→고압케이블→스파크 플러그","점화스위치→배터리→시동모터→배전기→점화코일→고압케이블→스파크 플러그","점화스위치→시동모터→점화코일→배터리→배전기→고압케이블→스파크 플러그"],1,0,"ew20220305"],["ew20220305-22",1,"T035","2022-03-05",22,84,"항공기 객실 내에서의 연기로 인한 이온밀도에 변화를 감지하는 연기감지기(Smoke detector)는?",["열감지기","불꽃감지기","이온화감지기","광전식감지기"],3,0,"ew20220305"],["ew20220305-23",1,"T061","2022-03-05",23,71,"화재조사 및 보고규정상 발화원인 판정에서 서술되는 용어의 정의 중 틀린 것은?",["발화란 열원에 의하여 가연물질에 지속적으로 불이 붙는 현상을 말한다.","발화열원이란 발화의 최초원인이 된 불꽃 또는 열을 말한다.","발화요인이란 발화열원에 의하여 발화로 이어진 연소현상에 영향을 준 물적요인만을 말한다.","최초착화물이란 발화열원에 의해 불이 붙고 이 물질을 통해 제어하기 힘든 화세로 발전한 가연물을 말한다."],3,0,"ew20220305"],["ew20220305-24",1,"T052","2022-03-05",24,72,"화재현장에 노출된 금속의 표면에 화재열에 의하여 나타나는 현상이 아닌 것은?",["변색","분해","만곡","용융"],2,0,"ew20220305"],["ew20220305-25",1,"T040","2022-03-05",25,75,"임야화재 중 수관화에 관한 설명으로 틀린 것은?",["땅속에 있는 연료가 타는 것을 말한다.","중심부 화염의 온도가 1175℃ 정도이다.","바람을 타고 바람이 부는 방향으로 V자형으로 퍼진다.","빨리 확산되고 짧은 기간에 심각한 피해를 발생시킨다."],1,0,"ew20220305"],["ew20220305-26",1,"T042","2022-03-05",26,68,"담뱃불로 인하여 화재가 발생한 현장의 주요 감식요령 중 틀린 것은?",["발화에 충분한 축열조건 입증","착화지점이 얕게 타들어간 흔적 입증","착화, 발염에 이르기까지의 경과시간과 착화물과의 관계의 타당성 입증","담뱃불에 의해 착화될 수 있는 가연물의 존재 여부 입증"],2,0,"ew20220305"],["ew20220305-27",1,"","2022-03-05",27,39,"용기 내용적이 5m3이고, 35℃에서 최고 충전압력이 4MPa인 압축가스용기의 최대저장능력(m3)은?",["10","20","25","30"],3,0,"ew20220305"],["ew20220305-28",1,"T054","2022-03-05",28,35,"화학적 폭발 이후에 화재로 진행되는 경우, 가연물과 공기의 혼합비율이 화재에 미치는 영향에 관한 설명으로 옳은 것은?",["연소상한계에 가까울수록 폭발 후 화재로 발전될 가능성이 높다.","연소하한계에 가까울수록 폭발 후 화재로 발전될 가능성이 높다.","연소 한계 범위 내에서는 혼합비율에 관계없이 화재로 발전가능성은 모두 같다.","연소범위 내에서 화학양론비에 가까울수록 화재로 발전될 가능성이 높다."],1,0,"ew20220305"],["ew20220305-30",1,"T061","2022-03-05",30,67,"화재현장에서 발생하는 소음으로서 목격자들이 폭발로 오인할 수 있는 경우가 아닌 것은?",["화재 시 콘크리트 폭렬에 의한 소음","개방된 용기의 변형 시 발생하는 소음","화재 열기에 의한 스프레이 캔, 방향제 캔 등의 파열 소음","화재 시 전선피복이 손상되면서 발생하는 전기적 합선의 소음"],2,0,"ew20220305"],["ew20220305-31",1,"T048","2022-03-05",31,46,"전기적 발화원인 중 근본적인 원인이 국부적 저항증가인 것은?",["누전","과전류","합선","불완전접촉"],4,0,"ew20220305"],["ew20220305-32",1,"T043","2022-03-05",32,75,"유염화원에 관한 사항 중 틀린 것은?",["미소화원에 비하여 훨씬 에너지량이 많다.","라이터불, 성냥불, 촛불과 같이 화염이 있는 화염이다.","오랜 시간동안 연소가 진행되고 깊게 탄 연소흔적을 보이며 표면적으로 연소가 확대되는 경우는 드물다.","무염화원에 대한 소화되기 전까지 불이 붙어 있거나 보통 소화되기 전까지 화염을 발하여 연소를 계속하고 있는 화원의 총칭이다."],3,0,"ew20220305"],["ew20220305-34",1,"T046","2022-03-05",34,67,"고압가스안전관리법령상 가연성가스 종류에 따른 용기의 도색구분으로 옳은 것은?",["LPG - 백색","수소 - 주황색","아세틸렌 - 녹색","액화암모니아 - 회색"],2,0,"ew20220305"],["ew20220305-35",1,"T055","2022-03-05",35,45,"산화에틸렌 90vol%와 메탄 10vol%가 혼합되어 있는 경우 폭발하한계 값(vol%)은?",["3.13","15.79","32.50","55.81"],1,0,"ew20220305"],["ew20220305-36",1,"","2022-03-05",36,74,"화재조사 및 보고규정상 항공기 화재의 소실정도에 관한 내용 중 틀린 것은?",["항공기의 50%가 소실된 경우 반소로 본다.","항공기의 70%이상 소실된 경우 전소로 본다.","항공기의 소실정도는 전소와 반소로만 구분한다.","항공기의 60%가 소실되었으나 잔존부분을 보수하여도 재사용이 불가능한 것은 전소로 본다."],3,0,"ew20220305"],["ew20220305-37",1,"T048","2022-03-05",37,65,"다음 흔적 중 전기기기 내부의 통전 입증이 가능한 증거가 아닌 것은?",["전류 퓨즈의 용단","기판의 전체적인 탄화","내부 배선의 합선흔적","내부 단자의 부분적 용융흔적"],2,0,"ew20220305"],["ew20220305-38",1,"T045","2022-03-05",38,86,"차량화재 조사 시 유의사항으로 옳은 것은?",["화재차량을 위주로만 세밀하게 조사한다.","차량 조사를 위해 차량을 함부로 이동 시킨다.","명확한 원인 조사를 위해 주변을 깨끗하게 정리 및 청소한다.","차량 주변의 수거 가능한 모든 증거물을 모아두고, 작은 것도 소홀히 취급해서는 안된다."],4,0,"ew20220305"],["ew20220305-40",1,"T034","2022-03-05",40,82,"방화형태의 이론에서 연쇄방화의 주요 조사 착안점 중 틀린 것은?",["행적 조사","연고감(緣故感)조사","피해액 조사","지리감(地理感)조사"],3,0,"ew20220305"],["ew20220305-41",2,"T069","2022-03-05",41,67,"화재증거물수집관리규칙상 화재현장 사진 및 비디오 촬영 시 유의사항 중 틀린 것은?",["증거물을 촬영할 때는 그 소재와 상태가 명백히 나타나도록 하며 구분이 용이하도록 반드시 번호표 등을 넣어 촬영한다.","화재와 연관성이 크다고 판단되는 증거물, 피해물품, 유류 등의 대상물은 형상을 면밀히 관찰 후 자세히 촬영한다.","현장사진 및 비디오 촬영과 현장기록물 확보 시에는 연소확대 경로 및 증거물 기록에 대한 번호표와 화살표 등을 활용하여 작성한다.","화재현장의 특정한 증거물 등을 촬영할 때 그 길이, 폭 등을 명백히 하기 위하여 측정용 자 또는 대조도구를 사용하여 촬영한다."],1,0,"ew20220305"],["ew20220305-42",2,"T092","2022-03-05",42,76,"냉온수기의 자동온도 조절장치에서 절연체의 오염에 의한 트래킹 화재가 발생한 경우 감정해야 할 증거물로 옳은 것은?",["응축기","압축기","서모스탯","과부하 계전기"],3,0,"ew20220305"],["ew20220305-43",2,"T084","2022-03-05",43,78,"화재조사를 위한 질문 및 녹음에 관한 설명으로 옳은 것은?",["경험이 많은 화재조사자의 직감에 의존하여 질문을 한다.","허위진술과 같은 불가피한 상황은 어느정도 인정하고 받아들어야 한다.","녹취가 필요한 경우 피질문자의 동의가 필요하다.","청소년을 대상으로 하는 질문을 가급적이면 편안하고 조용한 장소에서 1대 1로 진행한다."],3,0,"ew20220305"],["ew20220305-44",2,"T077","2022-03-05",44,77,"화재증거물수집관리규칙상 입수한 증거물 이송을 위해 포장한 후 부착하여야 할 상세정보가 아닌 것은?",["봉인자","수집일시","증거물 번호","증거물 포장용기 종류"],4,0,"ew20220305"],["ew20220305-45",2,"T097","2022-03-05",45,67,"화재로 인해 사망한 시체에서 볼 수 있는 특징과 거리가 가장 먼 것은?",["구강 개방","피부의 파열","권투선수자세","손과 발의 피부 장갑상 탈락"],1,0,"ew20220305"],["ew20220305-46",2,"T070","2022-03-05",46,54,"화재현장 촬영 시 사용되는 카메라의 기능 중 노출 측정이 어렵거나 측정치가 정확하지 않을 때 노출을 여러 단계로 두는 것은?",["다징(Dodging)","마젠타(Magenta)","비네팅(Vignetting)","브라케팅(Bracketing)"],4,0,"ew20220305"],["ew20220305-47",2,"T075","2022-03-05",47,71,"액체나 고체 촉진제의 증거물을 수집할 때 잘못된 방법은?",["일회용 비닐장갑을 끼고 수집한다.","보관용기 자체를 수집도구로 사용한다.","각 증거물에 대해 항상 새 장갑이나 새 봉지를 사용한다.","증거물을 수집할 때 증거물 수집 및 조사 기구를 휘발성 용매가 들어있는 클리너를 사용하여 수시로 닦아야 한다."],4,0,"ew20220305"],["ew20220305-49",2,"T076","2022-03-05",49,82,"화재증거물수집관리규칙상 증거물의 보관ㆍ이동에 관한 사항 중 틀린 것은?",["증거물은 화재증거 수집의 목적달성 후에는 5년간 소방서장이 보관하여야 한다.","증거물의 보관 및 이동은 장소 및 방법, 책임자 등이 지정된 상태에서 행해져야 한다.","증거물의 보관은 전용실 또는 전용함 등 변형이나 파손될 우려가 없는 장소에 보관해야 한다.","증거물은 수집 단계부터 검사 및 감정이 완료되어 반환 또는 폐기되는 전 과정에 있어서 화재조사자 또는 이와 동일한 자격 및 권한을 가진 자의 책임 하에 행해져야 한다."],1,0,"ew20220305"],["ew20220305-50",2,"T099","2022-03-05",50,49,"전신적 생활반응이 아닌 것은?",["색전증","피하출혈","속발성염증","전신적 빈혈"],2,0,"ew20220305"],["ew20220305-51",2,"T070","2022-03-05",51,74,"화재현장의 촬영에 관한 설명 중 틀린 것은?",["작은 물건을 촬영할 때에는 표식을 사용한다.","어두운 곳에서는 스트로보(Strobo)를 이용하여 촬영한다.","좁은 방에서는 광각렌즈보다 표준렌즈를 사용한다.","촬영의 목적을 분명하게 이해한 뒤 촬영에 임한다."],3,0,"ew20220305"],["ew20220305-52",2,"T074","2022-03-05",52,79,"화재현장에서 증거물 수집 시 증거물의 상태와 수집용기의 연결이 잘못된 것은?",["비닐팩 - 액체","종이상자 - 고체","유리병 - 고체, 액체","금속캔 - 고체, 액체"],1,0,"ew20220305"],["ew20220305-53",2,"T092","2022-03-05",53,79,"방화가 의심되는 화재현장의 물적 증거로 거리가 가장 먼 것은?",["촉진제 용기","반단선 코드","타이머가 부착된 점화장치","인위적인 가스밸브의 절단흔적"],2,0,"ew20220305"],["ew20220305-54",2,"T074","2022-03-05",54,71,"화재증거물수집관리규칙상 증거물 시료용기에 관한 설명 중 틀린 것은?",["주석 도금 캔은 재사용이 용이하다.","주석 도금 캔은 사용직전에 검사하여야 하고 새거나 녹슨 경우 폐기한다.","양철 캔은 프레스를 한 이음매 또는 외부표면에 용매로 송진 용제를 사용하여 납땜을 한 이음매가 있어야 한다.","양철 캔은 기름에 견딜 수 있는 디스크를 가진 스크루 마개 또는 누르는 금속마개로 밀폐될 수 있으며, 이러한 마개는 한번 사용한 후에는 폐기되어야 한다."],1,0,"ew20220305"],["ew20220305-55",2,"T082","2022-03-05",55,85,"화재 진압 작업 시 증거물 보존을 위한 주의사항 중 틀린 것은?",["소방 호스의 사용은 물리적 증거를 옮기거나 손상시킬 수 있으니 주의한다.","동력절단기 사용을 위한 연료주입은 화재현장 안에서 실시한다.","잔불을 정리하거나 복원 작업을 할 때 증거를 불필요하게 훼손하지 않도록 한다.","화재 패턴이 남아 있을 가능성이 있어 화재조사관이 바닥을 살펴봐야 하는 경우 소화 시 화재 패턴에 최소한의 영향만 주도록 한다."],2,0,"ew20220305"],["ew20220305-56",2,"T087","2022-03-05",56,66,"사후강직에 대한 설명으로 옳은 것은?",["사후강직은 형성 이후 계속 변화가 없다.","사후강직은 주변 온도에 영향을 받지 않는다.","사후강직은 사망 후 혈액이 침하되는 현상이다.","사망 직전의 급격한 근육활동은 사후강직의 시작을 빠르게 한다."],4,0,"ew20220305"],["ew20220305-57",2,"T088","2022-03-05",57,79,"개별적인 화재증거물들을 연관성 있는 정보끼리 연결하고 분석 및 재구성하여 지도를 그리듯 화재원인을 추론하는 과정은?",["타임라인","마인드 맵","브레인스토밍","PERT 차트"],2,0,"ew20220305"],["ew20220305-58",2,"T077","2022-03-05",58,67,"화재증거물수집관리규칙상 증거물 수집에 관한 사항 중 틀린 것은?",["현장 수거(채취)물은 그 목록을 작성하여야 한다.","증거물 수집 목적이 인화성 액체 성분 분석인 경우에는 인화성 액체 성분의 증발을 막기 위한 조치를 행하여야 한다.","증거물이 파손될 우려가 있는 경우에 취급방법에 대한 주의사항을 증거물에 직접 표기하여야 한다.","증거물 수집 과정에서는 증거물의 수집자, 수집 일자, 상황 등에 대하여 기록을 남겨야 하며, 기록은 가능한 법과학자용 표지 또는 태그를 사용하는 것을 원칙으로 한다."],3,0,"ew20220305"],["ew20220305-59",2,"T098","2022-03-05",59,68,"화재현장에서 채취한 증거물 분석 시 사용하는 가스크로마토그래피(GC)에 관한 사항 중 틀린 것은?",["물질이 유사한 여러 성분의 혼합계 분리에 매우 유효하다.","화재현장에서 유류의 존재를 입증하기 위해 사용되는 분석방식이다.","가스 상태로 분석을 행하기 때문에 조작이 어렵고 많은 시간이 소요된다.","각 성분을 검출하여 그 양을 전기적인 신호로 기록계에 저장하여 분석 결과가 객관적으로 보존된다."],3,0,"ew20220305"],["ew20220305-60",2,"T091","2022-03-05",60,68,"화재현장에서 발견되는 증거물 중 유리에 대한 설명 중 틀린 것은?",["파손형태에 따라 열에 의한 파손, 충격에 의한 파손, 폭발에 의한 파손 등을 구별할 수가 있다.","유리가 동심원 모양으로 파손된 경우 충격지점에 가까울수록 파편이 크고 멀수록 파편이 작다.","방사형 파단면의 리플마크를 관찰하면 내측의 충격에 의해 깨진 것인지 외측 충격에 의해 깨진 것인지 구분할 수 있다.","유리는 충격부위에서부터 주변으로 순차적인 동심원 형태의 파단이 되며 동심원 순서에 따라 안팎으로 번갈아 가며 장력을 받아 파손된다."],2,0,"ew20220305"],["ew20220305-63",3,"T112","2022-03-05",63,77,"화재조사 및 보고규정상 화재현장조사서 작성 시 화재원인 검토 항목이 아닌 것은? (단, 임야화재, 기타화재, 피해액이 없는 화재는 제외한다.)",["조사결과","방화가능성","인적 부주의","전기적 요인"],1,0,"ew20220305"],["ew20220305-64",3,"","2022-03-05",64,51,"건물에 포함하여 화재 피해액을 산정하는 것은?",["칸막이","구축물","영업시설","부대설비"],1,0,"ew20220305"],["ew20220305-65",3,"T122","2022-03-05",65,65,"화재조사 및 보고규정상 회화(그림), 골동품의 화재피해산정기준으로 옳은 것은?",["전부손해의 경우 감정가격으로 한다.","전부손해의 경우 시중 매매가격으로 한다.","전부손해가 아닌 경우 감정가격으로 한다.","전부손해가 아닌 경우 시중 매매가격으로 한다."],1,0,"ew20220305"],["ew20220305-68",3,"T125","2022-03-05",68,77,"화재조사 및 보고규정상 위험물ㆍ가스 제조소등 화재의 화재유형별 조사서 작성 시 위험물제조소 항목이 아닌 것은?",["주유 취급소","지하탱크 저장소","이동탱크 저장소","액화산소를 소비하는 시설"],4,0,"ew20220305"],["ew20220305-69",3,"T111","2022-03-05",69,48,"화재조사 및 보고규정상 화재현황조사서에 명시된 연소확대물이 아닌 것은? (단, 기타사항은 제외한다.)",["가구","전기, 전자","간판, 차양막","목조건물의 밀집"],4,0,"ew20220305"],["ew20220305-70",3,"T103","2022-03-05",70,71,"화재조사 및 보고규정상 민원인이 화재증명원 발급 신청을 할 때 소방서장이 발급하는 화재증명원의 기재 사항이 아닌 것은?",["피해내역","화재발생개요","화재피해대상","화재현장출동기록"],4,0,"ew20220305"],["ew20220305-71",3,"T106","2022-03-05",71,62,"화재조사 및 보고규정상 화재현황 조사서의 발화열원의 분류 항목에 포함되는 것은?",["부주의","전기적 요인","폭발물, 폭죽","가스누출(폭발)"],3,0,"ew20220305"],["ew20220305-72",3,"T105","2022-03-05",72,50,"화재현장조사서 작성에 관한 설명 중 옳은 것은?",["작성자는 현장조사를 직접 행한 자에 한정하지 않고 능력있는 조사관이 작성하는 것이 인정된다.","현장조사는 법률행위적 행정조사로서 권한을 가진 상대방의 승낙을 득하고 입회하는 임의조사이다.","대규모 건물화재 등에서 현장조사를 분담하여 실시한 경우 대표자가 취합하여 현장조사서를 작성한다.","현장조사서에는 주관적 판단이나 조사자가 의도하는 결론으로 유도하여 기재할 수 있다."],2,0,"ew20220305"],["ew20220305-73",3,"","2022-03-05",73,68,"당해 피해물의 시중매매사례가 충분하여 유사매매 사례를 비교하여 산정하는 방법으로서 예술품, 귀금속의 피해액산정에 사용되는 방법은?",["수익환원법","비교평가법","복성식평가법","매매사례비교법"],4,0,"ew20220305"],["ew20220305-74",3,"","2022-03-05",74,49,"특수한 경우의 화재 피해액 산정 시 우선 적용사항으로 옳은 것은?",["공구ㆍ기구, 집기비품, 가재도구를 일괄하여 피해액을 산정할 경우 재구입비의 30%를 피해액으로 한다.","중고집기비품의 시장거래가격이 신품가격보다 높을 경우 신품가격을 재구입비로 하여 피해액을 산정한다.","중고구입기계장치의 제작년도를 알 수 없는 경우 신품가액의 60%를 재구입비로 하여 피해액을 산정한다.","중고집기비품의 시장거래가격이 신품가액에서 감가수정을 한 금액보다 높을 경우 중고기계장치의 시장거래가격을 재구입비로 하여 피해액을 산정한다."],2,0,"ew20220305"],["ew20220305-75",3,"T124","2022-03-05",75,69,"화재조사 및 보고규정상 화재현장 출동보고서에 관한 내용 중 틀린 것은?",["화재 장소에서 사용된 장비에 대해 작성한다.","출입문 상태 및 소방대 건물 진입방법에 대해 작성한다.","반드시 진압작전도 및 발견사항 상세도를 기입한다.","현장 도착 시 발견사항으로 연기와 화염을 본 위치와 발생장소 등 전체적인 현장사항을 서술식으로 기재한다."],3,0,"ew20220305"],["ew20220305-76",3,"T116","2022-03-05",76,60,"화재조사 및 보고규정상 명시된 용어의 정의 중 틀린 것은?",["재구입비는 화재 당시의 피해물과 같거나 비슷한 것을 구입하는데 필요한 금액에 감가상각을 반영한 것을 말한다.","최초착화물이란 발화열원에 의해 불이 붙고 이 물질을 통해 제어하기 힘든 화세로 발전한 가연물을 말한다.","감식이란 화재원인의 판정을 위하여 전문적인 지식, 기술 및 경험을 활용하여 주로 시각에 의한 종합적인 판단으로 구체적인 사실관계를 명확하게 규명하는 것을 말한다.","감정이란 화재와 관계되는 물건의 형상, 구조, 재질, 성분, 성질 등 이와 관련된 모든 현상에 대하여 과학적 방법에 의한 필요한 실험을 행하고 그 결과를 근거로 화재원인을 밝히는 자료를 얻는 것을 말한다."],1,0,"ew20220305"],["ew20220305-78",3,"T122","2022-03-05",78,81,"화재조사 및 보고규정상 전부 손해의 경우 동물, 식물의 피해액 산정 기준은?",["시중매매가격","수리비 및 치료비","전문가의 감정가격","감정서의 감정가액"],1,0,"ew20220305"],["ew20220305-79",3,"T108","2022-03-05",79,81,"화재조사 및 보고규정상 소방서장이 관할 구역 내에서 발생한 화재에 대하여 작성하여야 할 화재조사서류가 아닌 것은?",["질문기록서","재산회계 보고서","화재현장출동보고서","화재발생종합보고서"],2,0,"ew20220305"],["ew20220305-80",3,"T104","2022-03-05",80,73,"화재조사 및 보고규정상 화재피해조사의 재산피해 범위가 아닌 것은?",["화재진압 중 발생한 부상자","소화활동으로 발생한 수손피해","화재중 발생한 폭발 등에 의한 피해","열에 의한 탄화, 용융, 파손 등의 피해"],1,0,"ew20220305"],["ew20220305-81",4,"T163","2022-03-05",81,72,"화재조사 및 보고규정상 긴급상황보고 및 조사결과보고와 관련된 설명 중 틀린 것은?",["화재상황보고는 최초보고, 중간보고, 최종보고로 구분한다.","사망 3명이거나 재산피해액이 30억원 이상으로 추정되는 화재는 긴급상황보고를 하여야 한다.","대상이 특수하여 사회적 이목이 집중될 것으로 예상되는 화재는 긴급상황보고를 하여야 한다.","긴급상황보고 대상이 아닌 일반화재는 화재인지로부터 15일 이내에 조사결과를 소방본부장에게 보고하여야 한다."],2,0,"ew20220305"],["ew20220305-83",4,"T164","2022-03-05",83,57,"화재로 인한 재해보상과 보험가입에 관한 법률상 특수건물의 범위에 해당하지 않는 것은?",["사격 및 사격장 안전관리에 관한 법률에 따른 실내사격장으로 사용하는 건물","관광진흥법에 따른 관광숙박업으로 사용하는 건물로서 연면적의 합계가 2천제곱미터 이상인 건물","식품위생법 시행령에 따른 일반음식점영업으로 사용하는 부분의 바닥면적의 합계가 2천제곱미터 이상인 건물","영화 및 비디오물의 진흥에 관한 법률에 따른 영화상영관으로 사용하는 부분의 바닥면적의 합계가 2천제곱미터 이상인 건물"],2,0,"ew20220305"],["ew20220305-84",4,"T167","2022-03-05",84,74,"화재로 인한 재해보상과 보험가입에 관한 법률상 특수건물의 소유자가 손해보험회사가 운영하는 특약부화재보험에 가입하지 않았을 때 벌칙기준은?",["200만원 이하의 벌금","300만원 이하의 벌금","500만원 이하의 벌금","1000만원 이하의 벌금"],3,0,"ew20220305"],["ew20220305-85",4,"T152","2022-03-05",85,83,"형법상 방화와 실화의 죄 중 현주건조물 등 방화로 분류되지 않는 것은?",["사람이 현존하는 자동차에 대한 방화","건주물 등 내부에 사람이 현존하는 대상물에 대한 방화","우사 측면에 접해 있으며 사람이 주거로 사용하고 있는 가옥에 대한 방화","사람이 일상생활의 장소로 사용하지 않고 내부에 사람이 없는 컨테이너박스에 대한 방화"],4,0,"ew20220305"],["ew20220305-86",4,"","2022-03-05",86,47,"소방기본법령상 소방활동에 필요한 사람 외의 사람이 소방활동구역을 출입하였을 때 부과되는 과태료 기준은?",["100만원 이하의 과태료","300만원 이하의 과태료","200만원 이하의 과태료","500만원 이하의 과태료"],3,0,"ew20220305"],["ew20220305-88",4,"T138","2022-03-05",88,83,"소방기본법령상 화재의 조사에 관한 사항 중 틀린 것은?",["소방청장, 소방본부장 또는 소방서장은 화재가 발생하였을 때에는 화재의 원인 및 피해 등에 대한 조사를 하여야 한다.","화재조사를 하는 관계 공무원은 그 권한을 표시하는 증표를 지니고 이를 관계인에게 보여 주어야 한다.","화재조사를 하는 관계 공무원은 관계인의 정당한 업무를 방해하거나 화재조사를 수행하면서 알게 된 비밀을 다른 사람에게 누설하여서는 아니 된다.","소방청장, 소방본부장 또는 소방서장은 수사기관이 방화 또는 실화의 혐의가 있어서 이미 피의자를 체포하였거나 증거물을 압수하였을 때에 화재조사를 위하여 필요한 경우에는 수사에 지장을 주지 아니하는 범위에서 그 피의자 또는 압수된 증거물에 대한 조사를 할 수 없다."],4,0,"ew20220305"],["ew20220305-90",4,"","2022-03-05",90,81,"화재조사 및 보고규정상 소방활동구역의 설정 및 현장보존에 관한 사항 중 틀린 것은?",["소방활동구역의 관리는 수사기관과 상호 협조하여야 한다.","소방활동구역의 설정은 최대한의 범위로 한다.","소방본부장 또는 서장은 소화활동시 현장물건 등의 이동 또는 파괴를 최소화하여 원활한 화재조사활동이 이루어 질 수 있도록 현장보존에 노력하여야 한다.","소방활동구역의 표시는 로프 등으로 범위를 한정하고 경고판을 부착하며 출입을 통제하는 등 현장보존에 최대한 노력하여야 한다."],2,0,"ew20220305"],["ew20220305-92",4,"T158","2022-03-05",92,78,"화재조사 및 보고규정상 화재유형에 관한 설명 중 틀린 것은?",["선박ㆍ항공기화재는 선박, 항공기 또는 그 적재물이 소손된 것을 말한다.","건축ㆍ구조물 화재는 건축물, 구조물 또는 그 수용물이 소손된 것을 말한다.","임야화재는 산림, 야산, 들판의 수목, 경작물을 보관하는 창고가 소손된 것을 말한다.","자동차ㆍ철도차량 화재는 자동차, 철도차량 및 피견인 차량 또는 그 적재물이 소손된 것을 말한다."],3,0,"ew20220305"],["ew20220305-93",4,"T156","2022-03-05",93,50,"실화책임에 관한 법률의 내용 설명으로 옳은 것은?",["실화자는 중대한 과실이 있는 경우에만 손해배상책임이 있다.","실화로 인한 연소(延燒) 부분 및 정신적 피해에 대한 손해배상청구를 포함한다.","법원은 손해배상액의 경감청구가 있을 경우 피해자의 경제 상태는 고려하지 아니한다.","법원은 손해배상액의 경감청구가 있을 경우 피해 확대의 원인을 고려할 수 있다."],4,0,"ew20220305"],["ew20220305-94",4,"T156","2022-03-05",94,55,"실화책임에 관한 법률상 손해배상의무자의 손해배상액 경감 청구가 있을 때 법원이 손해배상액을 경감할 수 있는 기준이 아닌 것은? (단, 실화가 중대한 과실로 인한 것이 아닌 경우이다.)",["피해의 대상과 정도","화재의 원인과 규모","배상의무자의 경제상태","피해 확대를 방지하기 위한 피해자의 노력"],4,0,"ew20220305"],["ew20220305-95",4,"T147","2022-03-05",95,52,"제조물책임법상 손해배상을 지는 자가 손해배상책임을 면하는 기준 중 틀린 것은?",["제조업자가 해당 제조물을 공급하지 아니하였다는 사실을 입증한 경우","제조업자가 해당 제조물을 공급한 당시의 과학ㆍ기술수준으로는 결함의 존재를 발견할 수 없었다는 사실을 입증한 경우","제조물의 결함이 제조업자가 해당 제조물의 결함이 발생한 당시의 법령이 정하는 기준을 준수함으로써 발생한 사실을 입증한 경우","원재료나 부품의 경우에는 그 원재료나 부품을 사용한 제조물 제조업자의 설계 또는 제작에 관한 지시로 인하여 결함이 발생하였다는 사실을 입증한 경우"],3,0,"ew20220305"],["ew20220305-96",4,"","2022-03-05",96,71,"국가배상법상 화재조사관이 직무를 집행하면서 과실로 법령을 위반하여 타인에게 손해를 입힐 경우 손해배상의 책임자는?",["소방서장","화재조사관","소방재난본부장","국가나 지방자치단체"],4,0,"ew20220305"],["ew20220305-97",4,"T144","2022-03-05",97,71,"소방기본법령상 화재조사의 종류 및 조사의 범위 중 화재피해조사의 조사 범위에 포함되지 않는 것은?",["소화활동 중 사용된 물로 인한 피해","소화활동으로 발생한 영업 손실 피해","소화활동 중 발생한 사망자 및 부상자","연기, 물품반출, 화재로 인한 폭발 등에 의한 피해"],2,0,"ew20220305"],["ew20220305-98",4,"T157","2022-03-05",98,81,"화재증거물수집관리규칙상 증거물 수집에 관한 설명 중 틀린 것은?",["증거물을 수집할 때는 휘발성이 낮은 것에서 높은 순서로 진행해야 한다.","증거물의 소손 또는 소실 정도가 심하여 증거물의 일부분 또는 전체가 유실될 우려가 있는 경우는 증거물을 밀봉하여야 한다.","증거물이 파손된 우려가 있는 경우에 충격금지 및 취급방법에 대한 주의사항을 증거물의 포장 외측에 적절하게 표기하여야 한다.","증거물 수집 과정에서는 증거물의 수집자, 수집 일자, 상황 등에 대하여 기록을 남겨야 하며, 기록은 가능한 법과학자용 표지 또는 태그를 사용하는 것을 원칙으로 한다."],1,0,"ew20220305"],["ew20220424-1",0,"T012","2022-04-24",1,85,"소방기본법령상 화재원인조사의 조사범위가 아닌 것은?",["소방활동 중 발생한 사망자 및 부상자","피난경로, 피난상의 장애요인 등의 상황","화재의 연소경로 및 확대원인 등의 상황","화재가 발생한 과정, 화재가 발생한 지점 및 불이 붙기 시작한 물질"],1,0,"ew20220424"],["ew20220424-3",0,"T027","2022-04-24",3,68,"콘크리트 박리(spalling)에 관한 설명으로 틀린 것은?",["콘크리트 등에 포함된 수분이 열에 의해 팽창하면서 시멘트를 부서지게 만든다.","콘크리트 내의 강철재의 팽창은 둘러싸고 있는 콘크리트를 파괴한다.","콘크리트, 회벽, 벽돌 면이 깨지거나 부서진 것을 말한다.","시멘트 내의 폴리프로필렌 섬유는 압력을 견디지 못하고 화재 폭발 시 녹아 박리를 크게 한다."],4,0,"ew20220424"],["ew20220424-4",0,"T020","2022-04-24",4,76,"가연성 물질에 관한 설명으로 옳은 것은?",["주기율표의 0족 원소","산소와 충분히 화합한 물질","산소와 흡열반응을 하는 물질","산소와 반응 시 발열량이 큰 물질"],4,0,"ew20220424"],["ew20220424-5",0,"T026","2022-04-24",5,58,"습기가 있는 상태에서 과산화나트륨과 혼촉 시 발화가 일어나지 않는 것은?",["톱밥","산화칼슘","유황","알루미늄 분말"],2,0,"ew20220424"],["ew20220424-6",0,"T017","2022-04-24",6,57,"화재조사 시 발화지점의 가설에 대해 사고실험을 통해 분석적으로 검증하는 방법은?",["연역적 추론","귀납적 추론","주관적 추론","객관적 추론"],1,0,"ew20220424"],["ew20220424-8",0,"T022","2022-04-24",8,52,"220V, 2A가 전선에 1분간 전기가 인가되었을 때 저항에 발생하는 열량(cal)은?",["105.6","440","6336","26400"],3,0,"ew20220424"],["ew20220424-9",0,"T007","2022-04-24",9,78,"다음 중 분진폭발의 위험이 가장 낮은 것은?",["강철 분말","티타늄 분말","생석회 분말","알루미늄 분말"],3,0,"ew20220424"],["ew20220424-10",0,"T024","2022-04-24",10,62,"화염확산속도에 영향을 미치지 않는 것은?",["연료의 밀도","연료의 비열","연료의 하중","연료의 온도(화염온도범위 외)"],3,0,"ew20220424"],["ew20220424-11",0,"T026","2022-04-24",11,78,"연소반응에 있어서 산소공급원의 역할을 하는 물질은?",["황린","칼륨","과산화나트륨","디에틸에테르"],3,0,"ew20220424"],["ew20220424-12",0,"T017","2022-04-24",12,78,"화재현장 조사계획 수립 단계에 해당하지 않는 것은?",["경찰 등 관계기관 연락","조사의 방법, 책임자 선정 및 임무분담","소훼된 부분에 대해 집중적으로 현장 감식","화재현장의 상황 및 특성에 적합한 조사과정의 수립"],3,0,"ew20220424"],["ew20220424-13",0,"T009","2022-04-24",13,59,"폭굉유도거리에 관한 설명으로 틀린 것은?",["압력이 낮을수록 폭굉유도거리는 짧아진다.","정상연소속도가 큰 혼합가스일수록 폭굉유도거리는 짧아진다.","관지름이 작을수록 폭굉유도거리는 짧아진다.","점화원의 에너지가 클수록 폭굉유도거리는 짧아진다."],1,0,"ew20220424"],["ew20220424-14",0,"T002","2022-04-24",14,49,"고체의 연소현상 중 훈소와 표면연소에 관한 설명으로 옳은 것은?",["담배의 연소는 표면연소의 대표적인 예이다.","훈소와 표면연소는 화염이 없이 타는 외관적 형태를 보인다.","표면연소는 훈소에 비하여 많은 연기가 발생한다.","숯은 산소와 온도 조건이 맞으면 화염으로 연소할 수 있다."],2,0,"ew20220424"],["ew20220424-15",0,"T012","2022-04-24",15,83,"화재조사법(소방의 화재조사에 관한 법률)상 화재의 조사에 관한 설명으로 틀린 것은?",["소방청장, 소방본부장 또는 소방서장은 화재조사를 하기 위하여 필요 시 관계인에게 보고 또는 자료 제출을 명할 수 있다.","소방청장, 소방본부장 또는 소방서장은 관계 공무원으로 하여금 관계 장소에 출입하여 화재의 원인과 피해의 상황을 조사하거나 관계인에게 질문하게 할 수 있다.","화재조사를 하는 관계 공무원은 관계인의 정당한 업무를 방해하거나 화재조사를 수행하면서 알게 된 비밀은 다른 사람에게 누설하여서는 아니 된다.","소방청장, 소방본부장 또는 소방서장은 수사기관이 방화(放火)의 혐의가 있어서 이미 피의자를 체포하였을 때 피의자에 대한 조사 권한이 없으므로 수사기관에 수사 의뢰한다."],4,0,"ew20220424"],["ew20220424-16",0,"T013","2022-04-24",16,50,"소방기본법령상 거점소방서를 포함한 소방본부의 화재조사전담부서에 갖추어야 할 화재조사 장비 및 시설 중 감식·감정용 기기가 아닌 것은?",["실체현미경","거리측정기","절연저항계","적외선열상카메라"],2,0,"ew20220424"],["ew20220424-17",0,"T024","2022-04-24",17,66,"개구부를 통한 화재확산 메커니즘이 아닌 것은?",["복사열에 의한 점화","불씨가 이동하여 점화","직접적인 화염에 의한 점화","장애물을 통한 열전도에 의한 점화"],4,0,"ew20220424"],["ew20220424-18",0,"T018","2022-04-24",18,58,"건축물의 구획된 공간에서 플래시오버가 발생하면 고온 연기층으로부터 바닥으로 방사되는 복사열유속(kW/m2)은?",["약 10kW/m2","약 20kW/m2","약 30kW/m2","약 40kW/m2"],2,0,"ew20220424"],["ew20220424-19",0,"T018","2022-04-24",19,52,"플래시오버 현상과 백드래프트 현상을 비교한 설명으로 옳은 것은?",["연소속도를 살펴보면 플래시오버에 비하여 백드래프트의 연소속도가 더욱 빠르다.","현상 발생 전 가연성 기체의 온도는 플래시오버의 경우 인화점 이상, 백드래프트의 경우 인화점 이하이다.","구획실 내에서 산소가 충분할 때 플래시오버와 백드래프트가 발생한다.","현상의 발생단계를 비교하면 플래시오버는 자유연소단계에서 성화기로 전환되는 사이에서 발생하며 백드래프트는 자유연소단계와 성화기 이후에 발생한다."],1,0,"ew20220424"],["ew20220424-20",0,"T016","2022-04-24",20,83,"화재현장 발굴 시 주의사항으로 틀린 것은?",["발굴지역의 경계구역을 설정한다.","낙하물 등을 우선 제거하여 안전을 확보한다.","가급적 삽과 같은 큰 장비를 사용하여 발굴시간을 단축한다.","상층부에서 하층부로 발굴을 하며 수작업을 원칙으로 한다."],3,0,"ew20220424"],["ew20220424-21",1,"T047","2022-04-24",21,60,"프로판(C3H8)가스의 물성값으로 옳은 것은?",["발화점은 약 150℃","기체 비중은 약 0.95","임계온도는 약 –96.8℃","연소범위는 약 2.1 ~ 9.5vol%"],4,0,"ew20220424"],["ew20220424-23",1,"T053","2022-04-24",23,65,"유지류의 자연발화가 용이하게 발생할 수 있는 조건이 아닌 것은?",["표면적이 작다.","주변의 온도가 높다.","산소의 공급이 원활하다.","다공성 물질에 흡습되었다."],1,0,"ew20220424"],["ew20220424-24",1,"T041","2022-04-24",24,60,"산불방향지표 중 후진성 산불의 특징으로 틀린 것은?",["확산속도가 빠르다.","화염의 길이가 짧다.","거시적인 지표보다 미시적인 지표가 많이 발견된다.","경사가 있는 지형에서 하향으로 내려오는 경우가 많다."],1,0,"ew20220424"],["ew20220424-25",1,"T043","2022-04-24",25,71,"무염(훈소)화재에 관한 설명으로 틀린 것은?",["발화 메커니즘은 '접촉→훈소→축열→착염→출화과정'을 거친다.","유독가스가 생성되며, 화염을 동반한다.","다공성 고체가연물, 혼합연료, 불침윤성 고체에서 발생될 수 있다.","고체가연물과 산소 사이에 반응이 상대적으로 느린 연소이며 반응이 산소가 고체표면으로 확산되면서 일어나고 표면은 적열 및 탄화가 진행된다."],2,0,"ew20220424"],["ew20220424-26",1,"T033","2022-04-24",26,70,"직접착화에 의한 방화원인 감식에 관한 사항으로 틀린 것은?",["독립적 발화 개소 여부를 확인한다.","화재당시 사람의 출입 여부를 확인하고 내부 또는 외부 소행인지 확인한다.","화재 전에 없던 가연물이 연소한 흔적이 있거나 물건의 위치가 변경되었는지 확인한다.","스위치로부터 전열기구로 가는 회로를 찾아 스위치와 전열기구와의 관계를 규명한다."],4,0,"ew20220424"],["ew20220424-27",1,"","2022-04-24",27,77,"항공기 화재의 특징으로 틀린 것은?",["항공기 화재 조사 시 공간협소성, 고밀집성 등 다양한 특성을 고려해야 한다.","항공기가 단시간에 화재에 둘러싸이고 주변 일대의 가연성 물질에 급격히 전파된다.","상공에서 항공기 화재가 발생한 경우 지상까지 화재가 확산될 가능성은 전혀 없다.","항공기 인화성이 높은 연료를 대량으로 탑재하고 있어 추락사고가 발생하면 폭발적으로 연소할 수 있다."],3,0,"ew20220424"],["ew20220424-28",1,"T061","2022-04-24",28,49,"화재 및 폭발의 사고조사 시 고려해야 할 사항으로 틀린 것은?",["구획된 실내공간에서 가스폭발이나 분진 폭발이 일어난 경우에는 폭심부가 명확하다.","폭발로 인하여 비산된 파편에 그을음의 부착여부를 가지고 화재와 폭발의 선후 관계를 알 수 있다.","비닐, 스티로폼 등 열에 쉽게 변형되는 물질의 열변형 흔적으로부터 폭발과 화재의 선후관계를 알 수 있다.","비닐, 스티로폼, 종이 등의 열변형 흔적으로부터 화학적폭발과 물리적폭발을 구분할 수 있다."],1,0,"ew20220424"],["ew20220424-29",1,"T046","2022-04-24",29,49,"가스용기와 안전밸브 종류의 연결이 옳은 것은?",["산화에틸렌 용기 – 파열판식 안전밸브","수소 압축가스용기 - 파열판식 안전밸브","아르곤 압축가스용기 - 스프링식 안전밸브","LPG 용기 – 스프링식과 파열판식의 2중 안전밸브"],2,0,"ew20220424"],["ew20220424-30",1,"T061","2022-04-24",30,74,"화재 현장조사 시 조기발견자로부터 획득할 수 있는 정보와 관계가 가장 적은 것은?",["발견시각","발화원인","발견위치","불의 위치"],2,0,"ew20220424"],["ew20220424-31",1,"T049","2022-04-24",31,73,"전기다리미에 200v의 전압을 가했더니 3A의 전류가 흘렀다. 이때 전기다리미가 소비하는 전력(W)은?",["150","300","400","600"],4,0,"ew20220424"],["ew20220424-32",1,"T037","2022-04-24",32,45,"선박 추진시스템에 관한 설명으로 옳은 것은?",["인보드 엔진에는 기화기가 장착되어 있거나 연료분사 시스템이 있는 2사이클 또는 4사이클 가솔린 엔진이 포함된다.","인보드 가솔린엔진의 연료탱크에 대한 모든 부속품은 탱크의 윗부분에 있어야 하며, 연료 라인도 탱크보다 높게 있어야 한다.","2사이클 엔진의 시스템 기본 원칙은 자동차 엔진과 유사하고 아웃보다 엔진에서 연료는 펌프가 있는 고압연료 전달시스템을 통해 전달된다.","아웃보드 엔진의 4사이클 엔진은 연료와 오일 혼합물을 사용하며 오일이 가솔린과 미리 혼합되거나 별도의 저장소에 있다가 연료와 자동적으로 혼합되는 방식으로 사용된다."],2,0,"ew20220424"],["ew20220424-33",1,"T033","2022-04-24",33,74,"방화의 일반적인 특징에 관한 설명으로 틀린 것은?",["음주를 한 후 실행하는 경우가 많다.","우발적인 경우는 없고 모든 방화는 계획적이다.","방화범은 단독범행이 많고 인적이 드문 야간이나 심야에 많이 발생한다.","가솔린, 신나 등 인화성물질을 매개체로 사용한다."],2,0,"ew20220424"],["ew20220424-34",1,"T045","2022-04-24",34,76,"차량 화재조사를 위해 수집해야 할 자료로 거리가 가장 먼 것은?",["과거의 수리기록","화재 조기발견자의 진술","차량 정비 기록부 및 리콜 정비 유무","피해 차량 운전자의 운전 경력 증명서"],4,0,"ew20220424"],["ew20220424-35",1,"T052","2022-04-24",35,71,"초기 가연물에 대한 설명으로 틀린 것은?",["초기 가연물은 오작동하거나 고장난 장치의 일부일 수 있다.","초기 가연물은 열을 발생시키는 장치에 너무 가까이 있는 물체일 수 있다.","화재를 유발한 사건을 이해하기 위해 초기 가연물을 확인하는 것이 중요하다.","표면 대 질량 비율이 낮은 비-기체 가연물은 표면 대 질량 비율이 높은 가연물보다 훨씬 쉽게 발화한다."],4,0,"ew20220424"],["ew20220424-36",1,"T051","2022-04-24",36,53,"유염연소와 무염연소에 관한 설명으로 틀린 것은?",["무염연소는 연소반응속도가 느리다.","무염연소는 발열량이 작고, 유염염소는 발열량이 크다.","목재의 무염연소 시 가연물의 내부보다는 표면으로 전파되는 속도가 빠르다.","무염연소는 고체가연물에서만 가능하다."],3,0,"ew20220424"],["ew20220424-37",1,"T046","2022-04-24",37,58,"LPG 차량의 구성 부품 중 LPG 봄베의 밸브 색상에 대한 설명으로 옳은 것은?",["충전밸브 : 적색","액체 송출밸브 : 적색","기체 송출밸브 : 청색","충전, 액체 송출, 기체 송출 밸브 : 청색"],2,0,"ew20220424"],["ew20220424-38",1,"","2022-04-24",38,49,"가연성 액체의 인화점에 관한 설명으로 옳은 것은?",["가연성 액체가 발화하는 최저온도","가연성 액체의 증기가 공기와 접촉하여 점화원 없이 연소되는 최고온도","가연성 액체에 착화되기 충분한 증기를 발생하는 최저온도","가연성 액체의 증기가 포화상태에 달하는 최저온도"],3,0,"ew20220424"],["ew20220424-39",1,"T040","2022-04-24",39,65,"산불의 종류로 틀린 것은?",["지표화","수간화","비산화","수관화"],3,0,"ew20220424"],["ew20220424-41",2,"T098","2022-04-24",41,62,"잔류물이 있는 용기에 상부공간에 숯(Charcoal)을 매달아 촉진제를 추출하는 방법은?",["흡착법","상부공간법","용매추출법","증기증류법"],1,0,"ew20220424"],["ew20220424-42",2,"T091","2022-04-24",42,63,"액체가연물의 연소에 의한 화재패턴이 아닌 것은?",["포어 패턴","도넛 패턴","스플래시 패턴","U자 모양 패턴"],4,0,"ew20220424"],["ew20220424-43",2,"","2022-04-24",43,52,"화재 증거물 검증에 관한 설명으로 옳은 것은?",["검증하는 단계는 모든 가설을 검증하여, 모든 가설이 사실과 과학적 원리에 부합할 때까지 계속되어야 한다.","연역적 추론에 의한 검증 단계를 통과한 가설이 없는 경우에는 이 문제를 해결된 것으로 간주하여야 한다.","화재원인 재현실험을 통해서 물리적으로 검증될 수도 있고, 사고실험에서 과학적 원리를 적용하여 분석적으로 검증될 수도 있다.","증거가 증명될 수 있는 경우라도 다른 방법으로 반드시 검증하여야 하며, 여기에는 새로운 증거물 수집이나 기존 증거물에 대한 재분석이 필요할 수도 있다."],3,0,"ew20220424"],["ew20220424-44",2,"T082","2022-04-24",44,72,"화재현장 보존을 위한 조치사항으로 틀린 것은?",["잔불 정리를 위해 현장 물건을 과도하게 변형하거나 이동되지 않도록 한다.","발화원 등의 연소잔해가 있는 방향에는 직수 소화에 의한 증거물 파괴를 피한다.","현장진입을 위해 개방하고자 하는 출입문이나 창문에서 파괴흔적 발견 시 화재조사관에게 알려야 한다.","현장에서 석유류의 연료를 사용하는 장비 사용 시 재급유는 현장 내에서 실시하도록 한다."],4,0,"ew20220424"],["ew20220424-45",2,"T091","2022-04-24",45,41,"물적 증거로서의 화재패턴에 관한 설명으로 옳은 것은?",["V패턴이나 포인터 및 화살패턴은 환기에 의해 형성되는 패턴이다.","엘리게이터(alligator) 탄화는 발화 중에 액체 위험물 촉진제가 사용되었다는 증거이다.","정상연소에서 화재패턴을 형성하는 화재플룸의 온도는 발화구획실 코너에서 가장 높다.","발화원이 확인되지 않은 완전연소 패턴구역의 식별에서 화재확산 방향이나 연소시간 또는 강도의 차이 규명을 위해 활용할 수 있는 화재패턴은 보호구역 및 열그림자이다."],3,0,"ew20220424"],["ew20220424-46",2,"T073","2022-04-24",46,73,"화재현장을 촬영하는 위치에 관한 설명으로 옳은 것은?",["카메라는 가능하면 수직으로만 촬영한다.","피사체가 냉장고일 경우 여러 방향으로 촬영한다.","촬영방향은 발화부로 추정되는 곳의 앞면을 집중적으로 촬영한다.","촬영된 사진은 화재조사자를 위한 자료이므로 촬영위치는 조사자의 재량에 달려 있다."],2,0,"ew20220424"],["ew20220424-47",2,"T091","2022-04-24",47,56,"화재 열로 파손된 유리의 특징으로 옳은 것은?",["리플마크가 형성된다.","거미줄 형태로 파손된다.","방사형 형태로 깨진다.","구불구불한 불규칙한 형태로 깨진다."],4,0,"ew20220424"],["ew20220424-48",2,"T069","2022-04-24",48,74,"화재현장 사진 및 비디오 촬영에 관한 사항으로 틀린 것은?",["화재조사의 진행 순서에 따라 촬영한다.","화재현장의 증거 확보를 위하여 필요하다.","화재조사관의 오랜 경험에 의존하여 촬영여부를 결정해야 한다.","방화, 실화 수사의 기초자료로 사용하기 위하여 필요하다."],3,0,"ew20220424"],["ew20220424-49",2,"T080","2022-04-24",49,62,"액체 촉진제의 특성에 대한 설명으로 옳은 것은?",["촉진제는 액체 상태로만 발견된다.","액체 촉진제는 대부분의 내부 마감재 및 기타 화재 잔해에 쉽게 흡수된다.","모든 액체 촉진제는 물과 접촉했을 때 물 아래로 가라앉는다.","액체 촉진제가 다공성 물질에 흡수되었을 때는 잔존 가능성이 매우 낮다."],2,0,"ew20220424"],["ew20220424-50",2,"T074","2022-04-24",50,62,"화재증거물수집관리규칙상 증거물 시료용기가 아닌 것은?",["유리병","아크릴 병","양철 캔(CAN)","주석 도금 캔(CAN)"],2,0,"ew20220424"],["ew20220424-51",2,"T075","2022-04-24",51,65,"증거수집 과정에서 증거물의 오염 방지를 위한 조치사항으로 틀린 것은?",["새 증거물 보관용기는 기존에 사용되었던 용기와 오염지역에서 떨어진 곳에 보관하여야 한다.","증거물 보관 용기 자체를 수집 도구로 사용하는 것은 증거물 오염이 될 수 있으므로 사용을 금지한다.","수집 장소에서 증거물을 담을 때에만 용기를 개봉하고 증거물을 담은 후에는 실험실에서 조사를 할 때까지 계속 봉인되어 있어야 한다.","상호 교차 오염을 방지하기 위해 화재조사관은 액체나 고체 촉진제 중 증거물을 수집할 때 일회용 비닐장갑을 착용하고 작업하는 것이 효과적이다."],2,0,"ew20220424"],["ew20220424-52",2,"T070","2022-04-24",52,70,"화재현장에서 화면의 일부만을 측광하는 방식으로 주 피사체의 정확한 노출을 측광할 수 있으며 역광 촬영 시 사용되는 방식은?",["스팟측광","평균측광","다분할 측광","중앙부 중점 측광"],1,0,"ew20220424"],["ew20220424-53",2,"T093","2022-04-24",53,62,"화재로 인한 3도 화상에 관한 설명으로 틀린 것은?",["수포주위에 홍반을 보이며, 혈액침하가 일어나더라도 홍반만 남는다.","신경섬유가 파괴되어 통증이 없거나 미약할 수 있다.","피하지방을 포함한 피부의 전층이 손상된 경우로 심한 경우 근육, 뼈, 내부 장기도 포함되는 경우가 있다.","부스럼 딱지 또는 생체 내의 피부조직이나 세포가 죽는 응고성 괴사에 빠지므로 괴사성 화상이라고도 한다."],1,0,"ew20220424"],["ew20220424-54",2,"T084","2022-04-24",54,74,"질문기록서 작성을 위하여 관계자의 진술을 녹음하려고 할 때 유의사항으로 틀린 것은?",["유도심문을 피한다.","관계자에게 녹취내용을 확인시키고 서명을 하게 한다.","관계자의 진술은 화재발생 직후보다 화재 진압 후 시간이 경과한 뒤 실시하는 것이 좋다.","18세 미만의 청소년에게 질문을 하는 경우는 친권자 등을 반드시 입회시켜야 하며 진술자는 물론 입회자에게도 서명을 받도록 한다."],3,0,"ew20220424"],["ew20220424-55",2,"T090","2022-04-24",55,41,"인화성 액체, 부유물을 가진 액체, 시험 조건에서 표면 막을 형성하기 쉬운 액체, 40℃~370℃의 온도범위를 가지는 기타 액체의 인화점을 시험하는 방법은?",["태그 개방컵 테스트","태크 밀폐컵 테스트","클리브랜드 개방컵 테스트","펜스키-마텐스식 밀폐컵 테스트"],4,0,"ew20220424"],["ew20220424-56",2,"T085","2022-04-24",56,68,"일산화탄소 중독사의 대표적인 특징은?",["선홍색 시반이 나타난다.","수포주위에 홍반이 생긴다.","코에서 출혈이 심하게 나타난다.","피부의 세포조직이 검게 타는 탄피층이 형성된다."],1,0,"ew20220424"],["ew20220424-57",2,"","2022-04-24",57,76,"법정 증언의 자세로 가장 적절하지 않은 것은?",["차분한 마음상태를 유지한다.","사실적이고 객관적으로 답변한다.","사투리, 속어 등의 단어를 피한다.","질문에 관계없이 빠르게 답변한다."],4,0,"ew20220424"],["ew20220424-58",2,"T097","2022-04-24",58,67,"화재현장에서 발견된 사망한 사체에 관한 설명으로 틀린 것은?",["일산화탄소를 흡입한 것으로 화재 당시 생존해 있었음에 대한 증거가 될 수 있다.","눈가의 주름 사이에 그을음이 부착되지 않은 것은 화재 당시 사망한 상태였다는 증거가 될 수 있다.","일산화탄소가 헤모글로빈과 결합함으로써 체내 산소의 공급이 차단되어 사망했을 가능성이 있다.","기도, 폐 등의 호흡기에서 발견되는 그을음은 화재 당시 생존해 있었음을 나타내는 증거가 될 수 있다."],2,0,"ew20220424"],["ew20220424-59",2,"T076","2022-04-24",59,73,"화재증거물수집관리규칙상 증거물 보관 및 이동에 관한 설명으로 틀린 것은?",["증거물의 보관은 파손될 우려가 없는 장소에 보관해야 한다.","증거물의 보관 및 이송은 장소, 방법, 책임자 등이 지정된 상태에서 행해져야 한다.","증거물은 어떠한 경우라도 폐기할 수 없으며, 화재증거수집의 목적달성 후에는 관계인에게 반환하여야 한다.","증거물 보관 시 화재조사의 관계없는 자의 접근은 엄격히 통제되어야 하며, 보관관리 이력을 작성하여야 한다."],3,0,"ew20220424"],["ew20220424-60",2,"T069","2022-04-24",60,74,"화재증거물수집관리규칙상 현장사진 및 비디오 촬영 시 유의사항으로 틀린 것은?",["최초 도착하였을 때의 현장 정리정돈 후 촬영한다.","화재상황을 추정할 수 있는 증거물, 피해물품, 유류의 형상은 면밀히 관찰 후 자세히 촬영한다.","증거물을 촬영할 때는 그 소재와 상태가 명백히 나타나도록 하며, 필요에 따라 구분이 용이하게 번호표 등을 넣어 촬영한다.","화재현장의 특정한 증거물 등을 촬영함에 있어서는 그 길이, 폭 등을 명백히 하기 위하여 측정용 자 또는 대조도구를 사용하여 촬영한다."],1,0,"ew20220424"],["ew20220424-63",3,"T118","2022-04-24",63,67,"화재조사 및 보고규정상 화재의 유형에 명시되지 않은 것은? (단, 기타화재는 제외한다.)",["전기·화학 화재","건축·구조물 화재","선박·항공기 화재","자동차·철도차량 화재"],1,0,"ew20220424"],["ew20220424-64",3,"T111","2022-04-24",64,62,"화재조사 및 보고규정상 명시된 연소확대물의 정의로 옳은 것은?",["지속적인 연소현상에 영향을 준 인적·물적·자연적인 가연물을 말한다.","연소가 확대되는데 있어 결정적 영향을 미친 가연물을 말한다.","가연물질에 지속적으로 불이 붙는 가연물을 말한다.","발화관련 기기나 제품을 작동 또는 연소시킬 때 사용되어진 연료 또는 에너지를 말한다."],2,0,"ew20220424"],["ew20220424-66",3,"T130","2022-04-24",66,58,"화재로 인한 자동차의 피해액 산정 기준으로 틀린 것은?",["자동차의 수리비는 자동차 수리업소의 견적서를 참고하여 산정한다.","피해 대상 자동차와 동일하거나 유사한 자동차의 시중매매가격을 피해액으로 한다.","부분 소손되어 수리가 가능한 경우에는 수리에 소요되는 금액을 자동차의 피해액으로 한다.","부분 소손되어 수리가 가능한 모든 경우에는 피해액에 대하여 감가공제 한다."],4,0,"ew20220424"],["ew20220424-67",3,"T115","2022-04-24",67,49,"20년된 일반주택의 잔가율은? (단, 주택의 내용연수는 40년으로 한다.)",["50%","60%","70%","80%"],2,0,"ew20220424"],["ew20220424-68",3,"T112","2022-04-24",68,67,"화재조사 및 보고규정상 화재원인조사 범위로 명시되지 않은 것은?",["수손피해 조사","연소상황 조사","피난상황 조사","발견, 통보 및 초기소화상황 조사"],1,0,"ew20220424"],["ew20220424-69",3,"T112","2022-04-24",69,67,"화재조사 및 보고규정상 화재현장 조사서의 화재원인 검토 항목에 해당하지 않는 것은? (단, 임야화재, 기타화재, 피해액이 없는 화재 이외의 화재현장 조사서를 말한다.)",["방화 가능성","기계적 요인","인적 부주의","현장조사결과"],4,0,"ew20220424"],["ew20220424-70",3,"T108","2022-04-24",70,70,"화재조사 및 보고규정상 화재조사서류의 서식이 아닌 것은?",["질문기록서","화재현장조사서","범죄사실확인서","소방방화시설 활용조사서"],3,0,"ew20220424"],["ew20220424-71",3,"T107","2022-04-24",71,47,"가재도구의 화재 피해액 산정에 관한 사항으로 옳은 것은?",["피해액 산정 대상에서 의류 생산 공장의 재봉틀은 가재도구로 분류된다.","수리비가 가재도구 재구입비의 50%미만인 경우에는 감가공제를 하지 않는다.","의류는 세탁에 의해 재사용이 가능한 경우에는 10%의 손해율을 적용한다.","신혼가정 등 특별한 경우를 제외하고는 잔가율을 일괄적·포괄적 기준을 적용하여 70%로 한다."],3,0,"ew20220424"],["ew20220424-72",3,"T125","2022-04-24",72,68,"화재조사 및 보고규정상 화재유형별조사서(임야화재)의 작성에 대한 설명으로 틀린 것은?",["논밭두렁의 화재는 들불에 속한다.","묘지에서 발생한 화재는 들불에 속한다.","피해사항 중 산림피해면적은 기재하지 않는다.","산불은 국유림, 공유림, 사유림으로 구분한다."],3,0,"ew20220424"],["ew20220424-74",3,"T130","2022-04-24",74,41,"화재피해액 산정 대상에서 선박화재로 볼 수 없는 것은?",["육상에 있는 미취항의 범선에서 발생한 화재","독행 기능을 가지지 않는 거룻배에서 발생한 화재","수리 등을 위해 육상에 일시적으로 있는 선박에서 발생한 화재","독행 기능을 가지는 선박에 의해 끌어진 물건에 발생한 화재"],1,0,"ew20220424"],["ew20220424-76",3,"T113","2022-04-24",76,60,"화재조사 및 보고규정상 부대설비의 화재피해액 산정기준으로 옳은 것은?",["건물신축단가×소실면적×설비종류별 재설비 비율×[1-(0.8×경과연수/내용연수)]","건물신축단가×소실면적×설비종류별 재설비 비율×[1-(0.8×경과연수/내용연수)]×손해율","건물신축단가×소실면적×설비종류별 재설비 비율×[1-(0.9×경과연수/내용연수)]","건물신축단가×소실면적×설비종류별 재설비 비율×[1-(0.9×경과연수/내용연수)]×손해율"],2,0,"ew20220424"],["ew20220424-77",3,"T122","2022-04-24",77,60,"화재조사 및 보고규정상 화재피해액 산정기준으로 옳은 것은?",["동물이 화재로 전부손해를 입은 경우 피해액은 시중매매가격으로 한다.","골동품이 전부손해를 입은 경우 피해액은 원상복구에 소요되는 비용으로 한다.","전부손해가 아닌 식물의 경우 피해액은 시중매매가격으로 한다.","임야의 입목은 최초 입목구입가격에서 소실한 입목의 잔존가격을 더한 가격으로 한다."],1,0,"ew20220424"],["ew20220424-78",3,"T116","2022-04-24",78,42,"화재조사 및 보고규정상 용어에 대한 정의 중 틀린 것은?",["잔가율이란 피해물의 취득 당시 가액에 대한 현재가의 비율을 말한다.","내용연수란 고정자산을 경제적으로 사용할 수 있는 연수를 말한다.","최종잔가율이란 피해물의 경제적 내용연수가 다한 경우 잔존하는 가치의 재구입비에 대한 비율을 말한다.","손해율이란 피해물의 종류, 손상 상태 및 정도에 따라 피해액을 적정화시키는 일정한 비율을 말한다."],1,0,"ew20220424"],["ew20220424-79",3,"","2022-04-24",79,30,"화재조사 및 보고규정상 방화·방화의심 조사서 작성 시 기재사항이 아닌 것은? (단, 기타 참고사항은 제외한다.)",["방화도구","방화피해사항","방화자 인적사항","도착 시 초기상황"],2,0,"ew20220424"],["ew20220424-80",3,"T114","2022-04-24",80,36,"화재로 인하여 공장·창고를 제외한 건물의 천장·벽·바닥 등 내부 마감재 및 건물 내 영업시설물 등이 소실된 경우 손해율은? (단, 건물의 용도, 건물구조, 손상상태 및 정도에 따른 가감은 제외한다.)",["10%","20%","40%","60%"],3,0,"ew20220424"],["ew20220424-82",4,"T146","2022-04-24",82,61,"제조물책임법상 명시된 결함의 분류가 아닌 것은?",["유통상의 결함","제조상의 결함","설계상의 결함","표시상의 결함"],1,0,"ew20220424"],["ew20220424-85",4,"T148","2022-04-24",85,54,"제조물책임법에 대한 설명으로 틀린 것은?",["제조업자는 제조물의 수입을 업으로 하는 자도 포함된다.","제조물책임법에 따른 손해배상책임을 배제하거나 제한하는 모든 특약은 유효하다.","동일한 손해에 대하여 배상할 책임이 있는 자가 2인 이상인 경우에는 연대하여 그 손해를 배상할 책임이 있다.","손해배상책임을 지는 자가 제조업자가 해당 제조물을 공급하지 아니하였다는 사실을 입증한 경우에는 손해배상책임을 면한다."],2,0,"ew20220424"],["ew20220424-86",4,"T164","2022-04-24",86,51,"화재로 인한 재해보상과 보험가입에 관한 법률 시행령상 특수건물의 기준으로 틀린 것은?",["영화상영관으로 사용하는 부분의 바닥면적의 합계가 1000m2 이상인 건물","일반음식점영업으로 사용하는 부분의 바닥면적의 합계가 2000m2 이상인 건물","목욕장업으로 사용하는 부분의 바닥면적의 합계가 2000m2 이상인 건물","병원급 의료기관으로 사용하는 건물로서 연면적의 합계가 3000m2 이상인 건물"],1,0,"ew20220424"],["ew20220424-88",4,"T159","2022-04-24",88,58,"화재조사 및 보고규정상 건물의 동수 산정 기준으로 옳은 것은?",["구조에 관계없이 지붕 및 실이 하나로 연결되어 있는 것은 같은 동으로 본다.","건널 복도 등으로 2이상의 동에 연결되어 있는 것은 같은 동으로 본다.","내화조 건물의 경우 격벽으로 방화구획이 되어 있는 경우는 각 동으로 한다.","독립된 건물과 건물 사이에 차광막, 비막이 등의 덮개를 설치하고 그 밑을 통로로 사용하는 경우에는 같은 동으로 한다."],1,0,"ew20220424"],["ew20220424-90",4,"T173","2022-04-24",90,59,"민법상 불법행위에 관한 사항으로 틀린 것은?",["고의 또는 과실로 인한 위법행위로 타인에게 손해를 가한 자는 그 손해를 배상할 책임이 있다.","타인에게 정신상 고통을 가한 자는 재산 이외의 손해에 대하여도 배상할 책임이 있다.","미성년자가 타인에게 손해를 가한 경우에 그 행위의 책임을 변식할 지능이 없는 때에는 배상의 책임이 없다.","타인의 생명을 해한 자는 피해자의 직계존속, 직계비속 및 배우자에 대하여는 재산상의 손해가 없는 경우에는 손해배상의 책임이 없다."],4,0,"ew20220424"],["ew20220424-91",4,"T136","2022-04-24",91,70,"소방기본법령상 화재가 발생하였을 때 화재 원인과 피해 등에 대한 조사를 실시하는 시기로 옳은 것은?",["화재진압 완료 후 실시","소방청장의 허가를 득한 후 실시","화재조사자가 임의로 정하는 시기에 실시","관계 공무원이 화재사실을 인지하는 즉시 실시"],4,0,"ew20220424"],["ew20220424-92",4,"T141","2022-04-24",92,72,"화재조사 및 보고규정상 화재조사 전담부서 설치에 관한 내용으로 틀린 것은?",["화재조사관은 그 직무를 이용하여 관계자의 민사분쟁에 적극적으로 개입하여야 한다.","화재조사의 정확성을 기하기 위하여 원인조사와 피해조사로 구분하여 조사하고 보조요원을 지정 운영하여야 한다.","소방학교장은 화재조사 전문가 육성과 화재원인 등을 조사·연구할 부서를 설치 운영한다.","화재조사의 원인감식과 피해조사의 전문화와 업무 발전을 위하여 소방본부와 소방서에 화재조사 전담부서를 설치 운영한다."],1,0,"ew20220424"],["ew20220424-93",4,"","2022-04-24",93,52,"소방기본법령상 화재조사에 관한 전문교육 과정의 교육과목 중 전문교육에 해당하는 과목이 아닌 것은?",["기초화학","심리상담기법","범죄심리학","소방시설조사"],2,0,"ew20220424"],["ew20220424-94",4,"T148","2022-04-24",94,71,"과도한 문어발식 콘센트 사용으로 발생한 전기화재로 인하여, 구입한 지 5년 된 세탁기가 소손되었다. 이 소손에 대하여 제조물책임법령상 손해배상책임에 관한 설명으로 옳은 것은?",["세탁기 제조상 결함으로 손해배상책임은 세탁기 제조사가 부담한다.","세탁기 소유자의 사용상 문제로 손해배상책임은 발생하지 않는다.","세탁기 설계상 결함으로 손해배상책임은 세탁기 설계자가 부담한다.","세탁기 유통상 결함으로 손해배상책임은 제품 유통 업체에서 부담한다."],2,0,"ew20220424"],["ew20220424-95",4,"T156","2022-04-24",95,64,"실화책임에 관한 법률에 관한 내용으로 틀린 것은?",["손해배상액의 경감 청구가 있을 경우 화재의 원인을 고려하여 손해배상액을 경감할 수 있다.","실화가 중대한 과실로 인한 것이 아닌 경우 그로 인한 손해의 배상의무자는 법원에 손해배상액의 경감을 청구할 수 없다.","실화로 인하여 화재가 발생한 경우 연소(延燒)로 인한 부분에 대한 손해배상청구에 한하여 적용한다.","실화(失火)의 특수성을 고려하여 실화자에게 중대한 과실이 없는 경우 그 손해배상액의 경감(輕減)에 관한 「민법」 제765조의 특례를 정함을 목적으로 한다."],2,0,"ew20220424"],["ew20220424-96",4,"T139","2022-04-24",96,62,"소방기본법령상 화재조사를 하는 관계공무원이 화재조사를 수행하면서 알게 된 비밀을 다른 사람에게 누설한 경우 벌금 기준은?",["100만원 이하의 벌금","200만원 이하의 벌금","300만원 이하의 벌금","500만원 이하의 벌금"],3,0,"ew20220424"],["ew20220424-100",4,"T168","2022-04-24",100,59,"화재로 인한 재해보상과 보험가입에 관한 법률상 보험가입에 관한 사항으로 틀린 것은?",["특수건물의 소유자는 특약부화재보험에 관한 계약을 매년 갱신하여야 한다.","손해보험회사는 특약부화재보험 계약의 체결을 거절할 수 있다.","특수건물의 소유자는 특약부화재보험에 부가하여 풍재(風災) 등으로 인한 손해를 담보하는 보험에 가입할 수 있다.","특수건물의 소유권이 변경된 경우 특수건물의 소유자는 그 건물의 소유권을 취득한 날부터 30일 이내에 특약부화재보험에 가입하여야 한다."],2,0,"ew20220424"]],"현행":["화재조사론","증거물관리 및 법과학","화재감식론","화재조사보고 및 피해평가","화재조사관계법규"]};
